const ROLE_LABEL: Record<string, string> = { admin: "Company owner", gerente: "Manager", funcionario: "Employee", cliente: "Client" };
function roleLabel(role: string): string {
  if (role === "admin") return tr("Company owner", "Dono da empresa", "Dueño de la empresa");
  if (role === "cliente") return tr("Client", "Cliente", "Cliente");
  if (role === "gerente") return tr("Manager", "Gerente", "Gerente");
  if (role === "funcionario") return tr("Employee", "Funcionário", "Empleado");
  return ROLE_LABEL[role] ?? role;
}
const STATUS_PROJ: Record<string, string> = { planejada: "Planned", andamento: "In progress", pausada: "Paused", concluida: "Completed" };
function projectStatusLabel(status: string): string {
  if (status === "planejada") return tr("Planned", "Planejada", "Planificada");
  if (status === "andamento") return tr("In progress", "Em andamento", "En curso");
  if (status === "pausada") return tr("Paused", "Pausada", "Pausada");
  if (status === "concluida") return tr("Completed", "Concluída", "Completada");
  return STATUS_PROJ[status] ?? status;
}
const PAYTYPE_LABEL: Record<string, string> = { hora: "Hourly", diaria: "Daily", contrato: "Contract" };
function payTypeLabel(payType: string): string {
  if (payType === "hora") return tr("Hourly", "Por hora", "Por hora");
  if (payType === "diaria") return tr("Daily", "Por dia", "Por día");
  if (payType === "contrato") return tr("Contract", "Por contrato", "Por contrato");
  return PAYTYPE_LABEL[payType] ?? payType;
}
const PAYTYPE_SUFFIX: Record<string, string> = { hora: "/hr", diaria: "/day", contrato: " flat" };
function payTypeSuffix(payType: string): string {
  if (payType === "hora") return tr("/hr", "/h", "/h");
  if (payType === "diaria") return tr("/day", "/dia", "/día");
  if (payType === "contrato") return tr(" flat", " fixo", " fijo");
  return PAYTYPE_SUFFIX[payType] ?? "";
}

function getGPS(): Promise<{ lat: number; lng: number } | null> {
  return new Promise((resolve) => {
    if (!("geolocation" in navigator)) return resolve(null);
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => resolve(null),
      { timeout: 8000, enableHighAccuracy: true },
    );
  });
}

const fmtDist = (m: number | null) => {
  if (m === null || m === undefined) return "";
  const ft = m * 3.28084;
  if (ft < 1000) return `${Math.round(ft)} ft`;
  return `${(m / 1609.34).toLocaleString("en-US", { maximumFractionDigits: 1 })} mi`;
};
const mToFt = (m: number) => Math.round(m * 3.28084);
const ftToM = (ft: number) => Math.max(25, Math.min(5000, Math.round(ft / 3.28084)));
function haversineClientM(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const R = 6371000;
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(a)));
}

/* ---------------- structured US address ---------------- */
type AddrParts = { streetNumber: string; streetName: string; city: string; state: string; zip: string };
const emptyAddr = (): AddrParts => ({ streetNumber: "", streetName: "", city: "", state: "", zip: "" });
function formatAddr(a: AddrParts): string {
  const line1 = [a.streetNumber, a.streetName].filter(Boolean).join(" ");
  const cityState = [a.city, a.state].filter(Boolean).join(", ");
  return [line1, cityState && a.zip ? `${cityState} ${a.zip}` : cityState || a.zip].filter(Boolean).join(", ");
}

const US_STATES: [string, string][] = [
  ["AL", "Alabama"], ["AK", "Alaska"], ["AZ", "Arizona"], ["AR", "Arkansas"], ["CA", "California"],
  ["CO", "Colorado"], ["CT", "Connecticut"], ["DE", "Delaware"], ["DC", "District of Columbia"], ["FL", "Florida"],
  ["GA", "Georgia"], ["HI", "Hawaii"], ["ID", "Idaho"], ["IL", "Illinois"], ["IN", "Indiana"],
  ["IA", "Iowa"], ["KS", "Kansas"], ["KY", "Kentucky"], ["LA", "Louisiana"], ["ME", "Maine"],
  ["MD", "Maryland"], ["MA", "Massachusetts"], ["MI", "Michigan"], ["MN", "Minnesota"], ["MS", "Mississippi"],
  ["MO", "Missouri"], ["MT", "Montana"], ["NE", "Nebraska"], ["NV", "Nevada"], ["NH", "New Hampshire"],
  ["NJ", "New Jersey"], ["NM", "New Mexico"], ["NY", "New York"], ["NC", "North Carolina"], ["ND", "North Dakota"],
  ["OH", "Ohio"], ["OK", "Oklahoma"], ["OR", "Oregon"], ["PA", "Pennsylvania"], ["RI", "Rhode Island"],
  ["SC", "South Carolina"], ["SD", "South Dakota"], ["TN", "Tennessee"], ["TX", "Texas"], ["UT", "Utah"],
  ["VT", "Vermont"], ["VA", "Virginia"], ["WA", "Washington"], ["WV", "West Virginia"], ["WI", "Wisconsin"], ["WY", "Wyoming"],
];
const STATE_BY_NAME = new Map(US_STATES.map(([code, name]) => [name.toLowerCase(), code]));

/* OpenStreetMap Nominatim — address autocomplete + geocoding (client-side).
   Suggestions are best-effort: any failure silently keeps manual entry. */
type GeoSuggestion = { parts: AddrParts; lat: number; lng: number; label: string };
type NominatimHit = {
  lat?: string; lon?: string; display_name?: string;
  address?: {
    house_number?: string; road?: string; city?: string; town?: string; village?: string;
    borough?: string; hamlet?: string; county?: string; state?: string; postcode?: string;
    "ISO3166-2-lvl4"?: string;
  };
};
/* `fallbackNumber` is the street number the user typed manually. Nominatim
   addressdetails often omits `house_number` (street-level hits), and a typed
   number must never be wiped by accepting such a suggestion. */
function hitToSuggestion(h: NominatimHit, fallbackNumber = ""): GeoSuggestion | null {
  const lat = parseFloat(h.lat ?? "");
  const lng = parseFloat(h.lon ?? "");
  const a = h.address ?? {};
  const iso = a["ISO3166-2-lvl4"];
  const state = (iso && iso.startsWith("US-") ? iso.slice(3) : STATE_BY_NAME.get((a.state ?? "").toLowerCase()) ?? a.state ?? "").slice(0, 2).toUpperCase();
  const parts: AddrParts = {
    streetNumber: a.house_number || fallbackNumber,
    streetName: a.road ?? "",
    city: a.city ?? a.town ?? a.village ?? a.borough ?? a.hamlet ?? "",
    state,
    zip: (a.postcode ?? "").slice(0, 5),
  };
  const label = formatAddr(parts) || (h.display_name ?? "");
  if (!label) return null;
  return { parts, lat: Number.isFinite(lat) ? lat : NaN, lng: Number.isFinite(lng) ? lng : NaN, label };
}
async function nominatimSearch(query: string, limit: number, fallbackNumber = ""): Promise<GeoSuggestion[]> {
  try {
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&countrycodes=us&limit=${limit}&q=${encodeURIComponent(query)}`;
    const res = await fetch(url, { headers: { Accept: "application/json" } });
    if (!res.ok) return [];
    const hits = (await res.json()) as NominatimHit[];
    return hits.map((h) => hitToSuggestion(h, fallbackNumber)).filter((s): s is GeoSuggestion => s !== null);
  } catch {
    return [];
  }
}

/** Reusable structured US address form: street number, street name, city,
 *  state, ZIP. Native autofill attributes + OpenStreetMap type-ahead on the
 *  street field. When `onPick` is provided (project form), choosing a
 *  suggestion also delivers the geocoded coordinates for the geofence. */
function AddressForm({ value, onChange, idPrefix, onPick }: {
  value: AddrParts;
  onChange: (v: AddrParts) => void;
  idPrefix: string;
  onPick?: (s: GeoSuggestion) => void;
}) {
  const [suggestions, setSuggestions] = useState<GeoSuggestion[]>([]);
  const [open, setOpen] = useState(false);
  const [searching, setSearching] = useState(false);
  const tokenRef = useRef(0);
  const skipNextRef = useRef(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  /* Close immediately and cancel everything pending: bumping the token
     invalidates any in-flight search, so a late response can never reopen
     the list while the form sits idle. */
  const closeSuggestions = () => {
    tokenRef.current += 1;
    if (timerRef.current) { clearTimeout(timerRef.current); timerRef.current = null; }
    setSearching(false);
    setSuggestions([]);
    setOpen(false);
  };

  useEffect(() => {
    if (skipNextRef.current) { skipNextRef.current = false; return; }
    const q = `${value.streetNumber} ${value.streetName}`.trim();
    if (q.length < 4) { setSuggestions([]); setOpen(false); return; }
    const token = ++tokenRef.current;
    const t = setTimeout(async () => {
      setSearching(true);
      const full = [q, value.city, value.state, value.zip].filter(Boolean).join(", ");
      const results = await nominatimSearch(full, 5, value.streetNumber);
      if (tokenRef.current !== token) return;
      setSearching(false);
      setSuggestions(results);
      setOpen(results.length > 0);
    }, 600);
    timerRef.current = t;
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value.streetNumber, value.streetName]);

  /* Tap/click anywhere outside the form closes the suggestions right away. */
  useEffect(() => {
    if (!open) return;
    const onDocPointer = (e: PointerEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) closeSuggestions();
    };
    document.addEventListener("pointerdown", onDocPointer, true);
    return () => document.removeEventListener("pointerdown", onDocPointer, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const set = (patch: Partial<AddrParts>) => onChange({ ...value, ...patch });
  const pick = (s: GeoSuggestion) => {
    skipNextRef.current = true;
    /* Never clear a manually typed street number: when the chosen suggestion
       carries no house number of its own, keep what the user typed. */
    const merged: AddrParts = { ...s.parts };
    if (!merged.streetNumber && value.streetNumber.trim()) merged.streetNumber = value.streetNumber;
    closeSuggestions();
    onChange(merged);
    onPick?.({ ...s, parts: merged, label: formatAddr(merged) || s.label });
  };

  return (
    <div className="space-y-3" ref={rootRef}>
      <div className="relative">
        <div className="grid grid-cols-[6.5rem_1fr] gap-2">
          <Field label={tr("Number", "Número", "Número")}>
            <input aria-label={tr("Street number", "Número da rua", "Número de la calle")} autoComplete="street-address" className={inputCls} value={value.streetNumber}
              onChange={(e) => set({ streetNumber: e.target.value })} placeholder="123" inputMode="numeric" />
          </Field>
          <Field label={tr("Street name", "Nome da rua", "Nombre de la calle")}>
            <input aria-label={tr("Street name", "Nome da rua", "Nombre de la calle")} autoComplete="street-address" className={inputCls} value={value.streetName}
              onChange={(e) => set({ streetName: e.target.value })}
              onFocus={() => { if (suggestions.length > 0) setOpen(true); }}
              onBlur={() => closeSuggestions()}
              onKeyDown={(e) => { if (e.key === "Escape") closeSuggestions(); }}
              placeholder="Main St" aria-expanded={open} role="combobox" aria-controls={`${idPrefix}-addr-list`} />
          </Field>
        </div>
        {open && suggestions.length > 0 && (
          <div className="absolute inset-x-0 top-full z-30 mt-1 overflow-hidden rounded-xl border border-[var(--border)] bg-[var(--surface)] shadow-lg">
            <ul id={`${idPrefix}-addr-list`} role="listbox" aria-label={tr("Address suggestions", "Sugestões de endereço", "Sugerencias de dirección")}>
              {suggestions.map((s, i) => (
                <li key={`${s.label}-${i}`}>
                  <button type="button" role="option" aria-selected="false" aria-label={tr(`Use address ${s.label}`, `Usar o endereço ${s.label}`, `Usar la dirección ${s.label}`)}
                    onPointerDown={(e) => { e.preventDefault(); pick(s); }}
                    className="block w-full px-3 py-2.5 text-left text-sm active:bg-[var(--surface2)]">
                    📍 {s.label}
                  </button>
                </li>
              ))}
            </ul>
            <p className="border-t border-[var(--border)] px-3 py-1.5 text-[11px] text-[var(--dim)]">{tr("Address suggestions by OpenStreetMap", "Sugestões de endereço por OpenStreetMap", "Sugerencias de dirección por OpenStreetMap")}</p>
          </div>
        )}
        {searching && <p className="mt-1 text-[11px] text-[var(--dim)]">{tr("Searching addresses…", "Buscando endereços…", "Buscando direcciones…")}</p>}
      </div>
      <Field label={tr("City", "Cidade", "Ciudad")}>
        <input aria-label={tr("City", "Cidade", "Ciudad")} autoComplete="address-level2" className={inputCls} value={value.city}
          onChange={(e) => set({ city: e.target.value })} placeholder="Toms River" />
      </Field>
      <div className="grid grid-cols-2 gap-2">
        <Field label={tr("State", "Estado", "Estado")}>
          <select aria-label={tr("State", "Estado", "Estado")} autoComplete="address-level1" className={inputCls} value={value.state} onChange={(e) => set({ state: e.target.value })}>
            <option value="">{tr("Select…", "Selecionar…", "Seleccionar…")}</option>
            {US_STATES.map(([code, name]) => <option key={code} value={code}>{code} — {name}</option>)}
          </select>
        </Field>
        <Field label={tr("ZIP code", "CEP (ZIP)", "Código postal (ZIP)")}>
          <input aria-label={tr("ZIP code", "CEP (ZIP)", "Código postal (ZIP)")} autoComplete="postal-code" className={inputCls} value={value.zip}
            onChange={(e) => set({ zip: e.target.value.replace(/[^\d-]/g, "").slice(0, 10) })} placeholder="08755" inputMode="numeric" />
        </Field>
      </div>
    </div>
  );
}

/* ---------------- small UI ---------------- */
function Kpi({ label, value, sub, accent }: { label: string; value: string; sub?: string; accent?: boolean }) {
  return (
    <div className={`rounded-2xl p-4 ${accent ? "bg-[#0f2a44] text-white" : "bg-[var(--surface)] border border-[var(--border)]"}`}>
      <p className={`text-xs font-semibold uppercase tracking-wide ${accent ? "text-white/60" : "text-[var(--dim)]"}`}>{label}</p>
      <p className="mt-1 text-xl font-bold leading-tight">{value}</p>
      {sub ? <p className={`mt-0.5 text-xs ${accent ? "text-white/60" : "text-[var(--dim)]"}`}>{sub}</p> : null}
    </div>
  );
}
function Badge({ text, tone }: { text: string; tone: "green" | "amber" | "red" | "gray" | "navy" }) {
  const cls = {
    green: "bg-green-100 text-green-800",
    amber: "bg-amber-100 text-amber-800",
    red: "bg-red-100 text-red-700",
    gray: "bg-gray-100 text-gray-600",
    navy: "bg-[#0f2a44]/10 text-[#0f2a44]",
  }[tone];
  return <span className={`inline-block rounded-full px-2 py-0.5 text-xs font-semibold ${cls}`}>{text}</span>;
}
function payBadge(payType: string, payRate: number) {
  const label = payTypeLabel(payType);
  const suffix = payTypeSuffix(payType);
  return <Badge text={`${label} • ${fmtUSD(payRate)}${suffix}`} tone={payType === "hora" ? "green" : payType === "diaria" ? "amber" : "navy"} />;
}
function sheetBadge(status: string) {
  if (status === "aprovado") return <Badge text={tr("Approved", "Aprovado", "Aprobado")} tone="green" />;
  if (status === "pendente") return <Badge text={tr("Pending", "Pendente", "Pendiente")} tone="amber" />;
  if (status === "rejeitado") return <Badge text={tr("Rejected", "Rejeitado", "Rechazado")} tone="red" />;
  return <Badge text={tr("Open", "Aberto", "Abierta")} tone="navy" />;
}
function zoneBadge(zone: string, distM: number | null, when: string) {
  if (zone === "fora") return <Badge text={tr(`🚨 OUTSIDE JOB SITE AREA (${when}${distM !== null ? ` • ${fmtDist(distM)}` : ""})`, `🚨 FORA DA ÁREA DA OBRA (${when}${distM !== null ? ` • ${fmtDist(distM)}` : ""})`, `🚨 FUERA DEL ÁREA DE LA OBRA (${when}${distM !== null ? ` • ${fmtDist(distM)}` : ""})`)} tone="red" />;
  if (zone === "dentro") return <Badge text={tr(`Inside site area${distM !== null ? ` • ${fmtDist(distM)}` : ""}`, `Dentro da área da obra${distM !== null ? ` • ${fmtDist(distM)}` : ""}`, `Dentro del área de la obra${distM !== null ? ` • ${fmtDist(distM)}` : ""}`)} tone="green" />;
  if (zone === "sem_gps") return <Badge text={tr("No GPS", "Sem GPS", "Sin GPS")} tone="gray" />;
  if (zone === "sem_cerca") return <Badge text={tr("No geofence set for this project", "Nenhuma cerca virtual definida para esta obra", "No hay geocerca definida para esta obra")} tone="gray" />;
  return null;
}
function invBadge(status: string) {
  if (status === "paga") return <Badge text={tr("Paid", "Pago", "Pagado")} tone="green" />;
  if (status === "parcial") return <Badge text={tr("Partial", "Parcial", "Parcial")} tone="amber" />;
  if (status === "vencida") return <Badge text={tr("Overdue", "Vencida", "Vencida")} tone="red" />;
  return <Badge text={tr("Open", "Aberta", "Abierta")} tone="gray" />;
}
function Field({ label, children }: { label: string; children: ReactNode }) {
  return (
    <label className="block">
      <span className="mb-1 block text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{label}</span>
      {children}
    </label>
  );
}
const inputCls = "w-full rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3 py-2.5 text-[var(--text)] outline-none focus:border-[#f97316]";
const btnPrimary = "rounded-xl bg-[#f97316] px-4 py-3 font-semibold text-white active:opacity-80 disabled:opacity-40";
const btnNavy = "rounded-xl bg-[#0f2a44] px-4 py-3 font-semibold text-white active:opacity-80 disabled:opacity-40";
const btnGhost = "rounded-xl border border-[var(--border)] bg-[var(--surface)] px-4 py-2.5 font-medium text-[var(--text)] active:opacity-70";

/* Pay type segmented selector — the choice that drives payroll. */
function PayTypePicker({ payType, payRate, onType, onRate }: {
  payType: string; payRate: string;
  onType: (t: string) => void; onRate: (v: string) => void;
}) {
  const options: { key: string; label: string; hint: string }[] = [
    { key: "hora", label: tr("Hourly", "Por hora", "Por hora"), hint: tr("Paid per approved hour worked", "Pago por hora aprovada trabalhada", "Pago por hora aprobada trabajada") },
    { key: "diaria", label: tr("Daily", "Por dia", "Por día"), hint: tr("Paid per day with an approved check-in", "Pago por dia com check-in aprovado", "Pago por día con registro de entrada aprobado") },
    { key: "contrato", label: tr("Contract", "Por contrato", "Por contrato"), hint: tr("Fixed amount for the period", "Valor fixo pelo período", "Importe fijo por el período") },
  ];
  const rateLabel = payType === "hora" ? tr("Rate per hour (USD)", "Valor por hora (USD)", "Tarifa por hora (USD)") : payType === "diaria" ? tr("Rate per day (USD)", "Valor por dia (USD)", "Tarifa por día (USD)") : tr("Contract amount (USD)", "Valor do contrato (USD)", "Importe del contrato (USD)");
  return (
    <div>
      <span className="mb-1 block text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Pay type — how this person gets paid", "Tipo de pagamento — como esta pessoa recebe", "Tipo de pago: cómo cobra esta persona")}</span>
      <div className="grid grid-cols-3 gap-2" role="radiogroup" aria-label={tr("Pay type", "Tipo de pagamento", "Tipo de pago")}>
        {options.map((o) => (
          <button key={o.key} type="button" role="radio" aria-checked={payType === o.key}
            aria-label={tr(`Pay type: ${o.label}`, `Tipo de pagamento: ${o.label}`, `Tipo de pago: ${o.label}`)}
            onClick={() => onType(o.key)}
            className={`rounded-xl border px-2 py-2.5 text-sm font-bold ${payType === o.key ? "border-[#f97316] bg-[#f97316] text-white" : "border-[var(--border)] bg-[var(--surface)] text-[var(--text)]"}`}>
            {o.label}
          </button>
        ))}
      </div>
      <p className="mt-1 text-xs text-[var(--dim)]">{options.find((o) => o.key === payType)?.hint}</p>
      <div className="mt-2">
        <Field label={rateLabel}>
          <input aria-label={rateLabel} className={inputCls} inputMode="decimal" value={payRate}
            onChange={(e) => onRate(e.target.value)} placeholder={payType === "contrato" ? "8,500.00" : payType === "diaria" ? "350.00" : "18.50"} />
        </Field>
      </div>
    </div>
  );
}

/* ---------------- job tasks (checklist) ---------------- */
type TaskPhotoLite = { id: number; taskId: number; photoUrl: string; stage: string; employeeId: number; employeeName: string; createdAt: string };
type TaskLite = {
  id: number; companyId: string; jobId: number; projectId: number; jobName: string; projectName: string;
  title: string; notes: string;
  assigneeIds: number[]; assigneeNames: string[];
  assigneeId: number | null; assigneeName: string; status: string;
  createdAt: string; startedAt: string | null; completedAt: string | null; sortOrder: number; photos: TaskPhotoLite[];
  totalMinutes: number; timerRunning: boolean; timerStartedAt: string | null;
};

/* Assignee display helpers (multi-select model): an empty assignee list
   means the whole job crew covers the task; names render as one chip each. */
function taskAssigneeIds(task: TaskLite): number[] {
  if (Array.isArray(task.assigneeIds) && task.assigneeIds.length > 0) return task.assigneeIds;
  return task.assigneeId !== null && task.assigneeId !== undefined ? [task.assigneeId] : [];
}
function taskAssigneeNames(task: TaskLite): string[] {
  if (Array.isArray(task.assigneeNames) && task.assigneeNames.length > 0) return task.assigneeNames;
  return task.assigneeName ? task.assigneeName.split(", ").filter(Boolean) : [];
}

const TASK_STATUS_LABEL: Record<string, string> = { todo: "To Do", in_progress: "In Progress", done: "Done" };
function taskStatusLabel(status: string): string {
  if (status === "todo") return tr("To Do", "A fazer", "Por hacer");
  if (status === "in_progress") return tr("In Progress", "Em andamento", "En curso");
  if (status === "done") return tr("Done", "Concluída", "Terminada");
  return TASK_STATUS_LABEL[status] ?? status;
}
const TASK_STATUS_GROUPS: { key: string; label: string }[] = [
  { key: "todo", label: "To Do" },
  { key: "in_progress", label: "In Progress" },
  { key: "done", label: "Done" },
];
function taskStatusGroups(): { key: string; label: string }[] {
  return [
    { key: "todo", label: taskStatusLabel("todo") },
    { key: "in_progress", label: taskStatusLabel("in_progress") },
    { key: "done", label: taskStatusLabel("done") },
  ];
}
const PHOTO_STAGES: { key: "before" | "during" | "after"; label: string; tone: "gray" | "amber" | "green" }[] = [
  { key: "before", label: "Before", tone: "gray" },
  { key: "during", label: "During", tone: "amber" },
  { key: "after", label: "After", tone: "green" },
];
function photoStages(): { key: "before" | "during" | "after"; label: string; tone: "gray" | "amber" | "green" }[] {
  return [
    { key: "before", label: tr("Before", "Antes", "Antes"), tone: "gray" },
    { key: "during", label: tr("During", "Durante", "Durante"), tone: "amber" },
    { key: "after", label: tr("After", "Depois", "Después"), tone: "green" },
  ];
}
const photoStageMeta = (stage: string): { key: "before" | "during" | "after"; label: string; tone: "gray" | "amber" | "green" } =>
  photoStages().find((s) => s.key === stage) ?? { key: "during", label: tr("During", "Durante", "Durante"), tone: "amber" };

function taskStatusBadge(status: string) {
  return <Badge text={taskStatusLabel(status)} tone={status === "done" ? "green" : status === "in_progress" ? "amber" : "gray"} />;
}

/* Whole calendar days between the local date of `fromIso` and today. */
function localDayDiff(fromIso: string): number {
  const a = new Date(fromIso);
  const start = new Date(a.getFullYear(), a.getMonth(), a.getDate()).getTime();
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  return Math.max(0, Math.round((today - start) / 86400000));
}
function inProgressMeta(startedAt: string | null): string {
  if (!startedAt) return tr("In progress", "Em andamento", "En curso");
  const d = localDayDiff(startedAt);
  if (d <= 0) return tr("Started today", "Começou hoje", "Empezó hoy");
  return tr(`In progress • ${d} day${d === 1 ? "" : "s"}`, `Em andamento • ${d} dia${d === 1 ? "" : "s"}`, `En curso • ${d} día${d === 1 ? "" : "s"}`);
}

/* Downscale a picked photo before upload so several photos per task stay
   light in the database. Falls back to the raw file if canvas is missing. */
function readPhotoFile(file: File): Promise<string> {
  return new Promise((resolve) => {
    const raw = () => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result ?? ""));
      reader.onerror = () => resolve("");
      reader.readAsDataURL(file);
    };
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const max = 1280;
      const scale = Math.min(1, max / Math.max(img.width, img.height));
      const w = Math.max(1, Math.round(img.width * scale));
      const h = Math.max(1, Math.round(img.height * scale));
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      const g = canvas.getContext("2d");
      if (!g) { URL.revokeObjectURL(url); raw(); return; }
      g.drawImage(img, 0, 0, w, h);
      URL.revokeObjectURL(url);
      resolve(canvas.toDataURL("image/jpeg", 0.82));
    };
    img.onerror = () => { URL.revokeObjectURL(url); raw(); };
    img.src = url;
  });
}

/* Company logo: downscale to at most 512px on the longest side, keeping
   transparency (PNG) when the source has it, so the invoice header stays
   light and prints cleanly on one page. */
function readLogoFile(file: File): Promise<string> {
  return new Promise((resolve) => {
    if (!file.type.startsWith("image/")) { resolve(""); return; }
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const max = 512;
      const scale = Math.min(1, max / Math.max(img.width, img.height));
      const w = Math.max(1, Math.round(img.width * scale));
      const h = Math.max(1, Math.round(img.height * scale));
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      const g = canvas.getContext("2d");
      if (!g) { URL.revokeObjectURL(url); resolve(""); return; }
      g.drawImage(img, 0, 0, w, h);
      URL.revokeObjectURL(url);
      const keepPng = file.type === "image/png" || file.type === "image/webp";
      resolve(canvas.toDataURL(keepPng ? "image/png" : "image/jpeg", 0.9));
    };
    img.onerror = () => { URL.revokeObjectURL(url); resolve(""); };
    img.src = url;
  });
}

/* ---------------- services catalog, measurements & plans ---------------- */
type ServiceLite = { id: number; companyId: string; name: string; unit: string; defaultRate: number };
type ProjectServiceLine = { id: number; companyId: string; projectId: number; serviceId: number | null; serviceName: string; unit: string; quantity: number; rate: number; lineTotal: number };
type ProjectPlanMeta = { id: number; companyId: string; projectId: number; name: string; mimeType: string; fileSize: number; isImage: boolean; thumbnailData: string; uploadedBy: number; uploadedByName: string; createdAt: string };

const SERVICE_UNIT_PRESETS = ["sq ft", "linear ft", "sq", "each", "hours"] as const;
const MAX_PLAN_BYTES = 6 * 1024 * 1024; // 6 MB original file
const fmtQty = (n: number) => n.toLocaleString("en-US", { maximumFractionDigits: 2 });

/* --- Service-name duplicate guard (client-side, no dependency) ---
   Names are compared normalized (trim, lowercase, collapsed spaces).
   An exact normalized match blocks the create; a near match (small
   edit distance — the classic "hardwod flor" typo) asks first. */
function normalizeServiceNameClient(raw: string): string {
  return raw.trim().toLowerCase().replace(/\s+/g, " ");
}
function levenshtein(a: string, b: string): number {
  if (a === b) return 0;
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j]! + 1, cur[j - 1]! + 1, prev[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length]!;
}
function serviceNameClash(name: string, services: ServiceLite[]): { kind: "exact" | "near"; match: ServiceLite } | null {
  const n = normalizeServiceNameClient(name);
  if (!n) return null;
  for (const s of services) {
    if (normalizeServiceNameClient(s.name) === n) return { kind: "exact", match: s };
  }
  let best: { match: ServiceLite; sim: number } | null = null;
  for (const s of services) {
    const m = normalizeServiceNameClient(s.name);
    const sim = 1 - levenshtein(n, m) / Math.max(n.length, m.length, 1);
    if (sim >= 0.78 && (!best || sim > best.sim)) best = { match: s, sim };
  }
  return best ? { kind: "near", match: best.match } : null;
}

function unitOptionLabel(unit: string): string {
  if (unit === "sq ft") return tr("Square feet (sq ft)", "Pés quadrados (sq ft)", "Pies cuadrados (sq ft)");
  if (unit === "linear ft") return tr("Linear feet (linear ft)", "Pés lineares (linear ft)", "Pies lineales (linear ft)");
  if (unit === "sq") return tr("Roofing squares (sq)", "Squares de telhado (sq)", "Squares de techo (sq)");
  if (unit === "each") return tr("Each (ea)", "Unidade (un)", "Unidad (ea)");
  if (unit === "hours") return tr("Hours (hr)", "Horas (h)", "Horas (h)");
  return unit;
}

/* Read a plan file for upload. Images are downscaled (max 2200px) onto a
   white background so blueprint lines stay readable and the stored copy
   stays light; a small thumbnail is derived for the list. PDFs pass
   through untouched. Returns null when the file can't be processed. */
function readPlanFile(file: File): Promise<{ mimeType: "application/pdf" | "image/jpeg" | "image/png"; fileData: string; thumbnailData: string } | null> {
  return new Promise((resolve) => {
    if (file.type === "application/pdf") {
      const reader = new FileReader();
      reader.onload = () => resolve({ mimeType: "application/pdf", fileData: String(reader.result ?? ""), thumbnailData: "" });
      reader.onerror = () => resolve(null);
      reader.readAsDataURL(file);
      return;
    }
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const render = (max: number, quality: number) => {
        const scale = Math.min(1, max / Math.max(img.width, img.height));
        const w = Math.max(1, Math.round(img.width * scale));
        const h = Math.max(1, Math.round(img.height * scale));
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        const g = canvas.getContext("2d");
        if (!g) return "";
        g.fillStyle = "#ffffff";
        g.fillRect(0, 0, w, h);
        g.drawImage(img, 0, 0, w, h);
        return canvas.toDataURL("image/jpeg", quality);
      };
      const full = render(2200, 0.88);
      const thumb = render(360, 0.72);
      URL.revokeObjectURL(url);
      if (!full) { resolve(null); return; }
      resolve({ mimeType: "image/jpeg", fileData: full, thumbnailData: thumb });
    };
    img.onerror = () => { URL.revokeObjectURL(url); resolve(null); };
    img.src = url;
  });
}

/* Full-screen plan viewer. Images scroll/pinch-zoom natively inside the
   overflow container (with +/− buttons for precise control); PDFs render
   in the built-in viewer. File bytes load on demand via getProjectPlan. */
function PlanViewerModal({ cid, actorId, plan, onClose }: { cid: string; actorId: number; plan: ProjectPlanMeta; onClose: () => void }) {
  const q = useQuery({ queryKey: ["project-plan-file", cid, plan.id], queryFn: () => api.getProjectPlan({ companyId: cid, planId: plan.id, actorId }) });
  const [zoom, setZoom] = useState(1);
  const data = q.data?.fileData ?? "";
  const isPdf = plan.mimeType === "application/pdf";
  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-black/90" role="dialog" aria-modal="true" aria-label={tr(`Plan ${plan.name}`, `Planta ${plan.name}`, `Plano ${plan.name}`)}>
      <div className="flex items-center justify-between gap-2 px-4 pb-2 pt-[max(0.75rem,env(safe-area-inset-top))]">
        <p className="min-w-0 truncate text-sm font-bold text-white">📐 {plan.name}</p>
        <span className="flex shrink-0 items-center gap-1.5">
          {!isPdf && data && (
            <>
              <button type="button" aria-label={tr("Zoom out plan", "Reduzir o zoom da planta", "Alejar el plano")} onClick={() => setZoom((z) => Math.max(0.5, Math.round((z - 0.25) * 100) / 100))} className="rounded-lg bg-white/15 px-3 py-1.5 text-sm font-black text-white active:opacity-70">−</button>
              <span className="min-w-11 text-center text-xs font-bold text-white/80" aria-label={tr(`Zoom ${Math.round(zoom * 100)} percent`, `Zoom de ${Math.round(zoom * 100)} por cento`, `Zoom del ${Math.round(zoom * 100)} por ciento`)}>{Math.round(zoom * 100)}%</span>
              <button type="button" aria-label={tr("Zoom in plan", "Aumentar o zoom da planta", "Acercar el plano")} onClick={() => setZoom((z) => Math.min(4, Math.round((z + 0.25) * 100) / 100))} className="rounded-lg bg-white/15 px-3 py-1.5 text-sm font-black text-white active:opacity-70">+</button>
            </>
          )}
          <button type="button" aria-label={tr("Close plan viewer", "Fechar o visualizador da planta", "Cerrar el visor del plano")} onClick={onClose} className="rounded-lg bg-white px-3 py-1.5 text-sm font-bold text-[#12222f] active:opacity-80">{tr("✕ Close", "✕ Fechar", "✕ Cerrar")}</button>
        </span>
      </div>
      <div className="min-h-0 flex-1 px-3 pb-3">
        {q.isPending && <p className="py-10 text-center text-sm text-white/70">{tr("Loading plan…", "Carregando a planta…", "Cargando el plano…")}</p>}
        {q.error && <p className="py-10 text-center text-sm font-semibold text-red-300">{tr("Could not load this plan. You may not be assigned to this project.", "Não foi possível carregar esta planta. Você pode não estar atribuído a esta obra.", "No se pudo cargar este plano. Es posible que no estés asignado a esta obra.")}</p>}
        {!q.isPending && !q.error && data && (isPdf ? (
          <iframe title={plan.name} src={data} className="h-full w-full rounded-xl bg-white" />
        ) : (
          <div className="h-full overflow-auto rounded-xl bg-white/5" style={{ touchAction: "pan-x pan-y pinch-zoom" }}>
            <img src={data} alt={tr(`Plan ${plan.name}`, `Planta ${plan.name}`, `Plano ${plan.name}`)} className="mx-auto block max-w-none" style={{ width: `${zoom * 100}%` }} draggable={false} />
          </div>
        ))}
        {!q.isPending && !q.error && data && (
          <p className="px-1 pt-2 text-center text-[11px] text-white/60">{isPdf ? tr("Use the PDF viewer's own zoom to read the plan up close.", "Use o zoom do próprio visualizador de PDF para ler a planta de perto.", "Usa el zoom del propio visor de PDF para leer el plano de cerca.") : tr("Pinch to zoom, or use the + / − buttons. Drag to move around the plan.", "Belisque para dar zoom, ou use os botões + / −. Arraste para se mover pela planta.", "Pellizca para hacer zoom, o usa los botones + / −. Arrastra para moverte por el plano.")}</p>
        )}
      </div>
    </div>
  );
}

/* Plans list shared by the project detail (manage) and the field view
   (read-only). Tapping a row opens the full-screen viewer. */
function ProjectPlansList({ cid, actorId, projectId, canManage }: { cid: string; actorId: number; projectId: number; canManage: boolean }) {
  const qc = useQueryClient();
  const plansQ = useQuery({ queryKey: ["project-plans", cid, projectId], queryFn: () => api.listProjectPlans({ companyId: cid, projectId, actorId }) });
  const [viewPlan, setViewPlan] = useState<ProjectPlanMeta | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<number | null>(null);
  const [msg, setMsg] = useState("");
  const [busy, setBusy] = useState(false);
  const fileRef = useRef<HTMLInputElement | null>(null);
  const del = useMutation({
    mutationFn: (planId: number) => api.deleteProjectPlan({ companyId: cid, actorId, planId }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["project-plans", cid, projectId] }); setConfirmDeleteId(null); setMsg(tr("Plan deleted.", "Planta excluída.", "Plano eliminado.")); },
    onError: () => setMsg(tr("Could not delete this plan.", "Não foi possível excluir esta planta.", "No se pudo eliminar este plano.")),
  });
  const onPickFiles = async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    setBusy(true);
    setMsg("");
    for (const f of Array.from(files)) {
      const lower = f.name.toLowerCase();
      const okType = f.type === "application/pdf" || f.type === "image/jpeg" || f.type === "image/png" || lower.endsWith(".pdf") || lower.endsWith(".jpg") || lower.endsWith(".jpeg") || lower.endsWith(".png");
      if (!okType) { setMsg(tr(`“${f.name}” is not a PDF, JPG, or PNG — skipped.`, `“${f.name}” não é PDF, JPG ou PNG — ignorado.`, `“${f.name}” no es PDF, JPG o PNG: se omitió.`)); continue; }
      if (f.size > MAX_PLAN_BYTES) { setMsg(tr(`“${f.name}” is ${fmtBytes(f.size)} — plans are limited to ${fmtBytes(MAX_PLAN_BYTES)} each. Please compress it or split it and try again.`, `“${f.name}” tem ${fmtBytes(f.size)} — plantas têm limite de ${fmtBytes(MAX_PLAN_BYTES)} cada. Comprima ou divida o arquivo e tente novamente.`, `“${f.name}” pesa ${fmtBytes(f.size)}: los planos tienen un límite de ${fmtBytes(MAX_PLAN_BYTES)} cada uno. Comprímelo o divídelo e inténtalo de nuevo.`)); continue; }
      const processed = await readPlanFile(f);
      if (!processed || !processed.fileData) { setMsg(tr(`Could not read “${f.name}”. Please try a different file.`, `Não foi possível ler “${f.name}”. Tente outro arquivo.`, `No se pudo leer “${f.name}”. Prueba con otro archivo.`)); continue; }
      try {
        await api.uploadProjectPlan({ companyId: cid, actorId, projectId, name: f.name, mimeType: processed.mimeType, fileData: processed.fileData, thumbnailData: processed.thumbnailData, fileSize: f.size });
      } catch {
        setMsg(tr(`Could not upload “${f.name}”. It may be too large after processing — try a smaller file.`, `Não foi possível enviar “${f.name}”. Ele pode ter ficado grande demais após o processamento — tente um arquivo menor.`, `No se pudo subir “${f.name}”. Puede haber quedado demasiado grande tras procesarlo: prueba con un archivo más pequeño.`));
      }
    }
    setBusy(false);
    qc.invalidateQueries({ queryKey: ["project-plans", cid, projectId] });
  };
  const plans = plansQ.data?.plans ?? [];
  return (
    <div>
      {canManage && (
        <div className="mt-3">
          <button type="button" aria-label={tr("Upload a plan or blueprint", "Enviar uma planta", "Subir un plano")} disabled={busy} onClick={() => fileRef.current?.click()} className={`${btnPrimary} w-full`}>
            {busy ? tr("Uploading…", "Enviando…", "Subiendo…") : tr("📐 Upload plan / blueprint", "📐 Enviar planta", "📐 Subir plano")}
          </button>
          <input ref={fileRef} type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" multiple className="hidden" aria-label={tr("Plan files to upload", "Arquivos de planta para enviar", "Archivos de plano para subir")} onChange={(e) => { void onPickFiles(e.target.files); e.target.value = ""; }} />
          <p className="mt-1 text-[11px] text-[var(--dim)]">{tr(`PDF, JPG, or PNG — up to ${fmtBytes(MAX_PLAN_BYTES)} per file. The crew on this project can open and read them in the field.`, `PDF, JPG ou PNG — até ${fmtBytes(MAX_PLAN_BYTES)} por arquivo. A equipe desta obra pode abri-los e lê-los no campo.`, `PDF, JPG o PNG: hasta ${fmtBytes(MAX_PLAN_BYTES)} por archivo. El equipo de esta obra puede abrirlos y leerlos en el campo.`)}</p>
        </div>
      )}
      {msg && <p className="mt-2 text-xs font-semibold text-red-600" role="alert">{msg}</p>}
      {plansQ.isPending && <p className="field-note mt-3 text-sm text-[var(--dim)]">{tr("Loading plans…", "Carregando plantas…", "Cargando planos…")}</p>}
      {!plansQ.isPending && plans.length === 0 && (
        <p className="field-note mt-3 rounded-xl border border-dashed border-[var(--border)] px-3 py-3 text-center text-sm text-[var(--dim)]">{canManage ? tr("No plans uploaded yet. Upload the blueprint so the crew can check it on site.", "Nenhuma planta enviada ainda. Envie a planta para a equipe consultar na obra.", "Todavía no se subió ningún plano. Sube el plano para que el equipo lo consulte en la obra.") : tr("No plans uploaded for this project yet.", "Nenhuma planta enviada para esta obra ainda.", "Todavía no se subió ningún plano para esta obra.")}</p>
      )}
      <div className="mt-3 space-y-2">
        {plans.map((pl) => (
          <div key={pl.id} className="flex items-center gap-3 rounded-xl bg-[var(--surface2)] p-2.5 text-[var(--text)]">
            <button type="button" onClick={() => setViewPlan(pl)} aria-label={tr(`View plan ${pl.name}`, `Ver a planta ${pl.name}`, `Ver el plano ${pl.name}`)} className="h-14 w-14 shrink-0 overflow-hidden rounded-lg bg-[var(--surface)] active:opacity-70">
              {pl.isImage && pl.thumbnailData ? (
                <img src={pl.thumbnailData} alt={tr(`Preview of plan ${pl.name}`, `Pré-visualização da planta ${pl.name}`, `Vista previa del plano ${pl.name}`)} className="h-full w-full object-cover" />
              ) : (
                <span className="flex h-full w-full flex-col items-center justify-center text-[var(--dim)]"><span className="text-xl" aria-hidden="true">📄</span><span className="text-[9px] font-black uppercase">PDF</span></span>
              )}
            </button>
            <button type="button" onClick={() => setViewPlan(pl)} aria-label={tr(`Open plan ${pl.name}`, `Abrir a planta ${pl.name}`, `Abrir el plano ${pl.name}`)} className="min-w-0 flex-1 text-left active:opacity-70">
              <span className="block truncate text-sm font-semibold">{pl.name}</span>
              <span className="block text-[11px] text-[var(--dim)]">{fmtDate(pl.createdAt)} • {fmtBytes(pl.fileSize)}{pl.uploadedByName ? ` • ${pl.uploadedByName}` : ""}</span>
              <span className="text-[11px] font-bold text-[#f97316]">{tr("Tap to view full-screen ›", "Toque para ver em tela cheia ›", "Toca para ver en pantalla completa ›")}</span>
            </button>
            {canManage && (confirmDeleteId === pl.id ? (
              <span className="flex shrink-0 items-center gap-1.5">
                <span className="text-[11px] font-bold text-red-600" role="alert">{tr("Delete?", "Excluir?", "¿Eliminar?")}</span>
                <button type="button" aria-label={tr(`Confirm delete plan ${pl.name}`, `Confirmar a exclusão da planta ${pl.name}`, `Confirmar la eliminación del plano ${pl.name}`)} disabled={del.isPending} onClick={() => del.mutate(pl.id)} className="rounded-lg bg-red-600 px-2.5 py-1.5 text-[11px] font-bold text-white active:opacity-80 disabled:opacity-40">{tr("Delete", "Excluir", "Eliminar")}</button>
                <button type="button" aria-label={tr("Cancel delete plan", "Cancelar a exclusão da planta", "Cancelar la eliminación del plano")} onClick={() => setConfirmDeleteId(null)} className="px-1 py-1.5 text-[11px] font-bold text-[var(--dim)]">{tr("Cancel", "Cancelar", "Cancelar")}</button>
              </span>
            ) : (
              <button type="button" aria-label={tr(`Delete plan ${pl.name}`, `Excluir a planta ${pl.name}`, `Eliminar el plano ${pl.name}`)} onClick={() => setConfirmDeleteId(pl.id)} className="shrink-0 px-1 py-1.5 text-[11px] font-bold text-red-600">{tr("Delete", "Excluir", "Eliminar")}</button>
            ))}
          </div>
        ))}
      </div>
      {viewPlan && <PlanViewerModal cid={cid} actorId={actorId} plan={viewPlan} onClose={() => setViewPlan(null)} />}
    </div>
  );
}

/* Required services & measurements for one project. Managers add/edit/
   remove lines from the catalog; the crew sees the same list read-only. */
function ProjectServicesSection({ cid, projectId, actorId, canManage }: { cid: string; projectId: number; actorId: number; canManage: boolean }) {
  const qc = useQueryClient();
  const linesQ = useQuery({ queryKey: ["project-services", cid, projectId], queryFn: () => api.listProjectServices({ companyId: cid, projectId, actorId }) });
  const catalogQ = useQuery({ queryKey: ["services", cid], queryFn: () => api.listServices({ companyId: cid }), enabled: canManage });
  const invalidate = () => qc.invalidateQueries({ queryKey: ["project-services", cid, projectId] });
  const [pickService, setPickService] = useState("");
  const [pickQty, setPickQty] = useState("");
  const [msg, setMsg] = useState("");
  const [editLineId, setEditLineId] = useState<number | null>(null);
  const [editQty, setEditQty] = useState("");
  const [confirmDeleteId, setConfirmDeleteId] = useState<number | null>(null);
  const addLine = useMutation({
    mutationFn: () => api.addProjectService({ companyId: cid, actorId, projectId, serviceId: Number(pickService), quantity: parseFloat(pickQty.replace(",", ".")) || 0 }),
    onSuccess: () => { invalidate(); setPickQty(""); setMsg(tr("Measurement added. The crew can see it now. ✅", "Medição adicionada. A equipe já pode vê-la. ✅", "Medición agregada. El equipo ya puede verla. ✅")); },
    onError: () => setMsg(tr("Could not add this measurement. Pick a service and a quantity above zero.", "Não foi possível adicionar esta medição. Escolha um serviço e uma quantidade acima de zero.", "No se pudo agregar esta medición. Elige un servicio y una cantidad mayor que cero.")),
  });
  const saveLine = useMutation({
    mutationFn: (lineId: number) => api.updateProjectService({ companyId: cid, actorId, lineId, quantity: parseFloat(editQty.replace(",", ".")) || 0 }),
    onSuccess: () => { invalidate(); setEditLineId(null); setMsg(tr("Measurement saved. ✅", "Medição salva. ✅", "Medición guardada. ✅")); },
    onError: () => setMsg(tr("Could not save this measurement. Quantity must be above zero.", "Não foi possível salvar esta medição. A quantidade precisa ser acima de zero.", "No se pudo guardar esta medición. La cantidad debe ser mayor que cero.")),
  });
  const delLine = useMutation({
    mutationFn: (lineId: number) => api.deleteProjectService({ companyId: cid, actorId, lineId }),
    onSuccess: () => { invalidate(); setConfirmDeleteId(null); },
    onError: () => setMsg(tr("Could not remove this measurement.", "Não foi possível remover esta medição.", "No se pudo quitar esta medición.")),
  });
  const lines = linesQ.data?.lines ?? [];
  const catalog = catalogQ.data?.services ?? [];
  const ratedTotal = lines.reduce((s, l) => s + l.lineTotal, 0);
  return (
    <div>
      {canManage && (
        <form className="mt-3 space-y-2 rounded-xl bg-[var(--surface2)] p-3" onSubmit={(e) => { e.preventDefault(); addLine.mutate(); }}>
          <div className="grid grid-cols-[1fr_7rem] gap-2">
            <Field label={tr("Service", "Serviço", "Servicio")}>
              <select aria-label={tr("Service for the new measurement", "Serviço da nova medição", "Servicio de la nueva medición")} className={inputCls} value={pickService} onChange={(e) => setPickService(e.target.value)} required>
                <option value="">{tr("Pick a service…", "Escolha um serviço…", "Elige un servicio…")}</option>
                {catalog.map((s) => <option key={s.id} value={s.id}>{s.name} ({s.unit}){s.defaultRate > 0 ? ` • ${fmtUSD(s.defaultRate)}/${s.unit}` : ""}</option>)}
              </select>
            </Field>
            <Field label={tr("Quantity", "Quantidade", "Cantidad")}>
              <input aria-label={tr("Quantity needed", "Quantidade necessária", "Cantidad necesaria")} className={inputCls} inputMode="decimal" value={pickQty} onChange={(e) => setPickQty(e.target.value)} placeholder="400" required />
            </Field>
          </div>
          {catalog.length === 0 && <p className="text-[11px] text-[var(--dim)]">{tr("The Services catalog is empty — add services in the Services tab first.", "O catálogo de serviços está vazio — adicione serviços primeiro na aba Serviços.", "El catálogo de servicios está vacío: primero agrega servicios en la pestaña Servicios.")}</p>}
          <button className={`${btnNavy} w-full`} disabled={addLine.isPending || !pickService || !(parseFloat(pickQty.replace(",", ".")) > 0)}>{addLine.isPending ? tr("Adding…", "Adicionando…", "Agregando…") : tr("+ Add measurement", "+ Adicionar medição", "+ Agregar medición")}</button>
          <p className="text-[11px] text-[var(--dim)]">{tr("Example: Hardwood floor — 400 sq ft. Whatever is listed here is exactly what the crew sees on this project.", "Exemplo: Piso de madeira — 400 sq ft. O que estiver listado aqui é exatamente o que a equipe vê nesta obra.", "Ejemplo: Piso de madera: 400 sq ft. Lo que aparezca aquí es exactamente lo que el equipo ve en esta obra.")}</p>
        </form>
      )}
      {msg && <p className="mt-2 text-xs font-semibold" role="status">{msg}</p>}
      {linesQ.isPending && <p className="field-note mt-3 text-sm text-[var(--dim)]">{tr("Loading measurements…", "Carregando medições…", "Cargando mediciones…")}</p>}
      {!linesQ.isPending && lines.length === 0 && (
        <p className="field-note mt-3 rounded-xl border border-dashed border-[var(--border)] px-3 py-3 text-center text-sm text-[var(--dim)]">{canManage ? tr("No services or measurements on this project yet. Add the first one above — e.g. Hardwood floor, 400 sq ft.", "Nenhum serviço ou medição nesta obra ainda. Adicione o primeiro acima — ex.: Piso de madeira, 400 sq ft.", "Todavía no hay servicios ni mediciones en esta obra. Agrega el primero arriba, p. ej., Piso de madera, 400 sq ft.") : tr("No required services have been added to this project yet.", "Nenhum serviço necessário foi adicionado a esta obra ainda.", "Todavía no se agregaron servicios necesarios a esta obra.")}</p>
      )}
      <div className="mt-3 space-y-2">
        {lines.map((l) => (
          <div key={l.id} className="rounded-xl bg-[var(--surface2)] px-3 py-2.5 text-[var(--text)]">
            <div className="flex items-center justify-between gap-2">
              <p className="min-w-0 font-semibold leading-snug">🧱 {l.serviceName}</p>
              <p className="shrink-0 text-sm font-black">{fmtQty(l.quantity)} {l.unit}</p>
            </div>
            {l.rate > 0 && <p className="mt-0.5 text-[11px] text-[var(--dim)]">{fmtUSD(l.rate)}/{l.unit} • {tr("Est.", "Est.", "Est.")} {fmtUSD(l.lineTotal)}</p>}
            {canManage && editLineId === l.id ? (
              <form className="mt-2 flex gap-2" onSubmit={(e) => { e.preventDefault(); saveLine.mutate(l.id); }}>
                <label className="sr-only" htmlFor={`edit-qty-${l.id}`}>{tr(`Quantity for ${l.serviceName}`, `Quantidade de ${l.serviceName}`, `Cantidad de ${l.serviceName}`)}</label>
                <input id={`edit-qty-${l.id}`} aria-label={tr(`Quantity for ${l.serviceName}`, `Quantidade de ${l.serviceName}`, `Cantidad de ${l.serviceName}`)} className={inputCls} inputMode="decimal" value={editQty} onChange={(e) => setEditQty(e.target.value)} />
                <span className="flex items-center text-sm font-semibold text-[var(--dim)]">{l.unit}</span>
                <button type="button" className={btnGhost} onClick={() => setEditLineId(null)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
                <button className={btnNavy} disabled={saveLine.isPending || !(parseFloat(editQty.replace(",", ".")) > 0)}>{saveLine.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save", "Salvar", "Guardar")}</button>
              </form>
            ) : canManage ? (
              <div className="mt-1 flex gap-3">
                <button type="button" aria-label={tr(`Edit quantity for ${l.serviceName}`, `Editar a quantidade de ${l.serviceName}`, `Editar la cantidad de ${l.serviceName}`)} className="text-xs font-bold text-[#f97316]" onClick={() => { setEditLineId(l.id); setEditQty(String(l.quantity)); setConfirmDeleteId(null); }}>{tr("Edit quantity", "Editar quantidade", "Editar cantidad")}</button>
                {confirmDeleteId === l.id ? (
                  <>
                    <span className="text-xs font-bold text-red-600" role="alert">{tr("Remove this line?", "Remover esta linha?", "¿Quitar esta línea?")}</span>
                    <button type="button" aria-label={tr(`Confirm remove ${l.serviceName} measurement`, `Confirmar a remoção da medição de ${l.serviceName}`, `Confirmar la eliminación de la medición de ${l.serviceName}`)} disabled={delLine.isPending} onClick={() => delLine.mutate(l.id)} className="text-xs font-bold text-red-600">{tr("Remove", "Remover", "Quitar")}</button>
                    <button type="button" aria-label={tr("Cancel remove measurement", "Cancelar a remoção da medição", "Cancelar la eliminación de la medición")} className="text-xs font-bold text-[var(--dim)]" onClick={() => setConfirmDeleteId(null)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
                  </>
                ) : (
                  <button type="button" aria-label={tr(`Remove ${l.serviceName} measurement`, `Remover a medição de ${l.serviceName}`, `Quitar la medición de ${l.serviceName}`)} className="text-xs font-bold text-red-600" onClick={() => setConfirmDeleteId(l.id)}>{tr("Remove", "Remover", "Quitar")}</button>
                )}
              </div>
            ) : null}
          </div>
        ))}
      </div>
      {lines.length > 0 && ratedTotal > 0 && (
        <p className="mt-2 text-right text-xs font-semibold text-[var(--dim)]">{tr("Estimated from catalog rates:", "Estimado pelas tarifas do catálogo:", "Estimado con las tarifas del catálogo:")} <span className="text-sm font-black text-[var(--text)]">{fmtUSD(ratedTotal)}</span></p>
      )}
    </div>
  );
}

/* Services catalog tab (admin/manager): reusable services with a unit and
   an optional default rate. Starter services arrive seeded and stay fully
   editable. */
function ServicesView({ cid, session }: { cid: string; session: Session }) {
  const qc = useQueryClient();
  const q = useQuery({ queryKey: ["services", cid], queryFn: () => api.listServices({ companyId: cid }) });
  const invalidate = () => { qc.invalidateQueries({ queryKey: ["services", cid] }); };
  const [name, setName] = useState("");
  const [unitChoice, setUnitChoice] = useState<string>("sq ft");
  const [customUnit, setCustomUnit] = useState("");
  const [rate, setRate] = useState("");
  const [editId, setEditId] = useState<number | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<number | null>(null);
  const [msg, setMsg] = useState("");
  const [formError, setFormError] = useState("");
  /* Duplicate guard for catalog creates: exact normalized name blocks,
     near-duplicate (typo-level) asks before creating a second entry. */
  const [dup, setDup] = useState<{ kind: "exact" | "near"; match: ServiceLite } | null>(null);
  const [forceCreate, setForceCreate] = useState(false);
  const effectiveUnit = unitChoice === "__custom" ? customUnit.trim() : unitChoice;
  const resetForm = () => { setName(""); setUnitChoice("sq ft"); setCustomUnit(""); setRate(""); setEditId(null); setFormError(""); setDup(null); setForceCreate(false); };
  const save = useMutation({
    mutationFn: async (): Promise<{ id: number; created: boolean }> => {
      if (editId !== null) {
        await api.updateService({ companyId: cid, actorId: session.userId, serviceId: editId, name, unit: effectiveUnit, defaultRate: parseMoney(rate) });
        return { id: editId, created: false };
      }
      const r = await api.createService({ companyId: cid, actorId: session.userId, name, unit: effectiveUnit, defaultRate: parseMoney(rate) });
      return { id: r.id, created: true };
    },
    onSuccess: (r) => { invalidate(); resetForm(); setMsg(r.created ? tr("Service added to the catalog. ✅", "Serviço adicionado ao catálogo. ✅", "Servicio agregado al catálogo. ✅") : tr("Service updated. ✅", "Serviço atualizado. ✅", "Servicio actualizado. ✅")); },
    onError: (e) => setFormError(e instanceof Error && e.message.includes("already exists")
      ? tr("This service already exists.", "Este serviço já existe.", "Este servicio ya existe.")
      : tr("Could not save this service. Only an admin or manager can edit the catalog.", "Não foi possível salvar este serviço. Somente um administrador ou gerente pode editar o catálogo.", "No se pudo guardar este servicio. Solo un administrador o gerente puede editar el catálogo.")),
  });
  const del = useMutation({
    mutationFn: (serviceId: number) => api.deleteService({ companyId: cid, actorId: session.userId, serviceId }),
    onSuccess: () => { invalidate(); setConfirmDeleteId(null); setMsg(tr("Service removed from the catalog. Measurements already on projects keep their saved name and unit.", "Serviço removido do catálogo. Medições já lançadas nas obras mantêm o nome e a unidade salvos.", "Servicio eliminado del catálogo. Las mediciones ya cargadas en las obras conservan el nombre y la unidad guardados.")); },
    onError: () => setMsg(tr("Could not remove this service.", "Não foi possível remover este serviço.", "No se pudo eliminar este servicio.")),
  });
  const openEdit = (s: ServiceLite) => {
    setEditId(s.id); setConfirmDeleteId(null); setFormError(""); setMsg(""); setDup(null); setForceCreate(false);
    setName(s.name);
    if ((SERVICE_UNIT_PRESETS as readonly string[]).includes(s.unit)) { setUnitChoice(s.unit); setCustomUnit(""); }
    else { setUnitChoice("__custom"); setCustomUnit(s.unit); }
    setRate(s.defaultRate > 0 ? moneyInput(s.defaultRate) : "");
  };
  const services = q.data?.services ?? [];
  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-xl font-bold">{tr("Services catalog", "Catálogo de serviços", "Catálogo de servicios")}</h2>
        <p className="mt-1 text-sm text-[var(--dim)]">{tr("The kinds of work you measure and sell — e.g. Hardwood floor per sq ft. Add them here once, then put the required quantity on each project (like 400 sq ft) and the crew sees it in the field.", "Os tipos de trabalho que você mede e vende — ex.: Piso de madeira por sq ft. Cadastre aqui uma vez, depois lance a quantidade necessária em cada obra (como 400 sq ft) e a equipe vê no campo.", "Los tipos de trabajo que mides y vendes, p. ej., Piso de madera por sq ft. Cárgalos aquí una vez, luego pon la cantidad necesaria en cada obra (como 400 sq ft) y el equipo lo ve en el campo.")}</p>
      </div>

      <form className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" onSubmit={(e) => {
        e.preventDefault();
        if (editId === null && !forceCreate) {
          const clash = serviceNameClash(name, q.data?.services ?? []);
          if (clash) {
            setDup(clash);
            setFormError(clash.kind === "exact" ? tr("This service already exists.", "Este serviço já existe.", "Este servicio ya existe.") : "");
            return;
          }
        }
        setDup(null);
        save.mutate();
      }}>
        <p className="font-bold">{editId !== null ? tr("Edit service", "Editar serviço", "Editar servicio") : tr("New service", "Novo serviço", "Nuevo servicio")}</p>
        <Field label={tr("Service name", "Nome do serviço", "Nombre del servicio")}>
          <input aria-label={tr("Service name", "Nome do serviço", "Nombre del servicio")} className={inputCls} value={name} onChange={(e) => { setName(e.target.value); setDup(null); setForceCreate(false); }} placeholder={tr("E.g.: Hardwood floor", "Ex.: Piso de madeira", "Ej.: Piso de madera")} required />
        </Field>
        {dup?.kind === "exact" && (
          <div className="rounded-lg bg-red-50 px-3 py-2 dark:bg-red-950/40" role="alert">
            <p className="text-xs font-bold text-red-700 dark:text-red-300">{tr("This service already exists.", "Este serviço já existe.", "Este servicio ya existe.")}</p>
            <button type="button" className="mt-1 text-xs font-bold text-[#f97316]" aria-label={tr(`Edit the existing service ${dup.match.name}`, `Editar o serviço existente ${dup.match.name}`, `Editar el servicio existente ${dup.match.name}`)} onClick={() => openEdit(dup.match)}>{tr(`Edit “${dup.match.name}” instead`, `Editar “${dup.match.name}” em vez disso`, `Editar “${dup.match.name}” en su lugar`)}</button>
          </div>
        )}
        {dup?.kind === "near" && (
          <div className="rounded-lg bg-amber-50 px-3 py-2 dark:bg-amber-950/40" role="alert">
            <p className="text-xs font-bold text-amber-800 dark:text-amber-200">{tr(`Did you mean “${dup.match.name}”?`, `Você quis dizer “${dup.match.name}”?`, `¿Quisiste decir “${dup.match.name}”?`)}</p>
            <div className="mt-1.5 flex flex-wrap gap-2">
              <button type="button" className={btnNavy} aria-label={tr(`Use the existing service ${dup.match.name}`, `Usar o serviço existente ${dup.match.name}`, `Usar el servicio existente ${dup.match.name}`)} onClick={() => openEdit(dup.match)}>{tr("Use existing", "Usar o existente", "Usar el existente")}</button>
              <button type="button" className={btnGhost} aria-label={tr("Create the new service anyway", "Criar o novo serviço mesmo assim", "Crear el nuevo servicio de todos modos")} disabled={save.isPending} onClick={() => { setForceCreate(true); setDup(null); save.mutate(); }}>{tr("Create new anyway", "Criar novo mesmo assim", "Crear nuevo de todos modos")}</button>
            </div>
          </div>
        )}
        <div className="grid grid-cols-2 gap-3">
          <Field label={tr("Unit", "Unidade", "Unidad")}>
            <select aria-label={tr("Service unit", "Unidade do serviço", "Unidad del servicio")} className={inputCls} value={unitChoice} onChange={(e) => setUnitChoice(e.target.value)}>
              {SERVICE_UNIT_PRESETS.map((u) => <option key={u} value={u}>{unitOptionLabel(u)}</option>)}
              <option value="__custom">{tr("Custom unit…", "Unidade personalizada…", "Unidad personalizada…")}</option>
            </select>
          </Field>
          <Field label={tr("Default rate (USD per unit, optional)", "Tarifa padrão (USD por unidade, opcional)", "Tarifa predeterminada (USD por unidad, opcional)")}>
            <input aria-label={tr("Default rate in US dollars per unit", "Tarifa padrão em dólares por unidade", "Tarifa predeterminada en dólares por unidad")} className={inputCls} inputMode="decimal" value={rate} onChange={(e) => setRate(e.target.value)} placeholder="0.00" />
          </Field>
        </div>
        {unitChoice === "__custom" && (
          <Field label={tr("Custom unit label", "Rótulo da unidade personalizada", "Etiqueta de la unidad personalizada")}>
            <input aria-label={tr("Custom unit label", "Rótulo da unidade personalizada", "Etiqueta de la unidad personalizada")} className={inputCls} value={customUnit} onChange={(e) => setCustomUnit(e.target.value)} placeholder={tr("E.g.: per room, lump sum, sheets", "Ex.: por cômodo, empreitada, chapas", "Ej.: por ambiente, tanto alzado, placas")} required />
          </Field>
        )}
        <p className="text-[11px] text-[var(--dim)]">{tr("The default rate is optional. When set, a project measurement (quantity × rate) shows an estimated amount. Leave it at $0 to track quantities only.", "A tarifa padrão é opcional. Quando definida, a medição da obra (quantidade × tarifa) mostra um valor estimado. Deixe em $0 para acompanhar só as quantidades.", "La tarifa predeterminada es opcional. Cuando se define, la medición de la obra (cantidad × tarifa) muestra un importe estimado. Déjala en $0 para controlar solo las cantidades.")}</p>
        {formError && <p className="text-sm font-semibold text-red-600" role="alert">{formError}</p>}
        <div className="flex gap-2">
          {editId !== null && <button type="button" className={btnGhost} onClick={resetForm}>{tr("Cancel", "Cancelar", "Cancelar")}</button>}
          <button className={`${btnNavy} flex-1`} disabled={save.isPending || !name.trim() || !effectiveUnit}>{save.isPending ? tr("Saving…", "Salvando…", "Guardando…") : editId !== null ? tr("Save changes", "Salvar alterações", "Guardar cambios") : tr("Add service", "Adicionar serviço", "Agregar servicio")}</button>
        </div>
      </form>
      {msg && <p className="text-sm font-semibold" role="status">{msg}</p>}

      {q.isPending && <p className="py-6 text-center text-sm text-[var(--dim)]">{tr("Loading services…", "Carregando serviços…", "Cargando servicios…")}</p>}
      <div className="space-y-2">
        {services.map((s) => (
          <div key={s.id} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-3.5">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <p className="font-bold leading-snug">🧱 {s.name}</p>
                <p className="mt-0.5 text-xs text-[var(--dim)]">{unitOptionLabel(s.unit)}{s.defaultRate > 0 ? ` • ${fmtUSD(s.defaultRate)} / ${s.unit}` : ` • ${tr("No default rate", "Sem tarifa padrão", "Sin tarifa predeterminada")}`}</p>
              </div>
              <span className="flex shrink-0 items-center gap-3">
                <button type="button" aria-label={tr(`Edit service ${s.name}`, `Editar o serviço ${s.name}`, `Editar el servicio ${s.name}`)} onClick={() => openEdit(s)} className="text-xs font-bold text-[#f97316]">{tr("Edit", "Editar", "Editar")}</button>
                {confirmDeleteId === s.id ? (
                  <>
                    <span className="text-xs font-bold text-red-600" role="alert">{tr("Delete?", "Excluir?", "¿Eliminar?")}</span>
                    <button type="button" aria-label={tr(`Confirm delete service ${s.name}`, `Confirmar a exclusão do serviço ${s.name}`, `Confirmar la eliminación del servicio ${s.name}`)} disabled={del.isPending} onClick={() => del.mutate(s.id)} className="text-xs font-bold text-red-600">{tr("Delete", "Excluir", "Eliminar")}</button>
                    <button type="button" aria-label={tr("Cancel delete service", "Cancelar a exclusão do serviço", "Cancelar la eliminación del servicio")} className="text-xs font-bold text-[var(--dim)]" onClick={() => setConfirmDeleteId(null)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
                  </>
                ) : (
                  <button type="button" aria-label={tr(`Delete service ${s.name}`, `Excluir o serviço ${s.name}`, `Eliminar el servicio ${s.name}`)} className="text-xs font-bold text-red-600" onClick={() => setConfirmDeleteId(s.id)}>{tr("Delete", "Excluir", "Eliminar")}</button>
                )}
              </span>
            </div>
          </div>
        ))}
        {!q.isPending && services.length === 0 && (
          <p className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] px-4 py-6 text-center text-sm text-[var(--dim)]">{tr("No services yet. Add the first one above — e.g. Hardwood floor, sq ft.", "Nenhum serviço ainda. Adicione o primeiro acima — ex.: Piso de madeira, sq ft.", "Todavía no hay servicios. Agrega el primero arriba, p. ej., Piso de madera, sq ft.")}</p>
        )}
      </div>
      <p className="text-[11px] text-[var(--dim)]">{tr("Starter services (Hardwood floor, Tile, Painting, Drywall, Roofing) come pre-loaded with no rates — edit them freely or delete the ones you don't use.", "Os serviços iniciais (Piso de madeira, Azulejo, Pintura, Drywall, Telhado) vêm pré-carregados sem tarifas — edite à vontade ou exclua os que não usar.", "Los servicios iniciales (Piso de madera, Azulejo, Pintura, Drywall, Techo) vienen precargados sin tarifas: edítalos libremente o elimina los que no uses.")}</p>
    </div>
  );
}

function PhotoLightbox({ photo, taskTitle, onClose }: { photo: TaskPhotoLite; taskTitle: string; onClose: () => void }) {
  const src = safeImgSrc(photo.photoUrl);
  const stage = photoStageMeta(photo.stage);
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/85 p-4" role="dialog" aria-modal="true" aria-label={tr(`Photo for the task ${taskTitle}`, `Foto da tarefa ${taskTitle}`, `Foto de la tarea ${taskTitle}`)} onClick={onClose}>
      <div className="max-h-full w-full max-w-2xl" onClick={(e) => e.stopPropagation()}>
        {src ? (
          <img src={src} alt={tr(`Task photo tagged ${stage.label}`, `Foto da tarefa marcada como ${stage.label}`, `Foto de la tarea marcada como ${stage.label}`)} className="max-h-[72vh] w-full rounded-xl bg-black object-contain" />
        ) : (
          <p className="rounded-xl bg-white/10 px-4 py-8 text-center text-white">{tr("This photo can't be displayed.", "Esta foto não pode ser exibida.", "Esta foto no se puede mostrar.")}</p>
        )}
        <div className="mt-3 flex items-center justify-between gap-2">
          <p className="flex min-w-0 flex-wrap items-center gap-2 text-sm text-white">
            <Badge text={stage.label} tone={stage.tone} />
            <span className="truncate">{fmtDate(photo.createdAt)} • {fmtTime(photo.createdAt)}{photo.employeeName ? ` — ${photo.employeeName}` : ""}</span>
          </p>
          <button type="button" aria-label={tr("Close photo", "Fechar foto", "Cerrar foto")} onClick={onClose} className="shrink-0 rounded-lg bg-white px-3 py-1.5 text-sm font-bold text-[#12222f] active:opacity-80">{tr("✕ Close", "✕ Fechar", "✕ Cerrar")}</button>
        </div>
      </div>
    </div>
  );
}

/* Multi-select assignee picker (checkboxes): pick any combination of the
   job's crew. An empty selection means "Whole crew" — everyone on the job
   can see and work the task, and it follows the crew automatically. Used
   by the task create/edit forms; the Dispatch sheet has its own variant
   with search + explicit Save. */
function AssigneeMultiPicker({ options, selected, onChange, idPrefix }: {
  options: EmpLite[]; selected: Set<number>; onChange: (next: Set<number>) => void; idPrefix: string;
}) {
  const allSelected = options.length > 0 && options.every((e) => selected.has(e.id));
  const toggle = (id: number) => {
    const next = new Set(selected);
    if (next.has(id)) next.delete(id); else next.add(id);
    onChange(next);
  };
  return (
    <div>
      <button
        type="button"
        aria-label={tr("Assign this task to the whole crew", "Atribuir esta tarefa à equipe toda", "Asignar esta tarea a todo el equipo")}
        aria-pressed={selected.size === 0}
        onClick={() => onChange(new Set())}
        className={`flex w-full items-center justify-between gap-2 rounded-xl border p-3 text-left active:opacity-70 ${selected.size === 0 ? "border-[#f97316] bg-orange-50 dark:bg-orange-950/30" : "border-[var(--border)] bg-[var(--surface2)]"}`}
      >
        <span>
          <span className="block font-bold">👥 {tr("Whole crew", "Equipe toda", "Todo el equipo")}</span>
          <span className="block text-xs text-[var(--dim)]">{options.length > 0
            ? tr(`Everyone on this job (${options.map((e) => e.name).join(", ")}) can see and work it. Follows the crew if people change.`, `Todos neste trabalho (${options.map((e) => e.name).join(", ")}) podem vê-la e executá-la. Segue a equipe se as pessoas mudarem.`, `Todos en este trabajo (${options.map((e) => e.name).join(", ")}) pueden verla y hacerla. Sigue al equipo si las personas cambian.`)
            : tr("No crew on this job yet — the task stays open to the whole crew.", "Nenhuma equipe neste trabalho ainda — a tarefa fica aberta para a equipe toda.", "Todavía no hay equipo en este trabajo: la tarea queda abierta a todo el equipo.")}</span>
        </span>
        {selected.size === 0 && <span className="shrink-0 text-lg" aria-hidden="true">✓</span>}
      </button>
      {options.length > 0 && (
        <>
          <div className="mt-2 flex items-center justify-between gap-2">
            <p className="text-[11px] font-bold text-[var(--dim)]">{tr("Or pick who does it — you can choose several:", "Ou escolha quem faz — pode escolher vários:", "O elige quién la hace: puedes elegir a varios:")}</p>
            <button type="button" aria-label={allSelected ? tr("Clear all assignees", "Limpar todos os responsáveis", "Borrar todos los responsables") : tr("Select the whole crew as assignees", "Selecionar a equipe toda como responsáveis", "Seleccionar a todo el equipo como responsables")} onClick={() => onChange(allSelected ? new Set() : new Set(options.map((e) => e.id)))} className="shrink-0 text-[11px] font-bold text-[#f97316]">
              {allSelected ? tr("Clear all", "Limpar tudo", "Borrar todo") : tr("Select all", "Selecionar todos", "Seleccionar todo")}
            </button>
          </div>
          <div className="mt-1.5 space-y-1.5" role="group" aria-label={tr("Task assignees", "Responsáveis pela tarefa", "Responsables de la tarea")}>
            {options.map((e) => {
              const checked = selected.has(e.id);
              return (
                <button
                  key={e.id}
                  type="button"
                  role="checkbox"
                  id={`${idPrefix}-assignee-${e.id}`}
                  aria-checked={checked}
                  aria-label={checked ? tr(`Remove ${e.name} from this task`, `Remover ${e.name} desta tarefa`, `Quitar a ${e.name} de esta tarea`) : tr(`Add ${e.name} to this task`, `Adicionar ${e.name} a esta tarefa`, `Agregar a ${e.name} a esta tarea`)}
                  onClick={() => toggle(e.id)}
                  className={`flex w-full items-center justify-between gap-2 rounded-xl border p-2.5 text-left active:opacity-70 ${checked ? "border-[#f97316] bg-orange-50 dark:bg-orange-950/30" : "border-[var(--border)] bg-[var(--surface2)]"}`}
                >
                  <span><span className="block text-sm font-bold">👤 {e.name}</span>{e.trade ? <span className="block text-[11px] text-[var(--dim)]">{e.trade}</span> : null}</span>
                  <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md border text-sm font-black ${checked ? "border-[#f97316] bg-[#f97316] text-white" : "border-[var(--border)] text-transparent"}`} aria-hidden="true">✓</span>
                </button>
              );
            })}
          </div>
          <p className="mt-1.5 text-[11px] font-semibold text-[var(--dim)]" role="status">
            {selected.size === 0
              ? tr("Whole crew selected — everyone on this job sees this task.", "Equipe toda selecionada — todos neste trabalho veem esta tarefa.", "Todo el equipo seleccionado: todos en este trabajo ven esta tarea.")
              : tr(`${selected.size} selected: ${options.filter((e) => selected.has(e.id)).map((e) => e.name).join(", ")}`, `${selected.size} selecionado(s): ${options.filter((e) => selected.has(e.id)).map((e) => e.name).join(", ")}`, `${selected.size} seleccionado(s): ${options.filter((e) => selected.has(e.id)).map((e) => e.name).join(", ")}`)}
          </p>
        </>
      )}
    </div>
  );
}

/* One checklist item. Shared by the Job detail (JobDetailView) and the field
   tr("My tasks", "Minhas tarefas", "Mis tareas") list: Start/Done for the crew, full manage controls and
   photo attachments where the caller allows them. */
function TaskItem({ cid, task, actorId, canManage, manageControls, employees }: {
  cid: string; task: TaskLite; actorId: number; canManage: boolean; manageControls: boolean; employees: EmpLite[];
}) {
  const qc = useQueryClient();
  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["job-tasks", cid, task.jobId] });
    qc.invalidateQueries({ queryKey: ["my-tasks", cid] });
    qc.invalidateQueries({ queryKey: ["project-detail", cid, task.projectId] });
    qc.invalidateQueries({ queryKey: ["task-time", cid, task.id] });
  };
  const [editing, setEditing] = useState(false);
  const [tTitle, setTTitle] = useState(task.title);
  const [tNotes, setTNotes] = useState(task.notes);
  const [tAssignees, setTAssignees] = useState<Set<number>>(() => new Set(taskAssigneeIds(task)));
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [photoStage, setPhotoStage] = useState<"before" | "during" | "after">("during");
  const [viewPhoto, setViewPhoto] = useState<TaskPhotoLite | null>(null);
  const [photoBusy, setPhotoBusy] = useState(false);
  const [photoMsg, setPhotoMsg] = useState("");
  const [showTime, setShowTime] = useState(false);
  const [logHours, setLogHours] = useState("");
  const fileRef = useRef<HTMLInputElement | null>(null);

  const setStatus = useMutation({
    mutationFn: async (status: "todo" | "in_progress" | "done") => {
      if (isOffline()) {
        await enqueueOutbox({ kind: "taskStatus", args: { companyId: cid, actorId, taskId: task.id, status } });
        return "queued" as const;
      }
      return api.setTaskStatus({ companyId: cid, actorId, taskId: task.id, status });
    },
    onSuccess: (r) => { invalidate(); if (r === "queued") setPhotoMsg(tr("📥 You're offline — this change is queued and will send when you're back online.", "📥 Você está offline — esta alteração está na fila e será enviada quando você voltar a ficar online.", "📥 Estás sin conexión: este cambio está en cola y se enviará cuando vuelvas a conectarte.")); },
    onError: () => setPhotoMsg(tr("Could not update this task. It may not be assigned to you.", "Não foi possível atualizar esta tarefa. Ela pode não estar atribuída a você.", "No se pudo actualizar esta tarea. Es posible que no te esté asignada.")),
  });
  const saveEdit = useMutation({
    mutationFn: () => api.updateTask({ companyId: cid, actorId, taskId: task.id, title: tTitle, notes: tNotes, assigneeIds: [...tAssignees] }),
    onSuccess: () => { invalidate(); setEditing(false); },
    onError: () => setPhotoMsg(tr("Could not save this task.", "Não foi possível salvar esta tarefa.", "No se pudo guardar esta tarea.")),
  });
  const removeTask = useMutation({
    mutationFn: () => api.deleteTask({ companyId: cid, actorId, taskId: task.id }),
    onSuccess: invalidate,
    onError: () => setPhotoMsg(tr("Could not delete this task.", "Não foi possível excluir esta tarefa.", "No se pudo eliminar esta tarea.")),
  });

  const onPickPhotos = async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    setPhotoBusy(true);
    setPhotoMsg("");
    for (const f of Array.from(files)) {
      const data = await readPhotoFile(f);
      if (!data) { setPhotoMsg(tr("Could not read that photo. Try again.", "Não foi possível ler essa foto. Tente novamente.", "No se pudo leer esa foto. Inténtalo de nuevo.")); continue; }
      try {
        if (isOffline()) {
          await enqueueOutbox({ kind: "taskPhoto", args: { companyId: cid, actorId, taskId: task.id, photoData: data, stage: photoStage } });
          setPhotoMsg(tr("📥 You're offline — photo queued and will send when you're back online.", "📥 Você está offline — foto na fila, será enviada quando você voltar a ficar online.", "📥 Estás sin conexión: foto en cola, se enviará cuando vuelvas a conectarte."));
        } else {
          await api.addTaskPhoto({ companyId: cid, actorId, taskId: task.id, photoData: data, stage: photoStage });
        }
      } catch {
        setPhotoMsg(tr("Could not save a photo. It may not be assigned to you.", "Não foi possível salvar uma foto. Ela pode não estar atribuída a você.", "No se pudo guardar una foto. Es posible que no te esté asignada."));
      }
    }
    setPhotoBusy(false);
    invalidate();
  };

  /* Work timer: only runs while the worker is checked in (server-enforced). */
  const startTimer = useMutation({
    mutationFn: () => api.startTaskTimer({ companyId: cid, actorId, taskId: task.id }),
    onSuccess: invalidate,
    onError: (e) => setPhotoMsg(e instanceof Error ? e.message : tr("Could not start the timer.", "Não foi possível iniciar o cronômetro.", "No se pudo iniciar el temporizador.")),
  });
  const pauseTimer = useMutation({
    mutationFn: () => api.pauseTaskTimer({ companyId: cid, actorId, taskId: task.id }),
    onSuccess: invalidate,
    onError: () => setPhotoMsg(tr("Could not pause the timer.", "Não foi possível pausar o cronômetro.", "No se pudo pausar el temporizador.")),
  });
  const logTime = useMutation({
    mutationFn: () => api.logTaskHours({ companyId: cid, actorId, taskId: task.id, hours: parseFloat(logHours.replace(",", ".")) || 0, note: "" }),
    onSuccess: () => { invalidate(); setLogHours(""); },
    onError: () => setPhotoMsg(tr("Could not log those hours.", "Não foi possível registrar essas horas.", "No se pudieron registrar esas horas.")),
  });
  const taskHours = task.totalMinutes > 0 ? `${(task.totalMinutes / 60).toFixed(1)}h` : "";

  const statusIcon = task.status === "done" ? "✅" : task.status === "in_progress" ? "🔄" : "⬜";
  /* The assignee picker offers this job's crew (the caller passes the crew,
     not the whole roster) plus the current assignee when they have since
     left the crew, so reassigning never silently drops who is on it now. */
  const currentIds = taskAssigneeIds(task);
  const assigneeOptions = employees.filter((e) => e.status === "ativo" || currentIds.includes(e.id));
  for (const id of currentIds) {
    if (!assigneeOptions.some((e) => e.id === id)) {
      const byId = employees.find((e) => e.id === id);
      if (byId) assigneeOptions.push(byId);
      else {
        const nm = taskAssigneeNames(task)[currentIds.indexOf(id)] ?? tr("Assigned employee", "Funcionário atribuído", "Empleado asignado");
        assigneeOptions.push({ id, name: nm, trade: "", payType: "hora", payRate: 0, status: "ativo" });
      }
    }
  }
  const displayNames = taskAssigneeNames(task);

  return (
    <div className="rounded-lg bg-[var(--surface)] p-2.5">
      <div className="flex items-start gap-2">
        <span className="mt-0.5 shrink-0 text-base" aria-hidden="true">{statusIcon}</span>
        <div className="min-w-0 flex-1">
          <p className={`font-semibold leading-snug ${task.status === "done" ? "text-[var(--dim)] line-through" : ""}`}>{task.title}</p>
          {task.notes && <p className="mt-0.5 whitespace-pre-line text-xs leading-relaxed text-[var(--dim)]">{task.notes}</p>}
          <p className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-0.5 text-[11px] text-[var(--dim)]">
            {displayNames.length > 0 ? (
              <span className="flex flex-wrap gap-1">{displayNames.map((n) => <span key={n} className="inline-flex rounded-full bg-[#0f2a44] px-2 py-0.5 text-[10px] font-bold text-white">👤 {n}</span>)}</span>
            ) : (
              <span>{tr("👥 Whole crew", "👥 Equipe toda", "👥 Todo el equipo")}</span>
            )}
            <span>{tr(`• Added ${fmtDate(task.createdAt)}`, `• Adicionada em ${fmtDate(task.createdAt)}`, `• Agregada el ${fmtDate(task.createdAt)}`)}</span>
            {taskHours && <span aria-label={tr(`Total time logged on this task: ${taskHours}`, `Tempo total registrado nesta tarefa: ${taskHours}`, `Tiempo total registrado en esta tarea: ${taskHours}`)}>• ⏱ {taskHours} {tr("logged", "registradas", "registradas")}</span>}
            {task.timerRunning && <span className="font-bold text-amber-700 dark:text-amber-400">{tr("⏱ timer running", "⏱ cronômetro rodando", "⏱ temporizador en marcha")}</span>}
          </p>
          {task.status === "in_progress" && (
            <p className="mt-0.5 text-[11px] font-bold text-amber-700 dark:text-amber-400" aria-label={tr(`Started ${task.startedAt ? fmtDate(task.startedAt) : ""}`, `Iniciada em ${task.startedAt ? fmtDate(task.startedAt) : ""}`, `Iniciada el ${task.startedAt ? fmtDate(task.startedAt) : ""}`)}>
              🔄 {inProgressMeta(task.startedAt)}{task.startedAt ? ` • ${tr("started", "iniciada em", "iniciada el")} ${fmtDate(task.startedAt)}` : ""}
            </p>
          )}
          {task.status === "done" && task.completedAt && (
            <p className="mt-0.5 text-[11px] font-bold text-green-700 dark:text-green-400">✅ {tr("Done", "Concluída", "Terminada")} {fmtDate(task.completedAt)}</p>
          )}
        </div>
        {taskStatusBadge(task.status)}
      </div>

      {/* Status actions — crew picks any order: Start, then Done when finished. */}
      <div className="mt-2 flex flex-wrap gap-2">
        {task.status === "todo" && (
          <button type="button" aria-label={tr(`Start task ${task.title}`, `Iniciar a tarefa ${task.title}`, `Iniciar la tarea ${task.title}`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate("in_progress")} className="rounded-lg bg-[#0f2a44] px-3 py-2 text-xs font-bold text-white active:opacity-80 disabled:opacity-40 dark:bg-white dark:text-[#0f2a44]">{tr("▶ Start", "▶ Iniciar", "▶ Iniciar")}</button>
        )}
        {task.status === "in_progress" && (
          <button type="button" aria-label={tr(`Mark task ${task.title} as done`, `Marcar a tarefa ${task.title} como concluída`, `Marcar la tarea ${task.title} como terminada`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate("done")} className="rounded-lg bg-green-600 px-3 py-2 text-xs font-bold text-white active:opacity-80 disabled:opacity-40">{tr("✓ Done", "✓ Concluir", "✓ Terminar")}</button>
        )}
        {task.status === "done" && canManage && (
          <button type="button" aria-label={tr(`Reopen task ${task.title}`, `Reabrir a tarefa ${task.title}`, `Reabrir la tarea ${task.title}`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate("todo")} className="rounded-lg border border-[var(--border)] px-3 py-2 text-xs font-bold active:opacity-80 disabled:opacity-40">{tr("↩ Reopen", "↩ Reabrir", "↩ Reabrir")}</button>
        )}
        {task.status === "in_progress" && canManage && (
          <button type="button" aria-label={tr(`Move task ${task.title} back to To Do`, `Mover a tarefa ${task.title} de volta para A fazer`, `Mover la tarea ${task.title} de vuelta a Por hacer`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate("todo")} className="rounded-lg border border-[var(--border)] px-3 py-2 text-xs font-bold active:opacity-80 disabled:opacity-40">{tr("↩ Back to To Do", "↩ Voltar para A fazer", "↩ Volver a Por hacer")}</button>
        )}
        {manageControls && !editing && (
          <span className="ml-auto flex gap-2">
            <button type="button" aria-label={tr(`Edit task ${task.title}`, `Editar a tarefa ${task.title}`, `Editar la tarea ${task.title}`)} className="px-1 py-2 text-xs font-bold text-[#f97316]" onClick={() => { setTTitle(task.title); setTNotes(task.notes); setTAssignees(new Set(taskAssigneeIds(task))); setEditing(true); }}>{tr("Edit", "Editar", "Editar")}</button>
            {confirmDelete ? (
              <>
                <span className="text-xs font-bold text-red-600" role="alert">{tr("Delete this task and its photos?", "Excluir esta tarefa e suas fotos?", "¿Eliminar esta tarea y sus fotos?")}</span>
                <button type="button" aria-label={tr(`Confirm delete task ${task.title}`, `Confirmar a exclusão da tarefa ${task.title}`, `Confirmar la eliminación de la tarea ${task.title}`)} disabled={removeTask.isPending} onClick={() => removeTask.mutate()} className="px-1 py-2 text-xs font-bold text-red-600">{tr("Delete", "Excluir", "Eliminar")}</button>
                <button type="button" aria-label={tr("Cancel delete task", "Cancelar a exclusão da tarefa", "Cancelar la eliminación de la tarea")} className="px-1 py-2 text-xs font-bold text-[var(--dim)]" onClick={() => setConfirmDelete(false)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
              </>
            ) : (
              <button type="button" aria-label={tr(`Delete task ${task.title}`, `Excluir a tarefa ${task.title}`, `Eliminar la tarea ${task.title}`)} className="px-1 py-2 text-xs font-bold text-red-600" onClick={() => setConfirmDelete(true)}>{tr("Delete", "Excluir", "Eliminar")}</button>
            )}
          </span>
        )}
      </div>

      {/* Work timer + logged hours. Start work only works while checked in. */}
      {task.status !== "done" && (
        <div className="mt-2 flex flex-wrap items-center gap-2">
          {task.timerRunning ? (
            <button type="button" aria-label={tr(`Pause work on task ${task.title}`, `Pausar o trabalho na tarefa ${task.title}`, `Pausar el trabajo en la tarea ${task.title}`)} disabled={pauseTimer.isPending} onClick={() => pauseTimer.mutate()} className="rounded-lg bg-amber-500 px-3 py-2 text-xs font-bold text-white active:opacity-80 disabled:opacity-40">{tr("⏸ Pause work", "⏸ Pausar o trabalho", "⏸ Pausar el trabajo")}</button>
          ) : (
            <button type="button" aria-label={tr(`Start work on task ${task.title}`, `Começar a trabalhar na tarefa ${task.title}`, `Empezar a trabajar en la tarea ${task.title}`)} disabled={startTimer.isPending} onClick={() => startTimer.mutate()} className="rounded-lg bg-[#f97316] px-3 py-2 text-xs font-bold text-white active:opacity-80 disabled:opacity-40">{tr("⏱ Start work", "⏱ Começar a trabalhar", "⏱ Empezar a trabajar")}</button>
          )}
          <span className="text-[11px] text-[var(--dim)]">{task.timerRunning ? tr("Timer running — it only counts while you're checked in.", "Cronômetro rodando — ele só conta enquanto você estiver com o ponto registrado.", "Temporizador en marcha: solo cuenta mientras tengas el registro de entrada activo.") : tr("Starts a timer. You must be checked in first.", "Inicia um cronômetro. Você precisa registrar o ponto primeiro.", "Inicia un temporizador. Primero debes registrar tu entrada.")}</span>
        </div>
      )}
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="sr-only" htmlFor={`log-hours-${task.id}`}>{tr("Log hours on", "Registrar horas em", "Registrar horas en")} {task.title}</label>
        <input id={`log-hours-${task.id}`} aria-label={tr(`Hours to log on task ${task.title}`, `Horas para registrar na tarefa ${task.title}`, `Horas para registrar en la tarea ${task.title}`)} className="w-24 rounded-lg border border-[var(--border)] bg-[var(--surface)] px-2 py-1.5 text-xs" inputMode="decimal" value={logHours} onChange={(e) => setLogHours(e.target.value)} placeholder={tr("Hours", "Horas", "Horas")} />
        <button type="button" aria-label={tr(`Log hours on task ${task.title}`, `Registrar horas na tarefa ${task.title}`, `Registrar horas en la tarea ${task.title}`)} disabled={logTime.isPending || !(parseFloat(logHours.replace(",", ".")) > 0)} onClick={() => logTime.mutate()} className="rounded-lg border border-[var(--border)] px-3 py-1.5 text-xs font-bold active:opacity-80 disabled:opacity-40">{tr("+ Log hours", "+ Registrar horas", "+ Registrar horas")}</button>
        <button type="button" aria-label={showTime ? tr(`Hide time log for task ${task.title}`, `Ocultar o registro de tempo da tarefa ${task.title}`, `Ocultar el registro de tiempo de la tarea ${task.title}`) : tr(`Show time log for task ${task.title}`, `Mostrar o registro de tempo da tarefa ${task.title}`, `Mostrar el registro de tiempo de la tarea ${task.title}`)} aria-expanded={showTime} onClick={() => setShowTime((s) => !s)} className="px-1 py-1.5 text-xs font-bold text-[#f97316]">{showTime ? tr("Hide time", "Ocultar tempo", "Ocultar tiempo") : tr("Time log", "Registro de tempo", "Registro de tiempo")}</button>
      </div>
      {showTime && <TaskTimeDetails cid={cid} taskId={task.id} />}

      {editing && manageControls && (
        <form className="mt-2 space-y-2 rounded-lg bg-[var(--surface2)] p-2.5" onSubmit={(e) => { e.preventDefault(); saveEdit.mutate(); }}>
          <Field label={tr("Task title", "Título da tarefa", "Título de la tarea")}><input aria-label={tr("Task title", "Título da tarefa", "Título de la tarea")} className={inputCls} value={tTitle} onChange={(e) => setTTitle(e.target.value)} required /></Field>
          <Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><textarea aria-label={tr("Task notes", "Observações da tarefa", "Notas de la tarea")} className={inputCls} rows={2} value={tNotes} onChange={(e) => setTNotes(e.target.value)} placeholder={tr("Anything the crew should know…", "Tudo o que a equipe precisa saber…", "Todo lo que el equipo debe saber…")} /></Field>
          <Field label={tr("Assigned to — pick one or several", "Atribuído a — escolha um ou vários", "Asignado a: elige uno o varios")}>
            <AssigneeMultiPicker idPrefix={`task-${task.id}`} options={assigneeOptions} selected={tAssignees} onChange={setTAssignees} />
          </Field>
          <div className="flex gap-2">
            <button type="button" className={btnGhost} onClick={() => setEditing(false)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
            <button className={`${btnNavy} flex-1`} disabled={saveEdit.isPending || !tTitle.trim()}>{saveEdit.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save task", "Salvar tarefa", "Guardar tarea")}</button>
          </div>
        </form>
      )}

      {/* Task photos — Before / During / After, timestamped. */}
      {task.photos.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-2" aria-label={tr(`Photos for task ${task.title}`, `Fotos da tarefa ${task.title}`, `Fotos de la tarea ${task.title}`)}>
          {task.photos.map((ph) => {
            const src = safeImgSrc(ph.photoUrl);
            const stage = photoStageMeta(ph.stage);
            return src ? (
              <button key={ph.id} type="button" aria-label={tr(`View ${stage.label} photo for ${task.title}, taken ${fmtDate(ph.createdAt)}`, `Ver a foto ${stage.label} da tarefa ${task.title}, tirada em ${fmtDate(ph.createdAt)}`, `Ver la foto ${stage.label} de la tarea ${task.title}, tomada el ${fmtDate(ph.createdAt)}`)} onClick={() => setViewPhoto(ph)} className="relative h-16 w-16 shrink-0 overflow-hidden rounded-lg active:opacity-80">
                <img src={src} alt={tr(`${stage.label} photo for ${task.title}`, `Foto ${stage.label} da tarefa ${task.title}`, `Foto ${stage.label} de la tarea ${task.title}`)} className="h-full w-full object-cover" />
                <span className={`absolute inset-x-0 bottom-0 px-1 py-0.5 text-center text-[9px] font-black uppercase tracking-wide text-white ${stage.key === "before" ? "bg-gray-700/85" : stage.key === "after" ? "bg-green-700/85" : "bg-amber-600/85"}`}>{stage.label}</span>
              </button>
            ) : null;
          })}
        </div>
      )}
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <div className="flex overflow-hidden rounded-lg border border-[var(--border)]" role="radiogroup" aria-label={tr(`Photo stage for ${task.title}`, `Etapa da foto para ${task.title}`, `Etapa de la foto para ${task.title}`)}>
          {photoStages().map((s) => (
            <button key={s.key} type="button" role="radio" aria-checked={photoStage === s.key} aria-label={tr(`Stage: ${s.label}`, `Etapa: ${s.label}`, `Etapa: ${s.label}`)}
              onClick={() => setPhotoStage(s.key)}
              className={`px-2 py-1.5 text-[11px] font-bold ${photoStage === s.key ? "bg-[#0f2a44] text-white dark:bg-white dark:text-[#0f2a44]" : "text-[var(--dim)]"}`}>
              {s.label}
            </button>
          ))}
        </div>
        <button type="button" aria-label={tr(`Add photo to task ${task.title}`, `Adicionar foto à tarefa ${task.title}`, `Agregar foto a la tarea ${task.title}`)} disabled={photoBusy} onClick={() => fileRef.current?.click()} className="rounded-lg border border-[var(--border)] px-3 py-1.5 text-xs font-bold active:opacity-80 disabled:opacity-40">
          {photoBusy ? tr("Saving…", "Salvando…", "Guardando…") : tr("📷 Add photo", "📷 Adicionar foto", "📷 Agregar foto")}
        </button>
        <input ref={fileRef} type="file" accept="image/*" capture="environment" multiple className="hidden" aria-label={tr(`Photo files for task ${task.title}`, `Arquivos de foto da tarefa ${task.title}`, `Archivos de foto de la tarea ${task.title}`)}
          onChange={(e) => { void onPickPhotos(e.target.files); e.target.value = ""; }} />
      </div>
      {photoMsg && <p className="mt-1 text-xs font-semibold text-red-600" role="alert">{photoMsg}</p>}
      {viewPhoto && <PhotoLightbox photo={viewPhoto} taskTitle={task.title} onClose={() => setViewPhoto(null)} />}
    </div>
  );
}

/* Time logged on one task: segments, per-person totals, and labor cost for
   hourly workers (hours-only where pay is daily/contract). */
function TaskTimeDetails({ cid, taskId }: { cid: string; taskId: number }) {
  const q = useQuery({ queryKey: ["task-time", cid, taskId], queryFn: () => api.listTaskTime({ companyId: cid, taskId }) });
  if (q.isPending) return <p className="mt-2 text-xs text-[var(--dim)]">{tr("Loading time log…", "Carregando o registro de tempo…", "Cargando el registro de tiempo…")}</p>;
  if (q.error || !q.data) return <p className="mt-2 text-xs font-semibold text-red-600">{tr("Could not load the time log.", "Não foi possível carregar o registro de tempo.", "No se pudo cargar el registro de tiempo.")}</p>;
  const d = q.data;
  return (
    <div className="mt-2 rounded-lg bg-[var(--surface2)] p-2.5" aria-label={tr("Task time details", "Detalhes de tempo da tarefa", "Detalles de tiempo de la tarea")}>
      <p className="text-xs font-bold">⏱ {tr("Total on this task:", "Total nesta tarefa:", "Total en esta tarea:")} {(d.totalMinutes / 60).toFixed(1)}h</p>
      {d.byEmployee.length > 0 && (
        <div className="mt-1.5 space-y-1">
          {d.byEmployee.map((b) => (
            <p key={b.employeeId} className="flex flex-wrap justify-between gap-2 text-xs">
              <span>{b.employeeName} <span className="text-[var(--dim)]">({payTypeLabel(b.payType)})</span></span>
              <span className="font-semibold">{(b.minutes / 60).toFixed(1)}h{b.laborCost !== null ? ` • ${fmtUSD(b.laborCost)} ${tr("labor", "de mão de obra", "de mano de obra")}` : tr(" • labor in daily/contract pay", " • mão de obra no pagamento por dia/contrato", " • mano de obra en el pago por día/contrato")}</span>
            </p>
          ))}
        </div>
      )}
      {d.logs.length === 0 && <p className="mt-1 text-xs text-[var(--dim)]">{tr("No time logged yet. Start work or log hours above.", "Nenhum tempo registrado ainda. Comece a trabalhar ou registre as horas acima.", "Todavía no hay tiempo registrado. Empieza a trabajar o registra las horas arriba.")}</p>}
      {d.logs.length > 0 && (
        <div className="mt-2 space-y-1 border-t border-[var(--border)] pt-2">
          {d.logs.slice(0, 8).map((l) => (
            <p key={l.id} className="text-[11px] text-[var(--dim)]">
              {l.kind === "timer" ? "⏱" : "✍️"} {l.employeeName} — {(l.minutes / 60).toFixed(2)}h
              {l.startedAt ? ` • ${fmtDate(l.startedAt)} ${fmtTime(l.startedAt)}${l.endedAt ? ` → ${fmtTime(l.endedAt)}` : tr(" → running", " → rodando", " → en marcha")}` : ` • ${tr("logged", "registrado em", "registrado el")} ${fmtDate(l.createdAt)}`}
              {l.note ? ` • ${l.note}` : ""}
            </p>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------------- Notifications (in-app) ---------------- */
type NotificationLite = { id: number; type: string; title: string; detail: string; payload?: string; linkView: string; linkId: number | null; read: boolean; createdAt: string };

/* Notifications are stored with a structured payload so title/detail can be
   rebuilt in the active language. Older rows fall back to the stored text. */
function localizeNotification(n: NotificationLite, tr: (en: string, pt: string, es?: string) => string): { title: string; detail: string } {
  let p: Record<string, string | number | boolean | null> | null = null;
  if (n.payload) {
    try { p = JSON.parse(n.payload) as Record<string, string | number | boolean | null>; } catch { p = null; }
  }
  if (!p) return { title: n.title, detail: n.detail };
  const s = (k: string) => (p[k] === null || p[k] === undefined ? "" : String(p[k]));
  switch (n.type) {
    case "timesheet_pending": {
      const auto = s("autoAt")
        ? s("autoAt") === "cutoff"
          ? tr(" (auto-closed at the cutoff)", " (fechado automaticamente no horário limite)", " (cerrado automáticamente a la hora límite)")
          : tr(` (auto-closed at ${s("autoAt")})`, ` (fechado automaticamente às ${s("autoAt")})`, ` (cerrado automáticamente a las ${s("autoAt")})`)
        : "";
      return {
        title: tr("🕐 Timesheet pending approval", "🕐 Registro de ponto aguardando aprovação", "🕐 Parte de horas pendiente de aprobación"),
        detail: `${s("name")} • ${s("date")} • ${s("hours")}h${auto}.`,
      };
    }
    case "no_show":
      return {
        title: tr(`⏰ No check-in — ${s("name")}`, `⏰ Sem check-in — ${s("name")}`, `⏰ Sin registro de entrada: ${s("name")}`),
        detail: tr(`${s("name")} was assigned today (${s("project")}) and has not checked in by ${s("cutoff")}.`, `${s("name")} estava escalado hoje (${s("project")}) e não fez check-in até às ${s("cutoff")}.`, `${s("name")} estaba asignado hoy (${s("project")}) y no ha registrado entrada hasta las ${s("cutoff")}.`),
      };
    case "invoice_overdue":
      return {
        title: tr(`🧾 Invoice #${s("number")} is overdue`, `🧾 A fatura nº ${s("number")} está vencida`, `🧾 La factura n.º ${s("number")} está vencida`),
        detail: tr(`${s("client")} • Balance due $${s("balance")} • was due ${s("dueDate")}.`, `${s("client")} • Saldo a pagar $${s("balance")} • venceu em ${s("dueDate")}.`, `${s("client")} • Saldo por pagar $${s("balance")} • venció el ${s("dueDate")}.`),
      };
    case "task_assigned": {
      const hint = tr("Open the Field tab to see it in My tasks.", "Abra a aba Campo para vê-la em Minhas tarefas.", "Abre la pestaña Campo para verla en Mis tareas.");
      return {
        title: p.fresh
          ? tr(`📌 New task assigned to you: ${s("task")}`, `📌 Nova tarefa atribuída a você: ${s("task")}`, `📌 Nueva tarea asignada a ti: ${s("task")}`)
          : tr(`📌 Task assigned to you: ${s("task")}`, `📌 Tarefa atribuída a você: ${s("task")}`, `📌 Tarea asignada a ti: ${s("task")}`),
        detail: s("notes") ? `${s("job")} • ${s("notes")}` : s("job") ? `${s("job")} • ${hint}` : hint,
      };
    }
    case "task_done":
      return {
        title: tr(`✅ Task done: ${s("task")}`, `✅ Tarefa concluída: ${s("task")}`, `✅ Tarea terminada: ${s("task")}`),
        detail: tr(`${s("job")} • finished by ${s("actor")}.`, `${s("job")} • concluída por ${s("actor")}.`, `${s("job")} • terminada por ${s("actor")}.`),
      };
    case "out_of_zone": {
      const distWord = typeof p.distM === "number"
        ? tr(`${fmtDist(p.distM)} from the site center`, `a ${fmtDist(p.distM)} do centro da obra`, `a ${fmtDist(p.distM)} del centro de la obra`)
        : "";
      if (p.phase === "out") {
        return {
          title: tr("🚨 Check-out outside job site area", "🚨 Check-out fora da área da obra", "🚨 Registro de salida fuera del área de la obra"),
          detail: tr(`${s("name")} checked out${distWord ? ` ${distWord}` : ""} (${s("project")}). Review before approving.`, `${s("name")} fez check-out${distWord ? ` ${distWord}` : ""} (${s("project")}). Revise antes de aprovar.`, `${s("name")} registró su salida${distWord ? ` ${distWord}` : ""} (${s("project")}). Revisa antes de aprobar.`),
        };
      }
      return {
        title: tr("🚨 Check-in outside job site area", "🚨 Check-in fora da área da obra", "🚨 Registro de entrada fuera del área de la obra"),
        detail: tr(`${s("name")} checked in${distWord ? ` ${distWord}` : ""} at ${s("project")}${s("job") ? ` (${s("job")})` : ""}. Review before approving.`, `${s("name")} fez check-in${distWord ? ` ${distWord}` : ""} em ${s("project")}${s("job") ? ` (${s("job")})` : ""}. Revise antes de aprovar.`, `${s("name")} registró su entrada${distWord ? ` ${distWord}` : ""} en ${s("project")}${s("job") ? ` (${s("job")})` : ""}. Revisa antes de aprobar.`),
      };
    }
    case "invoice_payment":
      return {
        title: tr(`💵 Payment recorded on invoice #${s("number")}`, `💵 Pagamento registrado na fatura nº ${s("number")}`, `💵 Pago registrado en la factura n.º ${s("number")}`),
        detail: tr(`$${s("amount")} via ${s("method")} • Balance due now $${s("balance")}.`, `$${s("amount")} via ${s("method")} • Saldo atual $${s("balance")}.`, `$${s("amount")} mediante ${s("method")} • Saldo ahora $${s("balance")}.`),
      };
    case "vehicle_oil": {
      const overdue = s("state") === "overdue";
      const dueBits = [
        s("dueMileage") && s("dueMileage") !== "0" ? tr(`due at ${Number(s("dueMileage")).toLocaleString("en-US")} mi`, `vence aos ${Number(s("dueMileage")).toLocaleString("en-US")} mi`, `vence a las ${Number(s("dueMileage")).toLocaleString("en-US")} mi`) : "",
        s("dueDate") ? tr(`due ${s("dueDate")}`, `vence em ${s("dueDate")}`, `vence el ${s("dueDate")}`) : "",
      ].filter(Boolean).join(" • ");
      return {
        title: overdue
          ? tr(`🛢️ Oil change OVERDUE — ${s("vehicle")}`, `🛢️ Troca de óleo VENCIDA — ${s("vehicle")}`, `🛢️ Cambio de aceite VENCIDO: ${s("vehicle")}`)
          : tr(`🛢️ Oil change due soon — ${s("vehicle")}`, `🛢️ Troca de óleo perto do vencimento — ${s("vehicle")}`, `🛢️ Cambio de aceite por vencer: ${s("vehicle")}`),
        detail: tr(`${s("vehicle")} • Odometer ${Number(s("mileage") || 0).toLocaleString("en-US")} mi${dueBits ? ` • ${dueBits}` : ""}. Open Fleet to log the oil change.`, `${s("vehicle")} • Odômetro ${Number(s("mileage") || 0).toLocaleString("en-US")} mi${dueBits ? ` • ${dueBits}` : ""}. Abra a Frota para registrar a troca de óleo.`, `${s("vehicle")} • Odómetro ${Number(s("mileage") || 0).toLocaleString("en-US")} mi${dueBits ? ` • ${dueBits}` : ""}. Abre Flota para registrar el cambio de aceite.`),
      };
    }
    default:
      return { title: n.title, detail: n.detail };
  }
}

function NotificationBell({ cid, session, onNavigate }: {
  cid: string; session: Session;
  onNavigate: (linkView: string, linkId: number | null) => void;
}) {
  const qc = useQueryClient();
  const [open, setOpen] = useState(false);
  const q = useQuery({
    queryKey: ["notifications", cid, session.userId],
    queryFn: () => api.listNotifications({ companyId: cid, userId: session.userId }),
    refetchInterval: 30000,
  });
  const items: NotificationLite[] = q.data?.notifications ?? [];
  const unread = q.data?.unread ?? 0;
  const invalidate = () => qc.invalidateQueries({ queryKey: ["notifications", cid, session.userId] });
  const markAll = useMutation({
    mutationFn: () => api.markAllNotificationsRead({ companyId: cid, userId: session.userId }),
    onSuccess: invalidate,
  });
  const openItem = async (n: NotificationLite) => {
    try { await api.markNotificationRead({ companyId: cid, userId: session.userId, id: n.id }); } catch { /* badge refreshes on next poll */ }
    invalidate();
    setOpen(false);
    if (n.linkView) onNavigate(n.linkView, n.linkId);
  };
  return (
    <div className="relative shrink-0">
      <button type="button" aria-label={unread > 0 ? tr(`Notifications, ${unread} unread`, `Notificações, ${unread} não lidas`, `Notificaciones, ${unread} sin leer`) : tr("Notifications", "Notificações", "Notificaciones")} aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        className="relative rounded-lg bg-white/10 px-3 py-2 text-sm active:opacity-70">
        🔔
        {unread > 0 && (
          <span className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-red-600 px-1 text-[11px] font-black text-white" aria-hidden="true">{unread > 9 ? "9+" : unread}</span>
        )}
      </button>
      {open && (
        <div className="absolute right-0 top-full z-30 mt-2 w-[min(22rem,calc(100vw-2rem))] rounded-2xl border border-[var(--border)] bg-[var(--surface)] text-[var(--text)] shadow-xl" role="dialog" aria-label={tr("Notifications", "Notificações", "Notificaciones")}>
          <div className="flex items-center justify-between gap-2 border-b border-[var(--border)] px-3 py-2.5">
            <p className="text-sm font-bold">{tr("Notifications", "Notificações", "Notificaciones")}</p>
            {unread > 0 && (
              <button type="button" aria-label={tr("Mark all notifications as read", "Marcar todas as notificações como lidas", "Marcar todas las notificaciones como leídas")} disabled={markAll.isPending} onClick={() => markAll.mutate()} className="text-xs font-bold text-[#f97316] active:opacity-70 disabled:opacity-40">{tr("Mark all read", "Marcar tudo como lido", "Marcar todo como leído")}</button>
            )}
          </div>
          <p className="border-b border-[var(--border)] px-3 py-1.5 text-[11px] text-[var(--dim)]">{tr("In-app notifications (push to phone comes with the native app).", "Notificações no app (o push para o celular virá com o app nativo).", "Notificaciones en la app (las notificaciones push llegarán con la app nativa).")}</p>
          <div className="max-h-[60vh] overflow-y-auto">
            {q.isPending && <p className="px-3 py-4 text-sm text-[var(--dim)]">{tr("Loading…", "Carregando…", "Cargando…")}</p>}
            {!q.isPending && items.length === 0 && <p className="px-3 py-4 text-sm text-[var(--dim)]">{tr("Nothing here yet. Out-of-area check-ins, no-shows, finished tasks, pending timesheets, overdue invoices, and payments will show up here.", "Nada por aqui ainda. Check-ins fora da área, faltas, tarefas concluídas, registros pendentes, faturas vencidas e pagamentos aparecerão aqui.", "Todavía no hay nada aquí. Los registros fuera del área, las ausencias, las tareas terminadas, los partes de horas pendientes, las facturas vencidas y los pagos aparecerán aquí.")}</p>}
            {items.map((n) => {
              const loc = localizeNotification(n, tr);
              return (
              <button key={n.id} type="button" onClick={() => void openItem(n)} aria-label={tr(`Open notification: ${loc.title}`, `Abrir a notificação: ${loc.title}`, `Abrir la notificación: ${loc.title}`)}
                className={`block w-full border-b border-[var(--border)] px-3 py-2.5 text-left active:opacity-70 ${n.read ? "opacity-70" : ""}`}>
                <p className="flex items-start gap-2 text-sm font-semibold leading-snug">
                  {!n.read && <span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-[#f97316]" aria-hidden="true" />}
                  <span className="min-w-0">{loc.title}</span>
                </p>
                {loc.detail && <p className="mt-0.5 text-xs leading-relaxed text-[var(--dim)]">{loc.detail}</p>}
                <p className="mt-0.5 text-[11px] text-[var(--dim)]">{new Date(n.createdAt).toLocaleString("en-US")}</p>
              </button>
              );
            })}
          </div>
          <button type="button" aria-label={tr("Close notifications", "Fechar notificações", "Cerrar notificaciones")} onClick={() => setOpen(false)} className="w-full px-3 py-2 text-center text-xs font-bold text-[var(--dim)] active:opacity-70">{tr("Close", "Fechar", "Cerrar")}</button>
        </div>
      )}
    </div>
  );
}

/* ---------------- App ---------------- */
export function App() {
  const [session, setSession] = useState<Session | null>(() => {
    try {
      const raw = localStorage.getItem("sb-session");
      return raw ? (JSON.parse(raw) as Session) : null;
    } catch { return null; }
  });
  // Interface language (EN / PT-BR / ES). Persisted per user; money, units,
  // and date formats always stay US regardless of this choice.
  const [lang, setLangState] = useState<Lang>(() => {
    try {
      const raw = localStorage.getItem("sb-session");
      const s = raw ? (JSON.parse(raw) as Session) : null;
      const key = s ? `sb-lang:${s.companyId}:${s.userId}` : "sb-lang";
      const v = localStorage.getItem(key) || localStorage.getItem("sb-lang");
      return v === "pt" ? "pt" : v === "es" ? "es" : "en";
    } catch { return "en"; }
  });
  setCurrentLang(lang);
  const setLang = (next: Lang) => {
    setLangState(next);
    setCurrentLang(next);
    try {
      localStorage.setItem("sb-lang", next);
      if (session) localStorage.setItem(`sb-lang:${session.companyId}:${session.userId}`, next);
    } catch { /* storage unavailable */ }
  };
  useEffect(() => {
    setCurrentLang(lang);
    try { document.documentElement.lang = langDocValue(lang); } catch { /* noop */ }
  }, [lang]);
  useEffect(() => {
    if (!session) return;
    try {
      const stored = localStorage.getItem(`sb-lang:${session.companyId}:${session.userId}`);
      if (stored === "pt" || stored === "en" || stored === "es") setLangState(stored);
    } catch { /* noop */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session?.companyId, session?.userId]);
  const langCtx = { lang, setLang, t: (en: string, pt: string, es?: string) => (lang === "pt" ? pt : lang === "es" ? (es ?? en) : en) };
  const [view, setView] = useState<View>("dashboard");
  const [selectedProject, setSelectedProject] = useState<number | null>(null);
  const [selectedInvoice, setSelectedInvoice] = useState<number | null>(null);
  /* Job deep link: tapping a job in the Field tab lands on that job's detail
     inside its project. Consumed by ProjectDetail once the data loads. */
  const [pendingJobId, setPendingJobId] = useState<number | null>(null);
  const [focusSheetId, setFocusSheetId] = useState<number | null>(null);
  const [invoicePrefill, setInvoicePrefill] = useState<{ clientId: number | null; projectId: number | null } | null>(null);
  // Platform owner (super-admin) session — separate from company logins.
  const [owner, setOwner] = useState<{ email: string; name: string } | null>(() => {
    try {
      const raw = localStorage.getItem("sb-owner");
      return raw ? (JSON.parse(raw) as { email: string; name: string }) : null;
    } catch { return null; }
  });
  const [ownerEmailInput, setOwnerEmailInput] = useState("owner@smartbuilder.app");
  const [ownerErr, setOwnerErr] = useState("");
  const ownerLogin = useMutation({
    mutationFn: () => api.ownerLogin({ email: ownerEmailInput }),
    onSuccess: (r) => {
      localStorage.setItem("sb-owner", JSON.stringify(r));
      setOwner(r);
      setOwnerErr("");
    },
    onError: () => setOwnerErr(tr("That email is not a platform owner account.", "Esse e-mail não é uma conta de proprietário da plataforma.", "Ese correo no es una cuenta de propietario de la plataforma.")),
  });
  const ownerLogout = () => { localStorage.removeItem("sb-owner"); setOwner(null); };
  // Client portal login (email + password, read-only level 5)
  const [clientEmailInput, setClientEmailInput] = useState("roberto.client@demo.smartbuilder");
  const [clientPwInput, setClientPwInput] = useState("");
  const [clientLoginErr, setClientLoginErr] = useState("");
  const clientLogin = useMutation({
    mutationFn: () => api.clientLogin({ email: clientEmailInput, password: clientPwInput }),
    onSuccess: (r) => {
      const s: Session = { companyId: r.companyId, companyName: r.companyName, userId: r.userId, userName: r.userName, role: r.role, clientId: r.clientId };
      localStorage.setItem("sb-session", JSON.stringify(s));
      setSession(s);
      setClientLoginErr("");
      setClientPwInput("");
    },
    onError: () => setClientLoginErr(tr("Invalid email or password. Check the credentials your contractor shared with you.", "E-mail ou senha inválidos. Verifique as credenciais que sua construtora compartilhou com você.", "Correo o contraseña inválidos. Verifica las credenciales que tu contratista compartió contigo.")),
  });

  // Employee login (email + password)
  const [empEmailInput, setEmpEmailInput] = useState("");
  const [empPwInput, setEmpPwInput] = useState("");
  const [empLoginErr, setEmpLoginErr] = useState("");
  const employeeLogin = useMutation({
    mutationFn: () => api.employeeLogin({ email: empEmailInput, password: empPwInput }),
    onSuccess: (r) => {
      const s: Session = { companyId: r.companyId, companyName: r.companyName, userId: r.userId, userName: r.userName, role: r.role };
      localStorage.setItem("sb-session", JSON.stringify(s));
      setSession(s);
      setView(r.role === "funcionario" ? "field" : "dashboard");
      setEmpLoginErr("");
      setEmpPwInput("");
    },
    onError: () => setEmpLoginErr(tr("Invalid email or password.", "E-mail ou senha inválidos.", "Correo o contraseña inválidos.")),
  });

  const boot = useQuery({ queryKey: ["bootstrap"], queryFn: () => api.getBootstrap({}) });

  /* Keep the saved session in sync with the server (e.g. a renamed demo
     user): the header badge must always show the current name and role. */
  useEffect(() => {
    if (!session || !boot.data) return;
    const comp = boot.data.companies.find((x) => x.id === session.companyId);
    // A suspended tenant cannot stay signed in: the server also refuses its
    // calls, so drop the local session and return to the login screen.
    if (comp && comp.status === "suspended") {
      localStorage.removeItem("sb-session");
      setSession(null);
      return;
    }
    const u = boot.data.users.find((x) => x.id === session.userId && x.companyId === session.companyId);
    const c = boot.data.companies.find((x) => x.id === session.companyId);
    if (!u || !c) return;
    if (u.name !== session.userName || u.role !== session.role || c.name !== session.companyName) {
      const next: Session = { ...session, userName: u.name, role: u.role, companyName: c.name };
      localStorage.setItem("sb-session", JSON.stringify(next));
      setSession(next);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [boot.data, session]);

  const login = (s: Session) => { localStorage.setItem("sb-session", JSON.stringify(s)); setSession(s); setView(s.role === "funcionario" ? "field" : "dashboard"); };
  const logout = () => { localStorage.removeItem("sb-session"); setSession(null); };

  /* Offline outbox: replay queued field actions when back online, then
     refresh everything so the UI reflects what the server accepted. These
     hooks must run on every render — before the login/owner early returns —
     or React throws a hook-order error when the session flips. */
  const appQc = useQueryClient();
  const online = useOnline();
  const outboxItems = useOutboxItems();
  useEffect(() => {
    startOutboxAutoSync();
    setOutboxSyncedHandler(() => { void appQc.invalidateQueries(); });
  }, [appQc]);
  useEffect(() => {
    if (online && outboxItems.length > 0) void syncOutbox();
  }, [online, outboxItems.length]);

  /* ---------- PLATFORM OWNER ---------- */
  if (owner) {
    return (
      <LanguageContext.Provider value={langCtx}>
        <OwnerPanel ownerEmail={owner.email} ownerName={owner.name} onSignOut={ownerLogout} />
      </LanguageContext.Provider>
    );
  }

  /* ---------- CLIENT PORTAL (level 5, read-only) ---------- */
  if (session?.role === "cliente") {
    return (
      <LanguageContext.Provider value={langCtx}>
        <ClientPortal session={session} onSignOut={logout} />
      </LanguageContext.Provider>
    );
  }

  /* ---------- LOGIN ---------- */
  if (!session) {
    return (
      <LanguageContext.Provider value={langCtx}>
      <div className="min-h-screen bg-[#0f2a44] px-4 pb-10 pt-10">
        <div className="mx-auto max-w-md">
          <div className="mb-3 flex items-start justify-between gap-2">
            <div className="flex items-center gap-2">
              <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#f97316] text-xl font-black text-white">SB</div>
              <div>
                <h1 className="text-2xl font-black text-white">SmartBuilder</h1>
                <p className="text-xs text-white/60">{tr("Construction management • Pilot", "Gestão de construção • Piloto", "Gestión de construcción • Piloto")}</p>
              </div>
            </div>
            <LanguageToggle compact />
          </div>
          <p className="mt-4 text-sm text-white/80">{tr("Sign in with your company email and password.", "Entre com seu e-mail da empresa e senha.", "Inicia sesión con tu correo de la empresa y contraseña.")}</p>

          {boot.isPending && <p className="mt-6 text-white/70">{tr("Loading…", "Carregando…", "Cargando…")}</p>}
          {boot.error && <p className="mt-6 text-red-300">{tr("Something went wrong loading.", "Algo deu errado ao carregar.", "Algo salió mal al cargar.")} <button className="underline" onClick={() => boot.refetch()}>{tr("Reload", "Recarregar", "Recargar")}</button></p>}
          {boot.data && (
            <div className="mt-6 space-y-5">
              <form className="rounded-2xl bg-white/5 p-4 ring-1 ring-white/10 space-y-3" onSubmit={(e) => { e.preventDefault(); employeeLogin.mutate(); }}>
                <Field label={tr("Email", "E-mail", "Correo")}>
                  <input aria-label={tr("Company email", "E-mail da empresa", "Correo de la empresa")} type="email" autoComplete="email" className="w-full rounded-xl bg-white px-4 py-2.5 text-sm text-[#12222f]" value={empEmailInput} onChange={(e) => setEmpEmailInput(e.target.value)} placeholder="you@company.com" required />
                </Field>
                <Field label={tr("Password", "Senha", "Contraseña")}>
                  <input aria-label={tr("Password", "Senha", "Contraseña")} type="password" autoComplete="current-password" className="w-full rounded-xl bg-white px-4 py-2.5 text-sm text-[#12222f]" value={empPwInput} onChange={(e) => setEmpPwInput(e.target.value)} required />
                </Field>
                <button type="submit" disabled={employeeLogin.isPending || !empEmailInput.trim() || !empPwInput} className="w-full rounded-xl bg-[#f97316] px-4 py-2.5 text-sm font-bold text-white active:opacity-80 disabled:opacity-40">
                  {employeeLogin.isPending ? tr("Signing in…", "Entrando…", "Iniciando…") : tr("Sign in", "Entrar", "Iniciar sesión")}
                </button>
                {empLoginErr && <p className="text-sm font-semibold text-red-300" role="alert">{empLoginErr}</p>}
              </form>
            </div>
          )}
          <div className="mt-6 rounded-2xl bg-white/5 p-4 ring-1 ring-white/10">
            <p className="font-bold text-white">🤝 {tr("Client portal", "Portal do cliente", "Portal del cliente")}</p>
            <p className="mt-0.5 text-xs text-white/60">{tr("Customers sign in here with the email and password their contractor created. Read-only: your projects, progress, and invoices — nothing can be changed.", "Os clientes entram aqui com o e-mail e a senha que a construtora criou. Somente leitura: suas obras, andamento e faturas — nada pode ser alterado.", "Los clientes inician sesión aquí con el correo y la contraseña que creó su contratista. Solo lectura: tus obras, progreso y facturas; no se puede cambiar nada.")}</p>
            <form className="mt-3 space-y-2" onSubmit={(e) => { e.preventDefault(); clientLogin.mutate(); }}>
              <input aria-label={tr("Client portal email", "E-mail do portal do cliente", "Correo del portal del cliente")} type="email" autoComplete="email" value={clientEmailInput} onChange={(e) => setClientEmailInput(e.target.value)}
                className="w-full rounded-xl border border-white/15 bg-white/10 px-3 py-2.5 text-sm text-white placeholder:text-white/40 outline-none focus:border-[#f97316]" placeholder="client@email.com" />
              <div className="flex gap-2">
                <input aria-label={tr("Client portal password", "Senha do portal do cliente", "Contraseña del portal del cliente")} type="password" autoComplete="current-password" value={clientPwInput} onChange={(e) => setClientPwInput(e.target.value)}
                  className="min-w-0 flex-1 rounded-xl border border-white/15 bg-white/10 px-3 py-2.5 text-sm text-white placeholder:text-white/40 outline-none focus:border-[#f97316]" placeholder="••••••••" />
                <button type="submit" disabled={clientLogin.isPending || !clientEmailInput.trim() || !clientPwInput} className="shrink-0 rounded-xl bg-[#f97316] px-4 py-2.5 text-sm font-bold text-white active:opacity-80 disabled:opacity-40">
                  {clientLogin.isPending ? tr("Checking…", "Verificando…", "Verificando…") : tr("Client sign in", "Entrar como cliente", "Iniciar sesión como cliente")}
                </button>
              </div>
            </form>
            {clientLoginErr && <p className="mt-2 text-sm font-semibold text-red-300" role="alert">{clientLoginErr}</p>}
            <p className="mt-2 text-[11px] text-white/40">{tr("Demo client: roberto.client@demo.smartbuilder / client123 — or tap Roberto Almeida in the LOG list above.", "Cliente demo: roberto.client@demo.smartbuilder / client123 — ou toque em Roberto Almeida na lista da LOG acima.", "Cliente de demostración: roberto.client@demo.smartbuilder / client123, o toca Roberto Almeida en la lista de LOG arriba.")}</p>
          </div>
          <div className="mt-6 rounded-2xl bg-white/5 p-4 ring-1 ring-white/10">
            <p className="font-bold text-white">{tr("Platform owner", "Proprietário da plataforma", "Propietario de la plataforma")}</p>
            <p className="mt-0.5 text-xs text-white/60">{tr("The SmartBuilder super-admin area — tenant companies, database exports, and isolation checks. This is not a company login.", "A área de superadministrador do SmartBuilder — empresas clientes, exportações de banco de dados e verificações de isolamento. Isto não é um login de empresa.", "El área de superadministrador de SmartBuilder: empresas cliente, exportaciones de base de datos y comprobaciones de aislamiento. Esto no es un inicio de sesión de empresa.")}</p>
            <form className="mt-3 flex gap-2" onSubmit={(e) => { e.preventDefault(); ownerLogin.mutate(); }}>
              <input aria-label={tr("Platform owner email", "E-mail do proprietário da plataforma", "Correo del propietario de la plataforma")} type="email" autoComplete="email" value={ownerEmailInput} onChange={(e) => setOwnerEmailInput(e.target.value)}
                className="min-w-0 flex-1 rounded-xl border border-white/15 bg-white/10 px-3 py-2.5 text-sm text-white placeholder:text-white/40 outline-none focus:border-[#f97316]" placeholder="owner@smartbuilder.app" />
              <button type="submit" disabled={ownerLogin.isPending || !ownerEmailInput.trim()} className="shrink-0 rounded-xl bg-[#f97316] px-4 py-2.5 text-sm font-bold text-white active:opacity-80 disabled:opacity-40">
                {ownerLogin.isPending ? tr("Checking…", "Verificando…", "Verificando…") : tr("Owner sign in", "Entrar como proprietário", "Iniciar sesión como propietario")}
              </button>
            </form>
            {ownerErr && <p className="mt-2 text-sm font-semibold text-red-300" role="alert">{ownerErr}</p>}
            <p className="mt-2 text-[11px] text-white/40">{tr("Demo owner account: owner@smartbuilder.app (no password in the pilot).", "Conta de demonstração do proprietário: owner@smartbuilder.app (sem senha no piloto).", "Cuenta de demostración del propietario: owner@smartbuilder.app (sin contraseña en el piloto).")}</p>
          </div>
          <p className="mt-6 text-center text-xs text-white/40">{tr("LOG (BUILDER001) comes loaded with demo data. Demo Construction (BUILDER002) starts empty — switch companies and confirm nothing from LOG shows up.", "A LOG (BUILDER001) já vem com dados de demonstração. A Demo Construction (BUILDER002) começa vazia — troque de empresa e confirme que nada da LOG aparece.", "LOG (BUILDER001) viene con datos de demostración. Demo Construction (BUILDER002) empieza vacía: cambia de empresa y confirma que no aparece nada de LOG.")}</p>
        </div>
      </div>
      </LanguageContext.Provider>
    );
  }

  const cid = session.companyId;
  const isAdmin = session.role === "admin";
  const isManager = session.role === "gerente" || isAdmin;
  const canMoney = isAdmin; // full payroll & invoices: admin only

  const goNotification = (linkView: string, linkId: number | null) => {
    if (linkView === "invoices") { setSelectedInvoice(linkId); setView("invoices"); }
    else if (linkView === "projects") { if (linkId !== null) setSelectedProject(linkId); setView("projects"); }
    else if (linkView === "entries") { setFocusSheetId(linkId); setView("entries"); }
    else if (linkView === "payroll") setView("payroll");
    else if (linkView === "field") setView("field");
    else if (linkView === "fleet") setView("fleet");
  };

  const navItems: { key: View; label: string; icon: string; show: boolean }[] = [
    { key: "dashboard", label: tr("Dashboard", "Painel", "Panel"), icon: "📊", show: isManager },
    { key: "dispatch", label: tr("Dispatch", "Distribuição", "Distribución"), icon: "🧭", show: isManager },
    { key: "projects", label: tr("Projects", "Obras", "Obras"), icon: "🏗️", show: true },
    { key: "field", label: tr("Field", "Campo", "Campo"), icon: "📍", show: true },
    { key: "entries", label: tr("Time", "Ponto", "Horas"), icon: "🕐", show: true },
    { key: "payroll", label: tr("Payroll", "Folha de pagamento", "Nómina"), icon: "💰", show: canMoney },
    { key: "expenses", label: tr("Expenses", "Despesas", "Gastos"), icon: "🧾", show: canMoney },
    { key: "costs", label: tr("Costs", "Custos", "Costos"), icon: "📊", show: canMoney },
    { key: "invoices", label: tr("Invoices", "Faturas", "Facturas"), icon: "📄", show: canMoney },
    { key: "team", label: tr("Team", "Equipe", "Equipo"), icon: "👥", show: true },
    { key: "clients", label: tr("Clients", "Clientes", "Clientes"), icon: "🤝", show: isManager },
    { key: "services", label: tr("Services", "Serviços", "Servicios"), icon: "🧱", show: isManager },
    { key: "fleet", label: tr("Fleet", "Frota", "Flota"), icon: "🚐", show: true },
    { key: "settings", label: tr("Settings", "Configurações", "Configuración"), icon: "⚙️", show: isAdmin },
  ];
  const openNewInvoice = (clientId: number | null, projectId: number | null) => { setInvoicePrefill({ clientId, projectId }); setSelectedInvoice(null); setView("invoices"); };

  return (
    <LanguageContext.Provider value={langCtx}>
    <div className="min-h-screen bg-[var(--bg)] pb-24 text-[var(--text)]">
      {/* header */}
      <header className="sticky top-0 z-20 bg-[#0f2a44] px-4 pb-3 pt-[max(0.75rem,env(safe-area-inset-top))] text-white shadow">
        <div className="mx-auto flex max-w-5xl items-center justify-between gap-2">
          <div className="flex min-w-0 items-center gap-2.5">
            <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#f97316] text-sm font-black">SB</div>
            <div className="min-w-0">
              <p className="truncate text-sm font-bold leading-tight">{session.companyName}</p>
              <p className="truncate text-xs text-white/60">{session.userName} • {roleLabel(session.role)}</p>
            </div>
          </div>
          <div className="flex shrink-0 items-center gap-1.5">
            <LanguageToggle compact />
            <NotificationBell cid={cid} session={session} onNavigate={goNotification} />
            <button aria-label={tr("Sign out / switch user", "Sair / trocar de usuário", "Cerrar sesión / cambiar de usuario")} onClick={logout} className="shrink-0 rounded-lg bg-white/10 px-3 py-2 text-xs font-semibold active:opacity-70">{tr("Switch user", "Trocar usuário", "Cambiar de usuario")}</button>
          </div>
        </div>
      </header>

      {(!online || outboxItems.length > 0) && (
        <div className={`px-4 py-2 text-center text-xs font-bold ${online ? "bg-amber-100 text-amber-900" : "bg-red-600 text-white"}`} role="status" aria-label={tr("Offline status", "Status offline", "Estado sin conexión")}>
          {online
            ? tr(`🔄 Back online — syncing ${outboxItems.length} queued action${outboxItems.length === 1 ? "" : "s"}…`, `🔄 De volta online — sincronizando ${outboxItems.length} aç${outboxItems.length === 1 ? "ão" : "ões"} na fila…`, `🔄 De nuevo en línea: sincronizando ${outboxItems.length} acción${outboxItems.length === 1 ? "" : "es"} en cola…`)
            : tr(`📴 You're offline — ${outboxItems.length} action${outboxItems.length === 1 ? "" : "s"} queued. Check-ins, task updates, and photos are saved on this phone and send automatically when you're back online.`, `📴 Você está offline — ${outboxItems.length} aç${outboxItems.length === 1 ? "ão" : "ões"} na fila. Check-ins, atualizações de tarefas e fotos ficam salvos neste celular e são enviados automaticamente quando você voltar a ficar online.`, `📴 Estás sin conexión: ${outboxItems.length} acción${outboxItems.length === 1 ? "" : "es"} en cola. Los registros de entrada, las actualizaciones de tareas y las fotos se guardan en este teléfono y se envían automáticamente cuando vuelvas a conectarte.`)}
        </div>
      )}

      <main className="mx-auto max-w-5xl px-4 pt-4">
        {view === "dashboard" && isManager && <Dashboard cid={cid} session={session} onGo={(v) => setView(v)} />}
        {view === "dispatch" && isManager && <DispatchView cid={cid} session={session} />}
        {view === "projects" && <Projects cid={cid} session={session} onOpen={(id) => { setSelectedProject(id); }} selected={selectedProject} onCloseDetail={() => setSelectedProject(null)} onNewInvoice={openNewInvoice} pendingJobId={pendingJobId} onConsumePendingJob={() => setPendingJobId(null)} />}
        {view === "field" && <FieldView cid={cid} session={session} onOpenJob={(projectId, jobId) => { setSelectedProject(projectId); setPendingJobId(jobId); setView("projects"); }} />}
        {view === "entries" && <TimeEntries cid={cid} session={session} focusSheetId={focusSheetId} onFocusConsumed={() => setFocusSheetId(null)} />}
        {view === "payroll" && canMoney && <Payroll cid={cid} session={session} />}
        {view === "expenses" && canMoney && <Expenses cid={cid} session={session} />}
        {view === "costs" && canMoney && <CostsView cid={cid} session={session} />}
        {view === "invoices" && canMoney && <Invoices cid={cid} session={session} selected={selectedInvoice} onSelect={setSelectedInvoice} prefill={invoicePrefill} onPrefillUsed={() => setInvoicePrefill(null)} />}
        {view === "team" && <Team cid={cid} session={session} />}
        {view === "clients" && <Clients cid={cid} session={session} onOpenProject={(id) => { setSelectedProject(id); setView("projects"); }} onOpenInvoice={(id) => { setSelectedInvoice(id); setView("invoices"); }} onNewInvoice={openNewInvoice} />}
        {view === "services" && isManager && <ServicesView cid={cid} session={session} />}
        {view === "fleet" && isManager && <FleetView cid={cid} session={session} />}
        {view === "settings" && isAdmin && <CompanySettings cid={cid} session={session} />}
        {(view === "dashboard" && !isManager) || (view === "dispatch" && !isManager) || (view === "payroll" && !canMoney) || ((view === "expenses" || view === "invoices" || view === "costs") && !canMoney) || (view === "services" && !isManager) || (view === "clients" && !isManager) ? (
          <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-6 text-center">
            <p className="font-semibold">{tr("Restricted for your role", "Restrito para o seu perfil", "Restringido para tu rol")}</p>
            <p className="mt-1 text-sm text-[var(--dim)]">{session.role === "funcionario" ? tr(`As ${roleLabel(session.role)}, use the Field, Projects, Time, and Team tabs.`, `Como ${roleLabel(session.role)}, use as abas Campo, Obras, Ponto e Equipe.`, `Como ${roleLabel(session.role)}, usa las pestañas Campo, Obras, Horas y Equipo.`) : tr(`As ${roleLabel(session.role)}, use the Field, Projects, Time, Team, and Clients tabs.`, `Como ${roleLabel(session.role)}, use as abas Campo, Obras, Ponto, Equipe e Clientes.`, `Como ${roleLabel(session.role)}, usa las pestañas Campo, Obras, Horas, Equipo y Clientes.`)}</p>
            <button className={`${btnNavy} mt-4`} onClick={() => setView("field")}>{tr("Go to Field", "Ir para o Campo", "Ir a Campo")}</button>
          </div>
        ) : null}
      </main>

      {/* bottom nav */}
      <nav className="fixed inset-x-0 bottom-0 z-20 border-t border-[var(--border)] bg-[var(--surface)] pb-[env(safe-area-inset-bottom)] print:hidden" aria-label={tr("Main navigation", "Navegação principal", "Navegación principal")}>
        <div className="mx-auto flex max-w-5xl overflow-x-auto">
          {navItems.filter((n) => n.show).map((n) => (
            <button
              key={n.key}
              aria-label={n.label}
              aria-current={view === n.key ? "page" : undefined}
              onClick={() => { setView(n.key); setSelectedProject(null); setPendingJobId(null); if (n.key !== "invoices") setSelectedInvoice(null); }}
              className={`flex min-w-[4.2rem] flex-1 flex-col items-center gap-0.5 py-2 text-[11px] font-semibold ${view === n.key ? "text-[#f97316]" : "text-[var(--dim)]"}`}
            >
              <span className="text-lg leading-none">{n.icon}</span>
              {n.label}
            </button>
          ))}
        </div>
      </nav>
    </div>
    </LanguageContext.Provider>
  );
}

/* ---------------- Dashboard ---------------- */
function Dashboard({ cid, session, onGo }: { cid: string; session: Session; onGo: (v: View) => void }) {
  const q = useQuery({ queryKey: ["dashboard", cid], queryFn: () => api.getDashboard({ companyId: cid, actorId: session.userId }) });
  const alerts = useQuery({ queryKey: ["alerts", cid], queryFn: () => api.getManagerAlerts({ companyId: cid }) });
  const qc = useQueryClient();
  const [cutoff, setCutoff] = useState("");
  const [closeTime, setCloseTime] = useState("");
  const [rulesMsg, setRulesMsg] = useState("");
  const saveRules = useMutation({
    mutationFn: () => api.updateSettings({ companyId: cid, actorId: session.userId, noShowCutoff: cutoff, autoCloseTime: closeTime }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["alerts", cid] }); setRulesMsg(tr("Time rules saved. ✅", "Regras de ponto salvas. ✅", "Reglas de horas guardadas. ✅")); },
    onError: () => setRulesMsg(tr("Could not save. Check the times (HH:MM).", "Não foi possível salvar. Verifique os horários (HH:MM).", "No se pudo guardar. Verifica las horas (HH:MM).")),
  });
  if (q.isPending) return <p className="py-10 text-center text-[var(--dim)]">{tr("Loading dashboard…", "Carregando o painel…", "Cargando el panel…")}</p>;
  if (q.error) return <p className="py-10 text-center text-red-600">{tr("Could not load the dashboard.", "Não foi possível carregar o painel.", "No se pudo cargar el panel.")}</p>;
  const d = q.data;
  const a = alerts.data;
  const effCutoff = cutoff || a?.noShowCutoff || "09:00";
  const effClose = closeTime || a?.autoCloseTime || "17:00";
  const hasAlerts = !!a && (a.outOfZone.length > 0 || a.noShows.length > 0);
  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between">
        <div>
          <h2 className="text-xl font-bold">{tr("This week", "Esta semana", "Esta semana")}</h2>
          <p className="text-sm text-[var(--dim)]">{fmtDate(d.weekStart)} {tr("to", "a", "al")} {fmtDate(d.weekEnd)}</p>
        </div>
        {d.pendingApprovals > 0 && (
          <button onClick={() => onGo("entries")} className="rounded-full bg-amber-100 px-3 py-1.5 text-xs font-bold text-amber-800" aria-label={tr(`${d.pendingApprovals} time entries pending approval`, `${d.pendingApprovals} registros de ponto aguardando aprovação`, `${d.pendingApprovals} registros de horas pendientes de aprobación`)}>
            ⚠ {d.pendingApprovals} {tr("pending approval", "aguardando aprovação", "pendientes de aprobación")}
          </button>
        )}
      </div>

      {/* Today's anti-fraud alerts */}
      {a && (
        <section aria-label={tr("Time alerts for today", "Alertas de ponto de hoje", "Alertas de horas de hoy")} className={`rounded-2xl border p-4 ${hasAlerts ? "border-red-300 bg-red-50" : "border-[var(--border)] bg-[var(--surface)]"}`}>
          <h3 className="font-bold">{tr("Time alerts — today", "Alertas de ponto — hoje", "Alertas de horas: hoy")}</h3>
          {!hasAlerts && a.openNow.length === 0 && a.autoClosedToday === 0 && (
            <p className="mt-1 text-sm text-[var(--dim)]">{tr("No alerts so far. Out-of-area check-ins, missing check-ins, and auto-closed shifts show up here.", "Nenhum alerta até agora. Check-ins fora da área, faltas de check-in e turnos fechados automaticamente aparecem aqui.", "Todavía no hay alertas. Los registros fuera del área, las ausencias y los turnos cerrados automáticamente aparecen aquí.")}</p>
          )}
          {a.outOfZone.length > 0 && (
            <div className="mt-2 space-y-1.5">
              {a.outOfZone.map((o) => (
                <button key={o.sheetId} onClick={() => onGo("entries")} aria-label={tr(`Review out-of-area entry for ${o.employeeName}`, `Revisar o registro fora da área de ${o.employeeName}`, `Revisar el registro fuera del área de ${o.employeeName}`)} className="block w-full rounded-xl bg-red-600 px-3 py-2 text-left text-sm font-bold text-white active:opacity-80">
                  🚨 OUTSIDE JOB SITE AREA — {o.employeeName} ({o.where}{o.distM !== null ? `, ${fmtDist(o.distM)} ${tr("from the site", "da obra", "de la obra")}` : ""}) • {o.projectName} • {fmtDate(o.workDate)} — {tr("tap to review", "toque para revisar", "toca para revisar")}
                </button>
              ))}
            </div>
          )}
          {a.noShows.length > 0 && (
            <div className="mt-2 space-y-1.5">
              {a.noShows.map((n) => (
                <p key={n.employeeId} className="rounded-xl bg-amber-100 px-3 py-2 text-sm font-semibold text-amber-800">
                  ⏰ {tr("NO CHECK-IN", "SEM CHECK-IN", "SIN REGISTRO")} — {n.employeeName} {tr("was assigned today", "foi atribuído hoje", "fue asignado hoy")} ({n.projectName}) {tr("and has not checked in by", "e ainda não registrou o ponto até", "y aún no ha registrado su entrada a las")} {a.noShowCutoff}.
                </p>
              ))}
            </div>
          )}
          {a.openNow.length > 0 && (
            <p className="mt-2 text-sm text-[var(--dim)]">🟢 {tr("In the field now:", "Em campo agora:", "En el campo ahora:")} {a.openNow.map((o) => `${o.employeeName} (${o.projectName}, ${tr("since", "desde", "desde")} ${fmtTime(o.since)})`).join(" • ")}</p>
          )}
          {a.autoClosedToday > 0 && (
            <p className="mt-1 text-sm text-[var(--dim)]">🕔 {a.autoClosedToday} {tr("shift(s) from today were auto-closed at", "turno(s) de hoje foram fechados automaticamente às", "turno(s) de hoy se cerraron automáticamente a las")} {a.autoCloseTime}.</p>
          )}
        </section>
      )}

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Kpi accent label={tr("Approved hours", "Horas aprovadas", "Horas aprobadas")} value={`${d.totalHours.toFixed(1)}h`} sub={tr("this week", "esta semana", "esta semana")} />
        {session.role === "admin" && <Kpi label={tr("Labor cost", "Custo de mão de obra", "Costo de mano de obra")} value={fmtUSD(d.laborCost)} sub={tr("approved hours", "horas aprovadas", "horas aprobadas")} />}
        {session.role === "admin" && <Kpi label={tr("Materials / expenses", "Materiais / despesas", "Materiales / gastos")} value={fmtUSD(d.materialsCost)} sub={tr("this week", "esta semana", "esta semana")} />}
        {session.role === "admin" && <Kpi label={tr("Total cost", "Custo total", "Costo total")} value={fmtUSD(d.totalCost)} sub={tr("labor + materials", "mão de obra + materiais", "mano de obra + materiales")} />}
      </div>
      {session.role === "admin" && (
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Kpi label={tr("Invoiced (all time)", "Faturado (todo o período)", "Facturado (todo el período)")} value={fmtUSD(d.invoiced)} />
        <Kpi label={tr("Received", "Recebido", "Recibido")} value={fmtUSD(d.received)} />
        <Kpi label={tr("Balance due", "Saldo a receber", "Saldo por cobrar")} value={fmtUSD(d.receivable)} />
        <Kpi label={tr("Profit (received − costs)", "Lucro (recebido − custos)", "Ganancia (recibido − costos)")} value={fmtUSD(d.profit)} sub={tr(`Margin ${d.margin}%`, `Margem de ${d.margin}%`, `Margen del ${d.margin}%`)} />
      </div>
      )}

      <div className="grid grid-cols-2 gap-3">
        <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-center">
          <p className="text-2xl font-black">{d.activeProjects}</p>
          <p className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Active projects", "Obras ativas", "Obras activas")}</p>
        </div>
        <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-center">
          <p className="text-2xl font-black">{d.totalEmployees}</p>
          <p className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Active employees", "Funcionários ativos", "Empleados activos")}</p>
        </div>
      </div>

      {session.role === "admin" && d.perProject.length > 0 && (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
          <h3 className="mb-3 font-bold">{tr("Cost per project (all time)", "Custo por obra (todo o período)", "Costo por obra (todo el período)")}</h3>
          <div className="space-y-3">
            {d.perProject.map((p) => (
              <div key={p.projectId} className="flex items-center justify-between gap-3 border-b border-[var(--border)] pb-3 last:border-0 last:pb-0">
                <div className="min-w-0">
                  <p className="truncate font-semibold">{p.projectName}</p>
                  <p className="text-xs text-[var(--dim)]">{p.hours.toFixed(1)}h • {tr("Labor", "Mão de obra", "Mano de obra")} {fmtUSD(p.labor)} • {tr("Materials", "Materiais", "Materiales")} {fmtUSD(p.materials)}</p>
                </div>
                <p className="shrink-0 font-bold">{fmtUSD(p.total)}</p>
              </div>
            ))}
          </div>
        </section>
      )}
      {d.perProject.length === 0 && d.activeProjects === 0 && (
        <div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center">
          <p className="text-4xl">🏗️</p>
          <p className="mt-2 font-semibold">{tr("No data in this company yet", "Nenhum dado nesta empresa ainda", "Todavía no hay datos en esta empresa")}</p>
          <p className="mt-1 text-sm text-[var(--dim)]">{tr("Create your first project in the Projects tab and check in from the Field tab to see the dashboard come alive.", "Crie sua primeira obra na aba Obras e registre o ponto na aba Campo para ver o painel ganhar vida.", "Crea tu primera obra en la pestaña Obras y registra tu entrada en la pestaña Campo para ver el panel cobrar vida.")}</p>
        </div>
      )}

      {/* Anti-fraud time rules */}
      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
        <h3 className="font-bold">{tr("Time rules (anti-fraud)", "Regras de ponto (antifraude)", "Reglas de horas (antifraude)")}</h3>
        <p className="mt-1 text-sm text-[var(--dim)]">
          {tr("Check-in and check-out GPS are validated against each project's geofence. Anyone who clocks in outside the area is flagged in red and needs your approval.", "O GPS de entrada e saída é validado contra a cerca virtual de cada obra. Quem registra o ponto fora da área é sinalizado em vermelho e precisa da sua aprovação.", "El GPS de entrada y salida se valida contra la geocerca de cada obra. Quien registre su entrada fuera del área se marca en rojo y necesita tu aprobación.")}
          {tr("An open shift is", "Um turno aberto é", "Un turno abierto se")} <strong>{tr("auto-closed at the cutoff time", "fechado automaticamente no horário limite", "cierra automáticamente a la hora límite")}</strong> — {tr("no hours count past it unless you extend them with a logged adjustment.", "nenhuma hora conta depois dele, a menos que você as estenda com um ajuste registrado.", "no cuentan horas después de esa hora a menos que las extiendas con un ajuste registrado.")}
        </p>
        <form className="mt-3 grid grid-cols-2 gap-3" onSubmit={(e) => { e.preventDefault(); saveRules.mutate(); }}>
          <Field label={tr("Flag no check-in after", "Sinalizar falta de check-in após", "Marcar ausencia después de")}>
            <input aria-label={tr("No check-in flag time", "Horário para sinalizar falta de check-in", "Hora para marcar la ausencia")} type="time" className={inputCls} value={effCutoff} onChange={(e) => setCutoff(e.target.value)} />
          </Field>
          <Field label={tr("Auto-close shifts at", "Fechar turnos automaticamente às", "Cerrar turnos automáticamente a las")}>
            <input aria-label={tr("Automatic shift close time", "Horário de fechamento automático dos turnos", "Hora de cierre automático de turnos")} type="time" className={inputCls} value={effClose} onChange={(e) => setCloseTime(e.target.value)} />
          </Field>
          <button className={`${btnNavy} col-span-2`} disabled={saveRules.isPending}>{saveRules.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save rules", "Salvar regras", "Guardar reglas")}</button>
        </form>
        {rulesMsg && <p className="mt-2 text-sm font-semibold" role="status">{rulesMsg}</p>}
        <p className="mt-3 rounded-xl bg-[var(--surface2)] px-3 py-2 text-xs text-[var(--dim)]">
          ⚠️ {tr("Honest limit of a web app: with the app", "Limite honesto de um app web: com o app", "Límite honesto de una app web: con la app")} <strong>{tr("open", "aberto", "abierta")}</strong>{tr(", the phone sends its location every 30 minutes. With the app closed or the phone locked, the browser cannot send background location — iOS and Android suspend the page. True continuous background tracking requires the native app (a later phase of SmartBuilder).", ", o celular envia sua localização a cada 30 minutos. Com o app fechado ou o celular bloqueado, o navegador não consegue enviar a localização em segundo plano — iOS e Android suspendem a página. O rastreamento contínuo em segundo plano exige o app nativo (uma fase posterior do SmartBuilder).", ", el teléfono envía su ubicación cada 30 minutos. Con la app cerrada o el teléfono bloqueado, el navegador no puede enviar la ubicación en segundo plano: iOS y Android suspenden la página. El seguimiento continuo en segundo plano requiere la app nativa (una fase posterior de SmartBuilder).")}
        </p>
      </section>
    </div>
  );
}

function jobStatusLabel(status: string): string {
  if (status === "scheduled") return tr("Scheduled", "Agendado", "Programado");
  if (status === "in_progress") return tr("In progress", "Em andamento", "En curso");
  if (status === "done") return tr("Done", "Concluído", "Terminado");
  return status;
}
function jobStatusBadge(status: string) {
  return <Badge text={jobStatusLabel(status)} tone={status === "in_progress" ? "green" : status === "done" ? "navy" : "gray"} />;
}

/* Service picker for the Job form (create + edit). Picking a catalog
   service links the job to it and seeds the job name from the service
   name (still editable via the small rename affordance). "＋ New
   service" quick-adds to the catalog (with the duplicate guard) and
   returns with it selected; "Custom…" falls back to a free-text name
   for one-off jobs that don't belong in the catalog. */
type JobServicePick = { serviceId: number | null; name: string };

function JobServicePicker({ cid, actorId, value, onChange }: {
  cid: string; actorId: number; value: JobServicePick; onChange: (v: JobServicePick) => void;
}) {
  const qc = useQueryClient();
  const catalogQ = useQuery({ queryKey: ["services", cid], queryFn: () => api.listServices({ companyId: cid }) });
  const catalog = catalogQ.data?.services ?? [];
  /* Start in picker mode ("Pick a service…"); fall back to the free-text
     name when editing an existing job that has a name but no catalog
     link (legacy/custom jobs keep their name visible, not hidden). */
  const [customMode, setCustomMode] = useState(value.serviceId === null && value.name.trim() !== "");
  const [nameEditing, setNameEditing] = useState(false);
  /* quick-add state */
  const [qaOpen, setQaOpen] = useState(false);
  const [qaName, setQaName] = useState("");
  const [qaUnitChoice, setQaUnitChoice] = useState<string>("sq ft");
  const [qaCustomUnit, setQaCustomUnit] = useState("");
  const [qaRate, setQaRate] = useState("");
  const [qaError, setQaError] = useState("");
  const [qaDup, setQaDup] = useState<{ kind: "exact" | "near"; match: ServiceLite } | null>(null);
  const qaUnit = qaUnitChoice === "__custom" ? qaCustomUnit.trim() : qaUnitChoice;

  const selectService = (s: ServiceLite) => {
    setCustomMode(false);
    setNameEditing(false);
    setQaOpen(false);
    setQaDup(null);
    setQaError("");
    onChange({ serviceId: s.id, name: s.name });
  };
  const qaCreate = useMutation({
    mutationFn: () => api.createService({ companyId: cid, actorId, name: qaName, unit: qaUnit, defaultRate: parseMoney(qaRate) }),
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["services", cid] });
      const created: ServiceLite = { id: r.id, companyId: cid, name: qaName.trim().replace(/\s+/g, " "), unit: qaUnit, defaultRate: parseMoney(qaRate) };
      setQaName(""); setQaUnitChoice("sq ft"); setQaCustomUnit(""); setQaRate("");
      selectService(created);
    },
    onError: (e) => setQaError(e instanceof Error && e.message.includes("already exists")
      ? tr("This service already exists.", "Este serviço já existe.", "Este servicio ya existe.")
      : tr("Could not save this service. Only an admin or manager can edit the catalog.", "Não foi possível salvar este serviço. Somente um administrador ou gerente pode editar o catálogo.", "No se pudo guardar este servicio. Solo un administrador o gerente puede editar el catálogo.")),
  });
  const submitQuickAdd = (force: boolean) => {
    setQaError("");
    if (!force) {
      const clash = serviceNameClash(qaName, catalog);
      if (clash) { setQaDup(clash); return; }
    }
    setQaDup(null);
    qaCreate.mutate();
  };

  const selectValue = qaOpen ? "__new" : customMode ? "__custom" : value.serviceId !== null ? String(value.serviceId) : "";
  return (
    <div className="space-y-2" onKeyDown={(e) => { if (e.key === "Enter" && (e.target as HTMLElement).tagName === "INPUT") e.preventDefault(); }}>
      <Field label={tr("Service", "Serviço", "Servicio")}>
        <select
          aria-label={tr("Service for this job", "Serviço deste trabalho", "Servicio de este trabajo")}
          className={inputCls}
          value={selectValue}
          onChange={(e) => {
            const v = e.target.value;
            if (v === "__new") { setQaOpen(true); setQaDup(null); setQaError(""); return; }
            if (v === "__custom") { setCustomMode(true); setNameEditing(false); setQaOpen(false); onChange({ serviceId: null, name: value.name }); return; }
            const svc = catalog.find((s) => s.id === Number(v));
            if (svc) selectService(svc);
          }}
        >
          <option value="">{tr("Pick a service…", "Escolha um serviço…", "Elige un servicio…")}</option>
          {catalog.map((s) => <option key={s.id} value={s.id}>{s.name} — {s.unit}{s.defaultRate > 0 ? ` • ${fmtUSD(s.defaultRate)}/${s.unit}` : ""}</option>)}
          <option value="__new">{tr("＋ New service…", "＋ Novo serviço…", "＋ Nuevo servicio…")}</option>
          <option value="__custom">{tr("Custom…", "Personalizado…", "Personalizado…")}</option>
        </select>
      </Field>
      {catalogQ.isSuccess && catalog.length === 0 && !qaOpen && (
        <p className="text-[11px] text-[var(--dim)]">{tr("The Services catalog is empty — use ＋ New service to add the first one, or Custom… for a one-off job.", "O catálogo de serviços está vazio — use ＋ Novo serviço para adicionar o primeiro, ou Personalizado… para um trabalho avulso.", "El catálogo de servicios está vacío: usa ＋ Nuevo servicio para agregar el primero, o Personalizado… para un trabajo único.")}</p>
      )}

      {qaOpen && (
        <div className="space-y-2 rounded-xl border border-[var(--border)] bg-[var(--surface)] p-3">
          <p className="text-sm font-bold">{tr("New service", "Novo serviço", "Nuevo servicio")}</p>
          <Field label={tr("Service name", "Nome do serviço", "Nombre del servicio")}>
            <input aria-label={tr("Quick-add service name", "Nome do serviço rápido", "Nombre del servicio rápido")} className={inputCls} value={qaName} onChange={(e) => { setQaName(e.target.value); setQaDup(null); setQaError(""); }} placeholder={tr("E.g.: Hardwood floor", "Ex.: Piso de madeira", "Ej.: Piso de madera")} />
          </Field>
          <div className="grid grid-cols-2 gap-2">
            <Field label={tr("Unit", "Unidade", "Unidad")}>
              <select aria-label={tr("Quick-add service unit", "Unidade do serviço rápido", "Unidad del servicio rápido")} className={inputCls} value={qaUnitChoice} onChange={(e) => setQaUnitChoice(e.target.value)}>
                {SERVICE_UNIT_PRESETS.map((u) => <option key={u} value={u}>{unitOptionLabel(u)}</option>)}
                <option value="__custom">{tr("Custom unit…", "Unidade personalizada…", "Unidad personalizada…")}</option>
              </select>
            </Field>
            <Field label={tr("Default rate (USD per unit, optional)", "Tarifa padrão (USD por unidade, opcional)", "Tarifa predeterminada (USD por unidad, opcional)")}>
              <input aria-label={tr("Quick-add default rate in US dollars per unit", "Tarifa padrão do serviço rápido em dólares por unidade", "Tarifa predeterminada rápida en dólares por unidad")} className={inputCls} inputMode="decimal" value={qaRate} onChange={(e) => setQaRate(e.target.value)} placeholder="0.00" />
            </Field>
          </div>
          {qaUnitChoice === "__custom" && (
            <Field label={tr("Custom unit label", "Rótulo da unidade personalizada", "Etiqueta de la unidad personalizada")}>
              <input aria-label={tr("Quick-add custom unit label", "Rótulo da unidade personalizada rápida", "Etiqueta de la unidad personalizada rápida")} className={inputCls} value={qaCustomUnit} onChange={(e) => setQaCustomUnit(e.target.value)} placeholder={tr("E.g.: per room, lump sum, sheets", "Ex.: por cômodo, empreitada, chapas", "Ej.: por ambiente, tanto alzado, placas")} />
            </Field>
          )}
          {qaDup?.kind === "exact" && (
            <div className="rounded-lg bg-red-50 px-3 py-2 dark:bg-red-950/40" role="alert">
              <p className="text-xs font-bold text-red-700 dark:text-red-300">{tr("This service already exists.", "Este serviço já existe.", "Este servicio ya existe.")}</p>
              <button type="button" className="mt-1 text-xs font-bold text-[#f97316]" aria-label={tr(`Select the existing service ${qaDup.match.name}`, `Selecionar o serviço existente ${qaDup.match.name}`, `Seleccionar el servicio existente ${qaDup.match.name}`)} onClick={() => selectService(qaDup.match)}>{tr(`Select “${qaDup.match.name}”`, `Selecionar “${qaDup.match.name}”`, `Seleccionar “${qaDup.match.name}”`)}</button>
            </div>
          )}
          {qaDup?.kind === "near" && (
            <div className="rounded-lg bg-amber-50 px-3 py-2 dark:bg-amber-950/40" role="alert">
              <p className="text-xs font-bold text-amber-800 dark:text-amber-200">{tr(`Did you mean “${qaDup.match.name}”?`, `Você quis dizer “${qaDup.match.name}”?`, `¿Quisiste decir “${qaDup.match.name}”?`)}</p>
              <div className="mt-1.5 flex flex-wrap gap-2">
                <button type="button" className={btnNavy} aria-label={tr(`Use the existing service ${qaDup.match.name}`, `Usar o serviço existente ${qaDup.match.name}`, `Usar el servicio existente ${qaDup.match.name}`)} onClick={() => selectService(qaDup.match)}>{tr("Use existing", "Usar o existente", "Usar el existente")}</button>
                <button type="button" className={btnGhost} aria-label={tr("Create the new service anyway", "Criar o novo serviço mesmo assim", "Crear el nuevo servicio de todos modos")} disabled={qaCreate.isPending} onClick={() => submitQuickAdd(true)}>{tr("Create new anyway", "Criar novo mesmo assim", "Crear nuevo de todos modos")}</button>
              </div>
            </div>
          )}
          {qaError && <p className="text-xs font-semibold text-red-600" role="alert">{qaError}</p>}
          <div className="flex gap-2">
            <button type="button" className={btnGhost} onClick={() => { setQaOpen(false); setQaDup(null); setQaError(""); }}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
            <button type="button" className={`${btnNavy} flex-1`} disabled={qaCreate.isPending || !qaName.trim() || !qaUnit} onClick={() => submitQuickAdd(false)}>{qaCreate.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Add service", "Adicionar serviço", "Agregar servicio")}</button>
          </div>
        </div>
      )}

      {!qaOpen && (customMode || nameEditing) && (
        <Field label={tr("Job name", "Nome do trabalho", "Nombre del trabajo")}>
          <input aria-label={tr("Job name", "Nome do trabalho", "Nombre del trabajo")} className={inputCls} value={value.name} onChange={(e) => onChange({ serviceId: value.serviceId, name: e.target.value })} placeholder={tr("E.g.: Roof replacement", "Ex.: Troca do telhado", "Ej.: Reemplazo del techo")} required />
        </Field>
      )}
      {!qaOpen && !customMode && !nameEditing && value.serviceId !== null && (
        <div className="flex items-center justify-between gap-2">
          <p className="min-w-0 truncate text-sm"><span className="font-semibold">{value.name}</span> <span className="text-[var(--dim)]">• {tr("from the catalog", "do catálogo", "del catálogo")}</span></p>
          <button type="button" className="shrink-0 text-xs font-bold text-[#f97316]" aria-label={tr("Edit the job name", "Editar o nome do trabalho", "Editar el nombre del trabajo")} onClick={() => setNameEditing(true)}>{tr("✏️ Edit name", "✏️ Editar nome", "✏️ Editar nombre")}</button>
        </div>
      )}
    </div>
  );
}

/* One job (trade) inside a project: scope, status, dates, crew, labor roll-up. */
type JobItem = { id: number; projectId: number; serviceId: number | null; serviceName: string; serviceUnit: string; name: string; scope: string; status: string; startDate: string; endDate: string; estimatedValue: number; laborCost: number; laborHours: number; crewIds: number[] };
type EmpLite = { id: number; name: string; trade: string; payType: string; payRate: number; status: string };

/* Compact, tappable job row for the project detail job list. Tapping opens
   the full JobDetailView for that job (its own estimate, crew, and tasks).
   Task counts reuse the same cached listTasks query the detail view runs. */
function JobRow({ cid, job, canManage, actorId, onOpen, showMoney = false }: {
  cid: string; job: JobItem; canManage: boolean; actorId: number; onOpen: () => void; showMoney?: boolean;
}) {
  const tasksQ = useQuery({ queryKey: ["job-tasks", cid, job.id], queryFn: () => api.listTasks({ companyId: cid, jobId: job.id, actorId }) });
  const rowTasks = tasksQ.data?.tasks ?? [];
  const doneCount = rowTasks.filter((t) => t.status === "done").length;
  return (
    <button
      type="button"
      onClick={onOpen}
      aria-label={tr(`Open job ${job.name}`, `Abrir o trabalho ${job.name}`, `Abrir el trabajo ${job.name}`)}
      className="flex w-full items-center gap-3 rounded-xl border border-[var(--border)] bg-[var(--surface2)] p-3 text-left active:opacity-70"
    >
      <div className="min-w-0 flex-1">
        <p className="truncate font-bold leading-snug">🔧 {job.name}</p>
        <p className="mt-0.5 text-xs text-[var(--dim)]">
          {rowTasks.length > 0
            ? `${doneCount}/${rowTasks.length} ${tr("tasks done", "tarefas concluídas", "tareas terminadas")}`
            : tr("No tasks yet", "Nenhuma tarefa ainda", "Todavía no hay tareas")}
          {showMoney && job.estimatedValue > 0 ? ` • ${tr("Estimate", "Estimativa", "Estimación")} ${fmtUSD(job.estimatedValue)}` : ""}
        </p>
        {rowTasks.length > 0 && (
          <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[var(--surface)]" role="progressbar" aria-valuenow={Math.round((doneCount / rowTasks.length) * 100)} aria-valuemin={0} aria-valuemax={100} aria-label={tr(`Task progress for ${job.name}`, `Andamento das tarefas de ${job.name}`, `Progreso de las tareas de ${job.name}`)}>
            <div className="h-full rounded-full bg-green-600" style={{ width: `${Math.round((doneCount / rowTasks.length) * 100)}%` }} />
          </div>
        )}
      </div>
      {jobStatusBadge(job.status)}
      <span aria-hidden="true" className="text-lg font-black text-[var(--dim)]">›</span>
    </button>
  );
}

function JobDetailView({ cid, projectId, projectName, job, employees, canManage, actorId, onBack }: {
  cid: string; projectId: number; projectName: string; job: JobItem; employees: EmpLite[]; canManage: boolean; actorId: number; onBack: () => void;
}) {
  const qc = useQueryClient();
  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["project-detail", cid, projectId] });
    qc.invalidateQueries({ queryKey: ["projects", cid] });
    qc.invalidateQueries({ queryKey: ["my-today", cid] });
    qc.invalidateQueries({ queryKey: ["alerts", cid] });
    qc.invalidateQueries({ queryKey: ["job-tasks", cid, job.id] });
    qc.invalidateQueries({ queryKey: ["my-tasks", cid] });
  };
  const [editing, setEditing] = useState(false);
  const [fPick, setFPick] = useState<JobServicePick>({ serviceId: job.serviceId, name: job.name });
  const [fScope, setFScope] = useState(job.scope);
  const [fStatus, setFStatus] = useState(job.status);
  const [fStart, setFStart] = useState(job.startDate);
  const [fEnd, setFEnd] = useState(job.endDate);
  const [fEst, setFEst] = useState("");
  const [msg, setMsg] = useState("");
  const [addEmpId, setAddEmpId] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(false);
  /* Per-job estimate: each job carries its own estimated value (the project
     total and the invoice pull come from these). Editable on its own here —
     no need to open the full job edit form just to change the number. */
  const [estInput, setEstInput] = useState<string | null>(null);
  const [estMsg, setEstMsg] = useState("");
  const saveEst = useMutation({
    mutationFn: () => api.updateJob({ companyId: cid, actorId, jobId: job.id, estimatedValue: parseMoney(estInput ?? "") }),
    onSuccess: () => { invalidate(); setEstInput(null); setEstMsg(tr("Job estimate saved. ✅", "Estimativa do trabalho salva. ✅", "Estimación del trabajo guardada. ✅")); },
    onError: () => setEstMsg(tr("Could not save this job's estimate. Only an admin or manager can change it.", "Não foi possível salvar a estimativa deste trabalho. Somente um administrador ou gerente pode alterá-la.", "No se pudo guardar la estimación de este trabajo. Solo un administrador o gerente puede cambiarla.")),
  });

  const saveJob = useMutation({
    mutationFn: () => api.updateJob({ companyId: cid, actorId, jobId: job.id, name: fPick.name, serviceId: fPick.serviceId, scope: fScope, status: fStatus as "scheduled" | "in_progress" | "done", startDate: fStart, endDate: fEnd, estimatedValue: fEst.trim() ? parseMoney(fEst) : job.estimatedValue }),
    onSuccess: () => { invalidate(); setEditing(false); setMsg(tr("Job saved. ✅", "Trabalho salvo. ✅", "Trabajo guardado. ✅")); },
    onError: () => setMsg(tr("Could not save this job. Only an admin or manager can edit jobs.", "Não foi possível salvar este trabalho. Somente um administrador ou gerente pode editar trabalhos.", "No se pudo guardar este trabajo. Solo un administrador o gerente puede editar trabajos.")),
  });
  const deleteJob = useMutation({
    mutationFn: () => api.deleteJob({ companyId: cid, actorId, jobId: job.id }),
    onSuccess: () => { invalidate(); },
    onError: () => setMsg(tr("Could not delete this job.", "Não foi possível excluir este trabalho.", "No se pudo eliminar este trabajo.")),
  });
  const addCrew = useMutation({
    mutationFn: (employeeId: number) => api.assignJobEmployee({ companyId: cid, actorId, projectId, jobId: job.id, employeeId }),
    onSuccess: () => { invalidate(); setAddEmpId(""); },
  });
  const removeCrew = useMutation({
    mutationFn: (employeeId: number) => api.unassignJobEmployee({ companyId: cid, projectId, jobId: job.id, employeeId }),
    onSuccess: () => { invalidate(); },
  });

  /* --- Job checklist (tasks) --- */
  const tasksQ = useQuery({ queryKey: ["job-tasks", cid, job.id], queryFn: () => api.listTasks({ companyId: cid, jobId: job.id, actorId }) });
  const jobTasks = tasksQ.data?.tasks ?? [];
  const doneCount = jobTasks.filter((t) => t.status === "done").length;
  const pctDone = jobTasks.length > 0 ? Math.round((doneCount / jobTasks.length) * 100) : 0;
  const [showAddTask, setShowAddTask] = useState(false);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskNotes, setNewTaskNotes] = useState("");
  const [newTaskAssignees, setNewTaskAssignees] = useState<Set<number>>(new Set());
  const [taskMsg, setTaskMsg] = useState("");
  const addTask = useMutation({
    mutationFn: () => api.createTask({ companyId: cid, actorId, jobId: job.id, title: newTaskTitle, notes: newTaskNotes, assigneeIds: [...newTaskAssignees] }),
    onSuccess: () => { invalidate(); setNewTaskTitle(""); setNewTaskNotes(""); setNewTaskAssignees(new Set()); setShowAddTask(false); setTaskMsg(tr("Task added. ✅", "Tarefa adicionada. ✅", "Tarea agregada. ✅")); },
    onError: () => setTaskMsg(tr("Could not add this task. Only an admin or manager can add tasks.", "Não foi possível adicionar esta tarefa. Somente um administrador ou gerente pode adicionar tarefas.", "No se pudo agregar esta tarea. Solo un administrador o gerente puede agregar tareas.")),
  });

  const crew = employees.filter((e) => job.crewIds.includes(e.id));
  const jobProfit = job.estimatedValue - job.laborCost;
  const showJobProfit = canManage && job.estimatedValue > 0;

  return (
    <>
      <button type="button" onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr(`Back to ${projectName}`, `Voltar para ${projectName}`, `Volver a ${projectName}`)}>← {tr("Back to", "Voltar para", "Volver a")} {projectName}</button>
      <div className="rounded-xl border border-[var(--border)] bg-[var(--surface2)] p-3">
      <div className="flex items-start justify-between gap-2">
        <p className="min-w-0 font-bold leading-snug">🔧 {job.name}</p>
        {jobStatusBadge(job.status)}
      </div>
      {job.serviceId !== null && job.serviceName && (
        <p className="mt-0.5 text-xs font-semibold text-[var(--dim)]" aria-label={tr(`Service: ${job.serviceName}, measured in ${job.serviceUnit}`, `Serviço: ${job.serviceName}, medido em ${job.serviceUnit}`, `Servicio: ${job.serviceName}, medido en ${job.serviceUnit}`)}>🧱 {job.serviceName} • {job.serviceUnit}</p>
      )}
      {(job.startDate || job.endDate) && <p className="mt-0.5 text-xs text-[var(--dim)]">{job.startDate ? fmtDate(job.startDate) : "…"} → {job.endDate ? fmtDate(job.endDate) : "…"}</p>}

      <div className="mt-2 rounded-lg bg-[var(--surface)] p-2.5" aria-label={tr(`What to do for ${job.name}`, `O que fazer em ${job.name}`, `Qué hacer en ${job.name}`)}>
        <p className="text-[11px] font-black uppercase tracking-wide text-[#f97316]">{tr("What to do", "O que fazer", "Qué hacer")}</p>
        {job.scope ? <p className="mt-0.5 whitespace-pre-line text-sm leading-relaxed">{job.scope}</p> : <p className="mt-0.5 text-sm text-[var(--dim)]">{tr("No description yet.", "Nenhuma descrição ainda.", "Todavía no hay descripción.")}</p>}
      </div>

      {/* Per-job estimate — editable on its own for managers */}
      {canManage && (
        <div className="mt-2 rounded-lg bg-[var(--surface)] p-2.5">
          <p className="text-[11px] font-black uppercase tracking-wide text-[#f97316]">{tr("This job's estimate", "Estimativa deste trabalho", "Estimación de este trabajo")}</p>
          <Field label={tr("Job estimated value (USD)", "Valor estimado do trabalho (USD)", "Valor estimado del trabajo (USD)")}>
            <div className="mt-1 flex gap-2">
              <input
                aria-label={tr(`Estimated value for ${job.name} in US dollars`, `Valor estimado de ${job.name} em dólares`, `Valor estimado de ${job.name} en dólares`)}
                className={inputCls}
                inputMode="decimal"
                value={estInput ?? moneyInput(job.estimatedValue)}
                onChange={(e) => { setEstInput(e.target.value); setEstMsg(""); }}
                placeholder="4,500.00"
              />
              <button
                type="button"
                className={btnNavy}
                aria-label={tr(`Save the estimate for ${job.name}`, `Salvar a estimativa de ${job.name}`, `Guardar la estimación de ${job.name}`)}
                disabled={saveEst.isPending || estInput === null || parseMoney(estInput ?? "") === job.estimatedValue}
                onClick={() => saveEst.mutate()}
              >
                {saveEst.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save estimate", "Salvar estimativa", "Guardar estimación")}
              </button>
            </div>
          </Field>
          {estMsg && <p className="mt-1 text-xs font-semibold" role="status">{estMsg}</p>}
          <p className="mt-1 text-[11px] text-[var(--dim)]">{tr("Each job has its own estimate — the project total and the invoice pull are built from these per-job numbers, one job at a time.", "Cada trabalho tem sua própria estimativa — o total da obra e a puxada para a fatura são montados a partir desses valores, um trabalho por vez.", "Cada trabajo tiene su propia estimación: el total de la obra y la transferencia a la factura se arman con estos valores, un trabajo a la vez.")}</p>
        </div>
      )}

      {canManage && (
        <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs">
          <span className="text-[var(--dim)]">{tr("Labor:", "Mão de obra:", "Mano de obra:")} <span className="font-bold text-[var(--text)]">{job.laborHours.toFixed(1)}h • {fmtUSD(job.laborCost)}</span></span>
          {job.estimatedValue > 0 && <span className="text-[var(--dim)]">{tr("Job estimate:", "Estimativa do trabalho:", "Estimación del trabajo:")} <span className="font-bold text-[var(--text)]">{fmtUSD(job.estimatedValue)}</span></span>}
          {showJobProfit && (
            <span className={`inline-flex items-center rounded-full px-2 py-0.5 font-bold ${jobProfit < 0 ? "bg-red-100 text-red-700" : "bg-green-100 text-green-800"}`} aria-label={tr(`Job profit ${fmtUSD(jobProfit)} before materials`, `Lucro do trabalho de ${fmtUSD(jobProfit)} antes dos materiais`, `Ganancia del trabajo de ${fmtUSD(jobProfit)} antes de los materiales`)}>
              {fmtUSD(jobProfit)} {tr("job profit*", "de lucro do trabalho*", "de ganancia del trabajo*")}
            </span>
          )}
        </div>
      )}
      {showJobProfit && <p className="mt-0.5 text-[11px] text-[var(--dim)]">{tr("* Estimate minus this job's labor. Materials stay at the project level.", "* Estimativa menos a mão de obra deste trabalho. Os materiais ficam no nível da obra.", "* Estimación menos la mano de obra de este trabajo. Los materiales quedan a nivel de la obra.")}</p>}

      <div className="mt-2">
        <p className="text-[11px] font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Crew on this job", "Equipe neste trabalho", "Equipo en este trabajo")} ({crew.length})</p>
        <div className="mt-1 space-y-1">
          {crew.map((e) => (
            <div key={e.id} className="flex items-center justify-between gap-2 rounded-lg bg-[var(--surface)] px-2.5 py-1.5 text-sm">
              <span className="min-w-0"><span className="font-semibold">{e.name}</span>{e.trade ? <span className="text-[var(--dim)]"> • {e.trade}</span> : null}</span>
              {canManage && <button type="button" aria-label={tr(`Remove ${e.name} from ${job.name}`, `Remover ${e.name} de ${job.name}`, `Quitar a ${e.name} de ${job.name}`)} onClick={() => removeCrew.mutate(e.id)} className="shrink-0 text-xs font-bold text-red-600">{tr("Remove", "Remover", "Quitar")}</button>}
            </div>
          ))}
          {crew.length === 0 && <p className="text-xs text-[var(--dim)]">{tr("Nobody on this crew yet.", "Ninguém nesta equipe ainda.", "Todavía no hay nadie en este equipo.")}</p>}
        </div>
        {canManage && (
          <div className="mt-2 flex gap-2">
            <select aria-label={tr(`Employee to add to ${job.name}`, `Funcionário para adicionar a ${job.name}`, `Empleado para agregar a ${job.name}`)} className={inputCls} value={addEmpId} onChange={(e) => setAddEmpId(e.target.value)}>
              <option value="">{tr("Add to crew…", "Adicionar à equipe…", "Agregar al equipo…")}</option>
              {employees.filter((e) => !job.crewIds.includes(e.id) && e.status === "ativo").map((e) => <option key={e.id} value={e.id}>{e.name} — {e.trade}</option>)}
            </select>
            <button type="button" className={btnNavy} disabled={!addEmpId || addCrew.isPending} aria-label={tr(`Add selected employee to ${job.name}`, `Adicionar o funcionário selecionado a ${job.name}`, `Agregar al empleado seleccionado a ${job.name}`)} onClick={() => addCrew.mutate(Number(addEmpId))}>{tr("Add", "Adicionar", "Agregar")}</button>
          </div>
        )}
      </div>

      {/* ---- Job checklist: tasks the crew works in any order ---- */}
      <div className="mt-3 border-t border-[var(--border)] pt-3">
        <div className="flex items-center justify-between gap-2">
          <p className="text-[11px] font-bold uppercase tracking-wide text-[var(--dim)]">✅ {tr("Tasks", "Tarefas", "Tareas")} ({doneCount}/{jobTasks.length} {tr("done", "concluídas", "terminadas")})</p>
          {canManage && (
            <button type="button" aria-label={tr(`Add task to ${job.name}`, `Adicionar tarefa a ${job.name}`, `Agregar tarea a ${job.name}`)} aria-expanded={showAddTask} className="shrink-0 rounded-lg bg-[#f97316] px-3 py-1.5 text-xs font-bold text-white active:opacity-80" onClick={() => { setShowAddTask((s) => !s); setTaskMsg(""); }}>
              {showAddTask ? tr("Close", "Fechar", "Cerrar") : tr("+ Add task", "+ Adicionar tarefa", "+ Agregar tarea")}
            </button>
          )}
        </div>
        {jobTasks.length > 0 && (
          <div className="mt-2">
            <div className="flex justify-between text-[11px] font-semibold text-[var(--dim)]"><span>{tr("Progress", "Andamento", "Progreso")}</span><span>{doneCount} {tr("of", "de", "de")} {jobTasks.length} • {pctDone}%</span></div>
            <div className="mt-1 h-2 overflow-hidden rounded-full bg-[var(--surface)]" role="progressbar" aria-valuenow={pctDone} aria-valuemin={0} aria-valuemax={100} aria-label={tr(`Task progress for ${job.name}`, `Andamento das tarefas de ${job.name}`, `Progreso de las tareas de ${job.name}`)}>
              <div className="h-full rounded-full bg-green-600" style={{ width: `${pctDone}%` }} />
            </div>
          </div>
        )}
        {tasksQ.isPending && <p className="mt-2 text-xs text-[var(--dim)]">{tr("Loading tasks…", "Carregando tarefas…", "Cargando tareas…")}</p>}
        {!tasksQ.isPending && jobTasks.length === 0 && (
          <p className="mt-2 text-xs text-[var(--dim)]">{tr("No tasks yet.", "Nenhuma tarefa ainda.", "Todavía no hay tareas.")}{canManage ? tr(" Break this job into steps the crew can start in any order and check off.", " Divida este trabalho em etapas que a equipe pode começar em qualquer ordem e ir marcando.", " Divide este trabajo en pasos que el equipo puede empezar en cualquier orden e ir marcando.") : ""}</p>
        )}
        {canManage && showAddTask && (
          <form className="mt-2 space-y-2 rounded-lg bg-[var(--surface)] p-2.5" onSubmit={(e) => { e.preventDefault(); addTask.mutate(); }}>
            <Field label={tr("Task title", "Título da tarefa", "Título de la tarea")}><input aria-label={tr("New task title", "Título da nova tarefa", "Título de la nueva tarea")} className={inputCls} value={newTaskTitle} onChange={(e) => setNewTaskTitle(e.target.value)} placeholder={tr("E.g.: Install ridge vent", "Ex.: Instalar a cumeeira ventilada", "Ej.: Instalar la ventilación de cumbrera")} required /></Field>
            <Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><textarea aria-label={tr("New task notes", "Observações da nova tarefa", "Notas de la nueva tarea")} className={inputCls} rows={2} value={newTaskNotes} onChange={(e) => setNewTaskNotes(e.target.value)} placeholder={tr("Anything the crew should know…", "Tudo o que a equipe precisa saber…", "Todo lo que el equipo debe saber…")} /></Field>
            <Field label={tr("Assigned to — pick one or several", "Atribuído a — escolha um ou vários", "Asignado a: elige uno o varios")}>
              <AssigneeMultiPicker idPrefix={`new-task-${job.id}`} options={crew} selected={newTaskAssignees} onChange={setNewTaskAssignees} />
            </Field>
            {crew.length === 0 && <p className="text-[11px] text-[var(--dim)]">{tr("No crew on this job yet — the task goes to the whole crew until the job has a crew.", "Nenhuma equipe neste trabalho ainda — a tarefa vai para a equipe toda até o trabalho ter uma equipe.", "Todavía no hay equipo en este trabajo: la tarea va a todo el equipo hasta que el trabajo tenga un equipo.")}</p>}
            <button className={`${btnNavy} w-full`} disabled={addTask.isPending || !newTaskTitle.trim()}>{addTask.isPending ? tr("Adding…", "Adicionando…", "Agregando…") : tr("Add task", "Adicionar tarefa", "Agregar tarea")}</button>
          </form>
        )}
        {taskMsg && <p className="mt-1 text-xs font-semibold" role="status">{taskMsg}</p>}

        {TASK_STATUS_GROUPS.map((g) => {
          const group = jobTasks.filter((t) => t.status === g.key);
          if (group.length === 0) return null;
          return (
            <div key={g.key} className="mt-3">
              <p className="text-[11px] font-black uppercase tracking-wide text-[var(--dim)]">{taskStatusLabel(g.key)} ({group.length})</p>
              <div className="mt-1.5 space-y-2">
                {group.map((t) => (
                  <TaskItem key={t.id} cid={cid} task={t} actorId={actorId} canManage={canManage} manageControls={canManage} employees={crew} />
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {canManage && !editing && (
        <div className="mt-2 flex gap-3">
          <button type="button" aria-label={tr(`Edit job ${job.name}`, `Editar o trabalho ${job.name}`, `Editar el trabajo ${job.name}`)} className="text-xs font-bold text-[#f97316]" onClick={() => { setFPick({ serviceId: job.serviceId, name: job.name }); setFScope(job.scope); setFStatus(job.status); setFStart(job.startDate); setFEnd(job.endDate); setFEst(moneyInput(job.estimatedValue)); setMsg(""); setEditing(true); }}>{tr("Edit job", "Editar trabalho", "Editar trabajo")}</button>
          <button type="button" aria-label={tr(`Mark ${job.name} as done`, `Marcar ${job.name} como concluído`, `Marcar ${job.name} como terminado`)} className="text-xs font-bold text-[#0f2a44] dark:text-white" disabled={job.status === "done" || saveJob.isPending} onClick={() => api.updateJob({ companyId: cid, actorId, jobId: job.id, status: "done" }).then(invalidate)}>{tr("Mark done", "Marcar como concluído", "Marcar como terminado")}</button>
        </div>
      )}

      {canManage && editing && (
        <form className="mt-2 space-y-2 rounded-lg bg-[var(--surface)] p-3" onSubmit={(e) => { e.preventDefault(); if (fPick.name.trim()) saveJob.mutate(); }}>
          <JobServicePicker cid={cid} actorId={actorId} value={fPick} onChange={setFPick} />
          <Field label={tr("Scope — what to do", "Escopo — o que fazer", "Alcance: qué hacer")}><textarea aria-label={tr("Job scope of work", "Escopo do trabalho", "Alcance del trabajo")} className={inputCls} rows={4} value={fScope} onChange={(e) => setFScope(e.target.value)} placeholder={tr("Describe exactly what this crew needs to do…", "Descreva exatamente o que esta equipe precisa fazer…", "Describe exactamente lo que este equipo debe hacer…")} /></Field>
          <div className="grid grid-cols-3 gap-2">
            <Field label={tr("Status", "Status", "Estado")}>
              <select aria-label={tr("Job status", "Status do trabalho", "Estado del trabajo")} className={inputCls} value={fStatus} onChange={(e) => setFStatus(e.target.value)}>
                <option value="scheduled">{tr("Scheduled", "Agendado", "Programado")}</option><option value="in_progress">{tr("In progress", "Em andamento", "En curso")}</option><option value="done">{tr("Done", "Concluído", "Terminado")}</option>
              </select>
            </Field>
            <Field label={tr("Start", "Início", "Inicio")}><input aria-label={tr("Job start date", "Data de início do trabalho", "Fecha de inicio del trabajo")} type="date" className={inputCls} value={fStart} onChange={(e) => setFStart(e.target.value)} /></Field>
            <Field label={tr("End", "Fim", "Fin")}><input aria-label={tr("Job end date", "Data de término do trabalho", "Fecha de fin del trabajo")} type="date" className={inputCls} value={fEnd} onChange={(e) => setFEnd(e.target.value)} /></Field>
          </div>
          <Field label={tr("Job estimated value (USD, optional)", "Valor estimado do trabalho (USD, opcional)", "Valor estimado del trabajo (USD, opcional)")}><input aria-label={tr("Job estimated value in US dollars", "Valor estimado do trabalho em dólares", "Valor estimado del trabajo en dólares")} className={inputCls} inputMode="decimal" value={fEst} onChange={(e) => setFEst(e.target.value)} placeholder="4,500.00" /></Field>
          {msg && <p className="text-xs font-semibold text-red-600" role="alert">{msg}</p>}
          <div className="flex gap-2">
            <button type="button" className={btnGhost} onClick={() => setEditing(false)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
            <button className={`${btnNavy} flex-1`} disabled={saveJob.isPending || !fPick.name.trim()}>{saveJob.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save job", "Salvar trabalho", "Guardar trabajo")}</button>
          </div>
          <div className="border-t border-[var(--border)] pt-2">
            {confirmDelete ? (
              <div className="flex items-center gap-2">
                <p className="flex-1 text-xs font-semibold text-red-700">{tr("Delete this job? Crew assignments clear; timesheets keep their hours but lose the job label.", "Excluir este trabalho? As atribuições da equipe são apagadas; os registros de ponto mantêm as horas, mas perdem o vínculo com o trabalho.", "¿Eliminar este trabajo? Las asignaciones del equipo se borran; los registros de horas conservan las horas, pero pierden la etiqueta del trabajo.")}</p>
                <button type="button" className={btnGhost} onClick={() => setConfirmDelete(false)}>{tr("Keep", "Manter", "Conservar")}</button>
                <button type="button" className="rounded-xl bg-red-600 px-4 py-2.5 font-semibold text-white active:opacity-80 disabled:opacity-40" aria-label={tr(`Confirm delete job ${job.name}`, `Confirmar a exclusão do trabalho ${job.name}`, `Confirmar la eliminación del trabajo ${job.name}`)} disabled={deleteJob.isPending} onClick={() => deleteJob.mutate()}>{tr("Delete", "Excluir", "Eliminar")}</button>
              </div>
            ) : (
              <button type="button" className="text-xs font-bold text-red-600" aria-label={tr(`Delete job ${job.name}`, `Excluir o trabalho ${job.name}`, `Eliminar el trabajo ${job.name}`)} onClick={() => setConfirmDelete(true)}>{tr("Delete job", "Excluir trabalho", "Eliminar trabajo")}</button>
            )}
          </div>
        </form>
      )}
      {msg && !editing && <p className="mt-1 text-xs font-semibold" role="status">{msg}</p>}
      </div>
    </>
  );
}

/* ---------------- Dispatch (work distribution hub) ----------------
   One screen for the manager: Project -> Jobs -> Tasks, with crew on the
   job and a named assignee (or Whole crew / Unassigned) on every task.
   Mental model, stated in the UI: "Jobs have crews. Tasks have assignees."
   A task is Unassigned when it has no specific assignee AND its job has
   no crew yet; with a crew in place, a task with no specific person is
   covered by the Whole crew and follows that crew automatically. */
type DispatchCrewMember = { id: number; name: string; trade: string };
type DispatchAssignCtx = { task: TaskLite; jobName: string; projectName: string; projectId: number; jobId: number; crew: DispatchCrewMember[] };
type DispatchCrewCtx = { jobId: number; jobName: string; projectId: number; crewIds: number[] };

function dispatchTaskUnassigned(task: TaskLite, crewCount: number): boolean {
  return taskAssigneeIds(task).length === 0 && crewCount === 0;
}
function shiftDateStr(dateStr: string, days: number): string {
  const d = new Date(`${dateStr}T12:00:00`);
  d.setDate(d.getDate() + days);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function DispatchView({ cid, session }: { cid: string; session: Session }) {
  const qc = useQueryClient();
  const [date, setDate] = useState(todayInput());
  const isToday = date === todayInput();
  const [unassignedOnly, setUnassignedOnly] = useState(false);
  const [expandedJobs, setExpandedJobs] = useState<Set<number>>(new Set());
  const [assignCtx, setAssignCtx] = useState<DispatchAssignCtx | null>(null);
  const [crewCtx, setCrewCtx] = useState<DispatchCrewCtx | null>(null);
  const [sheetSearch, setSheetSearch] = useState("");
  const [assignSelection, setAssignSelection] = useState<Set<number>>(new Set());
  const openAssignSheet = (ctx: DispatchAssignCtx) => {
    setAssignCtx(ctx);
    setAssignSelection(new Set(taskAssigneeIds(ctx.task)));
    setSheetSearch("");
  };
  const [crewSearch, setCrewSearch] = useState("");
  const [crewSelection, setCrewSelection] = useState<Set<number>>(new Set());
  const [saveMsg, setSaveMsg] = useState("");

  const dispatchQ = useQuery({ queryKey: ["dispatch", cid, date], queryFn: () => api.getDispatch({ companyId: cid, actorId: session.userId, date }) });
  const employeesQ = useQuery({ queryKey: ["employees", cid], queryFn: () => api.listEmployees({ companyId: cid }) });
  const allEmployees = employeesQ.data?.employees ?? [];
  const assignableEmployees = allEmployees.filter((e) => e.status === "ativo" && e.role !== "cliente");

  const invalidateDispatch = () => {
    qc.invalidateQueries({ queryKey: ["dispatch", cid] });
    qc.invalidateQueries({ queryKey: ["my-tasks", cid] });
    qc.invalidateQueries({ queryKey: ["job-tasks", cid] });
    qc.invalidateQueries({ queryKey: ["project-detail", cid] });
  };

  const assignTaskMut = useMutation({
    mutationFn: (args: { taskId: number; assigneeIds: number[] }) => api.updateTask({ companyId: cid, actorId: session.userId, taskId: args.taskId, assigneeIds: args.assigneeIds }),
    onSuccess: () => { invalidateDispatch(); setAssignCtx(null); setSheetSearch(""); setSaveMsg(tr("Assignees saved. ✅", "Responsáveis salvos. ✅", "Responsables guardados. ✅")); },
    onError: () => setSaveMsg(tr("Could not save this assignment. Try again.", "Não foi possível salvar esta atribuição. Tente novamente.", "No se pudo guardar esta asignación. Inténtalo de nuevo.")),
  });

  const saveCrewMut = useMutation({
    mutationFn: async (args: { ctx: DispatchCrewCtx; next: Set<number> }) => {
      const current = new Set(args.ctx.crewIds);
      for (const id of args.next) {
        if (!current.has(id)) await api.assignJobEmployee({ companyId: cid, actorId: session.userId, projectId: args.ctx.projectId, jobId: args.ctx.jobId, employeeId: id });
      }
      for (const id of current) {
        if (!args.next.has(id)) await api.unassignJobEmployee({ companyId: cid, projectId: args.ctx.projectId, jobId: args.ctx.jobId, employeeId: id });
      }
    },
    onSuccess: () => { invalidateDispatch(); setCrewCtx(null); setCrewSearch(""); setSaveMsg(tr("Crew saved. Whole-crew tasks now follow this crew. ✅", "Equipe salva. As tarefas da equipe toda agora seguem esta equipe. ✅", "Equipo guardado. Las tareas de todo el equipo ahora siguen a este equipo. ✅")); },
    onError: () => setSaveMsg(tr("Could not save this crew. Try again.", "Não foi possível salvar esta equipe. Tente novamente.", "No se pudo guardar este equipo. Inténtalo de nuevo.")),
  });

  const openCrewSheet = (ctx: DispatchCrewCtx) => {
    setCrewCtx(ctx);
    setCrewSelection(new Set(ctx.crewIds));
    setCrewSearch("");
  };

  const projectsRaw = dispatchQ.data?.projects ?? [];
  const unassignedCount = dispatchQ.data?.unassignedCount ?? 0;

  /* When "Unassigned only" is on, keep only the jobs/tasks that still
     need a person (auto-expanding them so the manager lands on the work). */
  const projects = projectsRaw.map((p) => {
    if (!unassignedOnly) return p;
    const jobs = p.jobs.map((j) => ({ ...j, tasks: j.tasks.filter((t) => dispatchTaskUnassigned(t, j.crew.length)) })).filter((j) => j.tasks.length > 0);
    return { ...p, jobs };
  }).filter((p) => p.jobs.length > 0);

  const isExpanded = (jobId: number, hasUnassigned: boolean) => unassignedOnly ? true : expandedJobs.has(jobId) || (expandedJobs.size === 0 && hasUnassigned);
  const toggleJob = (jobId: number) => setExpandedJobs((prev) => {
    const next = new Set(prev);
    // When nothing has been toggled yet, jobs with unassigned work start
    // open; the first tap records the explicit state for every such job.
    if (next.size === 0) {
      for (const p of projectsRaw) for (const j of p.jobs) if (j.unassignedCount > 0 && j.jobId !== jobId) next.add(j.jobId);
      if (!next.has(jobId)) next.add(jobId); else next.delete(jobId);
      // Ensure the tapped job ends up toggled from its initial open state:
      if (hasUnassignedInitial(jobId)) next.delete(jobId); else next.add(jobId);
      return next;
    }
    if (next.has(jobId)) next.delete(jobId); else next.add(jobId);
    return next;
  });
  const hasUnassignedInitial = (jobId: number) => projectsRaw.some((p) => p.jobs.some((j) => j.jobId === jobId && j.unassignedCount > 0));

  const sheetCrew = assignCtx ? assignCtx.crew.filter((c) => c.name.toLowerCase().includes(sheetSearch.trim().toLowerCase()) || c.trade.toLowerCase().includes(sheetSearch.trim().toLowerCase())) : [];
  const crewCandidates = assignableEmployees.filter((e) => e.name.toLowerCase().includes(crewSearch.trim().toLowerCase()) || e.trade.toLowerCase().includes(crewSearch.trim().toLowerCase()));

  return (
    <div className="space-y-4">
      <div className="print:hidden">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-bold">{tr("Dispatch", "Distribuição", "Distribución")}</h2>
          <button type="button" className={btnGhost} onClick={() => window.print()} aria-label={tr("Print or save as PDF", "Imprimir ou salvar como PDF", "Imprimir o guardar como PDF")}>🖨️ {tr("Print / PDF", "Imprimir / PDF", "Imprimir / PDF")}</button>
        </div>
        <p className="text-sm text-[var(--dim)]">{tr("Work distribution — who does what, on every project, at a glance.", "Distribuição de trabalhos — quem faz o quê, em cada obra, de relance.", "Distribución de trabajos: quién hace qué, en cada obra, de un vistazo.")}</p>
        <p className="mt-2 rounded-xl bg-[#0f2a44] px-3 py-2 text-sm font-bold text-white">{tr("Jobs have crews. Tasks have assignees.", "Trabalhos têm equipes. Tarefas têm responsáveis.", "Los trabajos tienen equipos. Las tareas tienen responsables.")}</p>
      </div>
      <div className="hidden print:block">
        <h2 className="text-xl font-bold">{tr("Dispatch", "Distribuição", "Distribución")} — {date}</h2>
        <p className="text-sm text-gray-600">{session.companyName}</p>
      </div>

      {/* Day selector + Unassigned filter */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex items-center gap-1 rounded-xl border border-[var(--border)] bg-[var(--surface)] p-1" role="group" aria-label={tr("Day selector", "Seletor de dia", "Selector de día")}>
          <button type="button" aria-label={tr("Previous day", "Dia anterior", "Día anterior")} onClick={() => setDate((d) => shiftDateStr(d, -1))} className="rounded-lg px-3 py-2 text-base font-black active:opacity-70">‹</button>
          <button type="button" aria-label={tr("Go to today", "Ir para hoje", "Ir a hoy")} aria-pressed={isToday} onClick={() => setDate(todayInput())} className={`rounded-lg px-3 py-2 text-sm font-bold ${isToday ? "bg-[#f97316] text-white" : "active:opacity-70"}`}>{tr("Today", "Hoje", "Hoy")}</button>
          <button type="button" aria-label={tr("Next day", "Próximo dia", "Día siguiente")} onClick={() => setDate((d) => shiftDateStr(d, 1))} className="rounded-lg px-3 py-2 text-base font-black active:opacity-70">›</button>
        </div>
        <p className="text-sm font-semibold" aria-label={tr(`Selected day ${fmtDate(date)}`, `Dia selecionado ${fmtDate(date)}`, `Día seleccionado ${fmtDate(date)}`)}>{fmtDate(date)}{isToday ? ` • ${tr("Today", "Hoje", "Hoy")}` : ""}</p>
        <button type="button" aria-label={tr(`Show unassigned tasks only, ${unassignedCount} unassigned`, `Mostrar só tarefas sem responsável, ${unassignedCount} sem responsável`, `Mostrar solo tareas sin responsable, ${unassignedCount} sin responsable`)} aria-pressed={unassignedOnly} onClick={() => setUnassignedOnly((v) => !v)} className={`ml-auto inline-flex items-center gap-2 rounded-full border px-3 py-2 text-sm font-bold ${unassignedOnly ? "border-orange-500 bg-orange-500 text-white" : "border-orange-300 bg-orange-50 text-orange-800 dark:bg-orange-950/40 dark:text-orange-200"}`}>
          {tr("Unassigned only", "Só sem responsável", "Solo sin responsable")}
          <span className={`rounded-full px-2 py-0.5 text-xs font-black ${unassignedOnly ? "bg-white text-orange-600" : "bg-orange-500 text-white"}`} aria-hidden="true">{unassignedCount} {tr("unassigned", "sem responsável", "sin responsable")}</span>
        </button>
      </div>

      {saveMsg && <p className="rounded-xl bg-[var(--surface)] px-3 py-2 text-sm font-semibold ring-1 ring-[var(--border)]" role="status">{saveMsg}</p>}
      {dispatchQ.isPending && <p className="py-10 text-center text-sm text-[var(--dim)]">{tr("Loading dispatch…", "Carregando a distribuição…", "Cargando la distribución…")}</p>}
      {dispatchQ.error && <p className="py-10 text-center text-sm font-semibold text-red-600">{tr("Could not load dispatch.", "Não foi possível carregar a distribuição.", "No se pudo cargar la distribución.")} <button type="button" className="underline" onClick={() => dispatchQ.refetch()}>{tr("Retry", "Tentar novamente", "Reintentar")}</button></p>}
      {!dispatchQ.isPending && !dispatchQ.error && projectsRaw.length === 0 && (
        <div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center">
          <p className="text-4xl">🧭</p>
          <p className="mt-2 font-semibold">{tr("No jobs scheduled for this day", "Nenhum trabalho agendado para este dia", "No hay trabajos programados para este día")}</p>
          <p className="mt-1 text-sm text-[var(--dim)]">{tr("Jobs appear here on the days between their start and end dates. Try another day, or create jobs inside a project first.", "Os trabalhos aparecem aqui nos dias entre suas datas de início e término. Tente outro dia, ou crie trabalhos dentro de uma obra primeiro.", "Los trabajos aparecen aquí en los días entre sus fechas de inicio y fin. Prueba otro día, o primero crea trabajos dentro de una obra.")}</p>
        </div>
      )}
      {!dispatchQ.isPending && !dispatchQ.error && projectsRaw.length > 0 && projects.length === 0 && unassignedOnly && (
        <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-6 text-center">
          <p className="font-semibold">✅ {tr("Everything is assigned for this day", "Tudo está atribuído neste dia", "Todo está asignado en este día")}</p>
          <p className="mt-1 text-sm text-[var(--dim)]">{tr("No task is waiting for a person. Turn off “Unassigned only” to see the full board.", "Nenhuma tarefa está aguardando um responsável. Desative “Só sem responsável” para ver o quadro completo.", "Ninguna tarea está esperando un responsable. Desactiva “Solo sin responsable” para ver el tablero completo.")}</p>
        </div>
      )}

      {projects.map((p) => (
        <section key={p.projectId} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr(`Project ${p.projectName}`, `Obra ${p.projectName}`, `Obra ${p.projectName}`)}>
          <div className="flex items-start justify-between gap-2">
            <h3 className="min-w-0 font-bold leading-snug">🏗️ {p.projectName}</h3>
            <Badge text={projectStatusLabel(p.projectStatus)} tone={p.projectStatus === "andamento" ? "green" : "gray"} />
          </div>
          <div className="mt-3 space-y-3">
            {p.jobs.map((j) => {
              const crewCount = j.crew.length;
              const expanded = isExpanded(j.jobId, j.unassignedCount > 0);
              const pct = j.taskTotal > 0 ? Math.round((j.taskDone / j.taskTotal) * 100) : 0;
              return (
                <div key={j.jobId} className="rounded-xl bg-[var(--surface2)] p-3">
                  <div className="flex items-start gap-2">
                    <button type="button" onClick={() => toggleJob(j.jobId)} aria-expanded={expanded} aria-label={expanded ? tr(`Collapse job ${j.jobName}`, `Recolher o trabalho ${j.jobName}`, `Contraer el trabajo ${j.jobName}`) : tr(`Expand job ${j.jobName} to see its tasks`, `Expandir o trabalho ${j.jobName} para ver suas tarefas`, `Expandir el trabajo ${j.jobName} para ver sus tareas`)} className="min-w-0 flex-1 text-left active:opacity-70">
                      <p className="font-bold leading-snug">🔧 {j.jobName}{j.serviceName ? <span className="font-semibold text-[var(--dim)]"> • {j.serviceName}{j.serviceUnit ? ` (${j.serviceUnit})` : ""}</span> : null}</p>
                      <p className="mt-0.5 text-xs text-[var(--dim)]">{j.taskDone}/{j.taskTotal} {tr("tasks done", "tarefas concluídas", "tareas terminadas")}{j.startDate || j.endDate ? ` • ${j.startDate ? fmtDate(j.startDate) : "…"} → ${j.endDate ? fmtDate(j.endDate) : "…"}` : ""}</p>
                      <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[var(--surface)]" role="progressbar" aria-valuenow={pct} aria-valuemin={0} aria-valuemax={100} aria-label={tr(`Task progress for ${j.jobName}: ${j.taskDone} of ${j.taskTotal} done`, `Andamento das tarefas de ${j.jobName}: ${j.taskDone} de ${j.taskTotal} concluídas`, `Progreso de las tareas de ${j.jobName}: ${j.taskDone} de ${j.taskTotal} terminadas`)}>
                        <div className="h-full rounded-full bg-green-600" style={{ width: `${pct}%` }} />
                      </div>
                    </button>
                    <span className="flex shrink-0 flex-col items-end gap-1.5">
                      {jobStatusBadge(j.jobStatus)}
                      <span aria-hidden="true" className="text-lg font-black leading-none text-[var(--dim)]">{expanded ? "▾" : "›"}</span>
                    </span>
                  </div>

                  {/* Crew chips — who is on this job */}
                  <div className="mt-2 flex flex-wrap items-center gap-1.5" aria-label={tr(`Crew on ${j.jobName}`, `Equipe de ${j.jobName}`, `Equipo de ${j.jobName}`)}>
                    <span className="text-[11px] font-black uppercase tracking-wide text-[var(--dim)]">{tr("Crew:", "Equipe:", "Equipo:")}</span>
                    {j.crew.map((c) => (
                      <span key={c.id} className="inline-flex items-center gap-1 rounded-full bg-[#0f2a44] px-2.5 py-1 text-xs font-bold text-white">👤 {c.name}</span>
                    ))}
                    {crewCount === 0 && <span className="inline-flex rounded-full bg-orange-100 px-2.5 py-1 text-xs font-black text-orange-800">{tr("No crew yet", "Sem equipe ainda", "Sin equipo aún")}</span>}
                    {j.unassignedCount > 0 && <span className="inline-flex rounded-full bg-orange-500 px-2.5 py-1 text-xs font-black text-white">{j.unassignedCount} {tr("unassigned", "sem responsável", "sin responsable")}</span>}
                    <button type="button" onClick={() => openCrewSheet({ jobId: j.jobId, jobName: j.jobName, projectId: p.projectId, crewIds: j.crew.map((c) => c.id) })} aria-label={tr(`Assign crew for ${j.jobName}`, `Atribuir equipe para ${j.jobName}`, `Asignar equipo para ${j.jobName}`)} className="ml-auto rounded-lg bg-[#f97316] px-3 py-1.5 text-xs font-black text-white active:opacity-80">{tr("Assign crew", "Atribuir equipe", "Asignar equipo")}</button>
                  </div>

                  {expanded && (
                    <div className="mt-3 space-y-2 border-t border-[var(--border)] pt-3">
                      {j.tasks.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No tasks on this job yet. Add tasks from the project’s job page — then assign each one here.", "Nenhuma tarefa neste trabalho ainda. Adicione tarefas na página do trabalho dentro da obra — depois atribua cada uma aqui.", "Todavía no hay tareas en este trabajo. Agrega tareas desde la página del trabajo dentro de la obra, y luego asigna cada una aquí.")}</p>}
                      {j.tasks.map((t) => {
                        const unassigned = dispatchTaskUnassigned(t, crewCount);
                        const dotCls = t.status === "done" ? "bg-green-600" : t.status === "in_progress" ? "bg-amber-500" : "bg-gray-400";
                        return (
                          <button key={t.id} type="button" onClick={() => openAssignSheet({ task: t, jobName: j.jobName, projectName: p.projectName, projectId: p.projectId, jobId: j.jobId, crew: j.crew })} aria-label={tr(`Who does the task ${t.title}? Currently ${unassigned ? "unassigned" : taskAssigneeNames(t).length > 0 ? taskAssigneeNames(t).join(", ") : "the whole crew"}`, `Quem faz a tarefa ${t.title}? Atualmente ${unassigned ? "sem responsável" : taskAssigneeNames(t).length > 0 ? taskAssigneeNames(t).join(", ") : "a equipe toda"}`, `¿Quién hace la tarea ${t.title}? Actualmente ${unassigned ? "sin responsable" : taskAssigneeNames(t).length > 0 ? taskAssigneeNames(t).join(", ") : "todo el equipo"}`)} className="flex w-full items-center gap-2.5 rounded-lg bg-[var(--surface)] p-2.5 text-left active:opacity-70">
                            <span className={`h-2.5 w-2.5 shrink-0 rounded-full ${dotCls}`} aria-hidden="true" />
                            <span className="min-w-0 flex-1">
                              <span className={`block font-semibold leading-snug ${t.status === "done" ? "text-[var(--dim)] line-through" : ""}`}>{t.title}</span>
                              <span className="block text-[11px] text-[var(--dim)]">{taskStatusLabel(t.status)}{t.notes ? ` • ${t.notes.slice(0, 80)}` : ""}</span>
                            </span>
                            {unassigned ? (
                              <span className="shrink-0 rounded-full bg-orange-500 px-2.5 py-1 text-xs font-black text-white">{tr("Unassigned", "Sem responsável", "Sin responsable")}</span>
                            ) : taskAssigneeNames(t).length > 0 ? (
                              <span className="flex max-w-[55%] shrink-0 flex-wrap justify-end gap-1">{taskAssigneeNames(t).map((n) => <span key={n} className="rounded-full bg-[#0f2a44] px-2 py-0.5 text-[11px] font-bold text-white">👤 {n}</span>)}</span>
                            ) : (
                              <span className="shrink-0 rounded-full bg-gray-200 px-2.5 py-1 text-xs font-bold text-gray-700 dark:bg-white/15 dark:text-white">👥 {tr("Whole crew", "Equipe toda", "Todo el equipo")}</span>
                            )}
                          </button>
                        );
                      })}
                      <p className="text-[11px] text-[var(--dim)]">{tr("Tap a task to choose who does it. “Whole crew” means everyone on this job’s crew can pick it up — it follows the crew automatically.", "Toque em uma tarefa para escolher quem a faz. “Equipe toda” significa que todos da equipe deste trabalho podem executá-la — ela segue a equipe automaticamente.", "Toca una tarea para elegir quién la hace. “Todo el equipo” significa que todos los del equipo de este trabajo pueden hacerla: sigue al equipo automáticamente.")}</p>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      ))}

      {/* ---- Bottom sheet: Who does this task? ---- */}
      {assignCtx && (
        <div className="fixed inset-0 z-50 flex items-end bg-black/50" role="dialog" aria-modal="true" aria-label={tr(`Who does the task ${assignCtx.task.title}?`, `Quem faz a tarefa ${assignCtx.task.title}?`, `¿Quién hace la tarea ${assignCtx.task.title}?`)}>
          <div className="max-h-[85vh] w-full overflow-y-auto rounded-t-3xl bg-[var(--surface)] p-4 pb-[max(1rem,env(safe-area-inset-bottom))]">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <h3 className="font-bold">{tr("Who does this task?", "Quem faz esta tarefa?", "¿Quién hace esta tarea?")}</h3>
                <p className="mt-0.5 truncate text-sm font-semibold">{assignCtx.task.title}</p>
                <p className="text-xs text-[var(--dim)]">{assignCtx.projectName} • {assignCtx.jobName}</p>
              </div>
              <button type="button" aria-label={tr("Close assignee picker", "Fechar o seletor de responsável", "Cerrar el selector de responsable")} onClick={() => setAssignCtx(null)} className="shrink-0 rounded-lg bg-[var(--surface2)] px-3 py-1.5 text-sm font-bold active:opacity-70">{tr("✕ Close", "✕ Fechar", "✕ Cerrar")}</button>
            </div>
            <p className="mt-2 text-xs text-[var(--dim)]">{tr("Jobs have crews. Tasks have assignees. Pick one or several people, or let the whole crew cover it.", "Trabalhos têm equipes. Tarefas têm responsáveis. Escolha uma ou várias pessoas, ou deixe a equipe toda cobrir.", "Los trabajos tienen equipos. Las tareas tienen responsables. Elige a una o varias personas, o deja que todo el equipo la cubra.")}</p>
            <div className="mt-3">
              <Field label={tr("Search crew", "Buscar na equipe", "Buscar en el equipo")}>
                <input aria-label={tr("Search crew members", "Buscar membros da equipe", "Buscar miembros del equipo")} className={inputCls} value={sheetSearch} onChange={(e) => setSheetSearch(e.target.value)} placeholder={tr("Type a name…", "Digite um nome…", "Escribe un nombre…")} />
              </Field>
            </div>
            <div className="mt-3 space-y-2">
              <button type="button" disabled={assignTaskMut.isPending} onClick={() => setAssignSelection(new Set())} aria-label={tr(`Assign the task ${assignCtx.task.title} to the whole crew`, `Atribuir a tarefa ${assignCtx.task.title} à equipe toda`, `Asignar la tarea ${assignCtx.task.title} a todo el equipo`)} aria-pressed={assignSelection.size === 0} className={`flex w-full items-center justify-between gap-2 rounded-xl border p-3 text-left active:opacity-70 disabled:opacity-40 ${assignSelection.size === 0 && assignCtx.crew.length > 0 ? "border-[#f97316] bg-orange-50 dark:bg-orange-950/30" : "border-[var(--border)] bg-[var(--surface2)]"}`}>
                <span>
                  <span className="block font-bold">👥 {tr("Whole crew", "Equipe toda", "Todo el equipo")}</span>
                  <span className="block text-xs text-[var(--dim)]">{assignCtx.crew.length > 0 ? tr(`Everyone on this job (${assignCtx.crew.map((c) => c.name).join(", ")}) can see and work it. Follows the crew if people change.`, `Todos neste trabalho (${assignCtx.crew.map((c) => c.name).join(", ")}) podem vê-la e executá-la. Segue a equipe se as pessoas mudarem.`, `Todos en este trabajo (${assignCtx.crew.map((c) => c.name).join(", ")}) pueden verla y hacerla. Sigue al equipo si las personas cambian.`) : tr("No crew on this job yet — assign a crew below and this task is covered automatically.", "Ainda não há equipe neste trabalho — atribua uma equipe abaixo e esta tarefa fica coberta automaticamente.", "Todavía no hay equipo en este trabajo: asigna un equipo abajo y esta tarea queda cubierta automáticamente.")}</span>
                </span>
                {assignSelection.size === 0 && assignCtx.crew.length > 0 && <span className="shrink-0 text-lg" aria-hidden="true">✓</span>}
              </button>
              {assignCtx.crew.length > 0 && (
                <div className="flex items-center justify-between gap-2 px-0.5">
                  <p className="text-[11px] font-bold text-[var(--dim)]">{tr("Or pick who does it — you can choose several:", "Ou escolha quem faz — pode escolher vários:", "O elige quién la hace: puedes elegir a varios:")}</p>
                  <button type="button" aria-label={assignSelection.size === assignCtx.crew.length ? tr("Clear all assignees", "Limpar todos os responsáveis", "Borrar todos los responsables") : tr("Select the whole crew as assignees", "Selecionar a equipe toda como responsáveis", "Seleccionar a todo el equipo como responsables")} onClick={() => setAssignSelection(assignSelection.size === assignCtx.crew.length ? new Set() : new Set(assignCtx.crew.map((c) => c.id)))} className="shrink-0 text-[11px] font-bold text-[#f97316]">{assignSelection.size === assignCtx.crew.length ? tr("Clear all", "Limpar tudo", "Borrar todo") : tr("Select all", "Selecionar todos", "Seleccionar todo")}</button>
                </div>
              )}
              {assignCtx.crew.length === 0 && (
                <div className="rounded-xl bg-orange-50 px-3 py-2.5 dark:bg-orange-950/30" role="alert">
                  <p className="text-sm font-bold text-orange-800 dark:text-orange-200">{tr("This job has no crew yet, so this task is Unassigned.", "Este trabalho ainda não tem equipe, então esta tarefa está Sem responsável.", "Este trabajo aún no tiene equipo, así que esta tarea está Sin responsable.")}</p>
                  <button type="button" onClick={() => { const ctx: DispatchCrewCtx = { jobId: assignCtx.jobId, jobName: assignCtx.jobName, projectId: assignCtx.projectId, crewIds: assignCtx.crew.map((c) => c.id) }; setAssignCtx(null); openCrewSheet(ctx); }} aria-label={tr(`Assign crew for ${assignCtx.jobName}`, `Atribuir equipe para ${assignCtx.jobName}`, `Asignar equipo para ${assignCtx.jobName}`)} className="mt-2 rounded-lg bg-[#f97316] px-3 py-2 text-xs font-black text-white active:opacity-80">{tr("Assign crew for this job", "Atribuir equipe para este trabalho", "Asignar equipo para este trabajo")}</button>
                </div>
              )}
              {sheetCrew.map((c) => {
                const checked = assignSelection.has(c.id);
                return (
                <button key={c.id} type="button" role="checkbox" aria-checked={checked} disabled={assignTaskMut.isPending} onClick={() => setAssignSelection((prev) => { const next = new Set(prev); if (next.has(c.id)) next.delete(c.id); else next.add(c.id); return next; })} aria-label={checked ? tr(`Remove ${c.name} from the task ${assignCtx.task.title}`, `Remover ${c.name} da tarefa ${assignCtx.task.title}`, `Quitar a ${c.name} de la tarea ${assignCtx.task.title}`) : tr(`Add ${c.name} to the task ${assignCtx.task.title}`, `Adicionar ${c.name} à tarefa ${assignCtx.task.title}`, `Agregar a ${c.name} a la tarea ${assignCtx.task.title}`)} className={`flex w-full items-center justify-between gap-2 rounded-xl border p-3 text-left active:opacity-70 disabled:opacity-40 ${checked ? "border-[#f97316] bg-orange-50 dark:bg-orange-950/30" : "border-[var(--border)] bg-[var(--surface2)]"}`}>
                  <span><span className="block font-bold">👤 {c.name}</span>{c.trade ? <span className="block text-xs text-[var(--dim)]">{c.trade}</span> : null}</span>
                  <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md border text-sm font-black ${checked ? "border-[#f97316] bg-[#f97316] text-white" : "border-[var(--border)] text-transparent"}`} aria-hidden="true">✓</span>
                </button>
                );
              })}
              {assignCtx.crew.length > 0 && sheetCrew.length === 0 && <p className="py-3 text-center text-sm text-[var(--dim)]">{tr("No crew member matches that search.", "Nenhum membro da equipe corresponde a essa busca.", "Ningún miembro del equipo coincide con esa búsqueda.")}</p>}
              <p className="text-[11px] font-semibold text-[var(--dim)]" role="status">{assignSelection.size === 0 ? (assignCtx.crew.length > 0 ? tr("Whole crew selected — everyone on this job sees this task.", "Equipe toda selecionada — todos neste trabalho veem esta tarefa.", "Todo el equipo seleccionado: todos en este trabajo ven esta tarea.") : tr("Nobody picked yet — this task is Unassigned until a crew is assigned.", "Ninguém escolhido ainda — esta tarefa fica Sem responsável até uma equipe ser atribuída.", "Nadie elegido aún: esta tarea queda Sin responsable hasta que se asigne un equipo.")) : tr(`${assignSelection.size} selected: ${assignCtx.crew.filter((c) => assignSelection.has(c.id)).map((c) => c.name).join(", ")}`, `${assignSelection.size} selecionado(s): ${assignCtx.crew.filter((c) => assignSelection.has(c.id)).map((c) => c.name).join(", ")}`, `${assignSelection.size} seleccionado(s): ${assignCtx.crew.filter((c) => assignSelection.has(c.id)).map((c) => c.name).join(", ")}`)}</p>
              <div className="flex gap-2 pt-1">
                <button type="button" className={btnGhost} onClick={() => setAssignCtx(null)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
                <button type="button" disabled={assignTaskMut.isPending} onClick={() => assignTaskMut.mutate({ taskId: assignCtx.task.id, assigneeIds: [...assignSelection] })} aria-label={tr(`Save assignees for the task ${assignCtx.task.title}, ${assignSelection.size} selected`, `Salvar responsáveis da tarefa ${assignCtx.task.title}, ${assignSelection.size} selecionado(s)`, `Guardar responsables de la tarea ${assignCtx.task.title}, ${assignSelection.size} seleccionado(s)`)} className={`${btnNavy} flex-1 disabled:opacity-40`}>{assignTaskMut.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr(`Save assignees (${assignSelection.size})`, `Salvar responsáveis (${assignSelection.size})`, `Guardar responsables (${assignSelection.size})`)}</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ---- Bottom sheet: Assign crew (multi-select) ---- */}
      {crewCtx && (
        <div className="fixed inset-0 z-50 flex items-end bg-black/50" role="dialog" aria-modal="true" aria-label={tr(`Assign crew for ${crewCtx.jobName}`, `Atribuir equipe para ${crewCtx.jobName}`, `Asignar equipo para ${crewCtx.jobName}`)}>
          <div className="max-h-[85vh] w-full overflow-y-auto rounded-t-3xl bg-[var(--surface)] p-4 pb-[max(1rem,env(safe-area-inset-bottom))]">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <h3 className="font-bold">{tr("Assign crew", "Atribuir equipe", "Asignar equipo")}</h3>
                <p className="mt-0.5 truncate text-sm font-semibold">{crewCtx.jobName}</p>
                <p className="text-xs text-[var(--dim)]">{tr("Pick everyone who works this job. Tasks set to “Whole crew” follow this crew automatically.", "Escolha todos que trabalham neste trabalho. Tarefas da “Equipe toda” seguem esta equipe automaticamente.", "Elige a todos los que trabajan en este trabajo. Las tareas de “Todo el equipo” siguen a este equipo automáticamente.")}</p>
              </div>
              <button type="button" aria-label={tr("Close crew picker", "Fechar o seletor de equipe", "Cerrar el selector de equipo")} onClick={() => setCrewCtx(null)} className="shrink-0 rounded-lg bg-[var(--surface2)] px-3 py-1.5 text-sm font-bold active:opacity-70">{tr("✕ Close", "✕ Fechar", "✕ Cerrar")}</button>
            </div>
            <div className="mt-3">
              <Field label={tr("Search employees", "Buscar funcionários", "Buscar empleados")}>
                <input aria-label={tr("Search employees for the crew", "Buscar funcionários para a equipe", "Buscar empleados para el equipo")} className={inputCls} value={crewSearch} onChange={(e) => setCrewSearch(e.target.value)} placeholder={tr("Type a name…", "Digite um nome…", "Escribe un nombre…")} />
              </Field>
            </div>
            <div className="mt-3 space-y-2">
              {crewCandidates.map((e) => {
                const checked = crewSelection.has(e.id);
                return (
                  <button key={e.id} type="button" role="checkbox" aria-checked={checked} aria-label={checked ? tr(`Remove ${e.name} from the crew of ${crewCtx.jobName}`, `Remover ${e.name} da equipe de ${crewCtx.jobName}`, `Quitar a ${e.name} del equipo de ${crewCtx.jobName}`) : tr(`Add ${e.name} to the crew of ${crewCtx.jobName}`, `Adicionar ${e.name} à equipe de ${crewCtx.jobName}`, `Agregar a ${e.name} al equipo de ${crewCtx.jobName}`)} onClick={() => setCrewSelection((prev) => { const next = new Set(prev); if (next.has(e.id)) next.delete(e.id); else next.add(e.id); return next; })} className={`flex w-full items-center justify-between gap-2 rounded-xl border p-3 text-left active:opacity-70 ${checked ? "border-[#f97316] bg-orange-50 dark:bg-orange-950/30" : "border-[var(--border)] bg-[var(--surface2)]"}`}>
                    <span><span className="block font-bold">👤 {e.name}</span>{e.trade ? <span className="block text-xs text-[var(--dim)]">{e.trade}</span> : null}</span>
                    <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md border text-sm font-black ${checked ? "border-[#f97316] bg-[#f97316] text-white" : "border-[var(--border)] text-transparent"}`} aria-hidden="true">✓</span>
                  </button>
                );
              })}
              {crewCandidates.length === 0 && <p className="py-3 text-center text-sm text-[var(--dim)]">{employeesQ.isPending ? tr("Loading employees…", "Carregando funcionários…", "Cargando empleados…") : tr("No employee matches that search.", "Nenhum funcionário corresponde a essa busca.", "Ningún empleado coincide con esa búsqueda.")}</p>}
            </div>
            <div className="mt-4 flex gap-2">
              <button type="button" className={btnGhost} onClick={() => setCrewCtx(null)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
              <button type="button" disabled={saveCrewMut.isPending} onClick={() => saveCrewMut.mutate({ ctx: crewCtx, next: new Set(crewSelection) })} aria-label={tr(`Save crew for ${crewCtx.jobName}, ${crewSelection.size} selected`, `Salvar equipe de ${crewCtx.jobName}, ${crewSelection.size} selecionado(s)`, `Guardar equipo de ${crewCtx.jobName}, ${crewSelection.size} seleccionado(s)`)} className={`${btnNavy} flex-1 disabled:opacity-40`}>{saveCrewMut.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr(`Save crew (${crewSelection.size})`, `Salvar equipe (${crewSelection.size})`, `Guardar equipo (${crewSelection.size})`)}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- Fleet / Vehicles ---------------- */
type VehicleLite = {
  id: number; companyId: string; name: string; make: string; model: string; year: number;
  plate: string; vin: string; photoUrl: string; status: string; mileage: number;
  oilIntervalMiles: number; oilIntervalMonths: number; lastOilMileage: number | null; lastOilDate: string;
  currentUserIds: number[]; currentUserNames: string[]; oilState: string; oilDueMileage: number | null; oilDueDate: string;
  openTickets: number;
};
const VEHICLE_STATUSES = ["active", "in_shop", "inactive"] as const;
function vehicleStatusLabel(status: string): string {
  if (status === "active") return tr("Active", "Ativo", "Activo");
  if (status === "in_shop") return tr("In shop", "Na oficina", "En el taller");
  return tr("Inactive", "Inativo", "Inactivo");
}
function vehicleStatusTone(status: string): "green" | "amber" | "gray" {
  return status === "active" ? "green" : status === "in_shop" ? "amber" : "gray";
}
const MAINT_TYPES = ["oil_change", "tires", "brakes", "inspection", "other"] as const;
function maintTypeLabel(t: string): string {
  if (t === "oil_change") return tr("Oil change", "Troca de óleo", "Cambio de aceite");
  if (t === "tires") return tr("Tires", "Pneus", "Neumáticos");
  if (t === "brakes") return tr("Brakes", "Freios", "Frenos");
  if (t === "inspection") return tr("Inspection", "Inspeção", "Inspección");
  return tr("Other", "Outro", "Otro");
}
function oilBadge(v: VehicleLite) {
  if (v.oilState === "overdue") return <Badge text={tr("Oil overdue", "Óleo vencido", "Aceite vencido")} tone="red" />;
  if (v.oilState === "due_soon") return <Badge text={tr("Oil due soon", "Óleo perto do vencimento", "Aceite por vencer")} tone="amber" />;
  if (v.oilState === "ok") return <Badge text={tr("Oil OK", "Óleo em dia", "Aceite al día")} tone="green" />;
  return null;
}
const fmtMiles = (n: number) => `${n.toLocaleString("en-US")} mi`;

function FleetView({ cid, session }: { cid: string; session: Session }) {
  const qc = useQueryClient();
  const actorId = session.userId;
  const [selected, setSelected] = useState<number | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [msg, setMsg] = useState("");
  const [fName, setFName] = useState("");
  const [fMake, setFMake] = useState("");
  const [fModel, setFModel] = useState("");
  const [fYear, setFYear] = useState("");
  const [fPlate, setFPlate] = useState("");
  const [fVin, setFVin] = useState("");
  const [fMileage, setFMileage] = useState("");
  const [fPhoto, setFPhoto] = useState("");
  const photoRef = useRef<HTMLInputElement | null>(null);

  const vehiclesQ = useQuery({ queryKey: ["vehicles", cid], queryFn: () => api.listVehicles({ companyId: cid, actorId }) });
  const vehicles = vehiclesQ.data?.vehicles ?? [];

  const create = useMutation({
    mutationFn: () => api.createVehicle({
      companyId: cid, actorId, name: fName, make: fMake, model: fModel,
      year: fYear.trim() ? Number(fYear) || 0 : 0, plate: fPlate, vin: fVin,
      photoUrl: fPhoto, status: "active", mileage: fMileage.trim() ? Math.round(Number(fMileage.replace(/[^0-9.]/g, "")) || 0) : 0,
    }),
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["vehicles", cid] });
      setShowForm(false); setFName(""); setFMake(""); setFModel(""); setFYear(""); setFPlate(""); setFVin(""); setFMileage(""); setFPhoto("");
      setMsg(tr("Vehicle added. ✅", "Veículo adicionado. ✅", "Vehículo agregado. ✅"));
      setSelected(r.id);
    },
    onError: () => setMsg(tr("Could not add this vehicle.", "Não foi possível adicionar este veículo.", "No se pudo agregar este vehículo.")),
  });

  if (selected !== null) {
    const v = vehicles.find((x) => x.id === selected);
    return <VehicleDetailView cid={cid} session={session} vehicleId={selected} fallbackName={v?.name ?? ""} onBack={() => setSelected(null)} />;
  }

  return (
    <div className="space-y-4">
      <div className="flex items-start justify-between gap-2">
        <div>
          <h2 className="text-xl font-bold">{tr("Fleet", "Frota", "Flota")}</h2>
          <p className="text-sm text-[var(--dim)]">{tr("Vehicles, who is using them, fuel, maintenance, and tickets.", "Veículos, quem está usando, combustível, manutenção e multas.", "Vehículos, quién los usa, combustible, mantenimiento y multas.")}</p>
        </div>
        {session.role !== "funcionario" && <button type="button" className={btnPrimary} aria-label={tr("New vehicle", "Novo veículo", "Nuevo vehículo")} aria-expanded={showForm} onClick={() => { setShowForm((s) => !s); setMsg(""); }}>{showForm ? tr("Close", "Fechar", "Cerrar") : tr("+ New vehicle", "+ Novo veículo", "+ Nuevo vehículo")}</button>}
      </div>

      {msg && <p className="rounded-xl bg-[var(--surface)] px-3 py-2 text-sm font-semibold ring-1 ring-[var(--border)]" role="status">{msg}</p>}

      {showForm && (
        <form className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" onSubmit={(e) => { e.preventDefault(); create.mutate(); }}>
          <Field label={tr("Unit name / number", "Nome / número da unidade", "Nombre / número de la unidad")}><input aria-label={tr("Unit name or number", "Nome ou número da unidade", "Nombre o número de la unidad")} className={inputCls} value={fName} onChange={(e) => setFName(e.target.value)} placeholder={tr("E.g.: Truck 3", "Ex.: Caminhão 3", "Ej.: Camión 3")} required /></Field>
          <div className="grid grid-cols-3 gap-2">
            <Field label={tr("Make", "Marca", "Marca")}><input aria-label={tr("Vehicle make", "Marca do veículo", "Marca del vehículo")} className={inputCls} value={fMake} onChange={(e) => setFMake(e.target.value)} placeholder="Ford" /></Field>
            <Field label={tr("Model", "Modelo", "Modelo")}><input aria-label={tr("Vehicle model", "Modelo do veículo", "Modelo del vehículo")} className={inputCls} value={fModel} onChange={(e) => setFModel(e.target.value)} placeholder="F-150" /></Field>
            <Field label={tr("Year", "Ano", "Año")}><input aria-label={tr("Vehicle year", "Ano do veículo", "Año del vehículo")} className={inputCls} inputMode="numeric" value={fYear} onChange={(e) => setFYear(e.target.value)} placeholder="2021" /></Field>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Field label={tr("Plate", "Placa", "Placa")}><input aria-label={tr("License plate", "Placa do veículo", "Placa del vehículo")} className={inputCls} value={fPlate} onChange={(e) => setFPlate(e.target.value)} placeholder="ABC-1234" /></Field>
            <Field label={tr("Current mileage (mi)", "Quilometragem atual (mi)", "Millaje actual (mi)")}><input aria-label={tr("Current odometer in miles", "Odômetro atual em milhas", "Odómetro actual en millas")} className={inputCls} inputMode="numeric" value={fMileage} onChange={(e) => setFMileage(e.target.value)} placeholder="48,250" /></Field>
          </div>
          <Field label={tr("VIN (optional)", "VIN (opcional)", "VIN (opcional)")}><input aria-label={tr("Vehicle VIN", "VIN do veículo", "VIN del vehículo")} className={inputCls} value={fVin} onChange={(e) => setFVin(e.target.value)} placeholder="1FTFW1E50MFA00000" /></Field>
          <div>
            <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Photo (optional)", "Foto (opcional)", "Foto (opcional)")}</p>
            {fPhoto ? <img src={safeImgSrc(fPhoto)} alt={tr("New vehicle photo preview", "Prévia da foto do novo veículo", "Vista previa de la foto del nuevo vehículo")} className="mb-2 h-32 w-full rounded-xl object-cover" /> : null}
            <button type="button" className={btnGhost} aria-label={tr("Add a photo of the vehicle", "Adicionar uma foto do veículo", "Agregar una foto del vehículo")} onClick={() => photoRef.current?.click()}>{fPhoto ? tr("📷 Change photo", "📷 Trocar foto", "📷 Cambiar foto") : tr("📷 Add photo", "📷 Adicionar foto", "📷 Agregar foto")}</button>
            <input ref={photoRef} type="file" accept="image/*" className="hidden" aria-label={tr("Vehicle photo file", "Arquivo de foto do veículo", "Archivo de foto del vehículo")} onChange={async (e) => { const f = e.target.files?.[0]; if (f) setFPhoto(await readPhotoFile(f)); e.target.value = ""; }} />
          </div>
          <button className={`${btnNavy} w-full`} disabled={create.isPending || !fName.trim()}>{create.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Add vehicle", "Adicionar veículo", "Agregar vehículo")}</button>
        </form>
      )}

      {vehiclesQ.isPending && <p className="py-10 text-center text-sm text-[var(--dim)]">{tr("Loading fleet…", "Carregando a frota…", "Cargando la flota…")}</p>}
      {vehiclesQ.error && <p className="py-10 text-center text-sm font-semibold text-red-600">{tr("Could not load the fleet.", "Não foi possível carregar a frota.", "No se pudo cargar la flota.")} <button type="button" className="underline" onClick={() => vehiclesQ.refetch()}>{tr("Retry", "Tentar novamente", "Reintentar")}</button></p>}
      {!vehiclesQ.isPending && !vehiclesQ.error && vehicles.length === 0 && !showForm && (
        <div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center">
          <p className="text-4xl">🚐</p>
          <p className="mt-2 font-semibold">{tr("No vehicles yet", "Nenhum veículo ainda", "Todavía no hay vehículos")}</p>
          <p className="mt-1 text-sm text-[var(--dim)]">{tr("Tap “+ New vehicle” to register the first truck or van.", "Toque em “+ Novo veículo” para cadastrar o primeiro caminhão ou van.", "Toca “+ Nuevo vehículo” para registrar el primer camión o furgoneta.")}</p>
        </div>
      )}

      <div className="space-y-3">
        {vehicles.map((v) => (
          <button key={v.id} type="button" onClick={() => setSelected(v.id)} aria-label={tr(`Open vehicle ${v.name}`, `Abrir o veículo ${v.name}`, `Abrir el vehículo ${v.name}`)} className="w-full rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-3 text-left active:opacity-80">
            <div className="flex items-start gap-3">
              {safeImgSrc(v.photoUrl) ? (
                <img src={safeImgSrc(v.photoUrl)} alt={tr(`Photo of ${v.name}`, `Foto de ${v.name}`, `Foto de ${v.name}`)} className="h-16 w-20 shrink-0 rounded-xl object-cover" />
              ) : (
                <span className="flex h-16 w-20 shrink-0 items-center justify-center rounded-xl bg-[var(--surface2)] text-3xl" aria-hidden="true">🚐</span>
              )}
              <div className="min-w-0 flex-1">
                <p className="flex flex-wrap items-center gap-2 font-bold leading-snug">{v.name} <Badge text={vehicleStatusLabel(v.status)} tone={vehicleStatusTone(v.status)} /> {oilBadge(v)}</p>
                <p className="mt-0.5 text-sm text-[var(--dim)]">{[v.year > 0 ? String(v.year) : "", v.make, v.model].filter(Boolean).join(" ") || tr("Vehicle", "Veículo", "Vehículo")}{v.plate ? ` • ${v.plate}` : ""}</p>
                <p className="text-sm text-[var(--dim)]">🛣️ {fmtMiles(v.mileage)}{v.openTickets > 0 ? ` • 🎫 ${v.openTickets} ${tr("open ticket(s)", "multa(s) aberta(s)", "multa(s) abierta(s)")}` : ""}</p>
                <p className="mt-1 flex flex-wrap gap-1">
                  {v.currentUserNames.length > 0
                    ? v.currentUserNames.map((n) => <span key={n} className="rounded-full bg-[#0f2a44] px-2 py-0.5 text-[11px] font-bold text-white">👤 {n}</span>)
                    : <span className="rounded-full bg-gray-200 px-2 py-0.5 text-[11px] font-bold text-gray-700 dark:bg-white/15 dark:text-white">{tr("Not assigned", "Não atribuído", "Sin asignar")}</span>}
                </p>
              </div>
              <span aria-hidden="true" className="text-lg font-black text-[var(--dim)]">›</span>
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}

function VehicleDetailView({ cid, session, vehicleId, fallbackName, onBack }: { cid: string; session: Session; vehicleId: number; fallbackName: string; onBack: () => void }) {
  const qc = useQueryClient();
  const actorId = session.userId;
  const detailQ = useQuery({ queryKey: ["vehicle-detail", cid, vehicleId], queryFn: () => api.getVehicleDetail({ companyId: cid, actorId, vehicleId }) });
  const employeesQ = useQuery({ queryKey: ["employees", cid], queryFn: () => api.listEmployees({ companyId: cid }) });
  const projectsQ = useQuery({ queryKey: ["projects", cid], queryFn: () => api.listProjects({ companyId: cid }) });
  const [msg, setMsg] = useState("");
  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["vehicle-detail", cid, vehicleId] });
    qc.invalidateQueries({ queryKey: ["vehicles", cid] });
  };

  const d = detailQ.data;
  const v = d?.vehicle;
  const employees = (employeesQ.data?.employees ?? []).filter((e: EmpLite & { role?: string }) => e.status === "ativo" && e.role !== "cliente");
  const projects = projectsQ.data?.projects ?? [];

  /* edit vehicle */
  const [editing, setEditing] = useState(false);
  const [eName, setEName] = useState(""); const [eMake, setEMake] = useState(""); const [eModel, setEModel] = useState("");
  const [eYear, setEYear] = useState(""); const [ePlate, setEPlate] = useState(""); const [eVin, setEVin] = useState("");
  const [eStatus, setEStatus] = useState("active"); const [eMileage, setEMileage] = useState("");
  const [eEzpass, setEEzpass] = useState(false); const [eTagNumber, setETagNumber] = useState("");
  const saveVehicle = useMutation({
    mutationFn: () => api.updateVehicle({ companyId: cid, actorId, vehicleId, name: eName, make: eMake, model: eModel, year: eYear.trim() ? Number(eYear) || 0 : 0, plate: ePlate, vin: eVin, status: eStatus as "active" | "in_shop" | "inactive", mileage: eMileage.trim() ? Math.round(Number(eMileage.replace(/[^0-9.]/g, "")) || 0) : (v?.mileage ?? 0), ezpass: eEzpass ? 1 : 0, tagNumber: eTagNumber }),
    onSuccess: () => { invalidate(); setEditing(false); setMsg(tr("Vehicle saved. ✅", "Veículo salvo. ✅", "Vehículo guardado. ✅")); },
    onError: () => setMsg(tr("Could not save this vehicle.", "Não foi possível salvar este veículo.", "No se pudo guardar este vehículo.")),
  });
  const [confirmDelete, setConfirmDelete] = useState(false);
  const deleteVehicle = useMutation({
    mutationFn: () => api.deleteVehicle({ companyId: cid, actorId, vehicleId }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["vehicles", cid] }); onBack(); },
    onError: () => setMsg(tr("Could not delete this vehicle.", "Não foi possível excluir este veículo.", "No se pudo eliminar este vehículo.")),
  });

  /* assignment */
  const [addUserId, setAddUserId] = useState("");
  const assignMut = useMutation({ mutationFn: (employeeId: number) => api.assignVehicle({ companyId: cid, actorId, vehicleId, employeeId }), onSuccess: () => { invalidate(); setAddUserId(""); }, onError: () => setMsg(tr("Could not assign this vehicle.", "Não foi possível atribuir este veículo.", "No se pudo asignar este vehículo.")) });
  const unassignMut = useMutation({ mutationFn: (employeeId: number) => api.unassignVehicle({ companyId: cid, actorId, vehicleId, employeeId }), onSuccess: invalidate, onError: () => setMsg(tr("Could not unassign this vehicle.", "Não foi possível desatribuir este veículo.", "No se pudo desasignar este vehículo.")) });

  /* mileage */
  const [mDate, setMDate] = useState(todayInput()); const [mOdo, setMOdo] = useState(""); const [mNotes, setMNotes] = useState("");
  const addMileage = useMutation({ mutationFn: () => api.addVehicleMileage({ companyId: cid, actorId, vehicleId, logDate: mDate, odometer: Math.round(Number(mOdo.replace(/[^0-9.]/g, "")) || 0), notes: mNotes }), onSuccess: () => { invalidate(); setMOdo(""); setMNotes(""); }, onError: () => setMsg(tr("Could not save the mileage reading.", "Não foi possível salvar a leitura de quilometragem.", "No se pudo guardar la lectura de millaje.")) });

  /* fuel */
  const [fuDate, setFuDate] = useState(todayInput()); const [fuPriceGal, setFuPriceGal] = useState(""); const [fuAmt, setFuAmt] = useState(""); const [fuOdo, setFuOdo] = useState(""); const [fuProj, setFuProj] = useState(""); const [fuNotes, setFuNotes] = useState(""); const [fuReceipt, setFuReceipt] = useState("");
  const fuCameraRef = useRef<HTMLInputElement | null>(null);
  const fuGalleryRef = useRef<HTMLInputElement | null>(null);
  const addFuel = useMutation({ mutationFn: () => api.addVehicleFuel({ companyId: cid, actorId, vehicleId, logDate: fuDate, gallons: 0, amount: parseMoney(fuAmt), odometer: Math.round(Number(fuOdo.replace(/[^0-9.]/g, "")) || 0), projectId: fuProj ? Number(fuProj) : null, notes: fuNotes + (fuPriceGal.trim() ? ` [${tr("Price/gal", "Preço/gal", "Precio/gal")}: $${fuPriceGal.trim()}]` : ""), receiptPhoto: fuReceipt }), onSuccess: () => { invalidate(); setFuPriceGal(""); setFuAmt(""); setFuOdo(""); setFuNotes(""); setFuReceipt(""); }, onError: () => setMsg(tr("Could not save the fuel entry.", "Não foi possível salvar o abastecimento.", "No se pudo guardar la carga de combustible.")) });

  /* maintenance */
  const [maDate, setMaDate] = useState(todayInput()); const [maType, setMaType] = useState<string>("oil_change"); const [maCost, setMaCost] = useState(""); const [maVendor, setMaVendor] = useState(""); const [maOdo, setMaOdo] = useState(""); const [maNotes, setMaNotes] = useState(""); const [maReceipt, setMaReceipt] = useState(""); const [maProj, setMaProj] = useState("");
  const addMaint = useMutation({ mutationFn: () => api.addVehicleMaintenance({ companyId: cid, actorId, vehicleId, maintDate: maDate, type: maType as "oil_change" | "tires" | "brakes" | "inspection" | "other", cost: parseMoney(maCost), vendor: maVendor, odometer: Math.round(Number(maOdo.replace(/[^0-9.]/g, "")) || 0), notes: maNotes, receiptNote: maReceipt, projectId: maProj ? Number(maProj) : null }), onSuccess: () => { invalidate(); setMaCost(""); setMaVendor(""); setMaOdo(""); setMaNotes(""); setMaReceipt(""); }, onError: () => setMsg(tr("Could not save the maintenance entry.", "Não foi possível salvar a manutenção.", "No se pudo guardar el mantenimiento.")) });

  /* tickets */
  const [tiDate, setTiDate] = useState(todayInput()); const [tiDesc, setTiDesc] = useState(""); const [tiAmt, setTiAmt] = useState(""); const [tiEmp, setTiEmp] = useState(""); const [tiNotes, setTiNotes] = useState("");
  const addTicket = useMutation({ mutationFn: () => api.addVehicleTicket({ companyId: cid, actorId, vehicleId, ticketDate: tiDate, description: tiDesc, amount: parseMoney(tiAmt), status: "open", employeeId: tiEmp ? Number(tiEmp) : null, notes: tiNotes }), onSuccess: () => { invalidate(); setTiDesc(""); setTiAmt(""); setTiNotes(""); }, onError: () => setMsg(tr("Could not save the ticket.", "Não foi possível salvar a multa.", "No se pudo guardar la multa.")) });
  const ticketStatus = useMutation({ mutationFn: (args: { ticketId: number; status: "open" | "paid" | "disputed" }) => api.updateVehicleTicket({ companyId: cid, actorId, ticketId: args.ticketId, status: args.status }), onSuccess: invalidate, onError: () => setMsg(tr("Could not update the ticket.", "Não foi possível atualizar a multa.", "No se pudo actualizar la multa.")) });

  /* oil settings */
  const [oilMiles, setOilMiles] = useState(""); const [oilMonths, setOilMonths] = useState(""); const [oilLastMiles, setOilLastMiles] = useState(""); const [oilLastDate, setOilLastDate] = useState("");
  const saveOil = useMutation({
    mutationFn: () => api.updateVehicle({ companyId: cid, actorId, vehicleId, oilIntervalMiles: Math.max(0, Math.round(Number(oilMiles.replace(/[^0-9.]/g, "")) || 0)), oilIntervalMonths: Math.max(0, Math.round(Number(oilMonths) || 0)), lastOilMileage: oilLastMiles.trim() ? Math.round(Number(oilLastMiles.replace(/[^0-9.]/g, "")) || 0) : null, lastOilDate: oilLastDate }),
    onSuccess: () => { invalidate(); setMsg(tr("Oil settings saved. ✅", "Configurações de óleo salvas. ✅", "Configuración de aceite guardada. ✅")); },
    onError: () => setMsg(tr("Could not save the oil settings.", "Não foi possível salvar as configurações de óleo.", "No se pudo guardar la configuración de aceite.")),
  });

  const deleteLog = useMutation({
    mutationFn: async (args: { kind: "mileage" | "fuel" | "maint" | "ticket"; id: number }) => {
      if (args.kind === "mileage") return api.deleteVehicleMileage({ companyId: cid, actorId, logId: args.id });
      if (args.kind === "fuel") return api.deleteVehicleFuel({ companyId: cid, actorId, logId: args.id });
      if (args.kind === "maint") return api.deleteVehicleMaintenance({ companyId: cid, actorId, logId: args.id });
      return api.deleteVehicleTicket({ companyId: cid, actorId, ticketId: args.id });
    },
    onSuccess: invalidate,
    onError: () => setMsg(tr("Could not delete that entry.", "Não foi possível excluir esse lançamento.", "No se pudo eliminar ese registro.")),
  });

  if (detailQ.isPending) return (<div><button type="button" onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to fleet", "Voltar para a frota", "Volver a la flota")}>← {tr("Back to Fleet", "Voltar para a Frota", "Volver a la Flota")}</button><p className="py-10 text-center text-sm text-[var(--dim)]">{tr("Loading vehicle…", "Carregando veículo…", "Cargando vehículo…")}</p></div>);
  if (detailQ.error || !d || !v) return (<div><button type="button" onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to fleet", "Voltar para a frota", "Volver a la flota")}>← {tr("Back to Fleet", "Voltar para a Frota", "Volver a la Flota")}</button><p className="py-10 text-center text-sm font-semibold text-red-600">{tr("Could not load this vehicle.", "Não foi possível carregar este veículo.", "No se pudo cargar este vehículo.")}</p></div>);

  const sectionCls = "rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4";
  const isEmployee = session.role === "funcionario";
  const currentAssignments = d.assignments.filter((a) => a.current);
  const history = d.assignments.filter((a) => !a.current);

  return (
    <div className="space-y-4">
      <button type="button" onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to fleet", "Voltar para a frota", "Volver a la flota")}>← {tr("Back to Fleet", "Voltar para a Frota", "Volver a la Flota")}</button>
      {msg && <p className="rounded-xl bg-[var(--surface)] px-3 py-2 text-sm font-semibold ring-1 ring-[var(--border)]" role="status">{msg}</p>}

      {/* header */}
      <div className={sectionCls}>
        {safeImgSrc(v.photoUrl) ? <img src={safeImgSrc(v.photoUrl)} alt={tr(`Photo of ${v.name}`, `Foto de ${v.name}`, `Foto de ${v.name}`)} className="mb-3 h-44 w-full rounded-xl object-cover" /> : null}
        <div className="flex flex-wrap items-center gap-2">
          <h2 className="text-xl font-bold">🚐 {v.name || fallbackName}</h2>
          <Badge text={vehicleStatusLabel(v.status)} tone={vehicleStatusTone(v.status)} />
          {oilBadge(v)}
        </div>
        <p className="mt-1 text-sm text-[var(--dim)]">{[v.year > 0 ? String(v.year) : "", v.make, v.model].filter(Boolean).join(" ")}{v.plate ? ` • ${tr("Plate", "Placa", "Placa")} ${v.plate}` : ""}{v.vin ? ` • VIN ${v.vin}` : ""}</p>
        <p className="mt-1 text-sm font-semibold">🛣️ {tr("Odometer:", "Odômetro:", "Odómetro:")} {fmtMiles(v.mileage)}</p>
        {v.ezpass === 1 && <p className="mt-1 text-sm font-semibold">🟣 EZPass{v.tagNumber ? `: ${v.tagNumber}` : ""}</p>}
        <p className="mt-1 flex flex-wrap gap-1">
          {v.currentUserNames.length > 0 ? v.currentUserNames.map((n) => <span key={n} className="rounded-full bg-[#0f2a44] px-2 py-0.5 text-[11px] font-bold text-white">👤 {n}</span>) : <span className="text-xs text-[var(--dim)]">{tr("Not assigned to anyone right now.", "Não atribuído a ninguém no momento.", "Sin asignar a nadie en este momento.")}</span>}
        </p>
        <p className="mt-2 text-xs text-[var(--dim)]">{tr("Totals:", "Totais:", "Totales:")} ⛽ {fmtUSD(d.totals.fuelCost)} • 🔧 {fmtUSD(d.totals.maintenanceCost)} • 🎫 {fmtUSD(d.totals.ticketsCost)}{d.totals.openTicketsAmount > 0 ? ` (${fmtUSD(d.totals.openTicketsAmount)} ${tr("open", "em aberto", "abiertas")})` : ""}</p>
        {!editing && !isEmployee ? (
          <div className="mt-3 flex gap-2">
            <button type="button" className={btnGhost} aria-label={tr(`Edit vehicle ${v.name}`, `Editar o veículo ${v.name}`, `Editar el vehículo ${v.name}`)} onClick={() => { setEName(v.name); setEMake(v.make); setEModel(v.model); setEYear(v.year > 0 ? String(v.year) : ""); setEPlate(v.plate); setEVin(v.vin); setEStatus(v.status); setEMileage(String(v.mileage)); setEEzpass(v.ezpass === 1); setETagNumber(v.tagNumber); setEditing(true); }}>{tr("Edit vehicle", "Editar veículo", "Editar vehículo")}</button>
            {confirmDelete ? (
              <>
                <span className="self-center text-xs font-bold text-red-600" role="alert">{tr("Delete this vehicle and all its logs?", "Excluir este veículo e todos os registros?", "¿Eliminar este vehículo y todos sus registros?")}</span>
                <button type="button" className="rounded-xl bg-red-600 px-4 py-2.5 font-semibold text-white active:opacity-80 disabled:opacity-40" disabled={deleteVehicle.isPending} aria-label={tr(`Confirm delete vehicle ${v.name}`, `Confirmar a exclusão do veículo ${v.name}`, `Confirmar la eliminación del vehículo ${v.name}`)} onClick={() => deleteVehicle.mutate()}>{tr("Delete", "Excluir", "Eliminar")}</button>
                <button type="button" className={btnGhost} onClick={() => setConfirmDelete(false)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
              </>
            ) : (
              <button type="button" className="rounded-xl border border-red-300 px-4 py-2.5 font-semibold text-red-600 active:opacity-70" aria-label={tr(`Delete vehicle ${v.name}`, `Excluir o veículo ${v.name}`, `Eliminar el vehículo ${v.name}`)} onClick={() => setConfirmDelete(true)}>{tr("Delete", "Excluir", "Eliminar")}</button>
            )}
          </div>
        ) : (
          <form className="mt-3 space-y-2" onSubmit={(e) => { e.preventDefault(); saveVehicle.mutate(); }}>
            <Field label={tr("Unit name / number", "Nome / número da unidade", "Nombre / número de la unidad")}><input aria-label={tr("Unit name or number", "Nome ou número da unidade", "Nombre o número de la unidad")} className={inputCls} value={eName} onChange={(e) => setEName(e.target.value)} required /></Field>
            <div className="grid grid-cols-3 gap-2">
              <Field label={tr("Make", "Marca", "Marca")}><input aria-label={tr("Vehicle make", "Marca do veículo", "Marca del vehículo")} className={inputCls} value={eMake} onChange={(e) => setEMake(e.target.value)} /></Field>
              <Field label={tr("Model", "Modelo", "Modelo")}><input aria-label={tr("Vehicle model", "Modelo do veículo", "Modelo del vehículo")} className={inputCls} value={eModel} onChange={(e) => setEModel(e.target.value)} /></Field>
              <Field label={tr("Year", "Ano", "Año")}><input aria-label={tr("Vehicle year", "Ano do veículo", "Año del vehículo")} className={inputCls} inputMode="numeric" value={eYear} onChange={(e) => setEYear(e.target.value)} /></Field>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <Field label={tr("Plate", "Placa", "Placa")}><input aria-label={tr("License plate", "Placa do veículo", "Placa del vehículo")} className={inputCls} value={ePlate} onChange={(e) => setEPlate(e.target.value)} /></Field>
              <Field label={tr("Status", "Status", "Estado")}>
                <select aria-label={tr("Vehicle status", "Status do veículo", "Estado del vehículo")} className={inputCls} value={eStatus} onChange={(e) => setEStatus(e.target.value)}>
                  {VEHICLE_STATUSES.map((st) => <option key={st} value={st}>{vehicleStatusLabel(st)}</option>)}
                </select>
              </Field>
            </div>
            <Field label={tr("VIN (optional)", "VIN (opcional)", "VIN (opcional)")}><input aria-label={tr("Vehicle VIN", "VIN do veículo", "VIN del vehículo")} className={inputCls} value={eVin} onChange={(e) => setEVin(e.target.value)} /></Field>
            <Field label={tr("Current mileage (mi)", "Quilometragem atual (mi)", "Millaje actual (mi)")}><input aria-label={tr("Current odometer in miles", "Odômetro atual em milhas", "Odómetro actual en millas")} className={inputCls} inputMode="numeric" value={eMileage} onChange={(e) => setEMileage(e.target.value)} /></Field>
            <div className="flex items-center gap-2">
              <input type="checkbox" id="ezpass-check" checked={eEzpass} onChange={(e) => setEEzpass(e.target.checked)} className="h-4 w-4" />
              <label htmlFor="ezpass-check" className="text-sm font-semibold">{tr("Has EZPass", "Tem EZPass", "Tiene EZPass")}</label>
            </div>
            {eEzpass && (
              <Field label={tr("Tag number", "Número da tag", "Número de tag")}><input aria-label={tr("EZPass tag number", "Número da tag EZPass", "Número de tag EZPass")} className={inputCls} value={eTagNumber} onChange={(e) => setETagNumber(e.target.value)} placeholder="123456789" /></Field>
            )}
            <div className="flex gap-2">
              <button type="button" className={btnGhost} onClick={() => setEditing(false)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
              <button className={`${btnNavy} flex-1`} disabled={saveVehicle.isPending || !eName.trim()}>{saveVehicle.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save vehicle", "Salvar veículo", "Guardar vehículo")}</button>
            </div>
          </form>
        )}
      </div>

      {!isEmployee && (<>
      {/* currently used by */}
      <div className={sectionCls}>
        <h3 className="font-bold">👥 {tr("Currently used by", "Em uso por", "En uso por")}</h3>
        <div className="mt-2 space-y-1.5">
          {currentAssignments.map((a) => (
            <div key={a.id} className="flex items-center justify-between gap-2 rounded-lg bg-[var(--surface2)] px-2.5 py-1.5 text-sm">
              <span className="min-w-0"><span className="font-semibold">{a.employeeName}</span> <span className="text-[var(--dim)]">• {tr("since", "desde", "desde")} {fmtDate(a.assignedAt)}</span></span>
              <button type="button" className="shrink-0 text-xs font-bold text-red-600" aria-label={tr(`Remove ${v.name} from ${a.employeeName}`, `Retirar ${v.name} de ${a.employeeName}`, `Retirar ${v.name} de ${a.employeeName}`)} disabled={unassignMut.isPending} onClick={() => unassignMut.mutate(a.employeeId)}>{tr("Remove", "Remover", "Quitar")}</button>
            </div>
          ))}
          {currentAssignments.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("Nobody is using this vehicle right now.", "Ninguém está usando este veículo no momento.", "Nadie está usando este vehículo en este momento.")}</p>}
        </div>
        <div className="mt-2 flex gap-2">
          <select aria-label={tr("Employee to assign this vehicle to", "Funcionário para atribuir este veículo", "Empleado al que asignar este vehículo")} className={inputCls} value={addUserId} onChange={(e) => setAddUserId(e.target.value)}>
            <option value="">{tr("Assign to…", "Atribuir a…", "Asignar a…")}</option>
            {employees.filter((e: EmpLite) => !currentAssignments.some((a) => a.employeeId === e.id)).map((e: EmpLite) => <option key={e.id} value={e.id}>{e.name}{e.trade ? ` — ${e.trade}` : ""}</option>)}
          </select>
          <button type="button" className={btnNavy} disabled={!addUserId || assignMut.isPending} aria-label={tr(`Assign ${v.name} to the selected employee`, `Atribuir ${v.name} ao funcionário selecionado`, `Asignar ${v.name} al empleado seleccionado`)} onClick={() => assignMut.mutate(Number(addUserId))}>{tr("Assign", "Atribuir", "Asignar")}</button>
        </div>
        {history.length > 0 && (
          <div className="mt-3 border-t border-[var(--border)] pt-2">
            <p className="text-[11px] font-black uppercase tracking-wide text-[var(--dim)]">{tr("Assignment history", "Histórico de atribuições", "Historial de asignaciones")}</p>
            <div className="mt-1 space-y-1">
              {history.map((a) => <p key={a.id} className="text-xs text-[var(--dim)]">👤 {a.employeeName} • {fmtDate(a.assignedAt)} → {a.unassignedAt ? fmtDate(a.unassignedAt) : "…"}</p>)}
            </div>
          </div>
        )}
      </div></>)}

      {!isEmployee && (<>
      {/* oil settings */}
      <div className={sectionCls}>
        <h3 className="font-bold">🛢️ {tr("Oil change alerts", "Alertas de troca de óleo", "Alertas de cambio de aceite")}</h3>
        <p className="mt-1 text-sm text-[var(--dim)]">
          {v.lastOilMileage !== null || v.lastOilDate
            ? tr(`Last oil change: ${v.lastOilMileage !== null ? fmtMiles(v.lastOilMileage) : "—"}${v.lastOilDate ? ` • ${fmtDate(v.lastOilDate)}` : ""}. Next due: ${v.oilDueMileage !== null ? fmtMiles(v.oilDueMileage) : "—"}${v.oilDueDate ? ` • ${fmtDate(v.oilDueDate)}` : ""}.`, `Última troca de óleo: ${v.lastOilMileage !== null ? fmtMiles(v.lastOilMileage) : "—"}${v.lastOilDate ? ` • ${fmtDate(v.lastOilDate)}` : ""}. Próximo vencimento: ${v.oilDueMileage !== null ? fmtMiles(v.oilDueMileage) : "—"}${v.oilDueDate ? ` • ${fmtDate(v.oilDueDate)}` : ""}.`, `Último cambio de aceite: ${v.lastOilMileage !== null ? fmtMiles(v.lastOilMileage) : "—"}${v.lastOilDate ? ` • ${fmtDate(v.lastOilDate)}` : ""}. Próximo vencimiento: ${v.oilDueMileage !== null ? fmtMiles(v.oilDueMileage) : "—"}${v.oilDueDate ? ` • ${fmtDate(v.oilDueDate)}` : ""}.`)
            : tr("No oil change recorded yet. Log an Oil change under Maintenance, or set the baseline below.", "Nenhuma troca de óleo registrada ainda. Lance uma Troca de óleo em Manutenção, ou defina a base abaixo.", "Todavía no hay ningún cambio de aceite registrado. Registra un Cambio de aceite en Mantenimiento, o define la base abajo.")}
        </p>
        <form className="mt-2 space-y-2" onSubmit={(e) => { e.preventDefault(); saveOil.mutate(); }}>
          <div className="grid grid-cols-2 gap-2">
            <Field label={tr("Every (miles)", "A cada (milhas)", "Cada (millas)")}><input aria-label={tr("Oil change interval in miles", "Intervalo de troca de óleo em milhas", "Intervalo de cambio de aceite en millas")} className={inputCls} inputMode="numeric" value={oilMiles || String(v.oilIntervalMiles)} onChange={(e) => setOilMiles(e.target.value)} /></Field>
            <Field label={tr("or every (months)", "ou a cada (meses)", "o cada (meses)")}><input aria-label={tr("Oil change interval in months", "Intervalo de troca de óleo em meses", "Intervalo de cambio de aceite en meses")} className={inputCls} inputMode="numeric" value={oilMonths || String(v.oilIntervalMonths)} onChange={(e) => setOilMonths(e.target.value)} /></Field>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Field label={tr("Last oil change (mi)", "Última troca (mi)", "Último cambio (mi)")}><input aria-label={tr("Odometer at last oil change in miles", "Odômetro na última troca de óleo em milhas", "Odómetro en el último cambio de aceite en millas")} className={inputCls} inputMode="numeric" value={oilLastMiles || (v.lastOilMileage !== null ? String(v.lastOilMileage) : "")} onChange={(e) => setOilLastMiles(e.target.value)} placeholder="45,000" /></Field>
            <Field label={tr("Last oil change (date)", "Última troca (data)", "Último cambio (fecha)")}><input aria-label={tr("Date of last oil change", "Data da última troca de óleo", "Fecha del último cambio de aceite")} type="date" className={inputCls} value={oilLastDate || v.lastOilDate} onChange={(e) => setOilLastDate(e.target.value)} /></Field>
          </div>
          <button className={`${btnNavy} w-full`} disabled={saveOil.isPending}>{saveOil.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save oil settings", "Salvar configurações de óleo", "Guardar configuración de aceite")}</button>
        </form>
      </div></>)}

      {!isEmployee && (<>
      {/* mileage log */}
      <div className={sectionCls}>
        <h3 className="font-bold">🛣️ {tr("Mileage log", "Registro de quilometragem", "Registro de millaje")}</h3>
        <form className="mt-2 grid grid-cols-2 gap-2" onSubmit={(e) => { e.preventDefault(); addMileage.mutate(); }}>
          <Field label={tr("Date", "Data", "Fecha")}><input aria-label={tr("Mileage reading date", "Data da leitura de quilometragem", "Fecha de la lectura de millaje")} type="date" className={inputCls} value={mDate} onChange={(e) => setMDate(e.target.value)} required /></Field>
          <Field label={tr("Odometer (mi)", "Odômetro (mi)", "Odómetro (mi)")}><input aria-label={tr("Odometer reading in miles", "Leitura do odômetro em milhas", "Lectura del odómetro en millas")} className={inputCls} inputMode="numeric" value={mOdo} onChange={(e) => setMOdo(e.target.value)} placeholder="48,250" required /></Field>
          <div className="col-span-2"><Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><input aria-label={tr("Mileage notes", "Observações da quilometragem", "Notas del millaje")} className={inputCls} value={mNotes} onChange={(e) => setMNotes(e.target.value)} /></Field></div>
          <button className={`${btnNavy} col-span-2 w-full`} disabled={addMileage.isPending || !mOdo.trim()}>{tr("Add reading", "Adicionar leitura", "Agregar lectura")}</button>
        </form>
        <div className="mt-2 space-y-1">
          {d.mileageLogs.map((m) => (
            <div key={m.id} className="flex items-center justify-between gap-2 rounded-lg bg-[var(--surface2)] px-2.5 py-1.5 text-sm">
              <span>{fmtDate(m.logDate)} • <span className="font-semibold">{fmtMiles(m.odometer)}</span>{m.notes ? <span className="text-[var(--dim)]"> • {m.notes}</span> : null}</span>
              <button type="button" className="shrink-0 text-xs font-bold text-red-600" aria-label={tr(`Delete mileage reading ${fmtMiles(m.odometer)} on ${fmtDate(m.logDate)}`, `Excluir a leitura de ${fmtMiles(m.odometer)} de ${fmtDate(m.logDate)}`, `Eliminar la lectura de ${fmtMiles(m.odometer)} del ${fmtDate(m.logDate)}`)} onClick={() => deleteLog.mutate({ kind: "mileage", id: m.id })}>{tr("Delete", "Excluir", "Eliminar")}</button>
            </div>
          ))}
          {d.mileageLogs.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No mileage readings yet.", "Nenhuma leitura ainda.", "Todavía no hay lecturas.")}</p>}
        </div>
      </div></>)}

      {/* fuel */}
      <div className={sectionCls}>
        <h3 className="font-bold">⛽ {tr("Fuel", "Combustível", "Combustible")} <span className="text-sm font-semibold text-[var(--dim)]">• {fmtUSD(d.totals.fuelCost)}</span></h3>
        <form className="mt-2 grid grid-cols-2 gap-2" onSubmit={(e) => { e.preventDefault(); addFuel.mutate(); }}>
          <Field label={tr("Date", "Data", "Fecha")}><input aria-label={tr("Fuel date", "Data do abastecimento", "Fecha de la carga")} type="date" className={inputCls} value={fuDate} onChange={(e) => setFuDate(e.target.value)} required /></Field>
          <Field label={tr("Odometer (mi)", "Odômetro (mi)", "Odómetro (mi)")}><input aria-label={tr("Odometer at fill in miles", "Odômetro no abastecimento em milhas", "Odómetro en la carga en millas")} className={inputCls} inputMode="numeric" value={fuOdo} onChange={(e) => setFuOdo(e.target.value)} placeholder="48,250" required /></Field>
          <Field label={tr("Price/gal (optional)", "Preço/gal (opcional)", "Precio/gal (opcional)")}><input aria-label={tr("Price per gallon", "Preço por galão", "Precio por galón")} className={inputCls} inputMode="decimal" value={fuPriceGal} onChange={(e) => setFuPriceGal(e.target.value)} placeholder="3.89" /></Field>
          <Field label={tr("Total (USD)", "Total (USD)", "Total (USD)")}><input aria-label={tr("Fuel total in US dollars", "Total do combustível em dólares", "Total del combustible en dólares")} className={inputCls} inputMode="decimal" value={fuAmt} onChange={(e) => setFuAmt(e.target.value)} placeholder="68.50" required /></Field>
          <div className="col-span-2">
            <Field label={tr("Project (optional)", "Obra (opcional)", "Obra (opcional)")}>
              <select aria-label={tr("Project for this fuel cost", "Obra deste custo de combustível", "Obra de este costo de combustible")} className={inputCls} value={fuProj} onChange={(e) => setFuProj(e.target.value)}>
                <option value="">{tr("No project", "Sem obra", "Sin obra")}</option>
                {projects.map((pr: { id: number; name: string }) => <option key={pr.id} value={pr.id}>{pr.name}</option>)}
              </select>
            </Field>
          </div>
          <div className="col-span-2"><Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><input aria-label={tr("Fuel notes", "Observações do abastecimento", "Notas de la carga")} className={inputCls} value={fuNotes} onChange={(e) => setFuNotes(e.target.value)} /></Field></div>
          <div className="col-span-2">
            <p className="mb-1 text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Receipt photo", "Foto do recibo", "Foto del recibo")}</p>
            {fuReceipt ? <img src={safeImgSrc(fuReceipt)} alt={tr("Gas receipt photo preview", "Prévia da foto do recibo", "Vista previa de la foto del recibo")} className="mb-2 h-32 w-full rounded-xl object-cover" /> : null}
            <div className="flex gap-2">
              <button type="button" className={btnGhost} aria-label={tr("Take a photo of the gas receipt", "Tirar foto do recibo de gasolina", "Tomar foto del recibo de gasolina")} onClick={() => fuCameraRef.current?.click()}>📷 {tr("Take photo", "Tirar foto", "Tomar foto")}</button>
              <button type="button" className={btnGhost} aria-label={tr("Choose receipt photo from gallery", "Escolher foto do recibo da galeria", "Elegir foto del recibo de la galería")} onClick={() => fuGalleryRef.current?.click()}>🖼️ {tr("Gallery", "Galeria", "Galería")}</button>
            </div>
            <input ref={fuCameraRef} type="file" accept="image/*" capture="environment" className="hidden" aria-label={tr("Take receipt photo", "Tirar foto do recibo", "Tomar foto del recibo")} onChange={async (e) => { const f = e.target.files?.[0]; if (f) setFuReceipt(await readPhotoFile(f)); e.target.value = ""; }} />
            <input ref={fuGalleryRef} type="file" accept="image/*" className="hidden" aria-label={tr("Choose receipt photo from gallery", "Escolher foto do recibo da galeria", "Elegir foto del recibo de la galería")} onChange={async (e) => { const f = e.target.files?.[0]; if (f) setFuReceipt(await readPhotoFile(f)); e.target.value = ""; }} />
          </div>
          <button className={`${btnNavy} col-span-2 w-full`} disabled={addFuel.isPending || !fuAmt.trim() || !fuOdo.trim()}>{tr("Add fill-up", "Adicionar abastecimento", "Agregar carga")}</button>
        </form>
        <div className="mt-2 space-y-1">
          {d.fuelLogs.map((f) => (
            <div key={f.id} className="flex items-center justify-between gap-2 rounded-lg bg-[var(--surface2)] px-2.5 py-1.5 text-sm">
              <span className="min-w-0">{f.receiptPhoto ? <img src={safeImgSrc(f.receiptPhoto)} alt={tr("Gas receipt", "Recibo de gasolina", "Recibo de gasolina")} className="mb-1 h-16 w-16 rounded-lg object-cover" /> : null}{fmtDate(f.logDate)} • <span className="font-semibold">{fmtUSD(f.amount)}</span> • {fmtMiles(f.odometer)}{f.projectName ? <span className="text-[var(--dim)]"> • 🏗️ {f.projectName}</span> : null}{f.notes ? <span className="text-[var(--dim)]"> • {f.notes}</span> : null}</span>
              {!isEmployee && <button type="button" className="shrink-0 text-xs font-bold text-red-600" aria-label={tr(`Delete fuel entry on ${fmtDate(f.logDate)}`, `Excluir o abastecimento de ${fmtDate(f.logDate)}`, `Eliminar la carga del ${fmtDate(f.logDate)}`)} onClick={() => deleteLog.mutate({ kind: "fuel", id: f.id })}>{tr("Delete", "Excluir", "Eliminar")}</button>}
            </div>
          ))}
          {d.fuelLogs.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No fuel entries yet. MPG appears from the second fill-up.", "Nenhum abastecimento ainda. O MPG aparece a partir do segundo abastecimento.", "Todavía no hay cargas. El MPG aparece a partir de la segunda carga.")}</p>}
        </div>
      </div>

      {!isEmployee && (<>
      {/* maintenance */}
      <div className={sectionCls}>
        <h3 className="font-bold">🔧 {tr("Maintenance", "Manutenção", "Mantenimiento")} <span className="text-sm font-semibold text-[var(--dim)]">• {fmtUSD(d.totals.maintenanceCost)}</span></h3>
        <form className="mt-2 grid grid-cols-2 gap-2" onSubmit={(e) => { e.preventDefault(); addMaint.mutate(); }}>
          <Field label={tr("Date", "Data", "Fecha")}><input aria-label={tr("Maintenance date", "Data da manutenção", "Fecha del mantenimiento")} type="date" className={inputCls} value={maDate} onChange={(e) => setMaDate(e.target.value)} required /></Field>
          <Field label={tr("Type", "Tipo", "Tipo")}>
            <select aria-label={tr("Maintenance type", "Tipo de manutenção", "Tipo de mantenimiento")} className={inputCls} value={maType} onChange={(e) => setMaType(e.target.value)}>
              {MAINT_TYPES.map((t) => <option key={t} value={t}>{maintTypeLabel(t)}</option>)}
            </select>
          </Field>
          <Field label={tr("Cost (USD)", "Custo (USD)", "Costo (USD)")}><input aria-label={tr("Maintenance cost in US dollars", "Custo da manutenção em dólares", "Costo del mantenimiento en dólares")} className={inputCls} inputMode="decimal" value={maCost} onChange={(e) => setMaCost(e.target.value)} placeholder="89.99" required /></Field>
          <Field label={tr("Odometer (mi)", "Odômetro (mi)", "Odómetro (mi)")}><input aria-label={tr("Odometer at maintenance in miles", "Odômetro na manutenção em milhas", "Odómetro en el mantenimiento en millas")} className={inputCls} inputMode="numeric" value={maOdo} onChange={(e) => setMaOdo(e.target.value)} placeholder="48,250" /></Field>
          <Field label={tr("Vendor", "Fornecedor / oficina", "Proveedor / taller")}><input aria-label={tr("Maintenance vendor", "Fornecedor da manutenção", "Proveedor del mantenimiento")} className={inputCls} value={maVendor} onChange={(e) => setMaVendor(e.target.value)} placeholder="Auto Service" /></Field>
          <Field label={tr("Receipt", "Recibo", "Recibo")}><input aria-label={tr("Receipt reference", "Referência do recibo", "Referencia del recibo")} className={inputCls} value={maReceipt} onChange={(e) => setMaReceipt(e.target.value)} placeholder={tr("Receipt # or note", "Nº do recibo ou observação", "N.º de recibo o nota")} /></Field>
          <div className="col-span-2">
            <Field label={tr("Project (optional)", "Obra (opcional)", "Obra (opcional)")}>
              <select aria-label={tr("Project for this maintenance cost", "Obra deste custo de manutenção", "Obra de este costo de mantenimiento")} className={inputCls} value={maProj} onChange={(e) => setMaProj(e.target.value)}>
                <option value="">{tr("No project", "Sem obra", "Sin obra")}</option>
                {projects.map((pr: { id: number; name: string }) => <option key={pr.id} value={pr.id}>{pr.name}</option>)}
              </select>
            </Field>
          </div>
          <div className="col-span-2"><Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><input aria-label={tr("Maintenance notes", "Observações da manutenção", "Notas del mantenimiento")} className={inputCls} value={maNotes} onChange={(e) => setMaNotes(e.target.value)} /></Field></div>
          <button className={`${btnNavy} col-span-2 w-full`} disabled={addMaint.isPending || !maCost.trim()}>{tr("Add maintenance", "Adicionar manutenção", "Agregar mantenimiento")}</button>
        </form>
        <div className="mt-2 space-y-1">
          {d.maintenance.map((m) => (
            <div key={m.id} className="flex items-center justify-between gap-2 rounded-lg bg-[var(--surface2)] px-2.5 py-1.5 text-sm">
              <span className="min-w-0">{fmtDate(m.maintDate)} • {maintTypeLabel(m.type)} • <span className="font-semibold">{fmtUSD(m.cost)}</span>{m.vendor ? <span className="text-[var(--dim)]"> • {m.vendor}</span> : null}{m.odometer > 0 ? <span className="text-[var(--dim)]"> • {fmtMiles(m.odometer)}</span> : null}{m.projectName ? <span className="text-[var(--dim)]"> • 🏗️ {m.projectName}</span> : null}{m.receiptNote ? <span className="text-[var(--dim)]"> • 🧾 {m.receiptNote}</span> : null}{m.notes ? <span className="text-[var(--dim)]"> • {m.notes}</span> : null}</span>
              <button type="button" className="shrink-0 text-xs font-bold text-red-600" aria-label={tr(`Delete maintenance on ${fmtDate(m.maintDate)}`, `Excluir a manutenção de ${fmtDate(m.maintDate)}`, `Eliminar el mantenimiento del ${fmtDate(m.maintDate)}`)} onClick={() => deleteLog.mutate({ kind: "maint", id: m.id })}>{tr("Delete", "Excluir", "Eliminar")}</button>
            </div>
          ))}
          {d.maintenance.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No maintenance yet.", "Nenhuma manutenção ainda.", "Todavía no hay mantenimiento.")}</p>}
        </div>
      </div></>)}

      {!isEmployee && (<>
      {/* tickets */}
      <div className={sectionCls}>
        <h3 className="font-bold">🎫 {tr("Tickets & fines", "Multas", "Multas")} <span className="text-sm font-semibold text-[var(--dim)]">• {fmtUSD(d.totals.ticketsCost)}{d.totals.openTicketsAmount > 0 ? ` (${fmtUSD(d.totals.openTicketsAmount)} ${tr("open", "em aberto", "abiertas")})` : ""}</span></h3>
        <form className="mt-2 grid grid-cols-2 gap-2" onSubmit={(e) => { e.preventDefault(); addTicket.mutate(); }}>
          <Field label={tr("Date", "Data", "Fecha")}><input aria-label={tr("Ticket date", "Data da multa", "Fecha de la multa")} type="date" className={inputCls} value={tiDate} onChange={(e) => setTiDate(e.target.value)} required /></Field>
          <Field label={tr("Amount (USD)", "Valor (USD)", "Importe (USD)")}><input aria-label={tr("Ticket amount in US dollars", "Valor da multa em dólares", "Importe de la multa en dólares")} className={inputCls} inputMode="decimal" value={tiAmt} onChange={(e) => setTiAmt(e.target.value)} placeholder="75.00" required /></Field>
          <div className="col-span-2"><Field label={tr("Description", "Descrição", "Descripción")}><input aria-label={tr("Ticket description", "Descrição da multa", "Descripción de la multa")} className={inputCls} value={tiDesc} onChange={(e) => setTiDesc(e.target.value)} placeholder={tr("E.g.: Parking ticket downtown", "Ex.: Multa de estacionamento no centro", "Ej.: Multa de estacionamiento en el centro")} required /></Field></div>
          <div className="col-span-2">
            <Field label={tr("Responsible employee (optional)", "Funcionário responsável (opcional)", "Empleado responsable (opcional)")}>
              <select aria-label={tr("Employee responsible for this ticket", "Funcionário responsável por esta multa", "Empleado responsable de esta multa")} className={inputCls} value={tiEmp} onChange={(e) => setTiEmp(e.target.value)}>
                <option value="">{tr("Not set", "Não definido", "Sin definir")}</option>
                {employees.map((e: EmpLite) => <option key={e.id} value={e.id}>{e.name}</option>)}
              </select>
            </Field>
          </div>
          <div className="col-span-2"><Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><input aria-label={tr("Ticket notes", "Observações da multa", "Notas de la multa")} className={inputCls} value={tiNotes} onChange={(e) => setTiNotes(e.target.value)} /></Field></div>
          <button className={`${btnNavy} col-span-2 w-full`} disabled={addTicket.isPending || !tiDesc.trim() || !tiAmt.trim()}>{tr("Add ticket", "Adicionar multa", "Agregar multa")}</button>
        </form>
        <div className="mt-2 space-y-1.5">
          {d.tickets.map((t) => (
            <div key={t.id} className="rounded-lg bg-[var(--surface2)] px-2.5 py-2 text-sm">
              <div className="flex items-start justify-between gap-2">
                <p className="min-w-0"><span className="font-semibold">{t.description || tr("Ticket", "Multa", "Multa")}</span> • {fmtUSD(t.amount)}<span className="block text-xs text-[var(--dim)]">{fmtDate(t.ticketDate)}{t.employeeName ? ` • 👤 ${t.employeeName}` : ""}{t.notes ? ` • ${t.notes}` : ""}</span></p>
                <Badge text={t.status === "paid" ? tr("Paid", "Paga", "Pagada") : t.status === "disputed" ? tr("Disputed", "Contestada", "Disputada") : tr("Open", "Aberta", "Abierta")} tone={t.status === "paid" ? "green" : t.status === "disputed" ? "amber" : "red"} />
              </div>
              <div className="mt-1.5 flex flex-wrap gap-1.5">
                {(["open", "paid", "disputed"] as const).map((st) => (
                  <button key={st} type="button" disabled={ticketStatus.isPending || t.status === st} aria-label={tr(`Mark ticket ${t.description} as ${st}`, `Marcar a multa ${t.description} como ${st}`, `Marcar la multa ${t.description} como ${st}`)} aria-pressed={t.status === st} onClick={() => ticketStatus.mutate({ ticketId: t.id, status: st })} className={`rounded-lg px-2.5 py-1 text-[11px] font-bold ${t.status === st ? "bg-[#0f2a44] text-white" : "border border-[var(--border)]"} disabled:opacity-40`}>{st === "paid" ? tr("Paid", "Paga", "Pagada") : st === "disputed" ? tr("Disputed", "Contestada", "Disputada") : tr("Open", "Aberta", "Abierta")}</button>
                ))}
                <button type="button" className="ml-auto text-[11px] font-bold text-red-600" aria-label={tr(`Delete ticket ${t.description}`, `Excluir a multa ${t.description}`, `Eliminar la multa ${t.description}`)} onClick={() => deleteLog.mutate({ kind: "ticket", id: t.id })}>{tr("Delete", "Excluir", "Eliminar")}</button>
              </div>
            </div>
          ))}
          {d.tickets.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No tickets. 🎉", "Nenhuma multa. 🎉", "Sin multas. 🎉")}</p>}
        </div>
      </div></>)}
    </div>
  );
}

/* ---------------- Projects ---------------- */
function Projects({ cid, session, onOpen, selected, onCloseDetail, onNewInvoice, pendingJobId, onConsumePendingJob }: { cid: string; session: Session; onOpen: (id: number) => void; selected: number | null; onCloseDetail: () => void; onNewInvoice?: (clientId: number | null, projectId: number | null) => void; pendingJobId?: number | null; onConsumePendingJob?: () => void }) {
  const q = useQuery({ queryKey: ["projects", cid], queryFn: () => api.listProjects({ companyId: cid }) });
  const clients = useQuery({ queryKey: ["clients", cid], queryFn: () => api.listClients({ companyId: cid }) });
  const canManage = session.role !== "funcionario";
  const [showForm, setShowForm] = useState(false);
  const [name, setName] = useState("");
  const [scope, setScope] = useState("");
  const [addr, setAddr] = useState<AddrParts>(emptyAddr());
  const [clientId, setClientId] = useState<string>("");
  const [budget, setBudget] = useState("");
  const [estimatedValue, setEstimatedValue] = useState("");
  const [geoLat, setGeoLat] = useState("");
  const [geoLng, setGeoLng] = useState("");
  const [geoRadiusFt, setGeoRadiusFt] = useState("650");
  const [geoMsg, setGeoMsg] = useState("");
  const [locating, setLocating] = useState(false);
  const qc = useQueryClient();
  const create = useMutation({
    mutationFn: () => api.createProject({
      companyId: cid, actorId: session.userId, name, scope, clientId: clientId ? Number(clientId) : null, budget: parseMoney(budget), estimatedValue: parseMoney(estimatedValue),
      startDate: todayInput(), endDate: "", status: "andamento", ...addr,
      geoLat: geoLat.trim() ? Number(geoLat) : null, geoLng: geoLng.trim() ? Number(geoLng) : null,
      geoRadius: ftToM(Number(geoRadiusFt) || 650),
    }),
    onSuccess: (r) => { qc.invalidateQueries({ queryKey: ["projects", cid] }); setShowForm(false); setName(""); setScope(""); setAddr(emptyAddr()); setBudget(""); setEstimatedValue(""); setGeoLat(""); setGeoLng(""); onOpen(r.id); },
  });
  const useMyLocation = async () => {
    setGeoMsg(tr("Getting your location…", "Obtendo sua localização…", "Obteniendo tu ubicación…"));
    const gps = await getGPS();
    if (gps) { setGeoLat(gps.lat.toFixed(6)); setGeoLng(gps.lng.toFixed(6)); setGeoMsg(tr("Location captured. Review and save.", "Localização capturada. Revise e salve.", "Ubicación capturada. Revisa y guarda.")); }
    else setGeoMsg(tr("Could not get GPS. Enter the coordinates manually.", "Não foi possível obter o GPS. Insira as coordenadas manualmente.", "No se pudo obtener el GPS. Ingresa las coordenadas manualmente."));
  };
  const locateOnMap = async () => {
    const query = formatAddr(addr);
    if (!query) { setGeoMsg(tr("Fill in the address first, then locate it on the map.", "Preencha o endereço primeiro e depois localize-o no mapa.", "Primero completa la dirección y luego localízala en el mapa.")); return; }
    setLocating(true);
    setGeoMsg(tr("Locating address…", "Localizando o endereço…", "Localizando la dirección…"));
    const hits = await nominatimSearch(query, 1);
    setLocating(false);
    const hit = hits[0];
    if (hit && Number.isFinite(hit.lat) && Number.isFinite(hit.lng)) {
      setGeoLat(hit.lat.toFixed(6));
      setGeoLng(hit.lng.toFixed(6));
      setGeoMsg(tr("Address located — the geofence is set to this point. Adjust the radius if needed.", "Endereço localizado — a cerca virtual está definida neste ponto. Ajuste o raio se necessário.", "Dirección localizada: la geocerca está fijada en este punto. Ajusta el radio si es necesario."));
    } else {
      setGeoMsg(tr("We couldn't locate that address. Double-check the fields, or enter latitude/longitude manually (or use “I'm at the site”).", "Não foi possível localizar esse endereço. Verifique os campos ou insira latitude/longitude manualmente (ou use “Estou na obra”).", "No se pudo localizar esa dirección. Verifica los campos o ingresa la latitud/longitud manualmente (o usa “Estoy en la obra”)."));
    }
  };
  const latNum = geoLat.trim() ? Number(geoLat) : NaN;
  const lngNum = geoLng.trim() ? Number(geoLng) : NaN;
  const showMap = Number.isFinite(latNum) && Number.isFinite(lngNum);

  if (selected !== null) {
    return <ProjectDetail cid={cid} projectId={selected} session={session} onBack={onCloseDetail} onNewInvoice={onNewInvoice} initialJobId={pendingJobId} onInitialJobConsumed={onConsumePendingJob} />;
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold">{tr("Projects", "Obras", "Obras")}</h2>
        <button className={btnPrimary} onClick={() => setShowForm((s) => !s)} aria-label={tr("New project", "Nova obra", "Nueva obra")}>{showForm ? tr("Close", "Fechar", "Cerrar") : "+ New project"}</button>
      </div>

      {showForm && (
        <form className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" onSubmit={(e) => { e.preventDefault(); create.mutate(); }}>
          <Field label={tr("Project name", "Nome da obra", "Nombre de la obra")}><input aria-label={tr("Project name", "Nome da obra", "Nombre de la obra")} autoComplete="off" className={inputCls} value={name} onChange={(e) => setName(e.target.value)} placeholder="E.g.: Smith Residence — Kitchen Remodel" required /></Field>
          <Field label={tr("Scope of work", "Escopo do trabalho", "Alcance del trabajo")}>
            <textarea aria-label={tr("Scope of work", "Escopo do trabalho", "Alcance del trabajo")} className={inputCls} rows={5} value={scope} onChange={(e) => setScope(e.target.value)} placeholder={tr("Describe what needs to be done on this job...", "Descreva o que precisa ser feito nesta obra...", "Describe lo que hay que hacer en esta obra...")} />
          </Field>
          <div>
            <span className="mb-1 block text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Job site address", "Endereço da obra", "Dirección de la obra")}</span>
            <AddressForm idPrefix="new-project" value={addr} onChange={setAddr} onPick={(s) => {
              if (Number.isFinite(s.lat) && Number.isFinite(s.lng)) {
                setGeoLat(s.lat.toFixed(6)); setGeoLng(s.lng.toFixed(6));
                setGeoMsg(tr("Address selected — geofence set to the same point.", "Endereço selecionado — cerca virtual definida no mesmo ponto.", "Dirección seleccionada: geocerca fijada en el mismo punto."));
              }
            }} />
          </div>
          <Field label={tr("Client", "Cliente", "Cliente")}>
            <select aria-label={tr("Project client", "Cliente da obra", "Cliente de la obra")} className={inputCls} value={clientId} onChange={(e) => setClientId(e.target.value)}>
              <option value="">{tr("No client", "Sem cliente", "Sin cliente")}</option>
              {(clients.data?.clients ?? []).map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            <span className="mt-1 block text-xs font-normal normal-case tracking-normal text-[var(--dim)]">{tr("Optional — a project can have one client, or none. A client can have many projects.", "Opcional — uma obra pode ter um cliente, ou nenhum. Um cliente pode ter várias obras.", "Opcional: una obra puede tener un cliente, o ninguno. Un cliente puede tener varias obras.")}</span>
          </Field>
          {canManage && (
            <Field label={tr("Estimated value (USD) — contract / quoted price", "Valor estimado (USD) — preço do contrato / orçamento", "Valor estimado (USD): precio del contrato / cotizado")}>
              <input aria-label={tr("Estimated value in US dollars", "Valor estimado em dólares", "Valor estimado en dólares")} className={inputCls} inputMode="decimal" value={estimatedValue} onChange={(e) => setEstimatedValue(e.target.value)} placeholder="12,500.00" />
              <span className="mt-1 block text-xs font-normal normal-case tracking-normal text-[var(--dim)]">{tr("What the client will pay for this job. Labor and materials are tracked against it automatically. Admin/manager only.", "O que o cliente pagará por este trabalho. Mão de obra e materiais são acompanhados contra ele automaticamente. Somente administrador/gerente.", "Lo que el cliente pagará por este trabajo. La mano de obra y los materiales se controlan contra ese valor automáticamente. Solo administrador/gerente.")}</span>
            </Field>
          )}
          <Field label={tr("Budget (USD)", "Orçamento (USD)", "Presupuesto (USD)")}><input aria-label={tr("Budget in US dollars", "Orçamento em dólares", "Presupuesto en dólares")} className={inputCls} inputMode="decimal" value={budget} onChange={(e) => setBudget(e.target.value)} placeholder="150,000.00" /></Field>
          <div className="rounded-xl bg-[var(--surface2)] p-3">
            <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Geofence (job site GPS)", "Cerca virtual (GPS da obra)", "Geocerca (GPS de la obra)")}</p>
            <p className="mt-1 text-xs text-[var(--dim)]">{tr("Check-ins outside this radius are flagged for the manager. Fill the address above and tap “Locate on map”, pick an address suggestion, or leave blank to skip validation.", "Check-ins fora deste raio são sinalizados para o gerente. Preencha o endereço acima e toque em “Localizar no mapa”, escolha uma sugestão de endereço ou deixe em branco para pular a validação.", "Los registros fuera de este radio se marcan para el gerente. Completa la dirección arriba y toca “Localizar en el mapa”, elige una sugerencia de dirección o déjalo en blanco para omitir la validación.")}</p>
            <button type="button" className={`${btnGhost} mt-2 w-full`} onClick={locateOnMap} disabled={locating} aria-label={tr("Locate the job site address on the map", "Localizar o endereço da obra no mapa", "Localizar la dirección de la obra en el mapa")}>
              {locating ? tr("Locating…", "Localizando…", "Localizando…") : tr("🗺️ Locate on map", "🗺️ Localizar no mapa", "🗺️ Localizar en el mapa")}
            </button>
            {showMap && <div className="mt-3"><GeoMap lat={latNum} lng={lngNum} label={formatAddr(addr) || name || tr("Job site", "Local da obra", "Lugar de la obra")} /></div>}
            <div className="mt-3 grid grid-cols-2 gap-2">
              <Field label={tr("Latitude", "Latitude", "Latitud")}><input aria-label={tr("Job site latitude", "Latitude da obra", "Latitud de la obra")} className={inputCls} inputMode="decimal" value={geoLat} onChange={(e) => setGeoLat(e.target.value)} placeholder="39.975600" /></Field>
              <Field label={tr("Longitude", "Longitude", "Longitud")}><input aria-label={tr("Job site longitude", "Longitude da obra", "Longitud de la obra")} className={inputCls} inputMode="decimal" value={geoLng} onChange={(e) => setGeoLng(e.target.value)} placeholder="-74.158400" /></Field>
            </div>
            <div className="mt-2 flex items-end gap-2">
              <div className="flex-1"><Field label={tr("Radius (feet)", "Raio (pés)", "Radio (pies)")}><input aria-label={tr("Geofence radius in feet", "Raio da cerca virtual em pés", "Radio de la geocerca en pies")} className={inputCls} inputMode="numeric" value={geoRadiusFt} onChange={(e) => setGeoRadiusFt(e.target.value)} /></Field></div>
              <button type="button" className={btnGhost} onClick={useMyLocation}>{tr("📍 I'm at the site", "📍 Estou na obra", "📍 Estoy en la obra")}</button>
            </div>
            {geoMsg && <p className="mt-1 text-xs font-semibold" role="status">{geoMsg}</p>}
          </div>
          <button className={`${btnNavy} w-full`} disabled={create.isPending || !name.trim()}>{create.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Create project", "Criar obra", "Crear obra")}</button>
        </form>
      )}

      {q.isPending && <p className="py-8 text-center text-[var(--dim)]">{tr("Loading projects…", "Carregando obras…", "Cargando obras…")}</p>}
      {q.data && q.data.projects.length === 0 && !showForm && (
        <div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center">
          <p className="text-4xl">🏗️</p>
          <p className="mt-2 font-semibold">{tr("No projects in this company yet", "Nenhuma obra nesta empresa ainda", "Todavía no hay obras en esta empresa")}</p>
          <p className="mt-1 text-sm text-[var(--dim)]">{tr("Tap “+ New project” to add the first one.", "Toque em “+ Nova obra” para adicionar a primeira.", "Toca “+ Nueva obra” para agregar la primera.")}</p>
        </div>
      )}
      <div className="space-y-3">
        {(q.data?.projects ?? []).map((p) => {
          const showProfit = session.role === "admin" && p.estimatedValue > 0;
          const profitNegative = p.profit < 0;
          return (
          <button key={p.id} onClick={() => onOpen(p.id)} aria-label={tr(`Open project ${p.name}`, `Abrir a obra ${p.name}`, `Abrir la obra ${p.name}`)} className="w-full rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left active:opacity-80">
            <div className="flex items-start justify-between gap-2">
              <p className="font-bold leading-snug">{p.name}</p>
              <Badge text={projectStatusLabel(p.status)} tone={p.status === "andamento" ? "green" : p.status === "concluida" ? "navy" : "gray"} />
            </div>
            {session.role !== "funcionario" && p.clientName && <p className="mt-1 text-sm text-[var(--dim)]">{tr("Client:", "Cliente:", "Cliente:")} {p.clientName}</p>}
            {p.address && <p className="text-sm text-[var(--dim)]">📍 {p.address}</p>}
            {p.scope && <p className="mt-1 line-clamp-2 text-sm text-[var(--text)]"><span className="font-semibold">{tr("What to do:", "O que fazer:", "Qué hacer:")}</span> {p.scope}</p>}
            <p className="text-xs font-semibold text-[var(--dim)]">{p.geoLat !== null ? `🛡️ ${tr("Geofence on", "Cerca virtual ativa", "Geocerca activa")} • ${mToFt(p.geoRadius)} ft ${tr("radius", "de raio", "de radio")}` : tr("⚠️ No geofence — GPS is not validated on this project", "⚠️ Sem cerca virtual — o GPS não é validado nesta obra", "⚠️ Sin geocerca: el GPS no se valida en esta obra")}</p>
            <div className="mt-3">
              <div className="flex justify-between text-xs font-semibold text-[var(--dim)]"><span>{tr("Progress", "Andamento", "Progreso")}</span><span>{p.progress}%</span></div>
              <div className="mt-1 h-2 overflow-hidden rounded-full bg-[var(--surface2)]"><div className="h-full rounded-full bg-[#f97316]" style={{ width: `${p.progress}%` }} /></div>
            </div>
            <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1">
              <p className="text-xs text-[var(--dim)]">{tr("Budget", "Orçamento", "Presupuesto")} {fmtUSD(p.budget)} • {fmtDate(p.startDate)} → {fmtDate(p.endDate)}</p>
              {showProfit && (
                <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-bold ${profitNegative ? "bg-red-100 text-red-700" : "bg-green-100 text-green-800"}`} aria-label={tr(`Profit ${fmtUSD(p.profit)}, margin ${p.profitMargin.toFixed(1)} percent`, `Lucro de ${fmtUSD(p.profit)}, margem de ${p.profitMargin.toFixed(1)} por cento`, `Ganancia de ${fmtUSD(p.profit)}, margen del ${p.profitMargin.toFixed(1)} por ciento`)}>
                  {fmtUSD(p.profit)} • {p.profitMargin.toFixed(1)}%
                </span>
              )}
              {canManage && p.estimatedValue === 0 && (
                <span className="text-xs font-semibold text-[var(--dim)]">{tr("No estimated value yet", "Nenhum valor estimado ainda", "Todavía no hay valor estimado")}</span>
              )}
            </div>
          </button>
          );
        })}
      </div>
    </div>
  );
}

function ProjectDetail({ cid, projectId, session, onBack, onNewInvoice, initialJobId, onInitialJobConsumed }: { cid: string; projectId: number; session: Session; onBack: () => void; onNewInvoice?: (clientId: number | null, projectId: number | null) => void; initialJobId?: number | null; onInitialJobConsumed?: () => void }) {
  const q = useQuery({ queryKey: ["project-detail", cid, projectId], queryFn: () => api.getProjectDetail({ companyId: cid, projectId }) });
  const [openJobId, setOpenJobId] = useState<number | null>(null);
  /* Deep link (e.g. tapping one of today's jobs in the Field tab): open that
     job's detail as soon as the project data lands, then consume the link. */
  useEffect(() => {
    if (initialJobId == null) return;
    if ((q.data?.jobs ?? []).some((j) => j.id === initialJobId)) {
      setOpenJobId(initialJobId);
      onInitialJobConsumed?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialJobId, q.data]);
  const emps = useQuery({ queryKey: ["employees", cid], queryFn: () => api.listEmployees({ companyId: cid }) });
  const clientsQ = useQuery({ queryKey: ["clients", cid], queryFn: () => api.listClients({ companyId: cid }) });
  const qc = useQueryClient();
  const assign = useMutation({ mutationFn: (employeeId: number) => api.assignEmployee({ companyId: cid, projectId, employeeId }), onSuccess: () => qc.invalidateQueries({ queryKey: ["project-detail", cid, projectId] }) });
  const unassign = useMutation({ mutationFn: (employeeId: number) => api.unassignEmployee({ companyId: cid, projectId, employeeId }), onSuccess: () => qc.invalidateQueries({ queryKey: ["project-detail", cid, projectId] }) });
  const upd = useMutation({ mutationFn: (args: { status?: string; progress?: number; estimatedValue?: number; clientId?: number | null; geoLat?: number | null; geoLng?: number | null; geoRadius?: number }) => api.updateProject({ companyId: cid, projectId, actorId: session.userId, ...args }), onSuccess: () => { qc.invalidateQueries({ queryKey: ["project-detail", cid, projectId] }); qc.invalidateQueries({ queryKey: ["projects", cid] }); qc.invalidateQueries({ queryKey: ["clients", cid] }); } });
  const saveSite = useMutation({
    mutationFn: (args: { addr: AddrParts; geoLat: number | null; geoLng: number | null; geoRadius: number }) =>
      api.updateProject({ companyId: cid, projectId, ...args.addr, geoLat: args.geoLat, geoLng: args.geoLng, geoRadius: args.geoRadius }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["project-detail", cid, projectId] }); qc.invalidateQueries({ queryKey: ["projects", cid] }); setGeoMsg(tr("Address and geofence saved. ✅", "Endereço e cerca virtual salvos. ✅", "Dirección y geocerca guardadas. ✅")); },
    onError: () => setGeoMsg(tr("Could not save. Please try again.", "Não foi possível salvar. Tente novamente.", "No se pudo guardar. Inténtalo de nuevo.")),
  });
  const saveScope = useMutation({
    mutationFn: (scope: string) => api.updateProject({ companyId: cid, projectId, scope }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["project-detail", cid, projectId] });
      qc.invalidateQueries({ queryKey: ["projects", cid] });
      qc.invalidateQueries({ queryKey: ["my-today", cid] });
      setScopeEdit(null);
      setScopeMsg(tr("Scope of work saved. ✅", "Escopo do trabalho salvo. ✅", "Alcance del trabajo guardado. ✅"));
    },
    onError: () => setScopeMsg(tr("Could not save the scope of work. Please try again.", "Não foi possível salvar o escopo do trabalho. Tente novamente.", "No se pudo guardar el alcance del trabajo. Inténtalo de nuevo.")),
  });
  const [assignId, setAssignId] = useState("");
  const [addrEdit, setAddrEdit] = useState<AddrParts | null>(null);
  const [geoLat, setGeoLat] = useState<string | null>(null);
  const [geoLng, setGeoLng] = useState<string | null>(null);
  const [geoRadiusFt, setGeoRadiusFt] = useState<string | null>(null);
  const [geoMsg, setGeoMsg] = useState("");
  const [locating, setLocating] = useState(false);
  const [scopeEdit, setScopeEdit] = useState<string | null>(null);
  const [scopeMsg, setScopeMsg] = useState("");
  const [estEdit, setEstEdit] = useState<string | null>(null);
  const [estMsg, setEstMsg] = useState("");
  const [clientEdit, setClientEdit] = useState<string | null>(null);
  const [clientLinkMsg, setClientLinkMsg] = useState("");
  const [showJobForm, setShowJobForm] = useState(false);
  const [jobPick, setJobPick] = useState<JobServicePick>({ serviceId: null, name: "" });
  const [jobScope, setJobScope] = useState("");
  const [jobStatus, setJobStatus] = useState("scheduled");
  const [jobStart, setJobStart] = useState(todayInput());
  const [jobEnd, setJobEnd] = useState("");
  const [jobEst, setJobEst] = useState("");
  const createJob = useMutation({
    mutationFn: () => api.createJob({ companyId: cid, actorId: session.userId, projectId, name: jobPick.name, serviceId: jobPick.serviceId, scope: jobScope, status: jobStatus as "scheduled" | "in_progress" | "done", startDate: jobStart, endDate: jobEnd, estimatedValue: parseMoney(jobEst) }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["project-detail", cid, projectId] }); qc.invalidateQueries({ queryKey: ["my-today", cid] }); setShowJobForm(false); setJobPick({ serviceId: null, name: "" }); setJobScope(""); setJobEst(""); },
  });
  /* Smart estimate: picked service's default rate × this project's
     measured quantity for that service. Shown as a tappable suggestion;
     the estimate field itself stays fully editable. */
  const catalogQ = useQuery({ queryKey: ["services", cid], queryFn: () => api.listServices({ companyId: cid }), enabled: session.role !== "funcionario" });
  const measuresQ = useQuery({ queryKey: ["project-services", cid, projectId], queryFn: () => api.listProjectServices({ companyId: cid, projectId, actorId: session.userId }), enabled: session.role !== "funcionario" });
  const pickedSvc = jobPick.serviceId !== null ? (catalogQ.data?.services ?? []).find((s) => s.id === jobPick.serviceId) : undefined;
  const pickedLine = pickedSvc ? (measuresQ.data?.lines ?? []).find((l) => l.serviceId === pickedSvc.id && l.quantity > 0) : undefined;
  const estSuggestion = pickedSvc && pickedLine && pickedSvc.defaultRate > 0 ? Math.round(pickedSvc.defaultRate * pickedLine.quantity) : 0;

  if (q.isPending) return <p className="py-10 text-center text-[var(--dim)]">{tr("Loading project…", "Carregando a obra…", "Cargando la obra…")}</p>;
  if (!q.data?.project) return <div className="py-10 text-center"><p>{tr("Project not found.", "Obra não encontrada.", "Obra no encontrada.")}</p><button className={`${btnGhost} mt-3`} onClick={onBack}>{tr("Back", "Voltar", "Volver")}</button></div>;
  const p = q.data.project;
  const teamIds = new Set(q.data.team.map((t) => t.id));
  const canManage = session.role !== "funcionario";
  const addrVal: AddrParts = addrEdit ?? { streetNumber: p.streetNumber, streetName: p.streetName, city: p.city, state: p.state, zip: p.zip };
  const latStr = geoLat ?? (p.geoLat?.toString() ?? "");
  const lngStr = geoLng ?? (p.geoLng?.toString() ?? "");
  const radiusFtStr = geoRadiusFt ?? String(mToFt(p.geoRadius));
  const latNum = latStr.trim() ? Number(latStr) : NaN;
  const lngNum = lngStr.trim() ? Number(lngStr) : NaN;
  const showMap = Number.isFinite(latNum) && Number.isFinite(lngNum);

  const locateOnMap = async () => {
    const query = formatAddr(addrVal);
    if (!query) { setGeoMsg(tr("Fill in the address first, then locate it on the map.", "Preencha o endereço primeiro e depois localize-o no mapa.", "Primero completa la dirección y luego localízala en el mapa.")); return; }
    setLocating(true);
    setGeoMsg(tr("Locating address…", "Localizando o endereço…", "Localizando la dirección…"));
    const hits = await nominatimSearch(query, 1);
    setLocating(false);
    const hit = hits[0];
    if (hit && Number.isFinite(hit.lat) && Number.isFinite(hit.lng)) {
      setGeoLat(hit.lat.toFixed(6)); setGeoLng(hit.lng.toFixed(6));
      setGeoMsg(tr("Address located — review the point and radius, then save.", "Endereço localizado — revise o ponto e o raio e depois salve.", "Dirección localizada: revisa el punto y el radio, y luego guarda."));
    } else {
      setGeoMsg(tr("We couldn't locate that address. Double-check the fields, or enter latitude/longitude manually (or use “I'm at the site”).", "Não foi possível localizar esse endereço. Verifique os campos ou insira latitude/longitude manualmente (ou use “Estou na obra”).", "No se pudo localizar esa dirección. Verifica los campos o ingresa la latitud/longitud manualmente (o usa “Estoy en la obra”)."));
    }
  };

  const openJob = openJobId !== null ? q.data.jobs.find((j) => j.id === openJobId) : undefined;
  if (openJob) {
    return (
      <div className="space-y-3">
        <JobDetailView cid={cid} projectId={projectId} projectName={p.name} job={openJob} employees={emps.data?.employees ?? []} canManage={canManage} actorId={session.userId} onBack={() => setOpenJobId(null)} />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <button onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to project list", "Voltar para a lista de obras", "Volver a la lista de obras")}>{tr("← Back to projects", "← Voltar para obras", "← Volver a obras")}</button>
      <div className="rounded-2xl bg-[#0f2a44] p-5 text-white">
        <div className="flex items-start justify-between gap-2">
          <h2 className="text-lg font-bold leading-snug">{p.name}</h2>
          <Badge text={projectStatusLabel(p.status)} tone={p.status === "andamento" ? "green" : "gray"} />
        </div>
        {session.role !== "funcionario" && p.clientName && <p className="mt-1 text-sm text-white/70">{tr("Client:", "Cliente:", "Cliente:")} {p.clientName}</p>}
        {p.address && <p className="text-sm text-white/70">📍 {p.address}</p>}
        <p className="mt-2 text-sm text-white/70">{fmtDate(p.startDate)} → {fmtDate(p.endDate)} • {tr("Budget", "Orçamento", "Presupuesto")} {fmtUSD(p.budget)}{session.role === "admin" && (q.data.jobs.length > 0 || p.estimatedValue > 0) ? ` • ${tr("Estimated value", "Valor estimado", "Valor estimado")} ${fmtUSD(q.data.jobs.length > 0 ? q.data.jobs.reduce((s, j) => s + j.estimatedValue, 0) : p.estimatedValue)}` : ""}</p>
        <div className="mt-4">
          <div className="flex justify-between text-xs font-semibold text-white/60"><span>{tr("Progress", "Andamento", "Progreso")}</span><span>{p.progress}%</span></div>
          <div className="mt-1 h-2.5 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#f97316]" style={{ width: `${p.progress}%` }} /></div>
        </div>
        {canManage && (
          <div className="mt-4 flex flex-wrap gap-2">
            {[0, 25, 50, 75, 100].map((v) => (
              <button key={v} aria-label={tr(`Set progress to ${v}%`, `Definir o andamento para ${v}%`, `Fijar el progreso en ${v}%`)} onClick={() => upd.mutate({ progress: v })} className={`rounded-lg px-3 py-1.5 text-xs font-bold ${p.progress === v ? "bg-[#f97316] text-white" : "bg-white/10 text-white"}`}>{v}%</button>
            ))}
            <select aria-label={tr("Project status", "Status da obra", "Estado de la obra")} className="rounded-lg bg-white/10 px-2 py-1.5 text-xs font-bold text-white" value={p.status} onChange={(e) => upd.mutate({ status: e.target.value })}>
              <option value="planejada">{tr("Planned", "Planejada", "Planificada")}</option><option value="andamento">{tr("In progress", "Em andamento", "En curso")}</option><option value="pausada">{tr("Paused", "Pausada", "Pausada")}</option><option value="concluida">{tr("Completed", "Concluída", "Completada")}</option>
            </select>
          </div>
        )}
      </div>

      {session.role === "admin" && onNewInvoice && (
        <button type="button" onClick={() => onNewInvoice(p.clientId, p.id)} aria-label={tr(`New invoice for project ${p.name}`, `Nova fatura para a obra ${p.name}`, `Nueva factura para la obra ${p.name}`)} className={`${btnPrimary} w-full`}>{tr("+ New invoice for this project", "+ Nova fatura para esta obra", "+ Nueva factura para esta obra")}{p.clientName ? ` — ${tr("bill to", "cobrar de", "facturar a")} ${p.clientName}` : ""}</button>
      )}

      <section className="rounded-2xl border-2 border-[#f97316] bg-[var(--surface)] p-4" aria-label={tr("What to do on this project", "O que fazer nesta obra", "Qué hacer en esta obra")}>
        <p className="text-xs font-black uppercase tracking-wide text-[#f97316]">{tr("What to do", "O que fazer", "Qué hacer")}</p>
        {canManage ? (
          <div className="mt-2 space-y-2">
            <Field label={tr("Scope of work", "Escopo do trabalho", "Alcance del trabajo")}>
              <textarea aria-label={tr("Scope of work", "Escopo do trabalho", "Alcance del trabajo")} className={inputCls} rows={5} value={scopeEdit ?? p.scope} onChange={(e) => { setScopeEdit(e.target.value); setScopeMsg(""); }} placeholder={tr("Describe what needs to be done on this job...", "Descreva o que precisa ser feito nesta obra...", "Describe lo que hay que hacer en esta obra...")} />
            </Field>
            <button type="button" className={`${btnNavy} w-full`} disabled={saveScope.isPending || (scopeEdit ?? p.scope) === p.scope} onClick={() => saveScope.mutate(scopeEdit ?? p.scope)}>
              {saveScope.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save scope of work", "Salvar o escopo do trabalho", "Guardar el alcance del trabajo")}
            </button>
            {scopeMsg && <p className="text-xs font-semibold" role="status">{scopeMsg}</p>}
          </div>
        ) : p.scope ? (
          <p className="mt-2 whitespace-pre-line text-base leading-relaxed">{p.scope}</p>
        ) : (
          <p className="mt-2 text-sm text-[var(--dim)]">{tr("No work description has been added yet. Ask your manager what needs to be done before starting.", "Nenhuma descrição de trabalho foi adicionada ainda. Pergunte ao seu gerente o que precisa ser feito antes de começar.", "Todavía no se ha agregado ninguna descripción del trabajo. Pregúntale a tu gerente qué hay que hacer antes de empezar.")}</p>
        )}
      </section>

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Services and measurements for this project", "Serviços e medições desta obra", "Servicios y mediciones de esta obra")}>
        <h3 className="font-bold">{tr("🧱 Services & measurements", "🧱 Serviços e medições", "🧱 Servicios y mediciones")}</h3>
        <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("What this project needs, in measured quantities — e.g. Hardwood floor, 400 sq ft. The crew sees this exact list in the field.", "O que esta obra precisa, em quantidades medidas — ex.: Piso de madeira, 400 sq ft. A equipe vê esta mesma lista no campo.", "Lo que esta obra necesita, en cantidades medidas, p. ej., Piso de madera, 400 sq ft. El equipo ve esta misma lista en el campo.")}</p>
        <ProjectServicesSection cid={cid} projectId={projectId} actorId={session.userId} canManage={canManage} />
      </section>

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Plans and blueprints for this project", "Plantas desta obra", "Planos de esta obra")}>
        <h3 className="font-bold">{tr("📐 Plans & blueprints", "📐 Plantas", "📐 Planos")}</h3>
        <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("The project's plans, readable on site. Tap any plan to view it full-screen.", "As plantas da obra, legíveis no local. Toque em qualquer planta para vê-la em tela cheia.", "Los planos de la obra, legibles en el lugar. Toca cualquier plano para verlo en pantalla completa.")}</p>
        <ProjectPlansList cid={cid} actorId={session.userId} projectId={projectId} canManage={canManage} />
      </section>

      {canManage && (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Project client", "Cliente da obra", "Cliente de la obra")}>
          <h3 className="font-bold">{tr("Client", "Cliente", "Cliente")}</h3>
          <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("A project can have one client, or none. A client can have many projects.", "Uma obra pode ter um cliente, ou nenhum. Um cliente pode ter várias obras.", "Una obra puede tener un cliente, o ninguno. Un cliente puede tener varias obras.")}</p>
          <div className="mt-3 flex gap-2">
            <select aria-label={tr("Project client", "Cliente da obra", "Cliente de la obra")} className={inputCls} value={clientEdit ?? (p.clientId !== null ? String(p.clientId) : "")} onChange={(e) => { setClientEdit(e.target.value); setClientLinkMsg(""); }}>
              <option value="">{tr("No client", "Sem cliente", "Sin cliente")}</option>
              {(clientsQ.data?.clients ?? []).map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            <button type="button" className={btnNavy} aria-label={tr("Save project client", "Salvar o cliente da obra", "Guardar el cliente de la obra")}
              disabled={upd.isPending || (clientEdit ?? (p.clientId !== null ? String(p.clientId) : "")) === (p.clientId !== null ? String(p.clientId) : "")}
              onClick={() => {
                const val = clientEdit ?? (p.clientId !== null ? String(p.clientId) : "");
                upd.mutate({ clientId: val ? Number(val) : null }, {
                  onSuccess: () => { setClientEdit(null); setClientLinkMsg(tr("Client link saved. ✅", "Vínculo com o cliente salvo. ✅", "Vínculo con el cliente guardado. ✅")); },
                  onError: () => setClientLinkMsg(tr("Could not save the client link. Please try again.", "Não foi possível salvar o vínculo com o cliente. Tente novamente.", "No se pudo guardar el vínculo con el cliente. Inténtalo de nuevo.")),
                });
              }}>
              {upd.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save", "Salvar", "Guardar")}
            </button>
          </div>
          {p.clientName ? <p className="mt-2 text-sm text-[var(--dim)]">{tr("Currently linked to", "Atualmente vinculado a", "Actualmente vinculado a")} <span className="font-semibold text-[var(--text)]">{p.clientName}</span>.</p> : <p className="mt-2 text-sm text-[var(--dim)]">{tr("No client linked to this project.", "Nenhum cliente vinculado a esta obra.", "Ningún cliente vinculado a esta obra.")}</p>}
          {clientLinkMsg && <p className="mt-1 text-xs font-semibold" role="status">{clientLinkMsg}</p>}
        </section>
      )}

      {session.role === "admin" ? (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Job profitability", "Lucratividade da obra", "Rentabilidad de la obra")}>
          <div className="flex items-start justify-between gap-2">
            <div>
              <h3 className="font-bold">{tr("Job profitability", "Lucratividade da obra", "Rentabilidad de la obra")}</h3>
              <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("Estimated value vs. actual cost. Labor updates automatically when timesheets are approved.", "Valor estimado × custo real. A mão de obra é atualizada automaticamente quando os registros de ponto são aprovados.", "Valor estimado frente a costo real. La mano de obra se actualiza automáticamente cuando se aprueban los registros de horas.")}</p>
            </div>
            <Badge text={tr("Company owner only", "Somente o dono da empresa", "Solo el dueño de la empresa")} tone="navy" />
          </div>

          {/* Estimate — per job when the project has jobs (each job carries
              its own number); the single project-level contract price stays
              only while the project has no jobs yet. */}
          {q.data.jobs.length > 0 ? (
            <div className="mt-3 rounded-xl bg-[var(--surface2)] p-3">
              <div className="flex items-center justify-between text-sm">
                <span className="text-[var(--dim)]">{tr("Total estimate — sum of the per-job estimates", "Estimativa total — soma das estimativas por trabalho", "Estimación total: suma de las estimaciones por trabajo")}</span>
                <span className="font-bold">{fmtUSD(q.data.jobs.reduce((s, j) => s + j.estimatedValue, 0))}</span>
              </div>
              <p className="mt-1 text-xs text-[var(--dim)]">{tr("Each job has its own estimate below. Tap a job in “Jobs on this site” to change its number — this total follows.", "Cada trabalho tem sua própria estimativa abaixo. Toque em um trabalho em “Trabalhos neste local” para mudar o valor dele — este total acompanha.", "Cada trabajo tiene su propia estimación abajo. Toca un trabajo en “Trabajos en este lugar” para cambiar su valor: este total lo sigue.")}</p>
            </div>
          ) : (
          <div className="mt-3 rounded-xl bg-[var(--surface2)] p-3">
            <Field label={tr("Estimated value (USD) — contract / quoted price", "Valor estimado (USD) — preço do contrato / orçamento", "Valor estimado (USD): precio del contrato / cotizado")}>
              <div className="flex gap-2">
                <input
                  aria-label={tr("Estimated value in US dollars", "Valor estimado em dólares", "Valor estimado en dólares")}
                  className={inputCls}
                  inputMode="decimal"
                  value={estEdit ?? moneyInput(p.estimatedValue)}
                  onChange={(e) => { setEstEdit(e.target.value); setEstMsg(""); }}
                  placeholder="12,500.00"
                />
                <button
                  type="button"
                  className={btnNavy}
                  aria-label={tr("Save estimated value", "Salvar o valor estimado", "Guardar el valor estimado")}
                  disabled={upd.isPending || estEdit === null || parseMoney(estEdit) === p.estimatedValue}
                  onClick={() => {
                    upd.mutate({ estimatedValue: parseMoney(estEdit ?? "") }, {
                      onSuccess: () => { setEstEdit(null); setEstMsg(tr("Estimated value saved. ✅", "Valor estimado salvo. ✅", "Valor estimado guardado. ✅")); },
                      onError: () => setEstMsg(tr("Could not save. Only an admin or manager can change this.", "Não foi possível salvar. Somente um administrador ou gerente pode alterar isso.", "No se pudo guardar. Solo un administrador o gerente puede cambiar esto.")),
                    });
                  }}
                >
                  {upd.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save", "Salvar", "Guardar")}
                </button>
              </div>
            </Field>
            {estMsg && <p className="mt-1 text-xs font-semibold" role="status">{estMsg}</p>}
            <p className="mt-1 text-xs text-[var(--dim)]">{tr("The price you quoted the client for this job. Profit is calculated against it below.", "O preço que você orçou para o cliente por este trabalho. O lucro é calculado contra ele abaixo.", "El precio que cotizaste al cliente por este trabajo. La ganancia se calcula contra ese valor abajo.")}</p>
          </div>
          )}

          {/* Breakdown */}
          {(() => {
            const hasJobs = q.data.jobs.length > 0;
            const est = hasJobs ? q.data.jobs.reduce((s, j) => s + j.estimatedValue, 0) : p.estimatedValue;
            const labor = q.data.laborCost;
            const mats = q.data.expensesTotal;
            const total = q.data.totalCost;
            const profit = est - total;
            const margin = est > 0 ? Math.round((profit / est) * 1000) / 10 : 0;
            const costPct = est > 0 ? Math.min(100, Math.round((total / est) * 1000) / 10) : 0;
            const over = est > 0 && total > est;
            return (
              <div className="mt-3 space-y-2">
                <div className="flex items-center justify-between text-sm"><span className="text-[var(--dim)]">{hasJobs ? tr("Estimated value (per-job sum)", "Valor estimado (soma por trabalho)", "Valor estimado (suma por trabajo)") : tr("Estimated value", "Valor estimado", "Valor estimado")}</span><span className="font-bold">{fmtUSD(est)}</span></div>
                <div className="flex items-center justify-between text-sm">
                  <span className="text-[var(--dim)]">{tr("Labor cost", "Custo de mão de obra", "Costo de mano de obra")} <span className="text-[11px]">{tr("(auto — approved timesheets)", "(automático — registros aprovados)", "(automático: registros aprobados)")}</span></span>
                  <span className="font-semibold">{fmtUSD(labor)}</span>
                </div>
                <p className="-mt-1 text-[11px] text-[var(--dim)]">{tr("Hourly = approved hours × rate • Daily = approved days × daily rate • Contract = contract amount. Read-only — approve time in the Time tab and this updates.", "Por hora = horas aprovadas × valor • Por dia = dias aprovados × diária • Por contrato = valor do contrato. Somente leitura — aprove o ponto na aba Ponto e isto é atualizado.", "Por hora = horas aprobadas × tarifa • Por día = días aprobados × tarifa diaria • Por contrato = importe del contrato. Solo lectura: aprueba las horas en la pestaña Horas y esto se actualiza.")}</p>
                {q.data.jobs.length > 0 && (
                  <div className="rounded-lg bg-[var(--surface2)] px-3 py-2" aria-label={tr("Estimate by job", "Estimativa por trabalho", "Estimación por trabajo")}>
                    <p className="text-[11px] font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Estimate by job", "Estimativa por trabalho", "Estimación por trabajo")}</p>
                    <div className="mt-1 space-y-1">
                      {q.data.jobs.map((j) => (
                        <div key={j.id} className="flex items-center justify-between gap-2 text-xs">
                          <span className="min-w-0 truncate">🔧 {j.name}</span>
                          <span className="shrink-0 font-semibold">
                            {j.estimatedValue > 0 ? `${tr("Est.", "Est.", "Est.")} ${fmtUSD(j.estimatedValue)}` : tr("No estimate", "Sem estimativa", "Sin estimación")} • {tr("Labor", "Mão de obra", "Mano de obra")} {fmtUSD(j.laborCost)}{j.estimatedValue > 0 ? ` • ${fmtUSD(j.estimatedValue - j.laborCost)}` : ""}
                          </span>
                        </div>
                      ))}
                    </div>
                    <p className="mt-1 text-[11px] text-[var(--dim)]">{tr("Per job: estimate • labor • estimate minus labor. Materials stay at the project level, below.", "Por trabalho: estimativa • mão de obra • estimativa menos mão de obra. Os materiais ficam no nível da obra, abaixo.", "Por trabajo: estimación • mano de obra • estimación menos mano de obra. Los materiales quedan a nivel de la obra, abajo.")}</p>
                  </div>
                )}
                <div className="flex items-center justify-between text-sm">
                  <span className="text-[var(--dim)]">{tr("Materials & expenses", "Materiais e despesas", "Materiales y gastos")} <span className="text-[11px]">{tr("(optional)", "(opcional)", "(opcional)")}</span></span>
                  <span className="font-semibold">{fmtUSD(mats)}</span>
                </div>
                <p className="-mt-1 text-[11px] text-[var(--dim)]">{tr("Sum of materials/expenses logged on this project. Leave at $0 if you don't track materials — it's never required.", "Soma dos materiais/despesas registrados nesta obra. Deixe em $0 se você não acompanha materiais — nunca é obrigatório.", "Suma de materiales/gastos registrados en esta obra. Déjalo en $0 si no controlas los materiales: nunca es obligatorio.")}</p>
                <div className="flex items-center justify-between border-t border-[var(--border)] pt-2 text-sm"><span className="font-semibold">{tr("Total cost", "Custo total", "Costo total")}</span><span className="font-bold">{fmtUSD(total)}</span></div>
                <div className="flex items-center justify-between text-sm">
                  <span className="font-semibold">{tr("Profit", "Lucro", "Ganancia")}</span>
                  <span className={`font-black ${profit < 0 ? "text-red-600" : "text-green-700"}`}>
                    {fmtUSD(profit)}{est > 0 ? ` • ${margin.toFixed(1)}% ${tr("margin", "de margem", "de margen")}` : ""}
                  </span>
                </div>
                {est === 0 && <p className="rounded-lg bg-amber-100 px-2.5 py-1.5 text-xs font-semibold text-amber-800">{hasJobs ? tr("Open each job and set its estimate to see profit and margin.", "Abra cada trabalho e defina a estimativa dele para ver o lucro e a margem.", "Abre cada trabajo y define su estimación para ver la ganancia y el margen.") : tr("Set an estimated value above to see profit and margin.", "Defina um valor estimado acima para ver o lucro e a margem.", "Define un valor estimado arriba para ver la ganancia y el margen.")}</p>}
                {/* Visual bar: total cost vs estimated value */}
                {est > 0 && (
                  <div className="pt-1" aria-label={tr(`Total cost is ${costPct.toFixed(1)} percent of the estimated value`, `O custo total é ${costPct.toFixed(1)} por cento do valor estimado`, `El costo total es el ${costPct.toFixed(1)} por ciento del valor estimado`)}>
                    <div className="flex justify-between text-[11px] font-semibold text-[var(--dim)]"><span>{tr("Total cost vs. estimated value", "Custo total × valor estimado", "Costo total frente a valor estimado")}</span><span>{costPct.toFixed(1)}%</span></div>
                    <div className="mt-1 h-3 overflow-hidden rounded-full bg-[var(--surface2)]">
                      <div className={`h-full rounded-full ${over ? "bg-red-500" : costPct > 80 ? "bg-amber-500" : "bg-green-600"}`} style={{ width: `${Math.min(100, costPct)}%` }} />
                    </div>
                    <div className="mt-1 flex justify-between text-[11px] text-[var(--dim)]"><span>{fmtUSD(total)} {tr("cost", "de custo", "de costo")}</span><span>{fmtUSD(est)} {tr("estimated", "estimado", "estimado")}</span></div>
                    {over && <p className="mt-1 text-xs font-bold text-red-600">⚠ {tr("Over the estimated value by", "Acima do valor estimado em", "Por encima del valor estimado por")} {fmtUSD(total - est)}.</p>}
                  </div>
                )}
              </div>
            );
          })()}
        </section>
      ) : (
        <div className="grid grid-cols-3 gap-3">
          <Kpi label={tr("Labor", "Mão de obra", "Mano de obra")} value={fmtUSD(q.data.laborCost)} />
          <Kpi label={tr("Materials", "Materiais", "Materiales")} value={fmtUSD(q.data.expensesTotal)} />
          <Kpi label={tr("Total cost", "Custo total", "Costo total")} value={fmtUSD(q.data.laborCost + q.data.expensesTotal)} />
        </div>
      )}

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Jobs on this project", "Trabalhos nesta obra", "Trabajos en esta obra")}>
        <div className="flex items-center justify-between gap-2">
          <div>
            <h3 className="font-bold">{tr("Jobs on this site", "Trabalhos neste local", "Trabajos en este lugar")} ({q.data.jobs.length})</h3>
            <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("One project (job site) can have several jobs — e.g. Roof and Siding — each with its own crew, dates, and “what to do”. Geofence and materials stay at the project level.", "Uma obra (local) pode ter vários trabalhos — ex.: Telhado e Revestimento — cada um com sua equipe, datas e “o que fazer”. A cerca virtual e os materiais ficam no nível da obra.", "Una obra (lugar) puede tener varios trabajos — p. ej., Techo y Revestimiento — cada uno con su equipo, fechas y “qué hacer”. La geocerca y los materiales quedan a nivel de la obra.")}</p>
          </div>
          {canManage && <button className={btnPrimary} onClick={() => setShowJobForm((s) => !s)} aria-label={tr("New job on this project", "Novo trabalho nesta obra", "Nuevo trabajo en esta obra")}>{showJobForm ? tr("Close", "Fechar", "Cerrar") : tr("+ New job", "+ Novo trabalho", "+ Nuevo trabajo")}</button>}
        </div>

        {canManage && showJobForm && (
          <form className="mt-3 space-y-3 rounded-xl bg-[var(--surface2)] p-3" onSubmit={(e) => { e.preventDefault(); if (jobPick.name.trim()) createJob.mutate(); }}>
            <JobServicePicker cid={cid} actorId={session.userId} value={jobPick} onChange={setJobPick} />
            {pickedSvc && pickedLine && estSuggestion > 0 && (
              <button
                type="button"
                className="w-full rounded-xl bg-amber-100 px-3 py-2 text-left text-xs font-bold text-amber-900 active:opacity-80 dark:bg-amber-950/50 dark:text-amber-100"
                aria-label={tr(`Use the suggested estimate of ${fmtUSD(estSuggestion)} for ${pickedSvc.name}`, `Usar a estimativa sugerida de ${fmtUSD(estSuggestion)} para ${pickedSvc.name}`, `Usar la estimación sugerida de ${fmtUSD(estSuggestion)} para ${pickedSvc.name}`)}
                onClick={() => setJobEst(moneyInput(estSuggestion))}
              >
                💡 {tr("Suggested estimate:", "Estimativa sugerida:", "Estimación sugerida:")} {fmtUSD(estSuggestion)} <span className="font-semibold opacity-80">({fmtQty(pickedLine.quantity)} {pickedSvc.unit} × {fmtUSD(pickedSvc.defaultRate)}/{pickedSvc.unit}) — {tr("tap to use", "toque para usar", "toca para usar")}</span>
              </button>
            )}
            <Field label={tr("Scope — what to do", "Escopo — o que fazer", "Alcance: qué hacer")}><textarea aria-label={tr("New job scope of work", "Escopo do novo trabalho", "Alcance del nuevo trabajo")} className={inputCls} rows={4} value={jobScope} onChange={(e) => setJobScope(e.target.value)} placeholder={tr("Describe exactly what this crew needs to do…", "Descreva exatamente o que esta equipe precisa fazer…", "Describe exactamente lo que este equipo debe hacer…")} /></Field>
            <div className="grid grid-cols-3 gap-2">
              <Field label={tr("Status", "Status", "Estado")}>
                <select aria-label={tr("New job status", "Status do novo trabalho", "Estado del nuevo trabajo")} className={inputCls} value={jobStatus} onChange={(e) => setJobStatus(e.target.value)}>
                  <option value="scheduled">{tr("Scheduled", "Agendado", "Programado")}</option><option value="in_progress">{tr("In progress", "Em andamento", "En curso")}</option><option value="done">{tr("Done", "Concluído", "Terminado")}</option>
                </select>
              </Field>
              <Field label={tr("Start", "Início", "Inicio")}><input aria-label={tr("New job start date", "Data de início do novo trabalho", "Fecha de inicio del nuevo trabajo")} type="date" className={inputCls} value={jobStart} onChange={(e) => setJobStart(e.target.value)} /></Field>
              <Field label={tr("End", "Fim", "Fin")}><input aria-label={tr("New job end date", "Data de término do novo trabalho", "Fecha de fin del nuevo trabajo")} type="date" className={inputCls} value={jobEnd} onChange={(e) => setJobEnd(e.target.value)} /></Field>
            </div>
            <Field label={tr("Job estimated value (USD, optional)", "Valor estimado do trabalho (USD, opcional)", "Valor estimado del trabajo (USD, opcional)")}><input aria-label={tr("New job estimated value in US dollars", "Valor estimado do novo trabalho em dólares", "Valor estimado del nuevo trabajo en dólares")} className={inputCls} inputMode="decimal" value={jobEst} onChange={(e) => setJobEst(e.target.value)} placeholder="4,500.00" /></Field>
            <button className={`${btnNavy} w-full`} disabled={createJob.isPending || !jobPick.name.trim()}>{createJob.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Create job", "Criar trabalho", "Crear trabajo")}</button>
          </form>
        )}

        <div className="mt-3 space-y-3">
          {q.data.jobs.map((j) => (
            <JobRow key={j.id} cid={cid} job={j} canManage={canManage} actorId={session.userId} showMoney={session.role === "admin"} onOpen={() => setOpenJobId(j.id)} />
          ))}
          {q.data.jobs.length === 0 && (
            <p className="rounded-xl border border-dashed border-[var(--border)] px-3 py-3 text-center text-sm text-[var(--dim)]">
              {tr("No jobs yet on this project.", "Nenhum trabalho nesta obra ainda.", "Todavía no hay trabajos en esta obra.")} {canManage ? tr("Add the first one — e.g. “Roof replacement” and “Siding installation” — and give each its own crew.", "Adicione o primeiro — ex.: “Troca do telhado” e “Instalação do revestimento” — e dê a cada um sua própria equipe.", "Agrega el primero — p. ej., “Reemplazo del techo” e “Instalación del revestimiento” — y asígnale a cada uno su propio equipo.") : tr("Your manager can split this site into jobs (roof, siding…) with separate crews.", "Seu gerente pode dividir este local em trabalhos (telhado, revestimento…) com equipes separadas.", "Tu gerente puede dividir este lugar en trabajos (techo, revestimiento…) con equipos separados.")}
            </p>
          )}
        </div>
      </section>

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
        <h3 className="font-bold">{tr("🛡️ Job site address & geofence", "🛡️ Endereço da obra e cerca virtual", "🛡️ Dirección de la obra y geocerca")}</h3>
        <p className="mt-1 text-sm text-[var(--dim)]">
          {tr("Crew check-ins are compared against this point. Inside the radius = validated. Outside = flagged", "Os check-ins da equipe são comparados com este ponto. Dentro do raio = validado. Fora = sinalizado como", "Los registros del equipo se comparan con este punto. Dentro del radio = validado. Fuera = marcado como")} <strong className="text-red-600">{tr("OUTSIDE JOB SITE AREA", "FORA DA ÁREA DA OBRA", "FUERA DEL ÁREA DE LA OBRA")}</strong> {tr("for the manager to approve or reject.", "para o gerente aprovar ou rejeitar.", "para que el gerente lo apruebe o rechace.")}
        </p>
        {p.geoLat !== null && p.geoLng !== null ? (
          <p className="mt-2 text-sm"><span className="font-semibold">{tr("Center:", "Centro:", "Centro:")}</span> {p.geoLat.toFixed(6)}, {p.geoLng.toFixed(6)} • <span className="font-semibold">{tr("Radius:", "Raio:", "Radio:")}</span> {mToFt(p.geoRadius)} ft {" "}
            <a className="font-semibold text-[#f97316] underline" href={`https://www.google.com/maps/search/?api=1&query=${p.geoLat},${p.geoLng}`} target="_blank" rel="noreferrer" aria-label={tr("View job site center in Google Maps", "Ver o centro da obra no Google Maps", "Ver el centro de la obra en Google Maps")}>{tr("Open in Maps", "Abrir no Maps", "Abrir en Maps")}</a>
          </p>
        ) : (
          <p className="mt-2 rounded-xl bg-amber-100 px-3 py-2 text-sm font-semibold text-amber-800">{tr("⚠️ This project has no geofence yet: entry GPS is not validated. Set the point below.", "⚠️ Esta obra ainda não tem cerca virtual: o GPS de entrada não é validado. Defina o ponto abaixo.", "⚠️ Esta obra todavía no tiene geocerca: el GPS de entrada no se valida. Define el punto abajo.")}</p>
        )}
        {canManage && (
          <div className="mt-3 space-y-3">
            <AddressForm idPrefix="edit-project" value={addrVal} onChange={setAddrEdit} onPick={(s) => {
              if (Number.isFinite(s.lat) && Number.isFinite(s.lng)) {
                setGeoLat(s.lat.toFixed(6)); setGeoLng(s.lng.toFixed(6));
                setGeoMsg(tr("Address selected — geofence set to the same point. Save to apply.", "Endereço selecionado — cerca virtual definida no mesmo ponto. Salve para aplicar.", "Dirección seleccionada: geocerca fijada en el mismo punto. Guarda para aplicar."));
              }
            }} />
            <button type="button" className={`${btnGhost} w-full`} onClick={locateOnMap} disabled={locating} aria-label={tr("Locate the job site address on the map", "Localizar o endereço da obra no mapa", "Localizar la dirección de la obra en el mapa")}>
              {locating ? tr("Locating…", "Localizando…", "Localizando…") : tr("🗺️ Locate on map", "🗺️ Localizar no mapa", "🗺️ Localizar en el mapa")}
            </button>
            {showMap && <GeoMap lat={latNum} lng={lngNum} label={formatAddr(addrVal) || p.name} />}
            <div className="grid grid-cols-2 gap-2">
              <Field label={tr("Latitude", "Latitude", "Latitud")}><input aria-label={tr("Geofence latitude", "Latitude da cerca virtual", "Latitud de la geocerca")} className={inputCls} inputMode="decimal" value={latStr} onChange={(e) => setGeoLat(e.target.value)} placeholder="39.975600" /></Field>
              <Field label={tr("Longitude", "Longitude", "Longitud")}><input aria-label={tr("Geofence longitude", "Longitude da cerca virtual", "Longitud de la geocerca")} className={inputCls} inputMode="decimal" value={lngStr} onChange={(e) => setGeoLng(e.target.value)} placeholder="-74.158400" /></Field>
            </div>
            <div className="flex items-end gap-2">
              <div className="flex-1"><Field label={tr("Radius (feet)", "Raio (pés)", "Radio (pies)")}><input aria-label={tr("Geofence radius in feet", "Raio da cerca virtual em pés", "Radio de la geocerca en pies")} className={inputCls} inputMode="numeric" value={radiusFtStr} onChange={(e) => setGeoRadiusFt(e.target.value)} /></Field></div>
              <button type="button" className={btnGhost} aria-label={tr("Use my current location as the job site center", "Usar minha localização atual como centro da obra", "Usar mi ubicación actual como centro de la obra")} onClick={async () => { setGeoMsg(tr("Getting your location…", "Obtendo sua localização…", "Obteniendo tu ubicación…")); const gps = await getGPS(); if (gps) { setGeoLat(gps.lat.toFixed(6)); setGeoLng(gps.lng.toFixed(6)); setGeoMsg(tr("Location captured — tap Save.", "Localização capturada — toque em Salvar.", "Ubicación capturada: toca Guardar.")); } else setGeoMsg(tr("GPS unavailable on this device.", "GPS indisponível neste dispositivo.", "GPS no disponible en este dispositivo.")); }}>{tr("📍 I'm at the site", "📍 Estou na obra", "📍 Estoy en la obra")}</button>
            </div>
            <div className="flex gap-2">
              <button className={`${btnNavy} flex-1`} disabled={saveSite.isPending} aria-label={tr("Save address and geofence", "Salvar endereço e cerca virtual", "Guardar dirección y geocerca")} onClick={() => {
                const la = latStr.trim() ? Number(latStr) : NaN;
                const ln = lngStr.trim() ? Number(lngStr) : NaN;
                const hasCoords = Number.isFinite(la) && Number.isFinite(ln);
                saveSite.mutate({ addr: addrVal, geoLat: hasCoords ? la : null, geoLng: hasCoords ? ln : null, geoRadius: ftToM(Number(radiusFtStr) || 650) });
              }}>{saveSite.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save address & geofence", "Salvar endereço e cerca virtual", "Guardar dirección y geocerca")}</button>
              {(p.geoLat !== null) && (
                <button className={btnGhost} aria-label={tr("Remove the geofence from this project", "Remover a cerca virtual desta obra", "Quitar la geocerca de esta obra")} onClick={() => upd.mutate({ geoLat: null, geoLng: null }, { onSuccess: () => { setGeoLat(""); setGeoLng(""); setGeoMsg(tr("Geofence removed.", "Cerca virtual removida.", "Geocerca eliminada.")); } })}>{tr("Remove", "Remover", "Quitar")}</button>
              )}
            </div>
            {geoMsg && <p className="text-xs font-semibold" role="status">{geoMsg}</p>}
          </div>
        )}
      </section>

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
        <h3 className="font-bold">{tr("Project crew", "Equipe da obra", "Equipo de la obra")} ({q.data.team.length})</h3>
        <div className="mt-2 space-y-2">
          {q.data.team.map((t) => (
            <div key={t.id} className="flex items-center justify-between gap-2 rounded-xl bg-[var(--surface2)] px-3 py-2">
              <span className="min-w-0 text-sm"><span className="font-semibold">{t.name}</span> <span className="text-[var(--dim)]">• {t.trade}</span></span>
              <span className="flex shrink-0 items-center gap-2">
                {payBadge(t.payType, t.payRate)}
                {canManage && <button aria-label={tr(`Remove ${t.name} from this project`, `Remover ${t.name} desta obra`, `Quitar a ${t.name} de esta obra`)} onClick={() => unassign.mutate(t.id)} className="text-xs font-bold text-red-600">{tr("Remove", "Remover", "Quitar")}</button>}
              </span>
            </div>
          ))}
          {q.data.team.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("Nobody assigned yet.", "Ninguém atribuído ainda.", "Todavía no hay nadie asignado.")}</p>}
        </div>
        {canManage && (
          <div className="mt-3 flex gap-2">
            <select aria-label={tr("Employee to assign", "Funcionário para atribuir", "Empleado para asignar")} className={inputCls} value={assignId} onChange={(e) => setAssignId(e.target.value)}>
              <option value="">{tr("Select an employee…", "Selecionar um funcionário…", "Seleccionar un empleado…")}</option>
              {(emps.data?.employees ?? []).filter((e) => !teamIds.has(e.id) && e.status === "ativo").map((e) => <option key={e.id} value={e.id}>{e.name} — {e.trade}</option>)}
            </select>
            <button className={btnNavy} disabled={!assignId || assign.isPending} onClick={() => { assign.mutate(Number(assignId)); setAssignId(""); }}>{tr("Assign", "Atribuir", "Asignar")}</button>
          </div>
        )}
      </section>

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
        <h3 className="font-bold">{tr("Field updates", "Atualizações de campo", "Actualizaciones de campo")}</h3>
        {q.data.progressFeed.length === 0 && <p className="mt-2 text-sm text-[var(--dim)]">{tr("No photos or notes yet. Use the Field tab to send one.", "Nenhuma foto ou observação ainda. Use a aba Campo para enviar uma.", "Todavía no hay fotos ni notas. Usa la pestaña Campo para enviar una.")}</p>}
        <div className="mt-3 space-y-3">
          {q.data.progressFeed.map((f) => (
            <div key={f.id} className="rounded-xl bg-[var(--surface2)] p-3">
              {safeImgSrc(f.photoUrl) && <img src={safeImgSrc(f.photoUrl)} alt={tr(`Progress photo sent by ${f.employeeName}`, `Foto de progresso enviada por ${f.employeeName}`, `Foto de progreso enviada por ${f.employeeName}`)} className="mb-2 max-h-64 w-full rounded-lg object-cover" />}
              {f.note && <p className="text-sm">{f.note}</p>}
              <p className="mt-1 text-xs text-[var(--dim)]">{f.employeeName} • {new Date(f.createdAt).toLocaleString("en-US")}</p>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

/* ---------------- Field ---------------- */
function FieldView({ cid, session, onOpenJob }: { cid: string; session: Session; onOpenJob?: (projectId: number, jobId: number) => void }) {
  const qc = useQueryClient();
  const projects = useQuery({ queryKey: ["projects", cid], queryFn: () => api.listProjects({ companyId: cid }) });
  const active = useQuery({ queryKey: ["active-sheet", cid, session.userId], queryFn: () => api.getActiveSheet({ companyId: cid, employeeId: session.userId }) });
  const myToday = useQuery({ queryKey: ["my-today", cid, session.userId], queryFn: () => api.getMyToday({ companyId: cid, employeeId: session.userId }) });
  const myTasks = useQuery({ queryKey: ["my-tasks", cid, session.userId], queryFn: () => api.getMyTasks({ companyId: cid, employeeId: session.userId }) });
  const feed = useQuery({ queryKey: ["progress", cid], queryFn: () => api.listProgress({ companyId: cid }) });
  const [projectId, setProjectId] = useState<string>("");
  const [jobPick, setJobPick] = useState<number | null>(null);
  const [note, setNote] = useState("");
  const [photo, setPhoto] = useState("");
  const [msg, setMsg] = useState("");
  const [msgTone, setMsgTone] = useState<"ok" | "warn" | "err">("ok");
  const [busy, setBusy] = useState(false);
  const [myDist, setMyDist] = useState<number | null>(null);
  const [distBusy, setDistBusy] = useState(false);
  const [pingCount, setPingCount] = useState(0);
  const [lastPing, setLastPing] = useState<string>("");
  const outboxItems = useOutboxItems();

  const sheet = active.data?.sheet;
  const queuedCheckIn = !sheet && outboxItems.some((i) => i.kind === "checkIn" && i.args.employeeId === session.userId);
  const queuedCheckOut = outboxItems.some((i) => i.kind === "checkOut" && i.args.employeeId === session.userId);
  const todayProject = myToday.data?.todayProject ?? null;
  const todayJobs = myToday.data?.todayJobs ?? [];

  const myTaskList = myTasks.data?.tasks ?? [];
  const myDoneCount = myTaskList.filter((t) => t.status === "done").length;
  const myTaskGroups: { jobId: number; jobName: string; projectName: string; tasks: TaskLite[] }[] = [];
  for (const t of myTaskList) {
    const g = myTaskGroups.find((x) => x.jobId === t.jobId);
    if (g) g.tasks.push(t);
    else myTaskGroups.push({ jobId: t.jobId, jobName: t.jobName, projectName: t.projectName, tasks: [t] });
  }

  const showMsg = (tone: "ok" | "warn" | "err", text: string) => { setMsgTone(tone); setMsg(text); };
  const zoneMsg = (zone: string, distM: number | null, when: string) => {
    if (zone === "fora") return { tone: "err" as const, text: tr(`🚨 Recorded, but OUTSIDE JOB SITE AREA at ${when}${distM !== null ? ` (${fmtDist(distM)} from the site center)` : ""}. Your manager was notified and will approve or reject this entry.`, `🚨 Registrado, mas FORA DA ÁREA DA OBRA em ${when}${distM !== null ? ` (${fmtDist(distM)} do centro da obra)` : ""}. Seu gerente foi avisado e aprovará ou rejeitará este registro.`, `🚨 Registrado, pero FUERA DEL ÁREA DE LA OBRA a las ${when}${distM !== null ? ` (${fmtDist(distM)} del centro de la obra)` : ""}. Tu gerente fue notificado y aprobará o rechazará este registro.`) };
    if (zone === "dentro") return { tone: "ok" as const, text: `✅ ${when === "check-in" ? tr("Check-in", "Check-in", "Registro de entrada") : tr("Check-out", "Check-out", "Registro de salida")} ${tr("validated: you are inside the job site area", "validado: você está dentro da área da obra", "validado: estás dentro del área de la obra")}${distM !== null ? ` (${fmtDist(distM)})` : ""}.` };
    if (zone === "sem_gps") return { tone: "warn" as const, text: `⚠️ ${when === "check-in" ? tr("Check-in", "Check-in", "Registro de entrada") : tr("Check-out", "Check-out", "Registro de salida")} ${tr("recorded without GPS. Your manager may ask for proof.", "registrado sem GPS. Seu gerente pode pedir uma comprovação.", "registrado sin GPS. Tu gerente puede pedir una comprobación.")}` };
    return { tone: "warn" as const, text: tr(`⚠️ Recorded. This project has no geofence yet, so GPS was not validated.`, `⚠️ Registrado. Esta obra ainda não tem cerca virtual, então o GPS não foi validado.`, `⚠️ Registrado. Esta obra todavía no tiene geocerca, así que el GPS no se validó.`) };
  };

  const checkIn = useMutation({
    mutationFn: async (args: { projId: number; jobToUse: number | null }) => {
      const gps = await getGPS();
      const payload = { companyId: cid, projectId: args.projId, jobId: args.jobToUse, employeeId: session.userId, lat: gps?.lat ?? null, lng: gps?.lng ?? null, manualNote: gps ? "" : tr("No GPS (manual)", "Sem GPS (manual)", "Sin GPS (manual)") };
      if (isOffline()) {
        await enqueueOutbox({ kind: "checkIn", args: payload });
        return { queued: true as const, zone: "", distM: null as number | null };
      }
      const r = await api.checkIn(payload);
      return { queued: false as const, ...r };
    },
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["active-sheet", cid, session.userId] });
      qc.invalidateQueries({ queryKey: ["my-today", cid, session.userId] });
      if (r.queued) { showMsg("warn", tr("📥 You're offline — check-in queued on this phone. It sends automatically when you're back online (the recorded time is when it syncs).", "📥 Você está offline — check-in na fila neste celular. Ele é enviado automaticamente quando você voltar a ficar online (o horário registrado é o da sincronização).", "📥 Estás sin conexión: registro de entrada en cola en este teléfono. Se envía automáticamente cuando vuelvas a conectarte (la hora registrada es la de la sincronización).")); return; }
      const m = zoneMsg(r.zone, r.distM, "check-in");
      showMsg(m.tone, `${m.text} ${tr("Have a good shift! 💪", "Bom turno! 💪", "¡Buen turno! 💪")}`);
    },
    onError: () => showMsg("err", tr("Could not check in. Please try again.", "Não foi possível registrar a entrada. Tente novamente.", "No se pudo registrar la entrada. Inténtalo de nuevo.")),
  });
  const checkOut = useMutation({
    mutationFn: async () => {
      const gps = await getGPS();
      if (isOffline()) {
        await enqueueOutbox({ kind: "checkOut", args: { companyId: cid, sheetId: active.data!.sheet!.id, lat: gps?.lat ?? null, lng: gps?.lng ?? null, employeeId: session.userId } });
        return { queued: true as const, hours: 0, autoClosed: false, zone: "", distM: null as number | null };
      }
      const r = await api.checkOut({ companyId: cid, sheetId: active.data!.sheet!.id, lat: gps?.lat ?? null, lng: gps?.lng ?? null });
      return { queued: false as const, ...r };
    },
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["active-sheet", cid, session.userId] });
      qc.invalidateQueries({ queryKey: ["my-today", cid, session.userId] });
      qc.invalidateQueries({ queryKey: ["sheets", cid] });
      if (r.queued) { showMsg("warn", tr("📥 You're offline — check-out queued on this phone. It sends automatically when you're back online.", "📥 Você está offline — check-out na fila neste celular. Ele é enviado automaticamente quando você voltar a ficar online.", "📥 Estás sin conexión: registro de salida en cola en este teléfono. Se envía automáticamente cuando vuelvas a conectarte.")); return; }
      const m = zoneMsg(r.zone, r.distM, "check-out");
      showMsg(m.tone, `${m.text} ${tr("Total:", "Total:", "Total:")} ${r.hours.toFixed(1)}h${r.autoClosed ? tr(" (counted up to the cutoff time)", " (contado até o horário limite)", " (contado hasta la hora límite)") : ""}. ${tr("Waiting for manager approval.", "Aguardando a aprovação do gerente.", "En espera de la aprobación del gerente.")}`);
    },
    onError: () => showMsg("err", tr("Could not check out. Please try again.", "Não foi possível registrar a saída. Tente novamente.", "No se pudo registrar la salida. Inténtalo de nuevo.")),
  });
  const sendProgress = useMutation({
    mutationFn: async () => {
      const payload = { companyId: cid, projectId: Number(projectId || sheet?.projectId || todayProject?.id || 0), employeeId: session.userId, note, photoUrl: photo };
      if (isOffline()) {
        await enqueueOutbox({ kind: "progress", args: payload });
        return { queued: true as const };
      }
      await api.createProgress(payload);
      return { queued: false as const };
    },
    onSuccess: (r) => { qc.invalidateQueries({ queryKey: ["progress", cid] }); setNote(""); setPhoto(""); showMsg(r.queued ? "warn" : "ok", r.queued ? tr("📥 You're offline — update queued on this phone and will send when you're back online.", "📥 Você está offline — atualização na fila neste celular, será enviada quando você voltar a ficar online.", "📥 Estás sin conexión: actualización en cola en este teléfono, se enviará cuando vuelvas a conectarte.") : tr("Update sent to the project. ✅", "Atualização enviada para a obra. ✅", "Actualización enviada a la obra. ✅")); },
  });
  const sendPing = useMutation({
    mutationFn: async () => { const gps = await getGPS(); if (!gps) throw new Error("no gps"); return api.recordPing({ companyId: cid, employeeId: session.userId, sheetId: sheet?.id ?? null, lat: gps.lat, lng: gps.lng }); },
    onSuccess: (r) => { setPingCount((c) => c + 1); setLastPing(new Date(r.at).toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })); },
  });

  // GPS trail: every 30 min WHILE the app is open (web app limitation).
  const sheetId = sheet?.id;
  useEffect(() => {
    if (!sheetId) return;
    const tick = () => { sendPing.mutate(); };
    const t = setInterval(tick, 30 * 60 * 1000);
    return () => clearInterval(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sheetId]);

  const refreshDist = async () => {
    if (!todayProject || todayProject.geoLat === null || todayProject.geoLng === null) return;
    setDistBusy(true);
    const gps = await getGPS();
    setDistBusy(false);
    if (gps) setMyDist(haversineClientM(gps.lat, gps.lng, todayProject.geoLat, todayProject.geoLng));
    else showMsg("warn", tr("Could not get your GPS right now.", "Não foi possível obter seu GPS agora.", "No se pudo obtener tu GPS ahora."));
  };

  const onPhoto = (file: File | undefined) => {
    if (!file) return;
    setBusy(true);
    const reader = new FileReader();
    reader.onload = () => { setPhoto(String(reader.result)); setBusy(false); };
    reader.readAsDataURL(file);
  };

  const effectiveProjectId = sheet ? sheet.projectId : projectId ? Number(projectId) : todayProject?.id ?? 0;
  const jobsForProject = todayJobs.filter((j) => j.projectId === effectiveProjectId);
  const selectedJobId = sheet ? sheet.jobId : jobsForProject.length === 1 ? jobsForProject[0]!.jobId : jobsForProject.some((j) => j.jobId === jobPick) ? jobPick : (jobsForProject[0]?.jobId ?? null);
  const inZoneNow = todayProject && todayProject.geoLat !== null && myDist !== null ? myDist <= todayProject.geoRadius : null;

  return (
    <div className="space-y-4">
      <h2 className="text-xl font-bold">{tr("Field — clock in & progress", "Campo — registro de ponto e progresso", "Campo: registro de entrada y progreso")}</h2>
      <p className="text-sm text-[var(--dim)]">{tr("Hi,", "Olá,", "Hola,")} {session.userName.split(" ")[0]}. {sheet ? tr("You are on the clock right now.", "Você está com o ponto registrado agora.", "Tienes tu registro de entrada activo ahora.") : tr("Your job site today comes from your assignment.", "Sua obra de hoje vem da sua atribuição.", "Tu obra de hoy viene de tu asignación.")}</p>

      {msg && <p className={`rounded-xl px-4 py-3 text-sm font-semibold ${msgTone === "err" ? "bg-red-600 text-white" : msgTone === "warn" ? "bg-amber-100 text-amber-800" : "bg-green-100 text-green-800"}`} role="status">{msg}</p>}

      {/* Your job site today */}
      <div className="rounded-2xl bg-[#0f2a44] p-4 text-white">
        <p className="text-xs font-semibold uppercase tracking-wide text-white/60">{tr("Your job site today", "Sua obra de hoje", "Tu obra de hoy")}</p>
        {todayProject ? (
          <>
            <p className="mt-1 text-lg font-bold leading-snug">{todayProject.name}</p>
            {todayProject.address && <p className="text-sm text-white/70">📍 {todayProject.address}</p>}
            <div className="mt-3 rounded-xl bg-white/10 p-3" aria-label={tr("What to do today", "O que fazer hoje", "Qué hacer hoy")}>
              <p className="text-xs font-black uppercase tracking-wide text-orange-300">{tr("What to do", "O que fazer", "Qué hacer")}</p>
              {todayProject.scope ? (
                <p className="mt-1 whitespace-pre-line text-sm leading-relaxed text-white">{todayProject.scope}</p>
              ) : (
                <p className="mt-1 text-sm text-white/70">{tr("No work description has been added yet. Ask your manager what needs to be done before you start.", "Nenhuma descrição de trabalho foi adicionada ainda. Pergunte ao seu gerente o que precisa ser feito antes de começar.", "Todavía no se ha agregado ninguna descripción del trabajo. Pregúntale a tu gerente qué hay que hacer antes de empezar.")}</p>
              )}
            </div>
            <div className="mt-3 rounded-xl bg-white/10 p-3 [&_.field-note]:border-white/40 [&_.field-note]:text-slate-200" aria-label={tr("Required services and measurements", "Serviços e medições necessários", "Servicios y mediciones necesarios")}>
              <p className="text-xs font-black uppercase tracking-wide text-orange-300">{tr("🧱 Required services & measurements", "🧱 Serviços e medições necessários", "🧱 Servicios y mediciones necesarios")}</p>
              <ProjectServicesSection cid={cid} projectId={todayProject.id} actorId={session.userId} canManage={false} />
            </div>
            <div className="mt-3 rounded-xl bg-white/10 p-3 [&_.field-note]:border-white/40 [&_.field-note]:text-slate-200" aria-label={tr("Plans and blueprints", "Plantas", "Planos")}>
              <p className="text-xs font-black uppercase tracking-wide text-orange-300">{tr("📐 Plans & blueprints", "📐 Plantas", "📐 Planos")}</p>
              <ProjectPlansList cid={cid} actorId={session.userId} projectId={todayProject.id} canManage={false} />
            </div>
            {todayJobs.length > 0 && (
              <div className="mt-3 space-y-2" aria-label={tr("Your jobs today", "Seus trabalhos de hoje", "Tus trabajos de hoy")}>
                {todayJobs.map((j) => (
                  <button
                    key={j.jobId}
                    type="button"
                    onClick={() => onOpenJob?.(j.projectId, j.jobId)}
                    aria-label={tr(`Open job ${j.jobName} in ${j.projectName}`, `Abrir o trabalho ${j.jobName} em ${j.projectName}`, `Abrir el trabajo ${j.jobName} en ${j.projectName}`)}
                    className="w-full rounded-xl bg-white/10 p-3 text-left active:opacity-70"
                  >
                    <p className="text-xs font-black uppercase tracking-wide text-orange-300">{tr("Your job today", "Seu trabalho de hoje", "Tu trabajo de hoy")}{j.projectId !== todayProject?.id ? ` • ${j.projectName}` : ""}</p>
                    <p className="mt-0.5 font-bold">🔧 {j.jobName}</p>
                    {j.scope ? (
                      <p className="mt-1 whitespace-pre-line text-sm leading-relaxed text-white">{j.scope}</p>
                    ) : (
                      <p className="mt-1 text-sm text-white/70">{tr("No description yet — ask your manager what needs to be done.", "Nenhuma descrição ainda — pergunte ao seu gerente o que precisa ser feito.", "Todavía no hay descripción: pregúntale a tu gerente qué hay que hacer.")}</p>
                    )}
                    <p className="mt-2 text-xs font-bold text-orange-300">{tr("Tap to open this job — its tasks and photos ›", "Toque para abrir este trabalho — suas tarefas e fotos ›", "Toca para abrir este trabajo: sus tareas y fotos ›")}</p>
                  </button>
                ))}
              </div>
            )}
            {todayProject.geoLat !== null ? (
              <div className="mt-2 flex flex-wrap items-center gap-2">
                <span className="rounded-full bg-white/10 px-2.5 py-1 text-xs font-semibold">{tr("Geofence:", "Cerca virtual:", "Geocerca:")} {mToFt(todayProject.geoRadius)} ft {tr("radius", "de raio", "de radio")}</span>
                {myDist !== null && (
                  <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${inZoneNow ? "bg-green-500 text-white" : "bg-red-500 text-white"}`}>
                    {inZoneNow ? tr("You are INSIDE the job site area", "Você está DENTRO da área da obra", "Estás DENTRO del área de la obra") : tr(`You are ${fmtDist(myDist)} from the site`, `Você está a ${fmtDist(myDist)} da obra`, `Estás a ${fmtDist(myDist)} de la obra`)}
                  </span>
                )}
                <button type="button" aria-label={tr("Check my distance to the job site", "Verificar minha distância até a obra", "Comprobar mi distancia a la obra")} disabled={distBusy} onClick={refreshDist} className="rounded-full bg-white/15 px-2.5 py-1 text-xs font-semibold active:opacity-70 disabled:opacity-40">{distBusy ? tr("Locating…", "Localizando…", "Localizando…") : tr("📍 Check my position", "📍 Verificar minha posição", "📍 Comprobar mi posición")}</button>
              </div>
            ) : (
              <p className="mt-2 text-xs text-white/60">{tr("This project has no geofence yet — the manager sets it in the project details.", "Esta obra ainda não tem cerca virtual — o gerente a define nos detalhes da obra.", "Esta obra todavía no tiene geocerca: el gerente la define en los detalles de la obra.")}</p>
            )}
          </>
        ) : (
          <p className="mt-1 text-sm text-white/70">{tr("No project assigned to you today. Talk to your manager, or pick a project below.", "Nenhuma obra atribuída a você hoje. Fale com seu gerente ou escolha uma obra abaixo.", "Hoy no tienes ninguna obra asignada. Habla con tu gerente o elige una obra abajo.")}</p>
        )}
      </div>

      <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
        <Field label={tr("Project for this entry", "Obra para este registro", "Obra para este registro")}>
          <select aria-label={tr("Project for check-in", "Obra para o check-in", "Obra para el registro de entrada")} className={inputCls} value={sheet ? String(sheet.projectId) : projectId} disabled={!!sheet} onChange={(e) => setProjectId(e.target.value)}>
            <option value="">{todayProject ? `${tr("Today's site:", "Obra de hoje:", "Obra de hoy:")} ${todayProject.name}` : tr("Select a project…", "Selecionar uma obra…", "Seleccionar una obra…")}</option>
            {(projects.data?.projects ?? []).filter((p) => p.status === "andamento" || p.status === "planejada").map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
          </select>
        </Field>

        {sheet ? (
          <div className="mt-4">
            <div className="rounded-xl bg-[#0f2a44] p-4 text-white">
              <p className="text-xs font-semibold uppercase tracking-wide text-white/60">{tr("On the clock since", "Com o ponto registrado desde", "Con registro de entrada desde")}</p>
              <p className="text-2xl font-black">{fmtTime(sheet.checkInAt)}</p>
              <p className="text-sm text-white/70">{sheet.projectName}</p>
              {sheet.jobName && <p className="text-sm font-semibold text-orange-300">🔧 {sheet.jobName}</p>}
              <div className="mt-2 flex flex-wrap gap-1.5">
                {zoneBadge(sheet.inZone, sheet.inDistM, "check-in")}
              </div>
              {sheet.inLat !== null && <p className="mt-1 text-xs text-white/50">{tr("Check-in GPS:", "GPS do check-in:", "GPS del registro de entrada:")} {sheet.inLat?.toFixed(5)}, {sheet.inLng?.toFixed(5)}</p>}
            </div>

            {/* GPS trail while the app is open */}
            <div className="mt-3 rounded-xl bg-[var(--surface2)] p-3">
              <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Location trail — while the app is open", "Rastro de localização — enquanto o app está aberto", "Rastro de ubicación: mientras la app está abierta")}</p>
              <p className="mt-1 text-xs text-[var(--dim)]">
                {tr("While this app is", "Enquanto este app estiver", "Mientras esta app esté")} <strong>{tr("open on your phone", "aberto no seu celular", "abierta en tu teléfono")}</strong>{tr(", your position is sent every 30 minutes to prove you are on site.", ", sua posição é enviada a cada 30 minutos para provar que você está na obra.", ", tu posición se envía cada 30 minutos para demostrar que estás en la obra.")}
                {lastPing ? ` ${tr("Last sent:", "Último envio:", "Último envío:")} ${lastPing} (${pingCount} ${tr("this session", "nesta sessão", "en esta sesión")}).` : tr(" The first automatic send happens within 30 min — or send now:", " O primeiro envio automático acontece em até 30 min — ou envie agora:", " El primer envío automático ocurre en 30 min, o envíalo ahora:")}
              </p>
              <button type="button" aria-label={tr("Send my position now", "Enviar minha posição agora", "Enviar mi posición ahora")} disabled={sendPing.isPending} onClick={() => sendPing.mutate()} className={`${btnGhost} mt-2 w-full text-sm`}>
                {sendPing.isPending ? tr("Sending position…", "Enviando a posição…", "Enviando la posición…") : tr("📍 Send my position now", "📍 Enviar minha posição agora", "📍 Enviar mi posición ahora")}
              </button>
              {sendPing.isError && <p className="mt-1 text-xs font-semibold text-red-600">{tr("No GPS signal right now. Try again outdoors.", "Sem sinal de GPS agora. Tente novamente ao ar livre.", "Sin señal de GPS ahora. Inténtalo de nuevo al aire libre.")}</p>}
              <p className="mt-2 text-xs text-[var(--dim)]">ℹ️ {tr("With the app closed or the phone locked, the web app cannot send your location (the system suspends the page). That's also why your shift", "Com o app fechado ou o celular bloqueado, o app web não consegue enviar sua localização (o sistema suspende a página). É também por isso que seu turno", "Con la app cerrada o el teléfono bloqueado, la app web no puede enviar tu ubicación (el sistema suspende la página). Por eso también tu turno")} <strong>{tr("auto-closes at the end of the workday", "é fechado automaticamente no fim do expediente", "se cierra automáticamente al final de la jornada")}</strong> — {tr("you never stay “clocked in” while not working.", "você nunca fica “com o ponto aberto” enquanto não está trabalhando.", "nunca quedas “con el registro activo” mientras no estás trabajando.")}</p>
            </div>

            <button aria-label={tr("Check out", "Registrar saída", "Registrar salida")} disabled={checkOut.isPending} onClick={() => checkOut.mutate()} className="mt-3 w-full rounded-2xl bg-red-600 py-5 text-lg font-black text-white active:opacity-80 disabled:opacity-40">
              {checkOut.isPending ? tr("Recording…", "Registrando…", "Registrando…") : tr("✓ CHECK OUT", "✓ REGISTRAR SAÍDA", "✓ REGISTRAR SALIDA")}
            </button>
            {queuedCheckOut && <p className="mt-2 rounded-xl bg-amber-100 px-3 py-2 text-center text-xs font-bold text-amber-900" role="status">{tr("📥 A check-out is queued and will send when you're back online.", "📥 Um check-out está na fila e será enviado quando você voltar a ficar online.", "📥 Un registro de salida está en cola y se enviará cuando vuelvas a conectarte.")}</p>}
          </div>
        ) : (
          <>
            {jobsForProject.length > 1 && (
              <div className="mt-4" role="radiogroup" aria-label={tr("Which job are you starting?", "Qual trabalho você vai começar?", "¿Qué trabajo vas a empezar?")}>
                <p className="text-sm font-semibold">{tr("You have", "Você tem", "Tienes")} {jobsForProject.length} {tr("jobs at this site today — tap the one you're starting:", "trabalhos neste local hoje — toque no que você vai começar:", "trabajos en este lugar hoy: toca el que vas a empezar:")}</p>
                <div className="mt-2 flex flex-wrap gap-2">
                  {jobsForProject.map((j) => (
                    <button key={j.jobId} type="button" role="radio" aria-checked={selectedJobId === j.jobId} aria-label={tr(`Start job ${j.jobName}`, `Começar o trabalho ${j.jobName}`, `Empezar el trabajo ${j.jobName}`)}
                      onClick={() => setJobPick(j.jobId)}
                      className={`rounded-full px-4 py-2 text-sm font-bold ${selectedJobId === j.jobId ? "bg-[#f97316] text-white" : "border border-[var(--border)] bg-[var(--surface)] text-[var(--text)]"}`}>
                      🔧 {j.jobName}
                    </button>
                  ))}
                </div>
              </div>
            )}
            {jobsForProject.length === 1 && (
              <p className="mt-3 text-sm text-[var(--dim)]">{tr("Job:", "Trabalho:", "Trabajo:")} <span className="font-semibold text-[var(--text)]">🔧 {jobsForProject[0]!.jobName}</span> — {tr("picked from your assignment.", "escolhido da sua atribuição.", "elegido de tu asignación.")}</p>
            )}
            {queuedCheckIn ? (
              <p className="mt-4 rounded-2xl bg-amber-100 px-4 py-4 text-center text-sm font-bold text-amber-900" role="status">
                {tr("📥 Check-in queued — you're offline. It will send by itself when the connection comes back; your shift starts counting from when it syncs.", "📥 Check-in na fila — você está offline. Ele será enviado sozinho quando a conexão voltar; seu turno começa a contar a partir da sincronização.", "📥 Registro de entrada en cola: estás sin conexión. Se enviará solo cuando vuelva la conexión; tu turno empieza a contar desde la sincronización.")}
              </p>
            ) : (
              <button aria-label={tr("Check in at the job site", "Registrar entrada na obra", "Registrar entrada en la obra")} disabled={!effectiveProjectId || checkIn.isPending} onClick={() => checkIn.mutate({ projId: effectiveProjectId, jobToUse: selectedJobId })} className="mt-4 w-full rounded-2xl bg-[#f97316] py-5 text-lg font-black text-white active:opacity-80 disabled:opacity-40">
                {checkIn.isPending ? tr("Getting location…", "Obtendo a localização…", "Obteniendo la ubicación…") : tr("📍 CHECK IN WITH GPS", "📍 REGISTRAR ENTRADA COM GPS", "📍 REGISTRAR ENTRADA CON GPS")}
              </button>
            )}
          </>
        )}
        <p className="mt-2 text-center text-xs text-[var(--dim)]">{tr("GPS is compared with the project's geofence. Outside the area, the entry is still recorded but flagged for the manager. No GPS = marked “No GPS”. Forgetting to check out never creates overtime: the shift auto-closes at the company's cutoff time.", "O GPS é comparado com a cerca virtual da obra. Fora da área, o registro ainda é feito, mas sinalizado para o gerente. Sem GPS = marcado como “Sem GPS”. Esquecer o check-out nunca gera hora extra: o turno é fechado automaticamente no horário limite da empresa.", "El GPS se compara con la geocerca de la obra. Fuera del área, el registro igual se hace, pero se marca para el gerente. Sin GPS = marcado como “Sin GPS”. Olvidar el registro de salida nunca genera horas extra: el turno se cierra automáticamente a la hora límite de la empresa.")}</p>
      </div>

      {/* My tasks — the crew works this checklist in any order */}
      <section className="rounded-2xl border-2 border-[#f97316] bg-[var(--surface)] p-4" aria-label={tr("My tasks", "Minhas tarefas", "Mis tareas")}>
        <div className="flex items-center justify-between gap-2">
          <h3 className="font-bold">{tr("✅ My tasks", "✅ Minhas tarefas", "✅ Mis tareas")}</h3>
          {myTaskList.length > 0 && <span className="text-xs font-semibold text-[var(--dim)]">{myDoneCount}/{myTaskList.length} {tr("done", "concluídas", "terminadas")}</span>}
        </div>
        <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("Start whichever task you want — tap", "Comece a tarefa que quiser — toque em", "Empieza la tarea que quieras: toca")} <strong>{tr("Start", "Início", "Inicio")}</strong>{tr(", work on it (it can take more than a day; it stays In Progress until you tap", ", trabalhe nela (pode levar mais de um dia; ela fica Em andamento até você tocar em", ", trabaja en ella (puede llevar más de un día; queda En curso hasta que toques")} <strong>{tr("Done", "Concluída", "Terminada")}</strong>{tr("), and add a photo when you can: Before, During, or After.", ") e adicione uma foto quando puder: Antes, Durante ou Depois.", ") y agrega una foto cuando puedas: Antes, Durante o Después.")}</p>
        {myTasks.isPending && <p className="mt-2 text-sm text-[var(--dim)]">{tr("Loading tasks…", "Carregando tarefas…", "Cargando tareas…")}</p>}
        {!myTasks.isPending && myTaskList.length === 0 && (
          <p className="mt-2 text-sm text-[var(--dim)]">{tr("No tasks for you yet. Your manager adds tasks on each job in the Projects tab.", "Nenhuma tarefa para você ainda. Seu gerente adiciona tarefas em cada trabalho na aba Obras.", "Todavía no hay tareas para ti. Tu gerente agrega tareas en cada trabajo en la pestaña Obras.")}</p>
        )}
        {myTaskGroups.map((g) => (
          <div key={g.jobId} className="mt-3">
            <p className="text-xs font-black uppercase tracking-wide text-[#f97316]">🔧 {g.jobName}{g.projectName ? <span className="font-semibold normal-case text-[var(--dim)]"> • {g.projectName}</span> : null}</p>
            <div className="mt-1.5 space-y-2">
              {g.tasks.map((t) => (
                <TaskItem key={t.id} cid={cid} task={t} actorId={session.userId} canManage={session.role !== "funcionario"} manageControls={false} employees={[]} />
              ))}
            </div>
          </div>
        ))}
      </section>

      {/* Today's entries */}
      {(myToday.data?.todaySheets ?? []).length > 0 && (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
          <h3 className="font-bold">{tr("My entries today", "Meus registros de hoje", "Mis registros de hoy")}</h3>
          <div className="mt-2 space-y-2">
            {(myToday.data?.todaySheets ?? []).map((s) => (
              <div key={s.id} className="rounded-xl bg-[var(--surface2)] px-3 py-2 text-sm">
                <div className="flex flex-wrap items-center gap-1.5">
                  <span className="font-semibold">{fmtTime(s.checkInAt)} → {s.checkOutAt ? fmtTime(s.checkOutAt) : "…"}</span>
                  <span>• {s.hoursCalc.toFixed(1)}h</span>
                  {s.jobName && <span className="font-semibold">• 🔧 {s.jobName}</span>}
                  {sheetBadge(s.status)}
                </div>
                <div className="mt-1 flex flex-wrap gap-1.5">
                  {zoneBadge(s.inZone, s.inDistM, "check-in")}
                  {s.checkOutAt && zoneBadge(s.outZone, s.outDistM, "check-out")}
                  {s.autoClosed && <Badge text={tr("Auto-closed", "Fechado automaticamente", "Cerrado automáticamente")} tone="amber" />}
                </div>
              </div>
            ))}
          </div>
          <p className="mt-2 text-xs text-[var(--dim)]">{tr("Your hours are set by GPS and your manager — you can't edit your own time. Something wrong? Ask your manager for an adjustment; every adjustment is logged with name, date, and reason.", "Suas horas são definidas pelo GPS e pelo seu gerente — você não pode editar seu próprio ponto. Algo errado? Peça um ajuste ao seu gerente; todo ajuste é registrado com nome, data e motivo.", "Tus horas las define el GPS y tu gerente: no puedes editar tu propio registro. ¿Algo está mal? Pídele un ajuste a tu gerente; cada ajuste queda registrado con nombre, fecha y motivo.")}</p>
        </section>
      )}

      <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
        <h3 className="font-bold">{tr("Send a progress photo / note", "Enviar foto / observação de progresso", "Enviar foto / nota de progreso")}</h3>
        <div className="mt-3 space-y-3">
          <Field label={tr("Project (if different from the check-in)", "Obra (se for diferente do check-in)", "Obra (si es distinta a la del registro)")}>
            <select aria-label={tr("Project for this update", "Obra para esta atualização", "Obra para esta actualización")} className={inputCls} value={projectId} onChange={(e) => setProjectId(e.target.value)}>
              <option value="">{sheet ? sheet.projectName : todayProject ? todayProject.name : "Select a project…"}</option>
              {(projects.data?.projects ?? []).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </Field>
          <Field label={tr("Note", "Observação", "Nota")}><textarea aria-label={tr("Progress note", "Observação de progresso", "Nota de progreso")} className={inputCls} rows={2} value={note} onChange={(e) => setNote(e.target.value)} placeholder={tr("E.g.: Second-floor framing done", "Ex.: Estrutura do segundo andar pronta", "Ej.: Estructura del segundo piso terminada")} /></Field>
          <Field label={tr("Photo", "Foto", "Foto")}>
            <input aria-label={tr("Progress photo", "Foto de progresso", "Foto de progreso")} type="file" accept="image/*" capture="environment" className={inputCls} onChange={(e) => onPhoto(e.target.files?.[0])} />
          </Field>
          {photo && <img src={photo} alt={tr("Progress photo preview", "Pré-visualização da foto de progresso", "Vista previa de la foto de progreso")} className="max-h-56 w-full rounded-xl object-cover" />}
          <button className={`${btnNavy} w-full`} disabled={busy || sendProgress.isPending || (!note.trim() && !photo)} onClick={() => sendProgress.mutate()}>
            {sendProgress.isPending ? tr("Sending…", "Enviando…", "Enviando…") : tr("Send update", "Enviar atualização", "Enviar actualización")}
          </button>
        </div>
      </div>

      {(feed.data?.items ?? []).length > 0 && (
        <section>
          <h3 className="mb-2 font-bold">{tr("Latest updates", "Últimas atualizações", "Últimas actualizaciones")}</h3>
          <div className="space-y-3">
            {(feed.data?.items ?? []).slice(0, 5).map((f) => (
              <div key={f.id} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-3">
                {safeImgSrc(f.photoUrl) && <img src={safeImgSrc(f.photoUrl)} alt={tr(`Photo from ${f.projectName}`, `Foto de ${f.projectName}`, `Foto de ${f.projectName}`)} className="mb-2 max-h-52 w-full rounded-lg object-cover" />}
                {f.note && <p className="text-sm">{f.note}</p>}
                <p className="mt-1 text-xs text-[var(--dim)]">{f.projectName} • {f.employeeName} • {new Date(f.createdAt).toLocaleString("en-US")}</p>
              </div>
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

/* ---------------- Time entries (Timesheets) ---------------- */
function TimeEntries({ cid, session, focusSheetId, onFocusConsumed }: { cid: string; session: Session; focusSheetId?: number | null; onFocusConsumed?: () => void }) {
  const isFunc = session.role === "funcionario";
  const isManager = session.role === "gerente" || session.role === "admin";
  const [filterStatus, setFilterStatus] = useState("");
  const [weekOnly, setWeekOnly] = useState(true);
  const [expandedId, setExpandedId] = useState<number | null>(null);
  /* Deep link from a notification: open that entry's details directly. */
  useEffect(() => {
    if (focusSheetId === null || focusSheetId === undefined) return;
    setWeekOnly(false);
    setFilterStatus("");
    setExpandedId(focusSheetId);
    onFocusConsumed?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [focusSheetId]);
  const q = useQuery({
    queryKey: ["sheets", cid, isFunc ? session.userId : "all", filterStatus, weekOnly],
    queryFn: () => api.listTimesheets({ companyId: cid, employeeId: isFunc ? session.userId : undefined, status: filterStatus || undefined, weekOnly }),
  });
  const qc = useQueryClient();
  const setStatus = useMutation({
    mutationFn: (args: { sheetId: number; status: string }) => api.setSheetStatus({ companyId: cid, sheetId: args.sheetId, status: args.status, actorId: session.userId }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["sheets", cid] }); qc.invalidateQueries({ queryKey: ["dashboard", cid] }); qc.invalidateQueries({ queryKey: ["payroll", cid] }); qc.invalidateQueries({ queryKey: ["alerts", cid] }); },
  });
  const sheets = q.data?.sheets ?? [];
  const totalHours = sheets.filter((s) => s.status === "aprovado").reduce((a, s) => a + s.hoursCalc, 0);
  const flaggedCount = sheets.filter((s) => s.inZone === "fora" || s.outZone === "fora").length;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold">{isFunc ? tr("My hours", "Minhas horas", "Mis horas") : tr("Time entries", "Registros de ponto", "Registros de horas")}</h2>
        <Badge text={tr(`${totalHours.toFixed(1)}h approved`, `${totalHours.toFixed(1)}h aprovadas`, `${totalHours.toFixed(1)}h aprobadas`)} tone="navy" />
      </div>
      {flaggedCount > 0 && (
        <p className="rounded-xl bg-red-600 px-4 py-3 text-sm font-bold text-white">🚨 {flaggedCount} {tr("entry OUTSIDE JOB SITE AREA in this list — review before approving.", "registro FORA DA ÁREA DA OBRA nesta lista — revise antes de aprovar.", "registro FUERA DEL ÁREA DE LA OBRA en esta lista: revísalo antes de aprobar.")}</p>
      )}
      {isFunc && (
        <p className="rounded-xl bg-[var(--surface2)] px-4 py-3 text-sm text-[var(--dim)]">{tr("You can't edit your own hours. If something looks wrong, ask your manager — every adjustment they make is logged with name, date, old/new values, and reason.", "Você não pode editar suas próprias horas. Se algo parecer errado, peça ao seu gerente — todo ajuste que ele fizer fica registrado com nome, data, valores antigo/novo e motivo.", "No puedes editar tus propias horas. Si algo parece incorrecto, pídele a tu gerente un ajuste: cada ajuste queda registrado con nombre, fecha, valores anterior/nuevo y motivo.")}</p>
      )}
      <div className="flex flex-wrap gap-2">
        <select aria-label={tr("Filter by status", "Filtrar por status", "Filtrar por estado")} className="rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm" value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="">{tr("All statuses", "Todos os status", "Todos los estados")}</option><option value="pendente">{tr("Pending", "Pendente", "Pendiente")}</option><option value="aprovado">{tr("Approved", "Aprovado", "Aprobado")}</option><option value="aberto">{tr("Open", "Aberto", "Abierto")}</option><option value="rejeitado">{tr("Rejected", "Rejeitado", "Rechazado")}</option>
        </select>
        <button aria-label={tr("Toggle this-week filter", "Alternar o filtro desta semana", "Alternar el filtro de esta semana")} onClick={() => setWeekOnly((w) => !w)} className={`rounded-xl px-3 py-2 text-sm font-semibold ${weekOnly ? "bg-[#0f2a44] text-white" : "border border-[var(--border)] bg-[var(--surface)]"}`}>{weekOnly ? tr("This week ✓", "Esta semana ✓", "Esta semana ✓") : tr("This week", "Esta semana", "Esta semana")}</button>
      </div>

      {q.isPending && <p className="py-8 text-center text-[var(--dim)]">{tr("Loading time entries…", "Carregando os registros de ponto…", "Cargando los registros de horas…")}</p>}
      {q.data && sheets.length === 0 && <div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center"><p className="font-semibold">{tr("No entries found", "Nenhum registro encontrado", "No se encontraron registros")}</p><p className="mt-1 text-sm text-[var(--dim)]">{tr("Check in from the Field tab to create the first one.", "Registre o ponto na aba Campo para criar o primeiro.", "Registra tu entrada en la pestaña Campo para crear el primero.")}</p></div>}

      <div className="space-y-3">
        {sheets.map((s) => {
          const flagged = s.inZone === "fora" || s.outZone === "fora";
          return (
            <div key={s.id} className={`rounded-2xl border bg-[var(--surface)] p-4 ${flagged ? "border-red-400 ring-1 ring-red-300" : "border-[var(--border)]"}`}>
              <div className="flex items-start justify-between gap-2">
                <div>
                  <p className="font-bold">{s.employeeName}</p>
                  <p className="text-sm text-[var(--dim)]">{s.projectName} • {fmtDate(s.workDate)}</p>
                </div>
                {sheetBadge(s.status)}
              </div>
              <div className="mt-2 flex flex-wrap gap-1.5">
                {s.jobName && <Badge text={`🔧 ${s.jobName}`} tone="navy" />}
                {zoneBadge(s.inZone, s.inDistM, "check-in")}
                {s.checkOutAt && zoneBadge(s.outZone, s.outDistM, "check-out")}
                {s.autoClosed && <Badge text={tr("⏰ Auto-closed at the cutoff time", "⏰ Fechado automaticamente no horário limite", "⏰ Cerrado automáticamente a la hora límite")} tone="amber" />}
              </div>
              <div className="mt-2 grid grid-cols-3 gap-2 text-center text-sm">
                <div className="rounded-lg bg-[var(--surface2)] py-2"><p className="text-xs text-[var(--dim)]">{tr("In", "Entrada", "Entrada")}</p><p className="font-bold">{fmtTime(s.checkInAt)}</p></div>
                <div className="rounded-lg bg-[var(--surface2)] py-2"><p className="text-xs text-[var(--dim)]">{tr("Out", "Saída", "Salida")}</p><p className="font-bold">{fmtTime(s.checkOutAt)}</p></div>
                <div className="rounded-lg bg-[var(--surface2)] py-2"><p className="text-xs text-[var(--dim)]">{tr("Hours", "Horas", "Horas")}</p><p className="font-bold">{s.hoursCalc.toFixed(1)}h</p></div>
              </div>
              {s.inLat !== null && <p className="mt-2 text-xs text-[var(--dim)]">📍 {tr("Check-in GPS", "GPS do check-in", "GPS del registro de entrada")} {s.inLat?.toFixed(5)}, {s.inLng?.toFixed(5)}{s.outLat !== null ? ` • ${tr("Check-out", "Check-out", "Registro de salida")} ${s.outLat?.toFixed(5)}, ${s.outLng?.toFixed(5)}` : ""}</p>}
              {s.note && <p className="mt-1 text-xs text-[var(--dim)]">{s.note}</p>}
              {!isFunc && s.status === "pendente" && (
                <div className="mt-3 flex gap-2">
                  <button aria-label={tr(`Approve entry for ${s.employeeName}`, `Aprovar o registro de ${s.employeeName}`, `Aprobar el registro de ${s.employeeName}`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate({ sheetId: s.id, status: "aprovado" })} className="flex-1 rounded-xl bg-green-600 py-2.5 font-bold text-white active:opacity-80">{tr("Approve ✓", "Aprovar ✓", "Aprobar ✓")}</button>
                  <button aria-label={tr(`Reject entry for ${s.employeeName}`, `Rejeitar o registro de ${s.employeeName}`, `Rechazar el registro de ${s.employeeName}`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate({ sheetId: s.id, status: "rejeitado" })} className="flex-1 rounded-xl bg-red-100 py-2.5 font-bold text-red-700 active:opacity-80">{tr("Reject", "Rejeitar", "Rechazar")}</button>
                </div>
              )}
              <button
                aria-label={expandedId === s.id ? tr(`Close details for ${s.employeeName}'s entry`, `Fechar os detalhes do registro de ${s.employeeName}`, `Cerrar los detalles del registro de ${s.employeeName}`) : tr(`View details for ${s.employeeName}'s entry`, `Ver os detalhes do registro de ${s.employeeName}`, `Ver los detalles del registro de ${s.employeeName}`)}
                aria-expanded={expandedId === s.id}
                onClick={() => setExpandedId(expandedId === s.id ? null : s.id)}
                className="mt-3 w-full rounded-xl border border-[var(--border)] py-2 text-sm font-semibold active:opacity-70"
              >
                {expandedId === s.id ? tr("Close details ▲", "Fechar detalhes ▲", "Cerrar detalles ▲") : tr("Details: GPS trail & adjustments ▼", "Detalhes: rastro de GPS e ajustes ▼", "Detalles: rastro de GPS y ajustes ▼")}
              </button>
              {expandedId === s.id && <SheetDetail cid={cid} sheetId={s.id} session={session} isManager={isManager} />}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function SheetDetail({ cid, sheetId, session, isManager }: { cid: string; sheetId: number; session: Session; isManager: boolean }) {
  const q = useQuery({ queryKey: ["sheet-detail", cid, sheetId], queryFn: () => api.getSheetDetail({ companyId: cid, sheetId }) });
  const qc = useQueryClient();
  const toLocalInput = (iso: string | null) => {
    if (!iso) return "";
    const d = new Date(iso);
    const p = (n: number) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
  };
  const [newIn, setNewIn] = useState<string | null>(null);
  const [newOut, setNewOut] = useState<string | null>(null);
  const [reason, setReason] = useState("");
  const [adjMsg, setAdjMsg] = useState("");
  const adjust = useMutation({
    mutationFn: () => api.adjustSheet({ companyId: cid, sheetId, actorId: session.userId, newCheckInAt: new Date(newIn ?? "").toISOString(), newCheckOutAt: newOut ? new Date(newOut).toISOString() : null, reason }),
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["sheet-detail", cid, sheetId] });
      qc.invalidateQueries({ queryKey: ["sheets", cid] });
      qc.invalidateQueries({ queryKey: ["payroll", cid] });
      setAdjMsg(tr(`Adjustment saved: ${r.hours.toFixed(1)}h. It's recorded in the history below.`, `Ajuste salvo: ${r.hours.toFixed(1)}h. Ele está registrado no histórico abaixo.`, `Ajuste guardado: ${r.hours.toFixed(1)}h. Queda registrado en el historial de abajo.`));
    },
    onError: (e) => setAdjMsg(e instanceof Error ? e.message : tr("Could not adjust.", "Não foi possível ajustar.", "No se pudo ajustar.")),
  });

  if (q.isPending) return <p className="mt-3 text-sm text-[var(--dim)]">{tr("Loading details…", "Carregando os detalhes…", "Cargando los detalles…")}</p>;
  if (!q.data?.sheet) return <p className="mt-3 text-sm text-red-600">{tr("Entry not found.", "Registro não encontrado.", "Registro no encontrado.")}</p>;
  const d = q.data;
  const sh = q.data.sheet;
  const effIn = newIn ?? toLocalInput(sh.checkInAt);
  const effOut = newOut ?? toLocalInput(sh.checkOutAt);

  return (
    <div className="mt-3 space-y-3 border-t border-[var(--border)] pt-3">
      <div>
        <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("GPS trail (positions while the app was open)", "Rastro de GPS (posições enquanto o app estava aberto)", "Rastro de GPS (posiciones mientras la app estaba abierta)")}</p>
        {d.trail.length === 0 && <p className="mt-1 text-sm text-[var(--dim)]">{tr("No positions recorded on this shift.", "Nenhuma posição registrada neste turno.", "No se registraron posiciones en este turno.")}</p>}
        <div className="mt-1 space-y-1">
          {d.trail.map((p) => (
            <div key={p.id} className="flex flex-wrap items-center gap-2 rounded-lg bg-[var(--surface2)] px-2.5 py-1.5 text-xs">
              <span className="font-bold">{new Date(p.at).toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })}</span>
              <span className="text-[var(--dim)]">{p.lat.toFixed(5)}, {p.lng.toFixed(5)}</span>
              {zoneBadge(p.zone, p.distM, "")}
            </div>
          ))}
        </div>
        <p className="mt-1 text-xs text-[var(--dim)]">{tr("The trail only exists while the app is open on the phone — a web app can't send background location.", "O rastro só existe enquanto o app está aberto no celular — um app web não consegue enviar a localização em segundo plano.", "El rastro solo existe mientras la app está abierta en el teléfono: una app web no puede enviar la ubicación en segundo plano.")}</p>
      </div>

      <div>
        <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Adjustment history (who / when / old → new)", "Histórico de ajustes (quem / quando / antigo → novo)", "Historial de ajustes (quién / cuándo / anterior → nuevo)")}</p>
        {d.adjustments.length === 0 && <p className="mt-1 text-sm text-[var(--dim)]">{tr("No adjustments on this entry.", "Nenhum ajuste neste registro.", "No hay ajustes en este registro.")}</p>}
        <div className="mt-1 space-y-1.5">
          {d.adjustments.map((a) => (
            <div key={a.id} className="rounded-lg bg-[var(--surface2)] px-2.5 py-2 text-xs">
              <p><span className="font-bold">{a.adjustedByName}</span> • {new Date(a.at).toLocaleString("en-US")}</p>
              <p className="mt-0.5">{tr("In:", "Entrada:", "Entrada:")} {fmtTime(a.oldIn)} → <strong>{fmtTime(a.newIn)}</strong> • {tr("Out:", "Saída:", "Salida:")} {a.oldOut ? fmtTime(a.oldOut) : "—"} → <strong>{a.newOut ? fmtTime(a.newOut) : "—"}</strong> • {tr("Hours:", "Horas:", "Horas:")} {a.oldHours.toFixed(1)}h → <strong>{a.newHours.toFixed(1)}h</strong></p>
              {a.reason && <p className="mt-0.5 text-[var(--dim)]">{tr("Reason:", "Motivo:", "Motivo:")} {a.reason}</p>}
            </div>
          ))}
        </div>
      </div>

      {isManager ? (
        <form className="rounded-xl border border-dashed border-[var(--border)] p-3" onSubmit={(e) => { e.preventDefault(); adjust.mutate(); }}>
          <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Adjust times (manager/admin only — always logged)", "Ajustar horários (somente gerente/administrador — sempre registrado)", "Ajustar horarios (solo gerente/administrador, siempre registrado)")}</p>
          <p className="mt-1 text-xs text-[var(--dim)]">{tr("Use it to fix a forgotten clock-in or", "Use para corrigir um check-in esquecido ou", "Úsalo para corregir un registro de entrada olvidado o")} <strong>{tr("extend past the cutoff time", "estender além do horário limite", "extender más allá de la hora límite")}</strong> {tr("when the employee really stayed late.", "quando o funcionário realmente ficou até mais tarde.", "cuando el empleado realmente se quedó hasta tarde.")}</p>
          <div className="mt-2 grid grid-cols-2 gap-2">
            <Field label={tr("New check-in", "Novo check-in", "Nuevo registro de entrada")}><input aria-label={tr("New check-in time", "Novo horário de check-in", "Nueva hora de registro de entrada")} type="datetime-local" className={inputCls} value={effIn} onChange={(e) => setNewIn(e.target.value)} required /></Field>
            <Field label={tr("New check-out", "Novo check-out", "Nuevo registro de salida")}><input aria-label={tr("New check-out time", "Novo horário de check-out", "Nueva hora de registro de salida")} type="datetime-local" className={inputCls} value={effOut} onChange={(e) => setNewOut(e.target.value)} /></Field>
          </div>
          <div className="mt-2"><Field label={tr("Reason for the adjustment", "Motivo do ajuste", "Motivo del ajuste")}><input aria-label={tr("Adjustment reason", "Motivo do ajuste", "Motivo del ajuste")} className={inputCls} value={reason} onChange={(e) => setReason(e.target.value)} placeholder={tr("E.g.: forgot to check in; GPS confirmed on site", "Ex.: esqueceu o check-in; GPS confirmou na obra", "Ej.: olvidó registrar la entrada; GPS confirmado en la obra")} /></Field></div>
          <button className={`${btnNavy} mt-2 w-full`} disabled={adjust.isPending || !effIn}>{adjust.isPending ? tr("Saving adjustment…", "Salvando o ajuste…", "Guardando el ajuste…") : tr("Save logged adjustment", "Salvar o ajuste registrado", "Guardar el ajuste registrado")}</button>
          {adjMsg && <p className="mt-2 text-xs font-semibold" role="status">{adjMsg}</p>}
        </form>
      ) : (
        <p className="rounded-xl bg-[var(--surface2)] px-3 py-2 text-xs text-[var(--dim)]">{tr("Adjustments can only be made by a manager or admin — and they are logged here.", "Ajustes só podem ser feitos por um gerente ou administrador — e ficam registrados aqui.", "Los ajustes solo puede hacerlos un gerente o administrador, y quedan registrados aquí.")}</p>
      )}
    </div>
  );
}

/* ---------------- Payroll ---------------- */
/* Week helpers (Mon–Sun) for the payroll period view. */
function payrollWeek(offset: number): { start: string; end: string; label: string } {
  const now = new Date();
  const day = now.getDay();
  const diff = day === 0 ? -6 : 1 - day;
  const mon = new Date(now); mon.setDate(now.getDate() + diff + offset * 7);
  const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
  const f = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const label = `${mon.toLocaleDateString("en-US", { month: "short", day: "numeric" })} – ${sun.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
  return { start: f(mon), end: f(sun), label };
}

function Payroll({ cid, session }: { cid: string; session: Session }) {
  const qc = useQueryClient();
  const [weekOffset, setWeekOffset] = useState(0);
  const week = payrollWeek(weekOffset);
  const q = useQuery({ queryKey: ["payroll", cid, week.start, week.end], queryFn: () => api.getPayroll({ companyId: cid, actorId: session.userId, weekOnly: true, periodStart: week.start, periodEnd: week.end }) });
  const payoutsQ = useQuery({ queryKey: ["payouts", cid], queryFn: () => api.listPayrollPayouts({ companyId: cid }) });
  const [selected, setSelected] = useState<Set<number>>(new Set());
  const [paidDate, setPaidDate] = useState(todayInput());
  const [method, setMethod] = useState("Check");
  const [reference, setReference] = useState("");
  const [payNotes, setPayNotes] = useState("");
  const [payMsg, setPayMsg] = useState("");
  const [stubId, setStubId] = useState<number | null>(null);
  const [customAmounts, setCustomAmounts] = useState<Record<number, string>>({});
  const [showAdvance, setShowAdvance] = useState(false);
  const [advEmployeeId, setAdvEmployeeId] = useState("");
  const [advAmount, setAdvAmount] = useState("");
  const [advDate, setAdvDate] = useState(todayInput());
  const [advNotes, setAdvNotes] = useState("");
  const stubQ = useQuery({ queryKey: ["pay-stub", cid, stubId], queryFn: () => api.getPayStub({ companyId: cid, payoutId: stubId ?? 0 }), enabled: stubId !== null });

  const advancesQ = useQuery({ queryKey: ["advances", cid], queryFn: () => api.listPayrollAdvances({ companyId: cid, actorId: session.userId }) });
  const recordAdvance = useMutation({
    mutationFn: () => api.recordPayrollAdvance({ companyId: cid, actorId: session.userId, employeeId: Number(advEmployeeId), amountCents: Math.round(parseFloat(advAmount.replace(",", ".")) * 100) || 0, advanceDate: advDate, notes: advNotes }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["advances", cid] });
      qc.invalidateQueries({ queryKey: ["payroll", cid] });
      setShowAdvance(false); setAdvEmployeeId(""); setAdvAmount(""); setAdvNotes("");
      setPayMsg(tr("Advance recorded.", "Vale lançado.", "Vale registrado."));
    },
    onError: () => setPayMsg(tr("Could not record the advance.", "Não foi possível lançar o vale.", "No se pudo registrar el vale.")),
  });

  const markPaid = useMutation({
    mutationFn: () => {
      const paidAmounts: Record<string, number> = {};
      for (const id of selected) {
        const custom = customAmounts[id]?.trim();
        if (custom) {
          const cents = Math.round(parseFloat(custom.replace(",", ".")) * 100);
          if (cents >= 0) paidAmounts[String(id)] = cents;
        }
      }
      return api.markPayrollPaid({ companyId: cid, actorId: session.userId, employeeIds: [...selected], periodStart: week.start, periodEnd: week.end, paidDate, method: method as "Check" | "Direct deposit" | "Cash" | "Other", reference, notes: payNotes, paidAmounts });
    },
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["payroll", cid] });
      qc.invalidateQueries({ queryKey: ["payouts", cid] });
      setSelected(new Set());
      setPayMsg(tr(`Marked ${r.count} ${r.count === 1 ? "person" : "people"} as paid for ${week.label}. Paid periods are locked — they won't recalculate. ✅`, `Marcou ${r.count} ${r.count === 1 ? "pessoa" : "pessoas"} como paga(s) para ${week.label}. Períodos pagos estão travados — não serão recalculados. ✅`, `Se marcaron ${r.count} ${r.count === 1 ? "persona" : "personas"} como pagadas para ${week.label}. Los períodos pagados están bloqueados: no se recalcularán. ✅`));
    },
    onError: (e) => setPayMsg(e instanceof Error ? e.message : tr("Could not mark as paid.", "Não foi possível marcar como pago.", "No se pudo marcar como pagado.")),
  });

  const rows = q.data?.rows ?? [];
  const selectable = rows.filter((r) => !r.paid);
  const allSelected = selectable.length > 0 && selectable.every((r) => selected.has(r.employeeId));
  const toggleAll = () => setSelected(allSelected ? new Set() : new Set(selectable.map((r) => r.employeeId)));
  const toggleOne = (id: number) => setSelected((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const stub = stubQ.data?.stub;

  if (stubId !== null) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between print:hidden">
          <button onClick={() => setStubId(null)} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to payroll", "Voltar para a folha de pagamento", "Volver a la nómina")}>{tr("← Back to payroll", "← Voltar para a folha", "← Volver a la nómina")}</button>
          <button type="button" className={btnGhost} disabled={!stub} aria-label={tr("Download this pay stub as a text file", "Baixar este comprovante como arquivo de texto", "Descargar este comprobante como archivo de texto")} onClick={() => {
            if (!stub) return;
            const lines = [
              stub.companyName,
              tr("PAY STUB", "COMPROVANTE DE PAGAMENTO", "COMPROBANTE DE PAGO"),
              "",
              `${tr("Employee", "Funcionário", "Empleado")}: ${stub.employeeName}${stub.trade ? ` — ${stub.trade}` : ""}`,
              `${tr("Pay period", "Período de pagamento", "Período de pago")}: ${fmtDate(stub.periodStart)} – ${fmtDate(stub.periodEnd)}`,
              `${tr("Pay type", "Tipo de pagamento", "Tipo de pago")}: ${payTypeLabel(stub.payType)} • ${fmtUSD(stub.payRate)}${payTypeSuffix(stub.payType)}`,
              "",
              ...(stub.payType === "hora"
                ? [
                    `${tr("Regular hours", "Horas regulares", "Horas regulares")} × ${fmtUSD(stub.payRate)}/hr — ${stub.regularHours.toFixed(1)}h — ${fmtUSD(stub.regularPay)}`,
                    ...(stub.otHours > 0 ? [`${tr("Overtime", "Hora extra", "Horas extra")} × ${stub.otMultiplier}× — ${stub.otHours.toFixed(1)}h — ${fmtUSD(stub.otPay)}`] : []),
                  ]
                : stub.payType === "diaria"
                  ? [`${tr("Days on site", "Dias na obra", "Días en la obra")} × ${fmtUSD(stub.payRate)}/day — ${stub.days} ${tr("day(s)", "dia(s)", "día(s)")} (${stub.hours.toFixed(1)}h) — ${fmtUSD(stub.gross)}`]
                  : [`${tr("Contract amount for the period", "Valor do contrato no período", "Importe del contrato en el período")} — ${stub.hours.toFixed(1)}h • ${stub.days} ${tr("day(s)", "dia(s)", "día(s)")} — ${fmtUSD(stub.gross)}`]),
              `${tr("Gross pay", "Salário bruto", "Pago bruto")}: ${fmtUSD(stub.gross)}`,
              "",
              `${tr("Paid on", "Pago em", "Pagado el")}: ${fmtDate(stub.paidDate)}`,
              `${tr("Method", "Método", "Método")}: ${stub.method}`,
              ...(stub.reference ? [`${tr("Reference", "Referência", "Referencia")}: ${stub.reference}`] : []),
              ...(stub.notes ? [`${tr("Notes", "Observações", "Notas")}: ${stub.notes}`] : []),
            ];
            downloadTextFile(`PayStub-${stub.employeeName.replace(/[^\w-]+/g, "_")}-${stub.periodStart}.txt`, lines.join("\n"), "text/plain");
          }}>{tr("Save stub", "Salvar comprovante", "Guardar comprobante")}</button>
        </div>
        {stubQ.isPending && <p className="py-8 text-center text-[var(--dim)]">{tr("Loading pay stub…", "Carregando o comprovante…", "Cargando el comprobante…")}</p>}
        {stub && (
          <article className="invoice-sheet rounded-2xl border border-[var(--border)] bg-white p-5 text-[#12222f] shadow-sm" aria-label={tr(`Pay stub for ${stub.employeeName}`, `Comprovante de pagamento de ${stub.employeeName}`, `Comprobante de pago de ${stub.employeeName}`)}>
            <header className="border-b-2 border-[#0f2a44] pb-3">
              <p className="text-xl font-black uppercase tracking-wide text-[#0f2a44]">{stub.companyName}</p>
              <p className="mt-0.5 text-sm font-bold tracking-wide text-[#5b6b7a]">{tr("PAY STUB", "COMPROVANTE DE PAGAMENTO", "COMPROBANTE DE PAGO")}</p>
            </header>
            <dl className="mt-4 space-y-1.5 text-sm">
              <div className="flex justify-between gap-3"><dt className="font-bold">{tr("Employee", "Funcionário", "Empleado")}</dt><dd>{stub.employeeName}{stub.trade ? ` — ${stub.trade}` : ""}</dd></div>
              <div className="flex justify-between gap-3"><dt className="font-bold">{tr("Pay period", "Período de pagamento", "Período de pago")}</dt><dd>{fmtDate(stub.periodStart)} – {fmtDate(stub.periodEnd)}</dd></div>
              <div className="flex justify-between gap-3"><dt className="font-bold">{tr("Pay type", "Tipo de pagamento", "Tipo de pago")}</dt><dd>{payTypeLabel(stub.payType)} • {fmtUSD(stub.payRate)}{payTypeSuffix(stub.payType)}</dd></div>
            </dl>
            <table className="mt-4 w-full text-left text-sm">
              <thead>
                <tr className="border-b-2 border-[#0f2a44] text-xs uppercase tracking-wide text-[#5b6b7a]">
                  <th className="py-2 pr-2 font-black">{tr("Earnings", "Rendimentos", "Ingresos")}</th>
                  <th className="py-2 px-2 text-right font-black">{tr("Hours / days", "Horas / dias", "Horas / días")}</th>
                  <th className="py-2 pl-2 text-right font-black">{tr("Amount", "Valor", "Importe")}</th>
                </tr>
              </thead>
              <tbody>
                {stub.payType === "hora" && (
                  <>
                    <tr className="border-b border-[#dde3ea]"><td className="py-2 pr-2">{tr("Regular hours", "Horas regulares", "Horas regulares")} × {fmtUSD(stub.payRate)}/hr</td><td className="py-2 px-2 text-right">{stub.regularHours.toFixed(1)}h</td><td className="py-2 pl-2 text-right font-semibold">{fmtUSD(stub.regularPay)}</td></tr>
                    {stub.otHours > 0 && <tr className="border-b border-[#dde3ea]"><td className="py-2 pr-2">{tr("Overtime", "Hora extra", "Horas extra")} × {stub.otMultiplier}×</td><td className="py-2 px-2 text-right">{stub.otHours.toFixed(1)}h</td><td className="py-2 pl-2 text-right font-semibold">{fmtUSD(stub.otPay)}</td></tr>}
                  </>
                )}
                {stub.payType === "diaria" && <tr className="border-b border-[#dde3ea]"><td className="py-2 pr-2">{tr("Days on site", "Dias na obra", "Días en la obra")} × {fmtUSD(stub.payRate)}/day</td><td className="py-2 px-2 text-right">{stub.days} {tr("day(s)", "dia(s)", "día(s)")} ({stub.hours.toFixed(1)}h)</td><td className="py-2 pl-2 text-right font-semibold">{fmtUSD(stub.gross)}</td></tr>}
                {stub.payType === "contrato" && <tr className="border-b border-[#dde3ea]"><td className="py-2 pr-2">{tr("Contract amount for the period", "Valor do contrato no período", "Importe del contrato en el período")}</td><td className="py-2 px-2 text-right">{stub.hours.toFixed(1)}h • {stub.days} {tr("day(s)", "dia(s)", "día(s)")}</td><td className="py-2 pl-2 text-right font-semibold">{fmtUSD(stub.gross)}</td></tr>}
                <tr><td className="py-2 pr-2 text-base font-black">{tr("Gross pay", "Salário bruto", "Pago bruto")}</td><td /><td className="py-2 pl-2 text-right text-base font-black">{fmtUSD(stub.gross)}</td></tr>
              </tbody>
            </table>
            <dl className="mt-4 space-y-1 border-t border-[#dde3ea] pt-3 text-sm">
              <div className="flex justify-between gap-3"><dt className="font-bold">{tr("Paid on", "Pago em", "Pagado el")}</dt><dd>{fmtDate(stub.paidDate)}</dd></div>
              <div className="flex justify-between gap-3"><dt className="font-bold">{tr("Method", "Método", "Método")}</dt><dd>{stub.method}</dd></div>
              {stub.reference && <div className="flex justify-between gap-3"><dt className="font-bold">{tr("Reference", "Referência", "Referencia")}</dt><dd>{stub.reference}</dd></div>}
              {stub.notes && <div className="flex justify-between gap-3"><dt className="font-bold">{tr("Notes", "Observações", "Notas")}</dt><dd>{stub.notes}</dd></div>}
            </dl>
            <p className="mt-4 text-xs text-[#5b6b7a]">{tr("This stub reflects a locked payroll payout — the numbers match what was paid and do not change if rates or hours are edited later.", "Este comprovante reflete uma baixa de folha travada — os valores correspondem ao que foi pago e não mudam se valores ou horas forem editados depois.", "Este comprobante refleja una nómina ya pagada y bloqueada: los valores corresponden a lo que se pagó y no cambian si luego se editan tarifas u horas.")}</p>
          </article>
        )}
        {!stubQ.isPending && !stub && <p className="py-8 text-center text-[var(--dim)]">{tr("Pay stub not found.", "Comprovante não encontrado.", "Comprobante no encontrado.")}</p>}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-2 print:hidden">
        <h2 className="text-xl font-bold">{tr("Payroll", "Folha de pagamento", "Nómina")}</h2>
        <div className="flex items-center gap-2">
          <button type="button" className={btnGhost} onClick={() => window.print()} aria-label={tr("Print or save as PDF", "Imprimir ou salvar como PDF", "Imprimir o guardar como PDF")}>🖨️ {tr("Print / PDF", "Imprimir / PDF", "Imprimir / PDF")}</button>
          <div className="flex items-center gap-1.5" role="group" aria-label={tr("Payroll week navigation", "Navegação da semana da folha", "Navegación de la semana de nómina")}>
            <button type="button" aria-label={tr("Previous week", "Semana anterior", "Semana anterior")} onClick={() => { setWeekOffset((o) => o - 1); setSelected(new Set()); }} className={btnGhost}>←</button>
            <span className="px-1 text-sm font-bold" aria-label={tr("Current payroll period", "Período atual da folha", "Período actual de nómina")}>{weekOffset === 0 ? tr("This week", "Esta semana", "Esta semana") : week.label}<span className="block text-center text-[11px] font-medium text-[var(--dim)]">{week.label}</span></span>
            <button type="button" aria-label={tr("Next week", "Próxima semana", "Semana siguiente")} disabled={weekOffset >= 0} onClick={() => { setWeekOffset((o) => o + 1); setSelected(new Set()); }} className={`${btnGhost} disabled:opacity-40`}>→</button>
          </div>
        </div>
      </div>
      <div className="hidden print:block">
        <h2 className="text-xl font-bold">{tr("Payroll", "Folha de pagamento", "Nómina")} — {week.label}</h2>
        <p className="text-sm text-gray-600">{session.companyName}</p>
      </div>
      <p className="text-sm text-[var(--dim)]">{tr("Weekly period (Mon–Sun), from", "Período semanal (seg–dom), somente de registros de ponto", "Período semanal (lun–dom), solo de registros de horas")} <strong>{tr("approved", "aprovados", "aprobados")}</strong> {tr("time entries only.", ".", ".")} <strong>{tr("Hourly", "Por hora", "Por hora")}</strong> = {tr("hours × rate", "horas × valor", "horas × tarifa")}{ q.data?.otEnabled ? <> {tr("with overtime: hours over", "com hora extra: horas acima de", "con horas extra: horas por encima de")} {q.data.otDailyHours}h/{tr("day", "dia", "día")} {tr("and", "e", "y")} {q.data.otWeeklyHours}h/{tr("week pay", "semana pagam", "semana pagan")} {q.data.otMultiplier}×</> : tr(" (overtime is off — an admin can turn it on in Settings)", " (hora extra desativada — um administrador pode ativá-la em Configurações)", " (horas extra desactivadas: un administrador puede activarlas en Configuración)")} • <strong>{tr("Daily", "Por dia", "Por día")}</strong> = {tr("days on site × daily rate", "dias na obra × diária", "días en la obra × tarifa diaria")} • <strong>{tr("Contract", "Por contrato", "Por contrato")}</strong> = {tr("fixed amount for the period. Select people and mark them paid — paid periods lock and never recalculate.", "valor fixo pelo período. Selecione as pessoas e marque como pago — períodos pagos travam e nunca são recalculados.", "importe fijo por el período. Selecciona a las personas y márcalas como pagadas: los períodos pagados se bloquean y nunca se recalculan.")}</p>
      {q.isPending && <p className="py-8 text-center text-[var(--dim)]">{tr("Calculating payroll…", "Calculando a folha…", "Calculando la nómina…")}</p>}
      {q.data && rows.length === 0 && <div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center"><p className="font-semibold">{tr("No approved hours in this period", "Nenhuma hora aprovada neste período", "No hay horas aprobadas en este período")}</p><p className="mt-1 text-sm text-[var(--dim)]">{tr("Approve entries in the Time tab to see payroll here.", "Aprove registros na aba Ponto para ver a folha aqui.", "Aprueba registros en la pestaña Horas para ver la nómina aquí.")}</p></div>}

      <div className="flex flex-wrap gap-2 print:hidden">
        <button type="button" className={btnGhost} onClick={() => setShowAdvance((s) => !s)}>{showAdvance ? tr("Close advance form", "Fechar vale", "Cerrar vale") : tr("💰 Record advance (vale)", "💰 Lançar vale", "💰 Registrar vale")}</button>
      </div>
      {showAdvance && (
        <section className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Record advance", "Lançar vale", "Registrar vale")}>
          <h3 className="font-bold">💰 {tr("Record advance (vale)", "Lançar vale", "Registrar vale")}</h3>
          <div className="grid grid-cols-2 gap-2">
            <Field label={tr("Employee", "Funcionário", "Empleado")}>
              <select aria-label={tr("Employee for advance", "Funcionário do vale", "Empleado del vale")} className={inputCls} value={advEmployeeId} onChange={(e) => setAdvEmployeeId(e.target.value)}>
                <option value="">{tr("Select…", "Selecione…", "Selecciona…")}</option>
                {rows.map((r) => <option key={r.employeeId} value={r.employeeId}>{r.employeeName}</option>)}
              </select>
            </Field>
            <Field label={tr("Amount (USD)", "Valor (USD)", "Importe (USD)")}>
              <input aria-label={tr("Advance amount", "Valor do vale", "Importe del vale")} className={inputCls} inputMode="decimal" value={advAmount} onChange={(e) => setAdvAmount(e.target.value)} placeholder="100.00" />
            </Field>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Field label={tr("Date", "Data", "Fecha")}><input aria-label={tr("Advance date", "Data do vale", "Fecha del vale")} type="date" className={inputCls} value={advDate} onChange={(e) => setAdvDate(e.target.value)} /></Field>
            <Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><input aria-label={tr("Advance notes", "Observações do vale", "Notas del vale")} className={inputCls} value={advNotes} onChange={(e) => setAdvNotes(e.target.value)} /></Field>
          </div>
          <button type="button" className={`${btnNavy} w-full`} disabled={recordAdvance.isPending || !advEmployeeId || !advAmount.trim()} onClick={() => recordAdvance.mutate()}>
            {recordAdvance.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Record advance", "Lançar vale", "Registrar vale")}
          </button>
          {advancesQ.data && advancesQ.data.advances.filter((a) => !a.deducted).length > 0 && (
            <div className="mt-2">
              <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Outstanding advances", "Vales em aberto", "Vales pendientes")}</p>
              <div className="mt-1 space-y-1">
                {advancesQ.data.advances.filter((a) => !a.deducted).map((a) => (
                  <p key={a.id} className="text-sm">{a.employeeName} • {fmtUSD(a.amountCents)} • {fmtDate(a.advanceDate)}{a.notes ? ` • ${a.notes}` : ""}</p>
                ))}
              </div>
            </div>
          )}
        </section>
      )}

      {rows.length > 0 && (
        <label className="flex items-center gap-2 text-sm font-semibold">
          <input type="checkbox" aria-label={tr("Select all unpaid people", "Selecionar todas as pessoas não pagas", "Seleccionar a todas las personas sin pagar")} checked={allSelected} disabled={selectable.length === 0} onChange={toggleAll} className="h-4 w-4" />
          {tr("Select all unpaid", "Selecionar todos os não pagos", "Seleccionar a todos los sin pagar")} ({selectable.length})
        </label>
      )}
      <div className="space-y-3">
        {rows.map((r) => (
          <div key={`${r.employeeId}-${r.payType}-${r.payRate}`} className="flex items-center justify-between gap-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
            <div className="flex min-w-0 items-start gap-3">
              <input type="checkbox" aria-label={tr(`Select ${r.employeeName} to mark as paid`, `Selecionar ${r.employeeName} para marcar como pago`, `Seleccionar a ${r.employeeName} para marcar como pagado`)} checked={selected.has(r.employeeId)} disabled={r.paid} onChange={() => toggleOne(r.employeeId)} className="mt-1 h-4 w-4 shrink-0 disabled:opacity-40" />
              <div className="min-w-0">
                <p className="truncate font-bold">{r.employeeName}</p>
                <div className="mt-1 flex flex-wrap items-center gap-1.5">{payBadge(r.payType, r.payRate)}{r.paid ? <Badge text={tr("Paid ✓ locked", "Pago ✓ travado", "Pagado ✓ bloqueado")} tone="green" /> : <Badge text={tr("Open", "Aberto", "Abierto")} tone="amber" />}</div>
                <p className="mt-1 text-xs text-[var(--dim)]">
                  {r.payType === "hora"
                    ? <>{r.trade ? `${r.trade} • ` : ""}{tr("Regular", "Regulares", "Regulares")} {r.regularHours.toFixed(1)}h{r.otHours > 0 ? <> • <span className="font-bold text-amber-700 dark:text-amber-400">OT {r.otHours.toFixed(1)}h</span></> : ""} • {tr("Total", "Total", "Total")} {r.hours.toFixed(1)}h</>
                    : r.payType === "diaria"
                      ? <>{r.trade ? `${r.trade} • ` : ""}{r.days} {tr("day(s) on site", "dia(s) na obra", "día(s) en la obra")} • {r.hours.toFixed(1)}h</>
                      : <>{r.trade ? `${r.trade} • ` : ""}{r.hours.toFixed(1)}h • {r.days} day(s)</>}
                </p>
              </div>
            </div>
            <div className="shrink-0 text-right">
              <p className="text-lg font-black">{fmtUSD(r.amount)}</p>
              {r.paid && r.paidAmount !== null && r.paidAmount !== r.amount && (
                <p className="text-xs font-semibold text-amber-700">{tr("Paid:", "Pago:", "Pagado:")} {fmtUSD(r.paidAmount)} • {tr("Balance:", "Saldo:", "Saldo:")} <span className={r.balance! > 0 ? "text-red-600" : "text-green-600"}>{fmtUSD(r.balance!)}</span></p>
              )}
              {r.outstandingAdvances > 0 && (
                <p className="text-xs font-semibold text-purple-700">💰 {tr("Advance:", "Vale:", "Vale:")} {fmtUSD(r.outstandingAdvances)}</p>
              )}
              {r.paid && r.payoutId !== null && <button type="button" aria-label={tr(`View pay stub for ${r.employeeName}`, `Ver o comprovante de ${r.employeeName}`, `Ver el comprobante de ${r.employeeName}`)} onClick={() => setStubId(r.payoutId)} className="text-xs font-bold text-[#f97316] active:opacity-70">{tr("Pay stub", "Comprovante", "Comprobante")}</button>}
            </div>
          </div>
        ))}
      </div>
      {rows.length > 0 && (
        <div className="rounded-2xl bg-[#0f2a44] p-4 text-white">
          <p className="text-xs font-semibold uppercase tracking-wide text-white/60">{tr("Payroll total", "Total da folha", "Total de la nómina")} ({week.label})</p>
          <p className="text-2xl font-black">{fmtUSD(q.data?.total ?? 0)}</p>
        </div>
      )}

      {selected.size > 0 && (
        <section className="space-y-3 rounded-2xl border-2 border-green-600 bg-[var(--surface)] p-4" aria-label={tr("Mark as paid", "Marcar como pago", "Marcar como pagado")}>
          <h3 className="font-bold">💵 {tr("Mark as paid", "Marcar como pago", "Marcar como pagado")} — {selected.size} {selected.size === 1 ? tr("person", "pessoa", "persona") : tr("people", "pessoas", "personas")} • {week.label}</h3>
          <div className="space-y-2">
            <p className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Amounts to pay (leave blank for the full amount)", "Valores a pagar (deixe em branco para o valor integral)", "Importes a pagar (deja en blanco para el importe total)")}</p>
            {rows.filter((r) => selected.has(r.employeeId)).map((r) => (
              <div key={r.employeeId} className="flex items-center justify-between gap-2 rounded-lg bg-[var(--surface2)] px-3 py-2">
                <span className="text-sm font-semibold">{r.employeeName} <span className="font-normal text-[var(--dim)]">({fmtUSD(r.amount)})</span></span>
                <input aria-label={tr(`Amount to pay ${r.employeeName}`, `Valor a pagar para ${r.employeeName}`, `Importe a pagar a ${r.employeeName}`)} className={inputCls} inputMode="decimal" value={customAmounts[r.employeeId] ?? ""} onChange={(e) => setCustomAmounts((prev) => ({ ...prev, [r.employeeId]: e.target.value }))} placeholder={fmtUSD(r.amount)} style={{ width: 110 }} />
              </div>
            ))}
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label={tr("Paid date", "Data do pagamento", "Fecha de pago")}><input aria-label={tr("Paid date", "Data do pagamento", "Fecha de pago")} type="date" className={inputCls} value={paidDate} onChange={(e) => setPaidDate(e.target.value)} /></Field>
            <Field label={tr("Method", "Método", "Método")}>
              <select aria-label={tr("Payout method", "Método de pagamento", "Método de pago")} className={inputCls} value={method} onChange={(e) => setMethod(e.target.value)}>
                <option value="Check">{tr("Check", "Cheque", "Cheque")}</option><option value="Direct deposit">{tr("Direct deposit", "Depósito direto", "Depósito directo")}</option><option value="Cash">{tr("Cash", "Dinheiro", "Efectivo")}</option><option value="Other">{tr("Other", "Outro", "Otro")}</option>
              </select>
            </Field>
          </div>
          <Field label={tr("Reference (check #, transfer id — optional)", "Referência (nº do cheque, ID da transferência — opcional)", "Referencia (n.º de cheque, ID de transferencia, opcional)")}><input aria-label={tr("Payout reference", "Referência do pagamento", "Referencia del pago")} className={inputCls} value={reference} onChange={(e) => setReference(e.target.value)} placeholder={tr("e.g. Check #1042", "ex.: Cheque nº 1042", "ej.: Cheque n.º 1042")} /></Field>
          <Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><input aria-label={tr("Payout notes", "Observações do pagamento", "Notas del pago")} className={inputCls} value={payNotes} onChange={(e) => setPayNotes(e.target.value)} placeholder={tr("Anything worth remembering", "Tudo o que vale lembrar", "Todo lo que valga la pena recordar")} /></Field>
          <button type="button" aria-label={tr(`Mark ${selected.size} people as paid`, `Marcar ${selected.size} pessoas como pagas`, `Marcar a ${selected.size} personas como pagadas`)} disabled={markPaid.isPending || !paidDate} onClick={() => markPaid.mutate()} className="w-full rounded-xl bg-green-600 px-4 py-3 font-black text-white active:opacity-80 disabled:opacity-40">
            {markPaid.isPending ? tr("Saving…", "Salvando…", "Guardando…") : `"+tr("Mark", "Marcar", "Marcar")+" ${selected.size} "+tr("as paid", "como pago", "como pagado")+"`}
          </button>
          <p className="text-xs text-[var(--dim)]">{tr("Amounts are recalculated on the server from approved hours. Once paid, this period locks for those people: their entries can't be edited, approved, or rejected, and the numbers never change.", "Os valores são recalculados no servidor a partir das horas aprovadas. Depois de pago, este período trava para essas pessoas: os registros delas não podem ser editados, aprovados ou rejeitados, e os valores nunca mudam.", "Los importes se recalculan en el servidor a partir de las horas aprobadas. Una vez pagado, este período se bloquea para esas personas: sus registros no se pueden editar, aprobar ni rechazar, y los valores nunca cambian.")}</p>
        </section>
      )}
      {payMsg && <p className="rounded-xl bg-green-100 px-3 py-2 text-sm font-semibold text-green-800" role="status">{payMsg}</p>}

      <section aria-label={tr("Payout history", "Histórico de pagamentos", "Historial de pagos")}>
        <h3 className="font-bold">{tr("Payout history", "Histórico de pagamentos", "Historial de pagos")}</h3>
        {payoutsQ.isPending && <p className="mt-2 text-sm text-[var(--dim)]">{tr("Loading payouts…", "Carregando os pagamentos…", "Cargando los pagos…")}</p>}
        {payoutsQ.data && payoutsQ.data.payouts.length === 0 && <p className="mt-2 text-sm text-[var(--dim)]">{tr("No payouts yet. Select people above and mark them paid to start the history.", "Nenhum pagamento ainda. Selecione as pessoas acima e marque como pago para iniciar o histórico.", "Todavía no hay pagos. Selecciona a las personas arriba y márcalas como pagadas para iniciar el historial.")}</p>}
        <div className="mt-2 space-y-2">
          {(payoutsQ.data?.payouts ?? []).map((p) => (
            <div key={p.id} className="flex items-center justify-between gap-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-3.5">
              <div className="min-w-0">
                <p className="truncate font-semibold">{p.employeeName}</p>
                <p className="text-xs text-[var(--dim)]">{fmtDate(p.periodStart)} – {fmtDate(p.periodEnd)} • {tr("Paid", "Pago em", "Pagado el")} {fmtDate(p.paidDate)} • {p.method}{p.reference ? ` • ${p.reference}` : ""}</p>
                <p className="text-xs text-[var(--dim)]">{p.payType === "hora" ? `"+tr("Regular", "Regulares", "Regulares")+" ${p.regularHours.toFixed(1)}h${p.otHours > 0 ? ` + OT ${p.otHours.toFixed(1)}h` : ""}` : p.payType === "diaria" ? `${p.days} "+tr("day(s)", "dia(s)", "día(s)")+"` : tr("Contract", "Por contrato", "Por contrato")}</p>
              </div>
              <div className="shrink-0 text-right">
                <p className="font-black">{fmtUSD(p.gross)}</p>
                <button type="button" aria-label={tr(`View pay stub for ${p.employeeName}, period starting ${p.periodStart}`, `Ver o comprovante de ${p.employeeName}, período iniciado em ${p.periodStart}`, `Ver el comprobante de ${p.employeeName}, período iniciado el ${p.periodStart}`)} onClick={() => setStubId(p.id)} className="text-xs font-bold text-[#f97316] active:opacity-70">{tr("Pay stub", "Comprovante", "Comprobante")}</button>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

/* ---------------- Expenses ---------------- */
function Expenses({ cid, session }: { cid: string; session: Session }) {
  const projects = useQuery({ queryKey: ["projects", cid], queryFn: () => api.listProjects({ companyId: cid }) });
  const q = useQuery({ queryKey: ["expenses", cid], queryFn: () => api.listExpenses({ companyId: cid }) });
  const qc = useQueryClient();
  const isManagerUser = session.role === "admin" || session.role === "gerente";
  const [unmarkId, setUnmarkId] = useState<number | null>(null);
  const unmark = useMutation({
    mutationFn: (expenseId: number) => api.unmarkExpenseBilled({ companyId: cid, actorId: session.userId, expenseId }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["expenses", cid] }); qc.invalidateQueries({ queryKey: ["invoices", cid] }); qc.invalidateQueries({ queryKey: ["project-materials", cid] }); setUnmarkId(null); },
  });
  const [projectId, setProjectId] = useState("");
  const [item, setItem] = useState("");
  const [qty, setQty] = useState("1");
  const [cost, setCost] = useState("");
  const [supplier, setSupplier] = useState("");
  const [date, setDate] = useState(todayInput());
  const create = useMutation({
    mutationFn: () => api.createExpense({ companyId: cid, actorId: session.userId, projectId: Number(projectId), item, quantity: parseFloat(qty.replace(",", ".")) || 1, unitCost: parseMoney(cost), supplier, expenseDate: date, receiptNote: "" }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["expenses", cid] }); qc.invalidateQueries({ queryKey: ["dashboard", cid] }); setItem(""); setCost(""); setSupplier(""); },
  });
  const total = (q.data?.expenses ?? []).reduce((s, e) => s + e.total, 0);
  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold">{tr("Materials & expenses", "Materiais e despesas", "Materiales y gastos")}</h2>
        <Badge text={tr(`Total ${fmtUSD(total)}`, `Total de ${fmtUSD(total)}`, `Total de ${fmtUSD(total)}`)} tone="navy" />
      </div>
      <form className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" onSubmit={(e) => { e.preventDefault(); create.mutate(); }}>
        <Field label={tr("Project", "Obra", "Obra")}>
          <select aria-label={tr("Expense project", "Obra da despesa", "Obra del gasto")} className={inputCls} value={projectId} onChange={(e) => setProjectId(e.target.value)} required>
            <option value="">{tr("Select a project…", "Selecionar uma obra…", "Seleccionar una obra…")}</option>
            {(projects.data?.projects ?? []).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
          </select>
        </Field>
        <Field label={tr("Item / material", "Item / material", "Concepto / material")}><input aria-label={tr("Expense item", "Item da despesa", "Concepto del gasto")} autoComplete="off" className={inputCls} value={item} onChange={(e) => setItem(e.target.value)} placeholder={tr("E.g.: Cement 50kg bag", "Ex.: Saco de cimento de 50 kg", "Ej.: Bolsa de cemento de 50 kg")} required /></Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label={tr("Quantity", "Quantidade", "Cantidad")}><input aria-label={tr("Quantity", "Quantidade", "Cantidad")} className={inputCls} inputMode="decimal" value={qty} onChange={(e) => setQty(e.target.value)} /></Field>
          <Field label={tr("Unit cost (USD)", "Custo unitário (USD)", "Costo unitario (USD)")}><input aria-label={tr("Unit cost in US dollars", "Custo unitário em dólares", "Costo unitario en dólares")} className={inputCls} inputMode="decimal" value={cost} onChange={(e) => setCost(e.target.value)} placeholder="38.90" /></Field>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Field label={tr("Supplier", "Fornecedor", "Proveedor")}><input aria-label={tr("Supplier", "Fornecedor", "Proveedor")} autoComplete="organization" className={inputCls} value={supplier} onChange={(e) => setSupplier(e.target.value)} placeholder={tr("Store / supplier", "Loja / fornecedor", "Tienda / proveedor")} /></Field>
          <Field label={tr("Date", "Data", "Fecha")}><input aria-label={tr("Expense date", "Data da despesa", "Fecha del gasto")} type="date" className={inputCls} value={date} onChange={(e) => setDate(e.target.value)} /></Field>
        </div>
        <button className={`${btnNavy} w-full`} disabled={create.isPending || !projectId || !item.trim()}>{create.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Add expense", "Adicionar despesa", "Agregar gasto")}</button>
      </form>

      {q.isPending && <p className="py-6 text-center text-[var(--dim)]">{tr("Loading expenses…", "Carregando as despesas…", "Cargando los gastos…")}</p>}
      {q.data && q.data.expenses.length === 0 && <p className="py-4 text-center text-sm text-[var(--dim)]">{tr("No expenses recorded in this company yet.", "Nenhuma despesa registrada nesta empresa ainda.", "Todavía no hay gastos registrados en esta empresa.")}</p>}
      <div className="space-y-2">
        {(q.data?.expenses ?? []).map((e) => (
          <div key={e.id} className="flex items-center justify-between rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-3.5">
            <div className="min-w-0">
              <p className="truncate font-semibold">{e.item}</p>
              <p className="text-xs text-[var(--dim)]">{e.projectName} • {e.quantity} × {fmtUSD(e.unitCost)}{e.supplier ? ` • ${e.supplier}` : ""} • {fmtDate(e.expenseDate)}</p>
              {e.billedInvoiceId !== null && (
                <p className="mt-1 flex flex-wrap items-center gap-2">
                  <Badge text={tr(`Billed • Invoice #${e.billedInvoiceNumber || e.billedInvoiceId}`, `Faturado • Fatura nº ${e.billedInvoiceNumber || e.billedInvoiceId}`, `Facturado • Factura n.º ${e.billedInvoiceNumber || e.billedInvoiceId}`)} tone="navy" />
                  {isManagerUser && (unmarkId === e.id ? (
                    <span className="flex items-center gap-2">
                      <span className="text-[11px] font-bold text-red-600" role="alert">{tr("Unbill and remove its line from the invoice?", "Desfazer a cobrança e remover a linha da fatura?", "¿Quitar la facturación y eliminar su línea de la factura?")}</span>
                      <button type="button" aria-label={tr(`Confirm unbilling ${e.item}`, `Confirmar a remoção da cobrança de ${e.item}`, `Confirmar quitar la facturación de ${e.item}`)} disabled={unmark.isPending} onClick={() => unmark.mutate(e.id)} className="text-[11px] font-bold text-red-600">{tr("Unbill", "Desfazer cobrança", "Quitar facturación")}</button>
                      <button type="button" aria-label={tr("Cancel unbilling", "Cancelar a remoção da cobrança", "Cancelar quitar la facturación")} onClick={() => setUnmarkId(null)} className="text-[11px] font-bold text-[var(--dim)]">{tr("Keep", "Manter", "Conservar")}</button>
                    </span>
                  ) : (
                    <button type="button" aria-label={tr(`Unbill ${e.item} from its invoice`, `Remover a cobrança de ${e.item} da fatura`, `Quitar la facturación de ${e.item} de su factura`)} onClick={() => setUnmarkId(e.id)} className="text-[11px] font-bold text-[#f97316]">{tr("Unbill", "Desfazer cobrança", "Quitar facturación")}</button>
                  ))}
                </p>
              )}
            </div>
            <p className="shrink-0 font-bold">{fmtUSD(e.total)}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ---------------- Costs ---------------- */
function CostsView({ cid, session }: { cid: string; session: Session }) {
  const q = useQuery({ queryKey: ["costs", cid], queryFn: () => api.getCosts({ companyId: cid, actorId: session.id }) });
  const [mode, setMode] = useState<"project" | "general">("general");

  const CostCard = ({ label, cents, color }: { label: string; cents: number; color: string }) => (
    <div className="rounded-xl bg-[var(--surface2)] p-3">
      <p className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{label}</p>
      <p className={`text-xl font-black ${color}`}>{fmtUSD(cents)}</p>
    </div>
  );

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between print:hidden">
        <h2 className="text-lg font-black">📊 {tr("Costs", "Custos", "Costos")}</h2>
        <div className="flex items-center gap-2">
          <button type="button" className={btnGhost} onClick={() => window.print()} aria-label={tr("Print or save as PDF", "Imprimir ou salvar como PDF", "Imprimir o guardar como PDF")}>🖨️ {tr("Print / PDF", "Imprimir / PDF", "Imprimir / PDF")}</button>
          <div className="flex gap-1 rounded-xl bg-[var(--surface2)] p-1">
            <button type="button" className={`rounded-lg px-3 py-1.5 text-sm font-bold ${mode === "general" ? "bg-[#0f2a44] text-white" : ""}`}
              onClick={() => setMode("general")}>{tr("General", "Geral", "General")}</button>
            <button type="button" className={`rounded-lg px-3 py-1.5 text-sm font-bold ${mode === "project" ? "bg-[#0f2a44] text-white" : ""}`}
              onClick={() => setMode("project")}>{tr("Per project", "Por obra", "Por obra")}</button>
          </div>
        </div>
      </div>
      <div className="hidden print:block">
        <h2 className="text-lg font-black">📊 {tr("Costs", "Custos", "Costos")} — {mode === "general" ? tr("General", "Geral", "General") : tr("Per project", "Por obra", "Por obra")}</h2>
        <p className="text-sm text-gray-600">{session.companyName} • {new Date().toLocaleDateString()}</p>
      </div>

      {q.isPending ? <p className="py-10 text-center text-sm text-[var(--dim)]">{tr("Loading…", "Carregando…", "Cargando…")}</p> : q.isError ? (
        <p className="py-10 text-center text-sm font-semibold text-red-600">{tr("Could not load costs.", "Não foi possível carregar os custos.", "No se pudieron cargar los costos.")}</p>
      ) : mode === "general" ? (
        <div className="space-y-3">
          <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
            <p className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Total costs", "Custos totais", "Costos totales")}</p>
            <p className="text-3xl font-black">{fmtUSD(q.data.general.totalCents)}</p>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <CostCard label={tr("Labor", "Mão de obra", "Mano de obra")} cents={q.data.general.laborCents} color="text-blue-700" />
            <CostCard label={tr("Materials", "Materiais", "Materiales")} cents={q.data.general.materialsCents} color="text-amber-700" />
            <CostCard label={tr("Fleet", "Frota", "Flota")} cents={q.data.general.fleetCents} color="text-green-700" />
          </div>
          <p className="text-xs text-[var(--dim)]">{tr("Labor from approved timesheets. Materials from expenses. Fleet from fuel, maintenance and tickets.", "Mão de obra dos timesheets aprovados. Materiais das despesas. Frota de combustível, manutenção e multas.", "Mano de obra de las horas aprobadas. Materiales de los gastos. Flota de combustible, mantenimiento y multas.")}</p>
        </div>
      ) : (
        <div className="space-y-3">
          {q.data.perProject.length === 0 && <p className="py-10 text-center text-sm text-[var(--dim)]">{tr("No projects yet.", "Nenhuma obra ainda.", "Aún no hay obras.")}</p>}
          {q.data.perProject.map((p) => (
            <div key={p.projectId} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
              <div className="flex items-center justify-between">
                <p className="font-bold">{p.projectName}</p>
                <p className="text-lg font-black">{fmtUSD(p.totalCents)}</p>
              </div>
              <div className="mt-2 grid grid-cols-3 gap-2 text-sm">
                <div><p className="text-xs text-[var(--dim)]">{tr("Labor", "Mão de obra", "Mano de obra")}</p><p className="font-semibold text-blue-700">{fmtUSD(p.laborCents)}</p></div>
                <div><p className="text-xs text-[var(--dim)]">{tr("Materials", "Materiais", "Materiales")}</p><p className="font-semibold text-amber-700">{fmtUSD(p.materialsCents)}</p></div>
                <div><p className="text-xs text-[var(--dim)]">{tr("Fleet", "Frota", "Flota")}</p><p className="font-semibold text-green-700">{fmtUSD(p.fleetCents)}</p></div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------------- Invoices ---------------- */
function dueFromTerms(issue: string, terms: string): string {
  const d = new Date(`${issue}T12:00:00`);
  if (terms === "NET 30") d.setDate(d.getDate() + 30);
  else if (terms === "NET 15") d.setDate(d.getDate() + 15);
  else if (terms === "Due on receipt") return issue;
  else return issue;
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function Invoices({ cid, session, selected, onSelect, prefill, onPrefillUsed }: { cid: string; session: Session; selected: number | null; onSelect: (id: number | null) => void; prefill?: { clientId: number | null; projectId: number | null } | null; onPrefillUsed?: () => void }) {
  const q = useQuery({ queryKey: ["invoices", cid], queryFn: () => api.listInvoices({ companyId: cid, actorId: session.userId }) });
  const clients = useQuery({ queryKey: ["clients", cid], queryFn: () => api.listClients({ companyId: cid }) });
  const projects = useQuery({ queryKey: ["projects", cid], queryFn: () => api.listProjects({ companyId: cid }) });
  const qc = useQueryClient();
  const [showForm, setShowForm] = useState(false);
  const [number, setNumber] = useState("");
  const [clientId, setClientId] = useState("");
  const [projectId, setProjectId] = useState("");
  const [issueDate, setIssueDate] = useState(todayInput());
  const [due, setDue] = useState(() => dueFromTerms(todayInput(), "NET 30"));
  const [terms, setTerms] = useState("NET 30");
  const [termsCustom, setTermsCustom] = useState("");
  const finalTerms = terms === "Custom" ? (termsCustom.trim() || "Custom") : terms;

  useEffect(() => {
    if (!prefill) return;
    if (prefill.clientId !== null) setClientId(String(prefill.clientId));
    if (prefill.projectId !== null) setProjectId(String(prefill.projectId));
    setShowForm(true);
    onPrefillUsed?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [prefill]);

  const suggest = useMutation({
    mutationFn: () => api.suggestInvoiceNumber({ companyId: cid, issueDate }),
    onSuccess: (r) => setNumber(r.number),
  });

  useEffect(() => { setDue(dueFromTerms(issueDate, terms)); }, [issueDate, terms]);

  // Line items drafted in the create form (pulled from the project estimate or typed as extra costs).
  const [lines, setLines] = useState<{ description: string; quantity: string; rate: string; expenseId?: number }[]>([]);
  const [pullMsg, setPullMsg] = useState("");
  const projDetail = useQuery({ queryKey: ["project-detail", cid, Number(projectId) || 0], queryFn: () => api.getProjectDetail({ companyId: cid, projectId: Number(projectId) }), enabled: !!projectId });
  const projMaterials = useQuery({ queryKey: ["project-materials", cid, Number(projectId) || 0], queryFn: () => api.listProjectMaterials({ companyId: cid, projectId: Number(projectId) }), enabled: !!projectId });
  const updateLine = (i: number, patch: { description?: string; quantity?: string; rate?: string }) => setLines((ls) => ls.map((l, j) => (j === i ? { ...l, ...patch } : l)));
  const linesTotal = lines.reduce((s, l) => s + Math.round((parseFloat(l.quantity.replace(",", ".")) || 0) * parseMoney(l.rate)), 0);
  const pullFromEstimate = () => {
    const d = projDetail.data;
    if (!d?.project) return;
    const allJobs = d.jobs ?? [];
    const withEst = allJobs.filter((j) => j.estimatedValue > 0);
    const withoutEst = allJobs.filter((j) => j.estimatedValue <= 0);
    if (withEst.length > 0) {
      // Line description comes from the job's linked catalog service when
      // there is one (falls back to the job name for custom jobs).
      setLines(withEst.map((j) => ({ description: j.serviceName || j.name, quantity: "1", rate: moneyInput(j.estimatedValue) })));
      const missing = withoutEst.length > 0 ? ` ${tr("No estimate yet on:", "Ainda sem estimativa:", "Todavía sin estimación:")} ${withoutEst.map((j) => j.name).join(", ")} — ${tr("open each job to set its own estimate.", "abra cada trabalho para definir a estimativa dele.", "abre cada trabajo para definir su estimación.")}` : "";
      setPullMsg(tr(`Pulled ${withEst.length} job estimate${withEst.length === 1 ? "" : "s"} from ${d.project.name}. Edit or remove any line, or add extra costs below.`, `Puxou ${withEst.length} estimativa(s) de trabalho de ${d.project.name}. Edite ou remova qualquer linha, ou adicione custos extras abaixo.`, `Se trajeron ${withEst.length} estimación(es) de trabajo de ${d.project.name}. Edita o elimina cualquier línea, o agrega costos extra abajo.`) + missing);
      return;
    }
    if (d.project.estimatedValue > 0) {
      setLines([{ description: `${d.project.name} — ${tr("Contract price", "Preço do contrato", "Precio del contrato")}`, quantity: "1", rate: moneyInput(d.project.estimatedValue) }]);
      setPullMsg(tr(`No per-job estimates on ${d.project.name} — pulled the project contract price instead.`, `Sem estimativas por trabalho em ${d.project.name} — puxou o preço do contrato da obra.`, `No hay estimaciones por trabajo en ${d.project.name}: se trajo el precio del contrato de la obra.`));
      return;
    }
    setLines([]);
    setPullMsg(tr(`No estimate set on ${d.project.name} yet. Set job estimates or the project contract price on the project first — or type extra cost lines below.`, `Nenhuma estimativa definida em ${d.project.name} ainda. Defina as estimativas dos trabalhos ou o preço do contrato na obra primeiro — ou digite linhas de custo extra abaixo.`, `Todavía no hay estimación definida en ${d.project.name}. Primero define las estimaciones de los trabajos o el precio del contrato en la obra, o escribe líneas de costo extra abajo.`));
  };
  /* Pull the project's unbilled materials/expenses as line items. They are
     marked Billed on this invoice when it's created, so the same material
     can never be pulled (and charged) twice. */
  const pullMaterials = () => {
    const mats = (projMaterials.data?.materials ?? []).filter((m) => m.billedInvoiceId === null);
    if (mats.length === 0) {
      setPullMsg(tr("No unbilled materials on this project — everything logged is already billed, or nothing was logged yet in Expenses.", "Nenhum material não faturado nesta obra — tudo o que foi registrado já foi faturado, ou nada foi registrado ainda em Despesas.", "No hay materiales sin facturar en esta obra: todo lo registrado ya está facturado, o todavía no se registró nada en Gastos."));
      return;
    }
    setLines((ls) => [
      ...ls.filter((l) => !l.expenseId),
      ...mats.map((m) => ({ description: `${tr("Material:", "Material:", "Material:")} ${m.item}`, quantity: String(m.quantity), rate: moneyInput(m.unitCost), expenseId: m.id })),
    ]);
    setPullMsg(tr(`Pulled ${mats.length} material${mats.length === 1 ? "" : "s"} (${fmtUSD(mats.reduce((s, m) => s + m.total, 0))}). Edit any line before creating — on Create they'll be marked Billed on this invoice so they can't be charged twice.`, `Puxou ${mats.length} material(is) (${fmtUSD(mats.reduce((s, m) => s + m.total, 0))}). Edite qualquer linha antes de criar — ao Criar, eles serão marcados como Faturado nesta fatura para não serem cobrados duas vezes.`, `Se trajeron ${mats.length} material(es) (${fmtUSD(mats.reduce((s, m) => s + m.total, 0))}). Edita cualquier línea antes de crear: al Crear se marcarán como Facturado en esta factura para que no se cobren dos veces.`));
  };

  const create = useMutation({
    mutationFn: async () => {
      const r = await api.createInvoice({ companyId: cid, actorId: session.userId, number: number || `INV-${Date.now().toString().slice(-6)}`, clientId: clientId ? Number(clientId) : null, projectId: projectId ? Number(projectId) : null, issueDate, dueDate: due, terms: finalTerms });
      const expenseIds = lines.map((l) => l.expenseId).filter((x): x is number => x !== undefined);
      if (expenseIds.length > 0) {
        await api.markExpensesBilled({ companyId: cid, actorId: session.userId, invoiceId: r.id, expenseIds });
      }
      for (const l of lines) {
        if (!l.description.trim()) continue;
        await api.addInvoiceItem({ companyId: cid, actorId: session.userId, invoiceId: r.id, description: l.description.trim(), quantity: parseFloat(l.quantity.replace(",", ".")) || 1, unitPrice: parseMoney(l.rate), expenseId: l.expenseId ?? null });
      }
      return r;
    },
    onSuccess: (r) => { qc.invalidateQueries({ queryKey: ["invoices", cid] }); qc.invalidateQueries({ queryKey: ["expenses", cid] }); qc.invalidateQueries({ queryKey: ["project-materials", cid] }); setShowForm(false); setNumber(""); setLines([]); setPullMsg(""); onSelect(r.id); },
  });
  const billToClient = (clients.data?.clients ?? []).find((c) => String(c.id) === clientId);
  const refProject = (projects.data?.projects ?? []).find((p) => String(p.id) === projectId);

  if (selected !== null) return <InvoiceDetail cid={cid} invoiceId={selected} session={session} onBack={() => onSelect(null)} />;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold">{tr("Invoices", "Faturas", "Facturas")}</h2>
        {(session.role === "admin" || session.role === "gerente") && <button className={btnPrimary} onClick={() => setShowForm((s) => !s)} aria-label={tr("New invoice", "Nova fatura", "Nueva factura")}>{showForm ? tr("Close", "Fechar", "Cerrar") : tr("+ New invoice", "+ Nova fatura", "+ Nueva factura")}</button>}
      </div>
      {showForm && (
        <form className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" onSubmit={(e) => { e.preventDefault(); create.mutate(); }}>
          <div className="grid grid-cols-2 gap-3">
            <Field label={tr("Invoice #", "Fatura nº", "Factura n.º")}>
              <div className="flex gap-2">
                <input aria-label={tr("Invoice number", "Número da fatura", "Número de la factura")} autoComplete="off" className={inputCls} value={number} onChange={(e) => setNumber(e.target.value)} placeholder="0708-24" />
                <button type="button" className={btnGhost} onClick={() => suggest.mutate()} disabled={suggest.isPending} aria-label={tr("Suggest invoice number", "Sugerir o número da fatura", "Sugerir el número de la factura")}>{suggest.isPending ? "…" : tr("Suggest", "Sugerir", "Sugerir")}</button>
              </div>
            </Field>
            <Field label={tr("Terms", "Condições", "Condiciones")}>
              <select aria-label={tr("Invoice terms", "Condições da fatura", "Condiciones de la factura")} className={inputCls} value={terms} onChange={(e) => setTerms(e.target.value)}>
                <option>NET 30</option><option>NET 15</option><option value="Due on receipt">{tr("Due on receipt", "Vencimento na entrega", "Vence al recibir")}</option><option value="Custom">{tr("Custom", "Personalizado", "Personalizado")}</option>
              </select>
            </Field>
          </div>
          {terms === "Custom" && <Field label={tr("Custom terms", "Condições personalizadas", "Condiciones personalizadas")}><input aria-label={tr("Custom terms", "Condições personalizadas", "Condiciones personalizadas")} className={inputCls} value={termsCustom} onChange={(e) => setTermsCustom(e.target.value)} placeholder={tr("e.g. NET 45", "ex.: NET 45", "ej.: NET 45")} /></Field>}
          <Field label={tr("Client — Bill to", "Cliente — Cobrar de", "Cliente: facturar a")}>
            <select aria-label={tr("Invoice client", "Cliente da fatura", "Cliente de la factura")} className={inputCls} value={clientId} onChange={(e) => setClientId(e.target.value)}>
              <option value="">{tr("Select…", "Selecionar…", "Seleccionar…")}</option>
              {(clients.data?.clients ?? []).map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </Field>
          {billToClient && (
            <div className="rounded-xl bg-[var(--surface2)] px-3 py-2.5" aria-label={tr("Bill-to preview", "Pré-visualização da cobrança", "Vista previa de facturación")}>
              <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("Bill to (auto-filled from the client record)", "Cobrar de (preenchido automaticamente do cadastro do cliente)", "Facturar a (completado automáticamente desde el registro del cliente)")}</p>
              <p className="mt-1 text-sm font-semibold">{billToClient.name}{billToClient.phone ? ` (${billToClient.phone})` : ""}</p>
              {billToClient.address && <p className="text-sm text-[var(--dim)]">{billToClient.address}</p>}
              {(billToClient.email || billToClient.email2) && <p className="text-sm text-[var(--dim)]">{[billToClient.email, billToClient.email2].filter(Boolean).join(" • ")}</p>}
            </div>
          )}
          <Field label={tr("Project — Ref. (job-site address)", "Obra — Ref. (endereço da obra)", "Obra: ref. (dirección de la obra)")}>
            <select aria-label={tr("Invoice project", "Obra da fatura", "Obra de la factura")} className={inputCls} value={projectId} onChange={(e) => { const v = e.target.value; setProjectId(v); const proj = (projects.data?.projects ?? []).find((p) => String(p.id) === v); if (proj?.clientId) setClientId(String(proj.clientId)); }}>
              <option value="">{tr("Select…", "Selecionar…", "Seleccionar…")}</option>
              {(projects.data?.projects ?? []).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </Field>
          {refProject && <p className="rounded-xl bg-[var(--surface2)] px-3 py-2 text-sm text-[var(--dim)]" aria-label={tr("Reference job site address", "Endereço de referência da obra", "Dirección de referencia de la obra")}>{tr("Ref.:", "Ref.:", "Ref.:")} {refProject.address || refProject.name}</p>}
          <div className="grid grid-cols-2 gap-3">
            <Field label={tr("Invoice date", "Data da fatura", "Fecha de la factura")}><input aria-label={tr("Invoice date", "Data da fatura", "Fecha de la factura")} type="date" className={inputCls} value={issueDate} onChange={(e) => setIssueDate(e.target.value)} /></Field>
            <Field label={tr("Due date", "Data de vencimento", "Fecha de vencimiento")}><input aria-label={tr("Due date", "Data de vencimento", "Fecha de vencimiento")} type="date" className={inputCls} value={due} onChange={(e) => setDue(e.target.value)} /></Field>
          </div>
          <div className="space-y-2" aria-label={tr("Invoice line items", "Itens da fatura", "Conceptos de la factura")}>
            <div className="flex items-center justify-between gap-2">
              <p className="text-sm font-bold">{tr("Line items", "Itens da fatura", "Conceptos")} <span className="font-normal text-[var(--dim)]">{tr("(optional)", "(opcional)", "(opcional)")}</span></p>
              {projectId && <span className="flex gap-2"><button type="button" className={btnGhost} onClick={pullFromEstimate} disabled={projDetail.isPending} aria-label={tr("Pull line items from the project estimate", "Puxar os itens da estimativa da obra", "Traer los conceptos de la estimación de la obra")}>{tr("Pull from estimate", "Puxar da estimativa", "Traer de la estimación")}</button><button type="button" className={btnGhost} onClick={pullMaterials} disabled={projMaterials.isPending} aria-label={tr("Pull unbilled project materials into this invoice", "Puxar os materiais não faturados da obra para esta fatura", "Traer los materiales no facturados de la obra a esta factura")}>{tr("Pull materials", "Puxar materiais", "Traer materiales")}</button></span>}
            </div>
            {!projectId && <p className="text-xs text-[var(--dim)]">{tr("Pick a project above to pull its estimate into line items — or add extra cost lines below.", "Escolha uma obra acima para puxar a estimativa dela para os itens — ou adicione linhas de custo extra abaixo.", "Elige una obra arriba para traer su estimación a los conceptos, o agrega líneas de costo extra abajo.")}</p>}
            {pullMsg && <p className="rounded-lg bg-green-100 px-2.5 py-2 text-xs font-bold text-green-800" role="status">{pullMsg}</p>}
            {lines.map((l, i) => {
              const amt = Math.round((parseFloat(l.quantity.replace(",", ".")) || 0) * parseMoney(l.rate));
              return (
                <div key={i} className="space-y-2 rounded-xl bg-[var(--surface2)] p-2.5">
                  <div className="flex gap-2">
                    <input aria-label={tr(`Line ${i + 1} description`, `Descrição da linha ${i + 1}`, `Descripción de la línea ${i + 1}`)} autoComplete="off" className={`${inputCls} min-w-0 flex-1`} value={l.description} onChange={(e) => updateLine(i, { description: e.target.value })} placeholder={tr("Description — e.g. Roof replacement", "Descrição — ex.: Troca do telhado", "Descripción — ej.: Reemplazo del techo")} />
                    <button type="button" className={btnGhost} onClick={() => setLines((ls) => ls.filter((_, j) => j !== i))} aria-label={tr(`Remove line ${i + 1}`, `Remover a linha ${i + 1}`, `Quitar la línea ${i + 1}`)}>{tr("Remove", "Remover", "Quitar")}</button>
                  </div>
                  {l.expenseId !== undefined && <p className="text-[11px] font-bold text-[#0f2a44] dark:text-orange-300">{tr("🧾 From Materials — will be marked Billed on this invoice", "🧾 De Materiais — será marcado como Faturado nesta fatura", "🧾 De Materiales: se marcará como Facturado en esta factura")}</p>}
                  <div className="grid grid-cols-3 gap-2">
                    <input aria-label={tr(`Line ${i + 1} quantity`, `Quantidade da linha ${i + 1}`, `Cantidad de la línea ${i + 1}`)} className={inputCls} inputMode="decimal" value={l.quantity} onChange={(e) => updateLine(i, { quantity: e.target.value })} placeholder={tr("Quantity", "Quantidade", "Cantidad")} />
                    <input aria-label={tr(`Line ${i + 1} rate in US dollars`, `Preço unitário da linha ${i + 1} em dólares`, `Precio unitario de la línea ${i + 1} en dólares`)} className={inputCls} inputMode="decimal" value={l.rate} onChange={(e) => updateLine(i, { rate: e.target.value })} placeholder={tr("Rate $", "Preço $", "Precio $")} />
                    <div className="flex items-center justify-end rounded-xl bg-[var(--surface)] px-3 text-sm font-bold" aria-label={tr(`Line ${i + 1} amount`, `Valor da linha ${i + 1}`, `Importe de la línea ${i + 1}`)}>{fmtUSD(amt)}</div>
                  </div>
                </div>
              );
            })}
            <button type="button" className={btnGhost} onClick={() => setLines((ls) => [...ls, { description: "", quantity: "1", rate: "" }])} aria-label={tr("Add an extra cost line", "Adicionar uma linha de custo extra", "Agregar una línea de costo extra")}>{tr("+ Add extra cost", "+ Adicionar custo extra", "+ Agregar costo extra")}</button>
            {lines.length > 0 && (
              <div className="flex items-center justify-between border-t border-[var(--border)] pt-2 text-sm"><span className="text-[var(--dim)]">{tr("Subtotal", "Subtotal", "Subtotal")}</span><span className="font-bold">{fmtUSD(linesTotal)}</span></div>
            )}
            <p className="text-xs text-[var(--dim)]">{tr("Amount is calculated automatically. You can also add or change items later on the invoice. Balance Due = Total − Paid.", "O valor é calculado automaticamente. Você também pode adicionar ou alterar itens depois na fatura. Saldo a pagar = Total − Pago.", "El importe se calcula automáticamente. También puedes agregar o cambiar conceptos después en la factura. Saldo por pagar = Total − Pagado.")}</p>
          </div>
          <button className={`${btnNavy} w-full`} disabled={create.isPending}>{create.isPending ? tr("Creating…", "Criando…", "Creando…") : tr("Create invoice", "Criar fatura", "Crear factura")}</button>
        </form>
      )}
      {q.isPending && <p className="py-8 text-center text-[var(--dim)]">{tr("Loading invoices…", "Carregando faturas…", "Cargando facturas…")}</p>}
      {q.data && q.data.invoices.length === 0 && <div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center"><p className="font-semibold">{tr("No invoices in this company yet", "Nenhuma fatura nesta empresa ainda", "Todavía no hay facturas en esta empresa")}</p><p className="mt-1 text-sm text-[var(--dim)]">{tr("Create the first invoice to start billing.", "Crie a primeira fatura para começar a cobrar.", "Crea la primera factura para empezar a cobrar.")}</p></div>}
      <div className="space-y-3">
        {(q.data?.invoices ?? []).map((inv) => (
          <button key={inv.id} onClick={() => onSelect(inv.id)} aria-label={tr(`Open invoice ${inv.number}`, `Abrir a fatura ${inv.number}`, `Abrir la factura ${inv.number}`)} className="w-full rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left active:opacity-80">
            <div className="flex items-center justify-between">
              <p className="font-bold">{inv.number}</p>
              {invBadge(inv.status)}
            </div>
            <p className="mt-1 text-sm text-[var(--dim)]">{inv.clientName || tr("No client", "Sem cliente", "Sin cliente")}{inv.projectName ? ` • ${inv.projectName}` : ""}</p>
            <p className="text-xs text-[var(--dim)]">{tr("Issued", "Emitida em", "Emitida el")} {fmtDate(inv.issueDate)} • {tr("Due", "Vence em", "Vence el")} {fmtDate(inv.dueDate)} • {inv.terms}</p>
            <div className="mt-3 grid grid-cols-3 gap-2 text-center text-sm">
              <div className="rounded-lg bg-[var(--surface2)] py-2"><p className="text-xs text-[var(--dim)]">{tr("Total", "Total", "Total")}</p><p className="font-bold">{fmtUSD(inv.total)}</p></div>
              <div className="rounded-lg bg-[var(--surface2)] py-2"><p className="text-xs text-[var(--dim)]">{tr("Paid", "Pago", "Pagado")}</p><p className="font-bold text-green-700">{fmtUSD(inv.paid)}</p></div>
              <div className="rounded-lg bg-[var(--surface2)] py-2"><p className="text-xs text-[var(--dim)]">{tr("Balance Due", "Saldo a pagar", "Saldo por pagar")}</p><p className="font-bold">{fmtUSD(inv.balance)}</p></div>
            </div>
            {inv.total > 0 && <div className="mt-2 h-2 overflow-hidden rounded-full bg-[var(--surface2)]"><div className="h-full rounded-full bg-green-600" style={{ width: `${Math.min(100, (inv.paid / inv.total) * 100)}%` }} /></div>}
          </button>
        ))}
      </div>
    </div>
  );
}

function InvoiceDetail({ cid, invoiceId, session, onBack }: { cid: string; invoiceId: number; session: Session; onBack: () => void }) {
  const q = useQuery({ queryKey: ["invoice-detail", cid, invoiceId], queryFn: () => api.getInvoiceDetail({ companyId: cid, actorId: session.userId, invoiceId }) });
  const clientsQ = useQuery({ queryKey: ["clients", cid], queryFn: () => api.listClients({ companyId: cid }) });
  const projectsQ = useQuery({ queryKey: ["projects", cid], queryFn: () => api.listProjects({ companyId: cid }) });
  const qc = useQueryClient();
  const [desc, setDesc] = useState("");
  const [qty, setQty] = useState("1");
  const [price, setPrice] = useState("");
  const [showPay, setShowPay] = useState(false);
  const [payAmt, setPayAmt] = useState("");
  const [payDate, setPayDate] = useState(todayInput());
  const [payMethod, setPayMethod] = useState("Check");
  const [payNotes, setPayNotes] = useState("");
  const [showEdit, setShowEdit] = useState(false);
  const [eNumber, setENumber] = useState("");
  const [eClientId, setEClientId] = useState("");
  const [eProjectId, setEProjectId] = useState("");
  const [eIssue, setEIssue] = useState("");
  const [eDue, setEDue] = useState("");
  const [eTerms, setETerms] = useState("NET 30");
  const [eTermsCustom, setETermsCustom] = useState("");
  const [shareMsg, setShareMsg] = useState("");
  const [editMsg, setEditMsg] = useState("");
  const [itemMsg, setItemMsg] = useState("");
  const [payMsg, setPayMsg] = useState("");
  const editFormRef = useRef<HTMLFormElement | null>(null);
  /* The edit form renders below the invoice sheet; bring it into view so
     tapping "Edit invoice" visibly does something on a phone. */
  useEffect(() => {
    if (showEdit) editFormRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, [showEdit]);

  const invalidate = () => { qc.invalidateQueries({ queryKey: ["invoice-detail", cid, invoiceId] }); qc.invalidateQueries({ queryKey: ["invoices", cid] }); qc.invalidateQueries({ queryKey: ["dashboard", cid] }); qc.invalidateQueries({ queryKey: ["clients", cid] }); };
  const addItem = useMutation({
    mutationFn: () => api.addInvoiceItem({ companyId: cid, actorId: session.userId, invoiceId, description: desc, quantity: parseFloat(qty.replace(",", ".")) || 1, unitPrice: parseMoney(price) }),
    onSuccess: () => { invalidate(); setDesc(""); setPrice(""); setQty("1"); setItemMsg(tr("Item added. ✅", "Item adicionado. ✅", "Concepto agregado. ✅")); },
    onError: () => setItemMsg(tr("Could not add this item. Please try again.", "Não foi possível adicionar este item. Tente novamente.", "No se pudo agregar este concepto. Inténtalo de nuevo.")),
  });
  const addPay = useMutation({
    mutationFn: () => api.addInvoicePayment({ companyId: cid, invoiceId, actorId: session.userId, amount: parseMoney(payAmt), payDate, method: payMethod, notes: payNotes }),
    onSuccess: () => { invalidate(); setPayAmt(""); setPayNotes(""); setShowPay(false); setPayMsg(""); setShareMsg(tr("Payment recorded. Paid and Balance Due are up to date. ✅", "Pagamento registrado. Pago e Saldo a pagar estão atualizados. ✅", "Pago registrado. Pagado y Saldo por pagar están actualizados. ✅")); },
    onError: () => setPayMsg(tr("Could not record this payment. Please try again.", "Não foi possível registrar este pagamento. Tente novamente.", "No se pudo registrar este pago. Inténtalo de nuevo.")),
  });
  const saveEdit = useMutation({
    mutationFn: () => api.updateInvoice({ companyId: cid, invoiceId, actorId: session.userId, number: eNumber, clientId: eClientId ? Number(eClientId) : null, projectId: eProjectId ? Number(eProjectId) : null, issueDate: eIssue, dueDate: eDue, terms: eTerms === "Custom" ? (eTermsCustom.trim() || "Custom") : eTerms }),
    onSuccess: () => { invalidate(); setShowEdit(false); setEditMsg(""); setShareMsg(tr("Invoice saved. ✅", "Fatura salva. ✅", "Factura guardada. ✅")); },
    onError: () => setEditMsg(tr("Could not save this invoice. Only an admin or manager can edit invoices — please try again.", "Não foi possível salvar esta fatura. Somente um administrador ou gerente pode editar faturas — tente novamente.", "No se pudo guardar esta factura. Solo un administrador o gerente puede editar facturas: inténtalo de nuevo.")),
  });

  if (q.isPending) return <p className="py-10 text-center text-[var(--dim)]">{tr("Loading invoice…", "Carregando fatura…", "Cargando factura…")}</p>;
  if (!q.data?.invoice) return <div className="py-10 text-center"><p>{tr("Invoice not found.", "Fatura não encontrada.", "Factura no encontrada.")}</p><button className={`${btnGhost} mt-3`} onClick={onBack}>{tr("Back", "Voltar", "Volver")}</button></div>;
  const inv = q.data.invoice;
  const billTo = q.data.billTo;
  const from = q.data.from;
  const isManagerUser = session.role === "admin" || session.role === "gerente";
  const lineAmount = (parseFloat(qty.replace(",", ".")) || 0) * (parseMoney(price) / 100);
  const rawAccent = from?.invoiceAccentColor ?? "#F97316";
  const accent = /^#[0-9a-fA-F]{6}$/.test(rawAccent) ? rawAccent : "#F97316";
  const accentTint = `${accent}14`;
  const accentTintStrong = `${accent}26`;
  const exactPrint = { WebkitPrintColorAdjust: "exact", printColorAdjust: "exact" } as const;

  const openEdit = () => {
    setENumber(inv.number); setEClientId(inv.clientId ? String(inv.clientId) : ""); setEProjectId(inv.projectId ? String(inv.projectId) : "");
    setEIssue(inv.issueDate); setEDue(inv.dueDate);
    if (["NET 30", "NET 15", "Due on receipt"].includes(inv.terms)) { setETerms(inv.terms); setETermsCustom(""); } else { setETerms("Custom"); setETermsCustom(inv.terms); }
    setEditMsg("");
    setShowEdit(true);
  };
  const openPay = () => { setPayAmt(q.data.balance > 0 ? moneyInput(q.data.balance) : ""); setPayDate(todayInput()); setShowPay(true); };

  /* Share / Send: build a real PDF of this invoice. Where the device
     supports sharing files, hand it to the share sheet; otherwise download
     the PDF and open the mail app with a prefilled message (the client
     attaches the downloaded file — one-tap background sending with the PDF
     attached needs a production email service). */
  /* Build the styled invoice PDF once; Share/Send and Save PDF both use it. */
  const buildInvoicePdf = async (): Promise<Blob | null> => {
    if (!q.data?.invoice) return null;
    const d = q.data;
    const statusLabelPdf = inv.status === "paga" ? tr("Paid", "Pago", "Pagado") : inv.status === "parcial" ? tr("Partial", "Parcial", "Parcial") : inv.status === "vencida" ? tr("Overdue", "Vencida", "Vencida") : tr("Open", "Aberta", "Abierta");
    try {
      return await makeStyledInvoicePdf({
        companyName: session.companyName,
        from: from ? { name: from.name, address: from.address, phone: from.phone, email: from.email, logoUrl: from.logoUrl } : null,
        billTo: billTo ? { name: billTo.name, contactName: billTo.contactName, phone: billTo.phone, email: billTo.email, email2: billTo.email2, address: billTo.address } : null,
        invoice: { number: inv.number, terms: inv.terms, issueDate: inv.issueDate, dueDate: inv.dueDate, projectAddress: inv.projectAddress, projectName: inv.projectName, status: inv.status, statusLabel: statusLabelPdf },
        items: d.items.map((i) => ({ description: i.description, quantity: i.quantity, unitPrice: i.unitPrice, total: i.total })),
        total: d.total,
        paid: d.paid,
        balance: d.balance,
        accentHex: accent,
        labels: {
          billTo: tr("Bill to:", "Cobrar de:", "Facturar a:"),
          invoiceNumber: tr("Invoice #", "Fatura nº", "Factura n.º"),
          terms: tr("Terms:", "Condições:", "Condiciones:"),
          invoiceDate: tr("Invoice Date:", "Data da fatura:", "Fecha de la factura:"),
          dueDate: tr("Due Date:", "Data de vencimento:", "Fecha de vencimiento:"),
          ref: "Ref.:",
          description: tr("Description", "Descrição", "Descripción"),
          quantity: tr("Quantity", "Quantidade", "Cantidad"),
          rate: tr("Rate", "Preço unitário", "Precio unitario"),
          amount: tr("Amount", "Valor", "Importe"),
          subtotal: tr("Subtotal", "Subtotal", "Subtotal"),
          total: tr("Total", "Total", "Total"),
          paid: tr("Paid", "Pago", "Pagado"),
          balanceDue: tr("Balance Due", "Saldo a pagar", "Saldo por pagar"),
          noClient: tr("No client linked.", "Nenhum cliente vinculado.", "Ningún cliente vinculado."),
          noItems: tr("No items yet.", "Nenhum item ainda.", "Todavía no hay conceptos."),
        },
        formatMoney: fmtUSD,
        formatDate: fmtDate,
      });
    } catch {
      setShareMsg(tr("Could not build the invoice PDF. Please try again.", "Não foi possível gerar o PDF da fatura. Tente novamente.", "No se pudo generar el PDF de la factura. Inténtalo de nuevo."));
      return null;
    }
  };

  /* Save the invoice as a PDF file on this device. The app shell can't
     print, so downloading the generated PDF is the working save path. */
  const downloadInvoicePdf = async () => {
    const pdf = await buildInvoicePdf();
    if (!pdf) return;
    downloadBlob(`Invoice-${inv.number.replace(/[^\w-]+/g, "_")}.pdf`, pdf);
    setShareMsg(tr("Invoice PDF downloaded. ✅", "PDF da fatura baixado. ✅", "PDF de la factura descargado. ✅"));
  };

  const shareInvoice = async () => {
    if (!q.data?.invoice) return;
    const d = q.data;
    const money = (c: number) => `$${(c / 100).toFixed(2)}`;
    const pdf = await buildInvoicePdf();
    if (!pdf) return;
    const fileName = `Invoice-${inv.number.replace(/[^\w-]+/g, "_")}.pdf`;
    const file = new File([pdf], fileName, { type: "application/pdf" });
    const nav = navigator as Navigator & { canShare?: (data: { files: File[] }) => boolean; share?: (data: { files?: File[]; title?: string; text?: string }) => Promise<void> };
    if (nav.share && nav.canShare && nav.canShare({ files: [file] })) {
      try {
        await nav.share({ files: [file], title: `Invoice #${inv.number}`, text: `${tr("Invoice", "Fatura", "Factura")} #${inv.number} ${tr("from", "de", "de")} ${from?.name || session.companyName} — ${tr("balance due", "saldo a pagar", "saldo por pagar")} ${money(d.balance)}.` });
        setShareMsg(tr("Share sheet opened with the invoice PDF. ✅", "A folha de compartilhamento foi aberta com o PDF da fatura. ✅", "Se abrió el menú para compartir con el PDF de la factura. ✅"));
      } catch {
        setShareMsg(tr("Sharing was canceled. You can download the PDF and email it instead.", "O compartilhamento foi cancelado. Você pode baixar o PDF e enviá-lo por e-mail.", "Se canceló compartir. Puedes descargar el PDF y enviarlo por correo."));
      }
      return;
    }
    downloadBlob(fileName, pdf);
    const emails = [billTo?.email, billTo?.email2].filter(Boolean).join(",");
    const subject = encodeURIComponent(`Invoice #${inv.number}`);
    const body = encodeURIComponent(`${tr("Hello", "Olá", "Hola")}${billTo?.contactName ? ` ${billTo.contactName}` : ""},\n\n${tr("Please find attached invoice", "Segue em anexo a fatura", "Se adjunta la factura")} #${inv.number} ${tr("from", "de", "de")} ${from?.name || session.companyName}.\n${tr("Balance due:", "Saldo a pagar:", "Saldo por pagar:")} ${money(d.balance)} (${tr("due", "vencimento", "vencimiento")} ${inv.dueDate}, ${tr("terms", "condições", "condiciones")} ${inv.terms}).\n\n${tr("Note: the PDF was just downloaded to this device — please attach it to this email before sending.", "Observação: o PDF acabou de ser baixado neste dispositivo — anexe-o a este e-mail antes de enviar.", "Nota: el PDF se acaba de descargar en este dispositivo: adjúntalo a este correo antes de enviarlo.")}\n\n${tr("Thank you!", "Obrigado!", "¡Gracias!")}`);
    window.location.href = `mailto:${emails}?subject=${subject}&body=${body}`;
    setShareMsg(tr("PDF downloaded and your email app opened with the message ready — attach the downloaded PDF before sending. (One-tap sending with the PDF already attached needs a production email service.)", "PDF baixado e seu app de e-mail aberto com a mensagem pronta — anexe o PDF baixado antes de enviar. (O envio com um toque e o PDF já anexado exige um serviço de e-mail de produção.)", "PDF descargado y tu app de correo abierta con el mensaje listo: adjunta el PDF descargado antes de enviar. (El envío con un toque y el PDF ya adjunto requiere un servicio de correo de producción.)"));
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between print:hidden">
        <button onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to invoices", "Voltar para faturas", "Volver a facturas")}>← {tr("Back to invoices", "Voltar para faturas", "Volver a facturas")}</button>
        <span className="flex gap-2">
          {isManagerUser && <button type="button" className={btnGhost} onClick={openEdit} aria-label={tr("Edit invoice", "Editar fatura", "Editar factura")}>{tr("Edit invoice", "Editar fatura", "Editar factura")}</button>}
          {isManagerUser && <button type="button" className={btnPrimary} onClick={() => void shareInvoice()} aria-label={tr("Share or send this invoice", "Compartilhar ou enviar esta fatura", "Compartir o enviar esta factura")}>{tr("Share / Send", "Compartilhar / Enviar", "Compartir / Enviar")}</button>}
          <button type="button" className={btnGhost} onClick={() => void downloadInvoicePdf()} aria-label={tr("Download this invoice as a PDF", "Baixar esta fatura como PDF", "Descargar esta factura como PDF")}>{tr("Save PDF", "Salvar PDF", "Guardar PDF")}</button>
        </span>
      </div>
      {shareMsg && <p className="rounded-xl bg-[var(--surface)] px-3 py-2 text-sm font-semibold print:hidden" role="status">{shareMsg}</p>}

      {/* Printable invoice — Giglio pattern, colorful */}
      <article
        className="invoice-sheet overflow-hidden rounded-2xl border-2 bg-white p-5 text-[#12222f] shadow-sm"
        style={{ borderColor: accent, ...exactPrint }}
        aria-label={tr(`Invoice ${inv.number}`, `Fatura ${inv.number}`, `Factura ${inv.number}`)}
      >
        <header
          className="rounded-xl px-4 py-4 text-white sm:px-5"
          style={{ backgroundColor: accent, color: "#ffffff", ...exactPrint }}
        >
          <div className="flex items-center gap-3">
            {from?.logoUrl ? (
              <img src={safeImgSrc(from.logoUrl)} alt={tr(`${from?.name || session.companyName} logo`, `Logo de ${from?.name || session.companyName}`, `Logotipo de ${from?.name || session.companyName}`)} className="h-12 w-auto max-w-[140px] shrink-0 rounded-md bg-white object-contain p-1" style={{ maxHeight: 48 }} />
            ) : null}
            <div className="min-w-0">
              <p className="truncate text-xl font-black uppercase leading-tight tracking-wide text-white">{from?.name || session.companyName}</p>
              {from?.address && <p className="mt-1 text-sm font-medium text-white/95">{from.address}</p>}
              {(from?.phone || from?.email) && <p className="text-sm text-white/85">{[from?.phone, from?.email].filter(Boolean).join(" • ")}</p>}
              {!from?.address && <p className="mt-1 text-xs text-white/85">{tr("Add your company address, phone, and email in Settings to complete this header.", "Adicione o endereço, telefone e e-mail da sua empresa em Configurações para completar este cabeçalho.", "Agrega la dirección, el teléfono y el correo de tu empresa en Configuración para completar este encabezado.")}</p>}
            </div>
          </div>
        </header>

        <div className="mt-5 grid gap-5 border-b-2 pb-4 sm:grid-cols-2" style={{ borderColor: accent }}>
          <section aria-label={tr("Bill to", "Cobrar de", "Facturar a")}>
            <p className="flex items-center gap-2 text-xs font-black uppercase tracking-wider" style={{ color: accent }}>
              <span aria-hidden="true" className="inline-block h-4 w-1 rounded-full" style={{ backgroundColor: accent, ...exactPrint }} />
              {tr("Bill to:", "Cobrar de:", "Facturar a:")}
            </p>
            {billTo ? (
              <div className="mt-2 space-y-0.5 text-[#12222f]">
                <p className="text-[15px] font-bold leading-snug">{billTo.name}{billTo.phone ? <span className="font-semibold text-[#334155]"> ({billTo.phone})</span> : ""}</p>
                {billTo.contactName && billTo.contactName !== billTo.name && <p className="text-sm text-[#334155]">{tr("Attn:", "A/C:", "Attn:")} {billTo.contactName}</p>}
                {billTo.address && <p className="text-sm leading-snug text-[#334155]">{billTo.address}</p>}
                {billTo.email && <p className="text-sm text-[#334155]">{billTo.email}</p>}
                {billTo.email2 && <p className="text-sm text-[#334155]">{billTo.email2}</p>}
              </div>
            ) : <p className="mt-2 text-sm text-[#5b6b7a]">{tr("No client linked.", "Nenhum cliente vinculado.", "Ningún cliente vinculado.")}</p>}
          </section>
          <section aria-label={tr("Invoice details", "Detalhes da fatura", "Detalles de la factura")} className="sm:text-right">
            <dl className="space-y-1.5 text-sm text-[#12222f]">
              <div className="flex justify-between gap-3 sm:justify-end"><dt className="font-bold text-[#334155]">{tr("Invoice #", "Fatura nº", "Factura n.º")}</dt><dd className="font-black" style={{ color: accent }}>{inv.number}</dd></div>
              <div className="flex justify-between gap-3 sm:justify-end"><dt className="font-bold text-[#334155]">{tr("Terms:", "Condições:", "Condiciones:")}</dt><dd className="font-semibold">{inv.terms}</dd></div>
              <div className="flex justify-between gap-3 sm:justify-end"><dt className="font-bold text-[#334155]">{tr("Invoice Date:", "Data da fatura:", "Fecha de la factura:")}</dt><dd className="font-medium">{fmtDate(inv.issueDate)}</dd></div>
              <div className="flex justify-between gap-3 sm:justify-end"><dt className="font-bold text-[#334155]">{tr("Due Date:", "Data de vencimento:", "Fecha de vencimiento:")}</dt><dd className="font-medium">{fmtDate(inv.dueDate)}</dd></div>
            </dl>
            <div className="mt-2.5">{invBadge(inv.status)}</div>
          </section>
        </div>
        {inv.projectAddress && (
          <p
            className="mt-4 rounded-lg px-3 py-2.5 text-sm text-[#12222f]"
            style={{ backgroundColor: accentTint, borderLeft: `4px solid ${accent}`, ...exactPrint }}
          >
            <span className="font-black" style={{ color: accent }}>Ref.:</span>{" "}
            <span className="font-medium">{inv.projectAddress}{inv.projectName ? ` — ${inv.projectName}` : ""}</span>
          </p>
        )}

        <div className="mt-5 overflow-x-auto rounded-xl border" style={{ borderColor: accentTintStrong }}>
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="text-xs uppercase tracking-wider text-white" style={{ backgroundColor: accent, color: "#ffffff", ...exactPrint }}>
                <th className="px-3 py-2.5 font-black">{tr("Description", "Descrição", "Descripción")}</th>
                <th className="px-2 py-2.5 text-right font-black">{tr("Quantity", "Quantidade", "Cantidad")}</th>
                <th className="px-2 py-2.5 text-right font-black">{tr("Rate", "Preço unitário", "Precio unitario")}</th>
                <th className="px-3 py-2.5 text-right font-black">{tr("Amount", "Valor", "Importe")}</th>
              </tr>
            </thead>
            <tbody>
              {q.data.items.map((i, idx) => (
                <tr
                  key={i.id}
                  className="border-b border-[#e2e8f0] text-[#12222f] last:border-b-0"
                  style={{ backgroundColor: idx % 2 === 1 ? "#f8fafc" : "#ffffff", ...exactPrint }}
                >
                  <td className="px-3 py-2.5 leading-snug">{i.description}</td>
                  <td className="px-2 py-2.5 text-right tabular-nums">{i.quantity}</td>
                  <td className="px-2 py-2.5 text-right tabular-nums">{fmtUSD(i.unitPrice)}</td>
                  <td className="px-3 py-2.5 text-right font-bold tabular-nums">{fmtUSD(i.total)}</td>
                </tr>
              ))}
              {q.data.items.length === 0 && <tr><td colSpan={4} className="px-3 py-5 text-center text-[#5b6b7a]">{tr("No items yet.", "Nenhum item ainda.", "Todavía no hay conceptos.")}</td></tr>}
            </tbody>
          </table>
        </div>

        <div className="mt-5 flex justify-end">
          <div className="w-full max-w-xs text-sm text-[#12222f]">
            <dl className="space-y-1.5">
              <div className="flex items-center justify-between px-1"><dt className="text-[#334155]">{tr("Subtotal", "Subtotal", "Subtotal")}</dt><dd className="font-medium tabular-nums">{fmtUSD(q.data.total)}</dd></div>
              <div className="flex items-center justify-between border-t-2 px-1 pt-2 font-bold" style={{ borderColor: accent }}><dt>{tr("Total", "Total", "Total")}</dt><dd className="tabular-nums">{fmtUSD(q.data.total)}</dd></div>
              <div className="flex items-center justify-between px-1 text-green-700"><dt>{tr("Paid", "Pago", "Pagado")}</dt><dd className="font-semibold tabular-nums">{fmtUSD(q.data.paid)}</dd></div>
            </dl>
            <div
              className="mt-3 flex items-center justify-between rounded-lg px-3 py-3 text-white shadow-sm"
              style={{ backgroundColor: accent, color: "#ffffff", ...exactPrint }}
              aria-label={tr(`Balance due ${fmtUSD(q.data.balance)}`, `Saldo a pagar de ${fmtUSD(q.data.balance)}`, `Saldo por pagar de ${fmtUSD(q.data.balance)}`)}
            >
              <span className="text-xs font-black uppercase tracking-wider text-white/95">{tr("Balance Due", "Saldo a pagar", "Saldo por pagar")}</span>
              <span className="text-lg font-black leading-none tabular-nums text-white">{fmtUSD(q.data.balance)}</span>
            </div>
          </div>
        </div>
      </article>

      {showEdit && isManagerUser && (
        <form ref={editFormRef} className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 print:hidden" onSubmit={(e) => { e.preventDefault(); saveEdit.mutate(); }} aria-label={tr("Edit invoice", "Editar fatura", "Editar factura")}>
          <p className="font-bold">{tr("Edit invoice", "Editar fatura", "Editar factura")}</p>
          <div className="grid grid-cols-2 gap-3">
            <Field label={tr("Invoice #", "Fatura nº", "Factura n.º")}><input aria-label={tr("Edit invoice number", "Editar o número da fatura", "Editar el número de la factura")} className={inputCls} value={eNumber} onChange={(e) => setENumber(e.target.value)} /></Field>
            <Field label={tr("Terms", "Condições", "Condiciones")}>
              <select aria-label={tr("Edit invoice terms", "Editar as condições da fatura", "Editar las condiciones de la factura")} className={inputCls} value={eTerms} onChange={(e) => setETerms(e.target.value)}><option>NET 30</option><option>NET 15</option><option value="Due on receipt">{tr("Due on receipt", "Vencimento na entrega", "Vence al recibir")}</option><option value="Custom">{tr("Custom", "Personalizado", "Personalizado")}</option></select>
            </Field>
          </div>
          {eTerms === "Custom" && <Field label={tr("Custom terms", "Condições personalizadas", "Condiciones personalizadas")}><input aria-label={tr("Edit custom terms", "Editar as condições personalizadas", "Editar las condiciones personalizadas")} className={inputCls} value={eTermsCustom} onChange={(e) => setETermsCustom(e.target.value)} /></Field>}
          <Field label={tr("Client — Bill to", "Cliente — Cobrar de", "Cliente: facturar a")}>
            <select aria-label={tr("Edit invoice client", "Editar o cliente da fatura", "Editar el cliente de la factura")} className={inputCls} value={eClientId} onChange={(e) => setEClientId(e.target.value)}><option value="">{tr("Select…", "Selecionar…", "Seleccionar…")}</option>{(clientsQ.data?.clients ?? []).map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
          </Field>
          <Field label={tr("Project — Ref.", "Obra — Ref.", "Obra: ref.")}>
            <select aria-label={tr("Edit invoice project", "Editar a obra da fatura", "Editar la obra de la factura")} className={inputCls} value={eProjectId} onChange={(e) => setEProjectId(e.target.value)}><option value="">{tr("Select…", "Selecionar…", "Seleccionar…")}</option>{(projectsQ.data?.projects ?? []).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select>
          </Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label={tr("Invoice date", "Data da fatura", "Fecha de la factura")}><input aria-label={tr("Edit invoice date", "Editar a data da fatura", "Editar la fecha de la factura")} type="date" className={inputCls} value={eIssue} onChange={(e) => setEIssue(e.target.value)} /></Field>
            <Field label={tr("Due date", "Data de vencimento", "Fecha de vencimiento")}><input aria-label={tr("Edit due date", "Editar a data de vencimento", "Editar la fecha de vencimiento")} type="date" className={inputCls} value={eDue} onChange={(e) => setEDue(e.target.value)} /></Field>
          </div>
          {editMsg && <p className="text-xs font-semibold text-red-600" role="alert">{editMsg}</p>}
          <div className="flex gap-2"><button type="button" className={btnGhost} onClick={() => setShowEdit(false)}>{tr("Cancel", "Cancelar", "Cancelar")}</button><button className={`${btnNavy} flex-1`} disabled={saveEdit.isPending}>{saveEdit.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save invoice", "Salvar fatura", "Guardar factura")}</button></div>
        </form>
      )}

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 print:hidden">
        <h3 className="font-bold">{tr("Line items", "Itens da fatura", "Conceptos")}</h3>
        <div className="mt-2 space-y-2">
          {q.data.items.map((i) => (
            <div key={i.id} className="flex justify-between rounded-xl bg-[var(--surface2)] px-3 py-2 text-sm"><span>{i.description} <span className="text-[var(--dim)]">({i.quantity} × {fmtUSD(i.unitPrice)})</span>{i.expenseId !== null && <span className="ml-1.5 rounded-full bg-[#0f2a44] px-1.5 py-0.5 text-[10px] font-bold text-white dark:bg-white dark:text-[#0f2a44]">{tr("Material • Billed", "Material • Faturado", "Material • Facturado")}</span>}</span><span className="font-bold">{fmtUSD(i.total)}</span></div>
          ))}
          {q.data.items.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No items yet.", "Nenhum item ainda.", "Todavía no hay conceptos.")}</p>}
        </div>
        {isManagerUser && (
          <form className="mt-3 space-y-2" onSubmit={(e) => { e.preventDefault(); addItem.mutate(); }}>
            <input aria-label={tr("Item description", "Descrição do item", "Descripción del concepto")} autoComplete="off" className={inputCls} value={desc} onChange={(e) => setDesc(e.target.value)} placeholder={tr("Description — e.g. Basement: Flooring installation", "Descrição — ex.: Porão: Instalação do piso", "Descripción — ej.: Sótano: Instalación del piso")} />
            <div className="grid grid-cols-3 gap-2">
              <input aria-label={tr("Item quantity", "Quantidade do item", "Cantidad del concepto")} className={inputCls} inputMode="decimal" value={qty} onChange={(e) => setQty(e.target.value)} placeholder={tr("Quantity", "Quantidade", "Cantidad")} />
              <input aria-label={tr("Unit price in US dollars", "Preço unitário em dólares", "Precio unitario en dólares")} className={inputCls} inputMode="decimal" value={price} onChange={(e) => setPrice(e.target.value)} placeholder={tr("Rate $", "Preço $", "Precio $")} />
              <div className="flex items-center justify-end rounded-xl bg-[var(--surface2)] px-3 text-sm font-bold" aria-label={tr("Line amount", "Valor da linha", "Importe de la línea")}>{fmtUSD(Math.round(lineAmount * 100))}</div>
            </div>
            <button className={`${btnNavy} w-full`} disabled={addItem.isPending || !desc.trim()}>{tr("Add item", "Adicionar item", "Agregar concepto")}</button>
          </form>
        )}
        {itemMsg && <p className="mt-2 text-xs font-semibold" role="status">{itemMsg}</p>}
      </section>

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 print:hidden" aria-label={tr("Payments", "Pagamentos", "Pagos")}>
        <div className="flex items-center justify-between gap-2">
          <h3 className="font-bold">{tr("Payments", "Pagamentos", "Pagos")}</h3>
          <span className="text-sm text-[var(--dim)]">{tr("Paid total:", "Total pago:", "Total pagado:")} <strong className="text-green-700">{fmtUSD(q.data.paid)}</strong> • {tr("Balance Due:", "Saldo a pagar:", "Saldo por pagar:")} <strong>{fmtUSD(q.data.balance)}</strong></span>
        </div>
        {isManagerUser && q.data.balance > 0 && (
          <button type="button" onClick={openPay} aria-label={tr("Record payment", "Registrar pagamento", "Registrar pago")} className="mt-3 w-full rounded-xl bg-green-600 px-4 py-3.5 text-base font-black text-white active:opacity-80">{tr("💵 Record payment", "💵 Registrar pagamento", "💵 Registrar pago")}</button>
        )}
        {isManagerUser && q.data.balance <= 0 && q.data.total > 0 && <p className="mt-3 rounded-xl bg-green-100 px-3 py-2 text-center text-sm font-bold text-green-800">{tr("Paid in full ✅", "Pago integralmente ✅", "Pagado en su totalidad ✅")}</p>}

        {showPay && isManagerUser && (
          <form className="mt-3 space-y-3 rounded-xl bg-[var(--surface2)] p-3" onSubmit={(e) => { e.preventDefault(); addPay.mutate(); }} aria-label={tr("Record payment form", "Formulário de registro de pagamento", "Formulario de registro de pago")}>
            <div className="grid grid-cols-2 gap-2">
              <Field label={tr("Amount (USD)", "Valor (USD)", "Importe (USD)")}><input aria-label={tr("Payment amount in US dollars", "Valor do pagamento em dólares", "Importe del pago en dólares")} className={inputCls} inputMode="decimal" value={payAmt} onChange={(e) => setPayAmt(e.target.value)} placeholder="0.00" /></Field>
              <Field label={tr("Date", "Data", "Fecha")}><input aria-label={tr("Payment date", "Data do pagamento", "Fecha de pago")} type="date" className={inputCls} value={payDate} onChange={(e) => setPayDate(e.target.value)} /></Field>
            </div>
            <Field label={tr("Method", "Método", "Método")}>
              <select aria-label={tr("Payment method", "Método de pagamento", "Método de pago")} className={inputCls} value={payMethod} onChange={(e) => setPayMethod(e.target.value)}>
                <option value="Check">{tr("Check", "Cheque", "Cheque")}</option><option value="Cash">{tr("Cash", "Dinheiro", "Efectivo")}</option><option value="Bank transfer">{tr("Bank transfer", "Transferência bancária", "Transferencia bancaria")}</option><option value="Other">{tr("Other", "Outro", "Otro")}</option>
              </select>
            </Field>
            <Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}><input aria-label={tr("Payment notes", "Observações do pagamento", "Notas del pago")} className={inputCls} value={payNotes} onChange={(e) => setPayNotes(e.target.value)} placeholder={tr("Check #, reference, etc.", "Nº do cheque, referência etc.", "N.º de cheque, referencia, etc.")} /></Field>
            <div className="flex gap-2">
              <button type="button" className={btnGhost} onClick={() => setPayAmt(moneyInput(q.data.balance))}>{tr("Use full balance", "Usar o saldo total", "Usar el saldo total")}</button>
              <button type="button" className={btnGhost} onClick={() => setShowPay(false)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
              <button className="flex-1 rounded-xl bg-green-600 px-4 py-2.5 font-bold text-white active:opacity-80" disabled={addPay.isPending || parseMoney(payAmt) <= 0}>{addPay.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save payment", "Salvar pagamento", "Guardar pago")}</button>
            </div>
            {payMsg && <p className="text-xs font-semibold text-red-600" role="alert">{payMsg}</p>}
            <p className="text-xs text-[var(--dim)]">{tr("Saving updates Paid and Balance Due automatically — Partial when some is paid, Paid when the balance reaches $0.", "Salvar atualiza Pago e Saldo a pagar automaticamente — Parcial quando parte é paga, Pago quando o saldo chega a $0.", "Guardar actualiza Pagado y Saldo por pagar automáticamente: Parcial cuando se paga una parte, Pagado cuando el saldo llega a $0.")}</p>
          </form>
        )}

        <div className="mt-3 space-y-2">
          {q.data.payments.map((p) => (
            <div key={p.id} className="rounded-xl bg-[var(--surface2)] px-3 py-2 text-sm">
              <div className="flex justify-between gap-2"><span>{fmtDate(p.payDate)} • {p.method}</span><span className="font-bold text-green-700">{fmtUSD(p.amount)}</span></div>
              {p.notes && <p className="mt-0.5 text-xs text-[var(--dim)]">{p.notes}</p>}
            </div>
          ))}
          {q.data.payments.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No payments recorded yet.", "Nenhum pagamento registrado ainda.", "Todavía no hay pagos registrados.")}</p>}
        </div>
      </section>
    </div>
  );
}


/* ---------------- Team (Employees only) ---------------- */
type EmpForm = { name: string; trade: string; phone: string; email: string; role: string; payType: string; payRate: string; status: string };
const emptyEmpForm = (): EmpForm => ({ name: "", trade: "", phone: "", email: "", role: "funcionario", payType: "hora", payRate: "", status: "ativo" });

function Team({ cid, session }: { cid: string; session: Session }) {
  const q = useQuery({ queryKey: ["employees", cid], queryFn: () => api.listEmployees({ companyId: cid }) });
  const qc = useQueryClient();
  const canManage = session.role !== "funcionario";
  const [showEmp, setShowEmp] = useState(false);
  const [editEmpId, setEditEmpId] = useState<number | null>(null);
  const [selectedEmpId, setSelectedEmpId] = useState<number | null>(null);
  const [savedEmpId, setSavedEmpId] = useState<number | null>(null);
  const [empSaveMsg, setEmpSaveMsg] = useState("");
  const [empFormError, setEmpFormError] = useState("");
  const [emp, setEmp] = useState<EmpForm>(emptyEmpForm());
  const saveEmp = useMutation({
    mutationFn: async (): Promise<{ id: number; created: boolean }> => {
      if (editEmpId !== null) {
        await api.updateEmployee({ companyId: cid, employeeId: editEmpId, actorId: session.userId, name: emp.name, trade: emp.trade, phone: emp.phone, email: emp.email, role: emp.role as "admin" | "gerente" | "funcionario" | "cliente", payType: emp.payType as "hora" | "diaria" | "contrato", payRate: parseMoney(emp.payRate), status: emp.status as "ativo" | "inativo" });
        return { id: editEmpId, created: false };
      }
      const r = await api.createEmployee({ companyId: cid, actorId: session.userId, name: emp.name, trade: emp.trade, phone: emp.phone, email: emp.email, payType: emp.payType as "hora" | "diaria" | "contrato", payRate: parseMoney(emp.payRate), role: emp.role as "admin" | "gerente" | "funcionario" | "cliente", status: emp.status as "ativo" | "inativo" });
      return { id: r.id, created: true };
    },
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["employees", cid] });
      qc.invalidateQueries({ queryKey: ["payroll", cid] });
      qc.invalidateQueries({ queryKey: ["bootstrap"] });
      setSelectedEmpId(r.id); setSavedEmpId(r.id);
      setEmpSaveMsg(r.created ? tr("Employee added. The details below are up to date.", "Funcionário adicionado. Os detalhes abaixo estão atualizados.", "Empleado agregado. Los detalles de abajo están actualizados.") : tr("Employee updated. The details below are up to date.", "Funcionário atualizado. Os detalhes abaixo estão atualizados.", "Empleado actualizado. Los detalles de abajo están actualizados."));
      setEmpFormError(""); setShowEmp(false); setEditEmpId(null); setEmp(emptyEmpForm());
      window.setTimeout(() => document.getElementById(`employee-detail-${r.id}`)?.scrollIntoView({ behavior: "smooth", block: "center" }), 80);
    },
    onError: () => setEmpFormError(tr("Could not save this employee. Only an admin or manager can edit employees — please try again.", "Não foi possível salvar este funcionário. Somente um administrador ou gerente pode editar funcionários — tente novamente.", "No se pudo guardar este empleado. Solo un administrador o gerente puede editar empleados: inténtalo de nuevo.")),
  });
  const openNewEmp = () => { setEditEmpId(null); setEmp(emptyEmpForm()); setEmpFormError(""); setShowEmp(true); };
  const openEditEmp = (e: { id: number; name: string; trade: string; phone: string; email: string; role: string; payType: string; payRate: number; status: string }) => {
    setEditEmpId(e.id); setSelectedEmpId(e.id); setSavedEmpId(null); setEmpSaveMsg(""); setEmpFormError("");
    setEmp({ name: e.name, trade: e.trade, phone: e.phone, email: e.email, role: e.role, payType: e.payType, payRate: moneyInput(e.payRate), status: e.status });
    setShowEmp(true);
  };

  return (
    <div className="space-y-5">
      <div>
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-bold">{tr("Team — Employees", "Equipe — Funcionários", "Equipo: empleados")}</h2>
          {canManage && <button className={btnPrimary} onClick={() => (showEmp ? setShowEmp(false) : openNewEmp())} aria-label={tr("New employee", "Novo funcionário", "Nuevo empleado")}>{showEmp ? tr("Close", "Fechar", "Cerrar") : tr("+ New", "+ Novo", "+ Nuevo")}</button>}
        </div>
        <p className="mt-1 text-sm text-[var(--dim)]">{tr("Employees only. Clients live in the Clients tab.", "Somente funcionários. Os clientes ficam na aba Clientes.", "Solo empleados. Los clientes están en la pestaña Clientes.")}</p>
        {showEmp && canManage && (
          <form className="mt-3 space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" onSubmit={(e) => { e.preventDefault(); saveEmp.mutate(); }}>
            <p className="font-bold">{editEmpId !== null ? tr("Edit employee", "Editar funcionário", "Editar empleado") : tr("New employee", "Novo funcionário", "Nuevo empleado")}</p>
            <Field label={tr("Full name", "Nome completo", "Nombre completo")}><input aria-label={tr("Employee full name", "Nome completo do funcionário", "Nombre completo del empleado")} autoComplete="name" className={inputCls} value={emp.name} onChange={(e) => setEmp({ ...emp, name: e.target.value })} required /></Field>
            <div className="grid grid-cols-2 gap-3">
              <Field label={tr("Trade / job role", "Ofício / função", "Oficio / función")}><input aria-label={tr("Employee trade", "Ofício do funcionário", "Oficio del empleado")} autoComplete="organization-title" className={inputCls} value={emp.trade} onChange={(e) => setEmp({ ...emp, trade: e.target.value })} placeholder={tr("Mason, electrician…", "Pedreiro, eletricista…", "Albañil, electricista…")} /></Field>
              <Field label={tr("Phone", "Telefone", "Teléfono")}><input aria-label={tr("Employee phone", "Telefone do funcionário", "Teléfono del empleado")} autoComplete="tel" type="tel" className={inputCls} value={emp.phone} onChange={(e) => setEmp({ ...emp, phone: e.target.value })} placeholder="(732) 555-0100" /></Field>
            </div>
            <Field label={tr("Email", "E-mail", "Correo electrónico")}><input aria-label={tr("Employee email", "E-mail do funcionário", "Correo del empleado")} autoComplete="email" type="email" className={inputCls} value={emp.email} onChange={(e) => setEmp({ ...emp, email: e.target.value })} placeholder="name@email.com" /></Field>
            <div className="grid grid-cols-2 gap-3">
              <Field label={tr("Access role", "Função de acesso", "Rol de acceso")}>
                <select aria-label={tr("Employee access role", "Função de acesso do funcionário", "Rol de acceso del empleado")} className={inputCls} value={emp.role} onChange={(e) => setEmp({ ...emp, role: e.target.value })}>
                  <option value="funcionario">{tr("Employee", "Funcionário", "Empleado")}</option><option value="gerente">{tr("Manager", "Gerente", "Gerente")}</option><option value="admin">{tr("Company owner", "Dono da empresa", "Dueño de la empresa")}</option>
                </select>
              </Field>
              <Field label={tr("Status", "Status", "Estado")}>
                <select aria-label={tr("Employee status", "Status do funcionário", "Estado del empleado")} className={inputCls} value={emp.status} onChange={(e) => setEmp({ ...emp, status: e.target.value })}>
                  <option value="ativo">{tr("Active", "Ativo", "Activa")}</option><option value="inativo">{tr("Inactive", "Inativo", "Inactivo")}</option>
                </select>
              </Field>
            </div>
            <PayTypePicker payType={emp.payType} payRate={emp.payRate} onType={(t) => setEmp({ ...emp, payType: t })} onRate={(v) => setEmp({ ...emp, payRate: v })} />
            {editEmpId !== null && <p className="rounded-xl bg-[var(--surface2)] px-3 py-2 text-xs text-[var(--dim)]">{tr("A pay change applies to future check-ins. Approved time entries keep the pay captured when the work was recorded.", "Uma alteração de pagamento vale para check-ins futuros. Os registros aprovados mantêm o pagamento capturado quando o trabalho foi registrado.", "Un cambio de pago aplica a futuros registros de entrada. Los registros aprobados conservan el pago capturado cuando se registró el trabajo.")}</p>}
            {empFormError && <p className="text-sm font-semibold text-red-600" role="alert">{empFormError}</p>}
            <div className="flex gap-2">
              <button type="button" className={btnGhost} onClick={() => { setShowEmp(false); setEditEmpId(null); setEmp(emptyEmpForm()); setEmpFormError(""); }}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
              <button className={`${btnNavy} flex-1`} disabled={saveEmp.isPending || !emp.name.trim()}>{saveEmp.isPending ? tr("Saving…", "Salvando…", "Guardando…") : editEmpId !== null ? tr("Save changes", "Salvar alterações", "Guardar cambios") : tr("Add employee", "Adicionar funcionário", "Agregar empleado")}</button>
            </div>
          </form>
        )}
        <div className="mt-3 space-y-2">
          {(q.data?.employees ?? []).filter((e) => e.role !== "cliente").map((e) => (
            <div key={e.id} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-3.5">
              <div className="flex items-center justify-between gap-2">
                <p className="font-bold">{e.name}</p>
                <Badge text={roleLabel(e.role)} tone={e.role === "admin" ? "navy" : e.role === "gerente" ? "amber" : "gray"} />
              </div>
              <p className="mt-0.5 text-sm text-[var(--dim)]">{e.trade}{e.phone ? ` • ${e.phone}` : ""}</p>
              <div className="mt-1.5 flex flex-wrap items-center gap-2">
                {session.role === "admin" && payBadge(e.payType, e.payRate)}
                <Badge text={e.status === "ativo" ? tr("Active", "Ativo", "Activa") : tr("Inactive", "Inativo", "Inactivo")} tone={e.status === "ativo" ? "green" : "gray"} />
                <button type="button" aria-label={selectedEmpId === e.id ? tr(`Hide details for ${e.name}`, `Ocultar os detalhes de ${e.name}`, `Ocultar los detalles de ${e.name}`) : tr(`View details for ${e.name}`, `Ver os detalhes de ${e.name}`, `Ver los detalles de ${e.name}`)} aria-expanded={selectedEmpId === e.id} onClick={() => setSelectedEmpId(selectedEmpId === e.id ? null : e.id)} className="text-xs font-bold text-[#0f2a44] underline decoration-[#f97316] underline-offset-2 dark:text-white">
                  {selectedEmpId === e.id ? tr("Hide details", "Ocultar detalhes", "Ocultar detalles") : tr("Details", "Detalhes", "Detalles")}
                </button>
                {canManage && <button type="button" aria-label={tr(`Edit employee ${e.name}`, `Editar o funcionário ${e.name}`, `Editar al empleado ${e.name}`)} onClick={() => openEditEmp(e)} className="text-xs font-bold text-[#f97316]">{tr("Edit", "Editar", "Editar")}</button>}
              </div>
              {selectedEmpId === e.id && (
                <div id={`employee-detail-${e.id}`} className="mt-3 rounded-xl bg-[var(--surface2)] p-3" aria-label={tr(`Employee details for ${e.name}`, `Detalhes do funcionário ${e.name}`, `Detalles del empleado ${e.name}`)}>
                  {savedEmpId === e.id && empSaveMsg && <p className="mb-2 rounded-lg bg-green-100 px-2.5 py-2 text-xs font-bold text-green-800" role="status">✅ {empSaveMsg}</p>}
                  <dl className="grid grid-cols-2 gap-x-3 gap-y-2 text-sm">
                    <div><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Access role", "Função de acesso", "Rol de acceso")}</dt><dd className="font-semibold">{roleLabel(e.role)}</dd></div>
                    <div><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Status", "Status", "Estado")}</dt><dd className="font-semibold">{e.status === "ativo" ? tr("Active", "Ativo", "Activa") : tr("Inactive", "Inativo", "Inactivo")}</dd></div>
                    <div><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Trade / job role", "Ofício / função", "Oficio / función")}</dt><dd>{e.trade || "—"}</dd></div>
                    <div><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Phone", "Telefone", "Teléfono")}</dt><dd>{e.phone || "—"}</dd></div>
                    <div className="col-span-2"><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Email", "E-mail", "Correo electrónico")}</dt><dd>{e.email || "—"}</dd></div>
                    {session.role === "admin" && <div className="col-span-2"><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Current pay", "Pagamento atual", "Pago actual")}</dt><dd>{payBadge(e.payType, e.payRate)}</dd></div>}
                  </dl>
                  <p className="mt-2 text-xs text-[var(--dim)]">{tr("Pay changes apply to future check-ins; approved entries keep their captured pay.", "Alterações de pagamento valem para check-ins futuros; registros aprovados mantêm o pagamento capturado.", "Los cambios de pago aplican a futuros registros de entrada; los registros aprobados conservan el pago capturado.")}</p>
                  {canManage && <button type="button" aria-label={tr(`Edit employee ${e.name} from details`, `Editar o funcionário ${e.name} pelos detalhes`, `Editar al empleado ${e.name} desde los detalles`)} onClick={() => openEditEmp(e)} className={`${btnNavy} mt-3 w-full py-2.5 text-sm`}>{tr("Edit employee", "Editar funcionário", "Editar empleado")}</button>}
                </div>
              )}
            </div>
          ))}
          {q.data && q.data.employees.length === 0 && <p className="py-4 text-center text-sm text-[var(--dim)]">{tr("No employees in this company yet.", "Nenhum funcionário nesta empresa ainda.", "Todavía no hay empleados en esta empresa.")}</p>}
        </div>
      </div>
    </div>
  );
}

/* ---------------- Clients (separate tab) ---------------- */
type ClientForm = { name: string; contactName: string; phone: string; email: string; email2: string; addr: AddrParts };
const emptyClientForm = (): ClientForm => ({ name: "", contactName: "", phone: "", email: "", email2: "", addr: emptyAddr() });

function Clients({ cid, session, onOpenProject, onOpenInvoice, onNewInvoice }: { cid: string; session: Session; onOpenProject?: (id: number) => void; onOpenInvoice?: (id: number) => void; onNewInvoice?: (clientId: number | null, projectId: number | null) => void }) {
  const clientsQ = useQuery({ queryKey: ["clients", cid], queryFn: () => api.listClients({ companyId: cid }) });
  const projectsQ = useQuery({ queryKey: ["projects", cid], queryFn: () => api.listProjects({ companyId: cid }) });
  const invoicesQ = useQuery({ queryKey: ["invoices", cid], queryFn: () => api.listInvoices({ companyId: cid, actorId: session.userId }) });
  const qc = useQueryClient();
  const canManage = session.role !== "funcionario";
  const [showClient, setShowClient] = useState(false);
  const [editClientId, setEditClientId] = useState<number | null>(null);
  const [selectedClientId, setSelectedClientId] = useState<number | null>(null);
  const [savedClientId, setSavedClientId] = useState<number | null>(null);
  const [clientSaveMsg, setClientSaveMsg] = useState("");
  const [clientFormError, setClientFormError] = useState("");
  const [cl, setCl] = useState<ClientForm>(emptyClientForm());
  const saveClient = useMutation({
    mutationFn: async (): Promise<{ id: number; created: boolean }> => {
      if (editClientId !== null) {
        await api.updateClient({ companyId: cid, clientId: editClientId, actorId: session.userId, name: cl.name, contactName: cl.contactName, phone: cl.phone, email: cl.email, email2: cl.email2, ...cl.addr });
        return { id: editClientId, created: false };
      }
      const r = await api.createClient({ companyId: cid, actorId: session.userId, name: cl.name, contactName: cl.contactName, phone: cl.phone, email: cl.email, email2: cl.email2, ...cl.addr });
      return { id: r.id, created: true };
    },
    onSuccess: (r) => {
      qc.invalidateQueries({ queryKey: ["clients", cid] });
      qc.invalidateQueries({ queryKey: ["invoices", cid] });
      qc.invalidateQueries({ queryKey: ["invoice-detail", cid] });
      qc.invalidateQueries({ queryKey: ["projects", cid] });
      setSelectedClientId(r.id); setSavedClientId(r.id);
      setClientSaveMsg(r.created ? tr("Client added. The details below are up to date.", "Cliente adicionado. Os detalhes abaixo estão atualizados.", "Cliente agregado. Los detalles de abajo están actualizados.") : tr("Client updated. Invoices now use these bill-to details.", "Cliente atualizado. As faturas agora usam estes dados de cobrança.", "Cliente actualizado. Las facturas ahora usan estos datos de facturación."));
      setClientFormError(""); setShowClient(false); setEditClientId(null); setCl(emptyClientForm());
      window.setTimeout(() => document.getElementById(`client-detail-${r.id}`)?.scrollIntoView({ behavior: "smooth", block: "center" }), 80);
    },
    onError: () => setClientFormError(tr("Could not save this client. Only an admin or manager can edit clients — please try again.", "Não foi possível salvar este cliente. Somente um administrador ou gerente pode editar clientes — tente novamente.", "No se pudo guardar este cliente. Solo un administrador o gerente puede editar clientes: inténtalo de nuevo.")),
  });
  const openNewClient = () => { setEditClientId(null); setCl(emptyClientForm()); setClientFormError(""); setShowClient(true); };
  const openEditClient = (c: { id: number; name: string; contactName: string; phone: string; email: string; email2: string; streetNumber: string; streetName: string; city: string; state: string; zip: string }) => {
    setEditClientId(c.id); setSelectedClientId(c.id); setSavedClientId(null); setClientSaveMsg(""); setClientFormError("");
    setCl({ name: c.name, contactName: c.contactName, phone: c.phone, email: c.email, email2: c.email2 ?? "", addr: { streetNumber: c.streetNumber, streetName: c.streetName, city: c.city, state: c.state, zip: c.zip } });
    setShowClient(true);
  };
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);
  const [deleteError, setDeleteError] = useState("");
  const [deleteMsg, setDeleteMsg] = useState("");
  const deleteClient = useMutation({
    mutationFn: (clientId: number) => api.deleteClient({ companyId: cid, clientId, actorId: session.userId }),
    onSuccess: (_r, clientId) => {
      qc.invalidateQueries({ queryKey: ["clients", cid] });
      qc.invalidateQueries({ queryKey: ["projects", cid] });
      qc.invalidateQueries({ queryKey: ["invoices", cid] });
      if (selectedClientId === clientId) setSelectedClientId(null);
      setDeleteConfirmId(null); setDeleteError(""); setDeleteMsg(tr("Client deleted.", "Cliente excluído.", "Cliente eliminado."));
    },
    onError: (e) => { setDeleteConfirmId(null); setDeleteMsg(""); setDeleteError(e instanceof Error ? e.message : tr("Could not delete this client.", "Não foi possível excluir este cliente.", "No se pudo eliminar este cliente.")); },
  });

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold">{tr("Clients", "Clientes", "Clientes")}</h2>
        {canManage && <button className={btnPrimary} onClick={() => (showClient ? setShowClient(false) : openNewClient())} aria-label={tr("New client", "Novo cliente", "Nuevo cliente")}>{showClient ? tr("Close", "Fechar", "Cerrar") : tr("+ New client", "+ Novo cliente", "+ Nuevo cliente")}</button>}
      </div>
      <p className="text-sm text-[var(--dim)]">{tr("Clients only — create a client with no projects, one project, or many. Each invoice bills the client who owns the project.", "Somente clientes — crie um cliente sem obras, com uma obra ou com várias. Cada fatura cobra o cliente dono da obra.", "Solo clientes: crea un cliente sin obras, con una obra o con varias. Cada factura cobra al cliente dueño de la obra.")}</p>
      {showClient && canManage && (
        <form className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" onSubmit={(e) => { e.preventDefault(); saveClient.mutate(); }}>
          <p className="font-bold">{editClientId !== null ? tr("Edit client", "Editar cliente", "Editar cliente") : tr("New client", "Novo cliente", "Nuevo cliente")}</p>
          <Field label={tr("Client name", "Nome do cliente", "Nombre del cliente")}><input aria-label={tr("Client name", "Nome do cliente", "Nombre del cliente")} autoComplete="organization" className={inputCls} value={cl.name} onChange={(e) => setCl({ ...cl, name: e.target.value })} placeholder={tr("Person or company", "Pessoa ou empresa", "Persona o empresa")} required /></Field>
          <Field label={tr("Contact person", "Pessoa de contato", "Persona de contacto")}><input aria-label={tr("Client contact person", "Pessoa de contato do cliente", "Persona de contacto del cliente")} autoComplete="name" className={inputCls} value={cl.contactName} onChange={(e) => setCl({ ...cl, contactName: e.target.value })} placeholder={tr("Who do we talk to?", "Com quem falamos?", "¿Con quién hablamos?")} /></Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label={tr("Phone", "Telefone", "Teléfono")}><input aria-label={tr("Client phone", "Telefone do cliente", "Teléfono del cliente")} autoComplete="tel" type="tel" className={inputCls} value={cl.phone} onChange={(e) => setCl({ ...cl, phone: e.target.value })} placeholder="(732) 555-0100" /></Field>
            <Field label={tr("Email", "E-mail", "Correo electrónico")}><input aria-label={tr("Client email", "E-mail do cliente", "Correo del cliente")} autoComplete="email" type="email" className={inputCls} value={cl.email} onChange={(e) => setCl({ ...cl, email: e.target.value })} placeholder="billing@email.com" /></Field>
          </div>
          <Field label={tr("Additional email (optional)", "E-mail adicional (opcional)", "Correo adicional (opcional)")}><input aria-label={tr("Client additional email", "E-mail adicional do cliente", "Correo adicional del cliente")} autoComplete="email" type="email" className={inputCls} value={cl.email2} onChange={(e) => setCl({ ...cl, email2: e.target.value })} placeholder="second@email.com" /></Field>
          <div>
            <span className="mb-1 block text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Billing address — used on invoices", "Endereço de cobrança — usado nas faturas", "Dirección de facturación: se usa en las facturas")}</span>
            <AddressForm idPrefix="client" value={cl.addr} onChange={(a) => setCl({ ...cl, addr: a })} />
          </div>
          <p className="rounded-xl bg-[var(--surface2)] px-3 py-2 text-xs text-[var(--dim)]">{tr("A project is optional. You can save this client with no projects and link projects later from the Projects tab.", "Uma obra é opcional. Você pode salvar este cliente sem obras e vincular obras depois na aba Obras.", "Una obra es opcional. Puedes guardar este cliente sin obras y vincular obras después en la pestaña Obras.")}</p>
          {clientFormError && <p className="text-sm font-semibold text-red-600" role="alert">{clientFormError}</p>}
          <div className="flex gap-2">
            <button type="button" className={btnGhost} onClick={() => { setShowClient(false); setEditClientId(null); setCl(emptyClientForm()); setClientFormError(""); }}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
            <button className={`${btnNavy} flex-1`} disabled={saveClient.isPending || !cl.name.trim()}>{saveClient.isPending ? tr("Saving…", "Salvando…", "Guardando…") : editClientId !== null ? tr("Save changes", "Salvar alterações", "Guardar cambios") : tr("Add client", "Adicionar cliente", "Agregar cliente")}</button>
          </div>
        </form>
      )}
      {deleteMsg && <p className="rounded-xl bg-green-100 px-3 py-2 text-sm font-semibold text-green-800" role="status">✅ {deleteMsg}</p>}
      {deleteError && <p className="rounded-xl bg-red-100 px-3 py-2 text-sm font-semibold text-red-700" role="alert">{deleteError}</p>}
      <div className="space-y-2">
        {(clientsQ.data?.clients ?? []).map((c) => {
          const linked = (projectsQ.data?.projects ?? []).filter((p) => p.clientId === c.id);
          const clientInvoices = (invoicesQ.data?.invoices ?? []).filter((inv) => inv.clientId === c.id);
          return (
            <div key={c.id} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-3.5">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <p className="font-semibold">{c.name}</p>
                  <span className={`mt-1 inline-block rounded-full px-2 py-0.5 text-[11px] font-bold ${c.projectCount > 0 ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-600"}`}>
                    {c.projectCount > 0 ? `🏗️ ${c.projectCount} ${tr("project", "obra", "obra")}${c.projectCount === 1 ? "" : "s"}` : tr("No projects", "Sem obras", "Sin obras")}
                  </span>
                </div>
                <span className="flex shrink-0 items-center gap-3">
                  <button type="button" aria-label={selectedClientId === c.id ? tr(`Hide details for client ${c.name}`, `Ocultar os detalhes do cliente ${c.name}`, `Ocultar los detalles del cliente ${c.name}`) : tr(`View details for client ${c.name}`, `Ver os detalhes do cliente ${c.name}`, `Ver los detalles del cliente ${c.name}`)} aria-expanded={selectedClientId === c.id} onClick={() => { setSelectedClientId(selectedClientId === c.id ? null : c.id); setDeleteError(""); setDeleteMsg(""); }} className="text-xs font-bold text-[#0f2a44] underline decoration-[#f97316] underline-offset-2 dark:text-white">
                    {selectedClientId === c.id ? tr("Hide details", "Ocultar detalhes", "Ocultar detalles") : tr("Details", "Detalhes", "Detalles")}
                  </button>
                  {canManage && <button type="button" aria-label={tr(`Edit client ${c.name}`, `Editar o cliente ${c.name}`, `Editar al cliente ${c.name}`)} onClick={() => openEditClient(c)} className="text-xs font-bold text-[#f97316]">{tr("Edit", "Editar", "Editar")}</button>}
                </span>
              </div>
              {c.contactName && c.contactName !== c.name && <p className="text-sm text-[var(--dim)]">{tr("Contact:", "Contato:", "Contacto:")} {c.contactName}</p>}
              {(c.phone || c.email) && <p className="text-sm text-[var(--dim)]">{[c.phone, c.email, c.email2].filter(Boolean).join(" • ")}</p>}
              {c.address && <p className="text-xs text-[var(--dim)]">📍 {c.address}</p>}
              {selectedClientId === c.id && (
                <div id={`client-detail-${c.id}`} className="mt-3 rounded-xl bg-[var(--surface2)] p-3" aria-label={tr(`Client details for ${c.name}`, `Detalhes do cliente ${c.name}`, `Detalles del cliente ${c.name}`)}>
                  {savedClientId === c.id && clientSaveMsg && <p className="mb-2 rounded-lg bg-green-100 px-2.5 py-2 text-xs font-bold text-green-800" role="status">✅ {clientSaveMsg}</p>}
                  <dl className="grid grid-cols-2 gap-x-3 gap-y-2 text-sm">
                    <div><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Contact person", "Pessoa de contato", "Persona de contacto")}</dt><dd>{c.contactName || "—"}</dd></div>
                    <div><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Phone", "Telefone", "Teléfono")}</dt><dd>{c.phone || "—"}</dd></div>
                    <div className="col-span-2"><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Email", "E-mail", "Correo electrónico")}</dt><dd>{c.email || "—"}</dd></div>
                    <div className="col-span-2"><dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Additional email", "E-mail adicional", "Correo adicional")}</dt><dd>{c.email2 || "—"}</dd></div>
                    <div className="col-span-2">
                      <dt className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Billing address", "Endereço de cobrança", "Dirección de facturación")}</dt>
                      <dd className="whitespace-pre-line">{[[c.streetNumber, c.streetName].filter(Boolean).join(" "), [c.city, [c.state, c.zip].filter(Boolean).join(" ")].filter(Boolean).join(", ")].filter(Boolean).join("\n") || c.address || "—"}</dd>
                    </div>
                  </dl>
                  <p className="mt-2 text-xs text-[var(--dim)]">{tr("This address and contact information appear in the invoice bill-to block.", "Este endereço e estas informações de contato aparecem no bloco de cobrança da fatura.", "Esta dirección e información de contacto aparecen en el bloque de facturación de la factura.")}</p>

                  <section className="mt-4" aria-label={tr(`Projects for ${c.name}`, `Obras de ${c.name}`, `Obras de ${c.name}`)}>
                    <div className="flex items-center justify-between gap-2">
                      <h4 className="text-sm font-bold">{tr("Projects", "Obras", "Obras")} ({linked.length})</h4>
                      {linked.length > 0 && <span className="text-[11px] font-semibold text-[var(--dim)]">{tr("Tap a project to open it", "Toque em uma obra para abri-la", "Toca una obra para abrirla")}</span>}
                    </div>
                    {linked.length === 0 ? (
                      <div className="mt-2 rounded-xl border border-dashed border-[var(--border)] bg-[var(--surface)] px-3 py-3 text-center">
                        <p className="text-sm font-semibold">{tr("No projects yet", "Nenhuma obra ainda", "Todavía no hay obras")}</p>
                        <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("This client is saved on its own — that's fine. Link projects anytime from the Projects tab.", "Este cliente está salvo sozinho — tudo bem. Vincule obras quando quiser na aba Obras.", "Este cliente está guardado por su cuenta: está bien. Vincula obras cuando quieras en la pestaña Obras.")}</p>
                      </div>
                    ) : (
                      <div className="mt-2 space-y-2">
                        {linked.map((p) => {
                          const showProfit = session.role === "admin" && p.estimatedValue > 0;
                          const profitNegative = p.profit < 0;
                          return (
                            <button key={p.id} type="button" onClick={() => onOpenProject?.(p.id)} aria-label={tr(`Open project ${p.name}`, `Abrir a obra ${p.name}`, `Abrir la obra ${p.name}`)} className="block w-full rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3 py-2.5 text-left active:opacity-80">
                              <div className="flex items-start justify-between gap-2">
                                <p className="min-w-0 font-semibold leading-snug">{p.name}</p>
                                <Badge text={projectStatusLabel(p.status)} tone={p.status === "andamento" ? "green" : p.status === "concluida" ? "navy" : "gray"} />
                              </div>
                              {p.address && <p className="mt-0.5 text-xs text-[var(--dim)]">📍 {p.address}</p>}
                              <div className="mt-1.5 flex flex-wrap items-center gap-2">
                                <span className="text-[11px] font-semibold text-[var(--dim)]">{tr("Progress", "Andamento", "Progreso")} {p.progress}%</span>
                                {showProfit && <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-bold ${profitNegative ? "bg-red-100 text-red-700" : "bg-green-100 text-green-800"}`}>{fmtUSD(p.profit)} • {p.profitMargin.toFixed(1)}%</span>}
                              </div>
                            </button>
                          );
                        })}
                      </div>
                    )}
                  </section>

                  {session.role === "admin" && (
                  <section className="mt-4" aria-label={tr(`Invoices for ${c.name}`, `Faturas de ${c.name}`, `Facturas de ${c.name}`)}>
                    <div className="flex items-center justify-between gap-2">
                      <h4 className="text-sm font-bold">{tr("Invoices", "Faturas", "Facturas")} ({clientInvoices.length})</h4>
                      {canManage && onNewInvoice && <button type="button" onClick={() => onNewInvoice(c.id, linked.length === 1 ? (linked[0]?.id ?? null) : null)} aria-label={tr(`New invoice for ${c.name}`, `Nova fatura para ${c.name}`, `Nueva factura para ${c.name}`)} className="rounded-lg bg-[#f97316] px-3 py-1.5 text-xs font-bold text-white active:opacity-80">{tr("+ New invoice", "+ Nova fatura", "+ Nueva factura")}</button>}
                    </div>
                    {clientInvoices.length === 0 ? (
                      <p className="mt-2 rounded-xl border border-dashed border-[var(--border)] bg-[var(--surface)] px-3 py-3 text-center text-sm text-[var(--dim)]">{tr("No invoices yet.", "Nenhuma fatura ainda.", "Todavía no hay facturas.")}</p>
                    ) : (
                      <div className="mt-2 space-y-2">
                        {clientInvoices.map((inv) => (
                          <button key={inv.id} type="button" onClick={() => onOpenInvoice?.(inv.id)} aria-label={tr(`Open invoice ${inv.number} for ${c.name}`, `Abrir a fatura ${inv.number} de ${c.name}`, `Abrir la factura ${inv.number} de ${c.name}`)} className="block w-full rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3 py-2.5 text-left active:opacity-80">
                            <div className="flex items-center justify-between gap-2">
                              <p className="font-bold">{inv.number}</p>
                              {invBadge(inv.status)}
                            </div>
                            <p className="mt-0.5 text-xs text-[var(--dim)]">{fmtDate(inv.issueDate)}{inv.projectName ? ` • ${inv.projectName}` : ""}</p>
                            <div className="mt-1.5 flex justify-between text-sm">
                              <span className="text-[var(--dim)]">{tr("Total", "Total", "Total")} <strong className="text-[var(--text)]">{fmtUSD(inv.total)}</strong></span>
                              <span className="text-[var(--dim)]">{tr("Balance Due", "Saldo a pagar", "Saldo por pagar")} <strong className="text-[var(--text)]">{fmtUSD(inv.balance)}</strong></span>
                            </div>
                          </button>
                        ))}
                      </div>
                    )}
                  </section>
                  )}
                  {session.role === "admin" && <ClientPortalAccess cid={cid} session={session} clientId={c.id} clientName={c.name} defaultEmail={c.email} />}

                  {canManage && <button type="button" aria-label={tr(`Edit client ${c.name} from details`, `Editar o cliente ${c.name} pelos detalhes`, `Editar al cliente ${c.name} desde los detalles`)} onClick={() => openEditClient(c)} className={`${btnNavy} mt-3 w-full py-2.5 text-sm`}>{tr("Edit client", "Editar cliente", "Editar cliente")}</button>}
                  {canManage && (
                    <div className="mt-3 border-t border-[var(--border)] pt-3">
                      {deleteConfirmId === c.id ? (
                        <div className="rounded-xl bg-red-50 px-3 py-3" role="alertdialog" aria-label={tr(`Confirm deleting client ${c.name}`, `Confirmar a exclusão do cliente ${c.name}`, `Confirmar la eliminación del cliente ${c.name}`)}>
                          <p className="text-sm font-bold text-red-700">{tr("Delete", "Excluir", "Eliminar")} {c.name}?</p>
                          <p className="mt-1 text-xs text-red-700/80">{tr("This cannot be undone. If projects or invoices are still linked, deletion is blocked.", "Isto não pode ser desfeito. Se obras ou faturas ainda estiverem vinculadas, a exclusão é bloqueada.", "Esto no se puede deshacer. Si todavía hay obras o facturas vinculadas, la eliminación se bloquea.")}</p>
                          <div className="mt-2 flex gap-2">
                            <button type="button" className={btnGhost} aria-label={tr("Cancel deleting client", "Cancelar a exclusão do cliente", "Cancelar la eliminación del cliente")} onClick={() => setDeleteConfirmId(null)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
                            <button type="button" className="flex-1 rounded-xl bg-red-600 px-4 py-2.5 font-semibold text-white active:opacity-80 disabled:opacity-40" aria-label={tr(`Confirm delete client ${c.name}`, `Confirmar a exclusão do cliente ${c.name}`, `Confirmar la eliminación del cliente ${c.name}`)} disabled={deleteClient.isPending} onClick={() => deleteClient.mutate(c.id)}>{deleteClient.isPending ? tr("Deleting…", "Excluindo…", "Eliminando…") : tr("Delete client", "Excluir cliente", "Eliminar cliente")}</button>
                          </div>
                        </div>
                      ) : (
                        <button type="button" aria-label={tr(`Delete client ${c.name}`, `Excluir o cliente ${c.name}`, `Eliminar al cliente ${c.name}`)} onClick={() => { setDeleteConfirmId(c.id); setDeleteError(""); setDeleteMsg(""); }} className="w-full rounded-xl border border-red-200 bg-[var(--surface)] px-4 py-2.5 text-sm font-semibold text-red-600 active:opacity-70">{tr("Delete client", "Excluir cliente", "Eliminar cliente")}</button>
                      )}
                      <p className="mt-1.5 text-center text-[11px] text-[var(--dim)]">{tr("Blocked while projects or invoices are linked — unlink them first; they keep their data.", "Bloqueado enquanto obras ou faturas estiverem vinculadas — desvincule-as primeiro; elas mantêm os dados.", "Bloqueado mientras haya obras o facturas vinculadas: primero desvincúlalas; ellas conservan sus datos.")}</p>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
        {clientsQ.data && clientsQ.data.clients.length === 0 && <p className="py-2 text-sm text-[var(--dim)]">{tr("No clients yet.", "Nenhum cliente ainda.", "Todavía no hay clientes.")}</p>}
      </div>
    </div>
  );
}

/* ---------------- Client portal access (Company owner only) ----------------
   Create / reset / disable the read-only portal login linked to a client.
   The client can only ever view — there is no client write path anywhere. */
function ClientPortalAccess({ cid, session, clientId, clientName, defaultEmail }: { cid: string; session: Session; clientId: number; clientName: string; defaultEmail: string }) {
  const qc = useQueryClient();
  const q = useQuery({ queryKey: ["client-portal-logins", cid, clientId], queryFn: () => api.listClientPortalLogins({ companyId: cid, actorId: session.userId, clientId }) });
  const [email, setEmail] = useState(defaultEmail);
  const [password, setPassword] = useState("");
  const [resetPw, setResetPw] = useState<Record<number, string>>({});
  const [msg, setMsg] = useState("");
  const invalidate = () => { qc.invalidateQueries({ queryKey: ["client-portal-logins", cid, clientId] }); qc.invalidateQueries({ queryKey: ["bootstrap"] }); };
  const create = useMutation({
    mutationFn: () => api.createClientPortalLogin({ companyId: cid, actorId: session.userId, clientId, email: email.trim(), password, name: clientName }),
    onSuccess: () => { invalidate(); setPassword(""); setMsg(tr("Portal login created. Share the email and password with your client — they sign in from the Client portal box on the login screen.", "Login do portal criado. Compartilhe o e-mail e a senha com seu cliente — ele entra pela caixa Portal do cliente na tela de login.", "Acceso al portal creado. Comparte el correo y la contraseña con tu cliente: inicia sesión desde el cuadro Portal del cliente en la pantalla de inicio.")); },
    onError: (e) => setMsg(e instanceof Error ? e.message : tr("Could not create the portal login.", "Não foi possível criar o login do portal.", "No se pudo crear el acceso al portal.")),
  });
  const update = useMutation({
    mutationFn: (args: { userId: number; password?: string; enabled?: boolean }) => api.updateClientPortalLogin({ companyId: cid, actorId: session.userId, ...args }),
    onSuccess: () => { invalidate(); setMsg(tr("Portal access updated. ✅", "Acesso ao portal atualizado. ✅", "Acceso al portal actualizado. ✅")); },
    onError: () => setMsg(tr("Could not update the portal access.", "Não foi possível atualizar o acesso ao portal.", "No se pudo actualizar el acceso al portal.")),
  });
  const logins = q.data?.logins ?? [];
  return (
    <section className="mt-4 rounded-xl border border-[var(--border)] bg-[var(--surface)] p-3" aria-label={tr(`Client portal access for ${clientName}`, `Acesso ao portal do cliente para ${clientName}`, `Acceso al portal del cliente para ${clientName}`)}>
      <h4 className="text-sm font-bold">🔑 {tr("Client portal access", "Acesso ao portal do cliente", "Acceso al portal del cliente")}</h4>
      <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("Read-only: your client sees their projects, progress photos, and invoices — never costs, payroll, or other clients. They cannot change anything.", "Somente leitura: seu cliente vê as obras dele, fotos de andamento e faturas — nunca custos, folha ou outros clientes. Ele não pode alterar nada.", "Solo lectura: tu cliente ve sus obras, fotos de progreso y facturas, nunca costos, nómina ni otros clientes. No puede cambiar nada.")}</p>
      {logins.map((l) => (
        <div key={l.id} className="mt-2 rounded-lg bg-[var(--surface2)] px-3 py-2.5">
          <div className="flex items-center justify-between gap-2">
            <p className="min-w-0 truncate text-sm font-semibold">{l.email}</p>
            <Badge text={l.enabled ? tr("Active", "Ativo", "Activo") : tr("Disabled", "Desativado", "Desactivado")} tone={l.enabled ? "green" : "gray"} />
          </div>
          <div className="mt-2 flex gap-2">
            <input aria-label={tr(`New password for ${l.email}`, `Nova senha para ${l.email}`, `Nueva contraseña para ${l.email}`)} type="text" autoComplete="new-password" className={inputCls} placeholder={tr("New password (min. 6)", "Nova senha (mín. 6)", "Nueva contraseña (mín. 6)")} value={resetPw[l.id] ?? ""} onChange={(e) => setResetPw({ ...resetPw, [l.id]: e.target.value })} />
            <button type="button" className={btnGhost} disabled={update.isPending || (resetPw[l.id] ?? "").length < 6} aria-label={tr(`Reset password for ${l.email}`, `Redefinir a senha de ${l.email}`, `Restablecer la contraseña de ${l.email}`)} onClick={() => update.mutate({ userId: l.id, password: resetPw[l.id] })}>{tr("Reset password", "Redefinir senha", "Restablecer contraseña")}</button>
          </div>
          <button type="button" className="mt-2 text-xs font-bold text-red-600" disabled={update.isPending} aria-label={l.enabled ? tr(`Disable portal access for ${l.email}`, `Desativar o acesso ao portal de ${l.email}`, `Desactivar el acceso al portal de ${l.email}`) : tr(`Enable portal access for ${l.email}`, `Ativar o acesso ao portal de ${l.email}`, `Activar el acceso al portal de ${l.email}`)} onClick={() => update.mutate({ userId: l.id, enabled: !l.enabled })}>
            {l.enabled ? tr("Disable access", "Desativar acesso", "Desactivar acceso") : tr("Enable access", "Ativar acesso", "Activar acceso")}
          </button>
        </div>
      ))}
      <form className="mt-3 space-y-2" onSubmit={(e) => { e.preventDefault(); create.mutate(); }}>
        <Field label={tr("Portal email", "E-mail do portal", "Correo del portal")}><input aria-label={tr("Client portal email", "E-mail do portal do cliente", "Correo del portal del cliente")} type="email" autoComplete="email" className={inputCls} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="client@email.com" required /></Field>
        <Field label={tr("Password", "Senha", "Contraseña")}><input aria-label={tr("Client portal password", "Senha do portal do cliente", "Contraseña del portal del cliente")} type="text" autoComplete="new-password" className={inputCls} value={password} onChange={(e) => setPassword(e.target.value)} placeholder={tr("At least 6 characters", "Pelo menos 6 caracteres", "Al menos 6 caracteres")} required /></Field>
        <button className={`${btnNavy} w-full py-2.5 text-sm`} disabled={create.isPending || password.length < 6 || !email.trim()}>{create.isPending ? tr("Creating…", "Criando…", "Creando…") : tr("Create portal login", "Criar login do portal", "Crear acceso al portal")}</button>
      </form>
      {msg && <p className="mt-2 text-xs font-semibold" role="status">{msg}</p>}
    </section>
  );
}

/* ---------------- Client portal (level 5 — STRICTLY read-only) ----------------
   Viewing + PDF download + language toggle ONLY. No create/edit/pay/upload
   controls exist here, and the server rejects client writes regardless. */
function ClientPortal({ session, onSignOut }: { session: Session; onSignOut: () => void }) {
  const cid = session.companyId;
  const [tab, setTab] = useState<"projects" | "invoices">("projects");
  const [openProjectId, setOpenProjectId] = useState<number | null>(null);
  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
  const projectsQ = useQuery({ queryKey: ["client-projects", cid, session.userId], queryFn: () => api.getClientPortalProjects({ companyId: cid, userId: session.userId }) });
  const invoicesQ = useQuery({ queryKey: ["client-invoices", cid, session.userId], queryFn: () => api.getClientInvoices({ companyId: cid, userId: session.userId }) });
  return (
    <div className="min-h-screen bg-[var(--bg)] pb-24 text-[var(--text)]">
      <header className="sticky top-0 z-20 bg-[#0f2a44] px-4 pb-3 pt-[max(0.75rem,env(safe-area-inset-top))] text-white shadow">
        <div className="mx-auto flex max-w-5xl items-center justify-between gap-2">
          <div className="flex min-w-0 items-center gap-2.5">
            <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#f97316] text-sm font-black">SB</div>
            <div className="min-w-0">
              <p className="truncate text-sm font-bold leading-tight">{session.companyName}</p>
              <p className="truncate text-xs text-white/60">{session.userName} • {tr("Client portal", "Portal do cliente", "Portal del cliente")} • {tr("View only", "Somente visualização", "Solo lectura")}</p>
            </div>
          </div>
          <div className="flex shrink-0 items-center gap-1.5">
            <LanguageToggle compact />
            <button aria-label={tr("Sign out", "Sair", "Cerrar sesión")} onClick={onSignOut} className="shrink-0 rounded-lg bg-white/10 px-3 py-2 text-xs font-semibold active:opacity-70">{tr("Sign out", "Sair", "Cerrar sesión")}</button>
          </div>
        </div>
      </header>
      <main className="mx-auto max-w-5xl px-4 pt-4">
        {openProjectId !== null ? (
          <ClientProjectDetail cid={cid} session={session} projectId={openProjectId} onBack={() => setOpenProjectId(null)} />
        ) : openInvoiceId !== null ? (
          <ClientInvoiceDetail cid={cid} session={session} invoiceId={openInvoiceId} onBack={() => setOpenInvoiceId(null)} />
        ) : tab === "projects" ? (
          <div className="space-y-3">
            <h2 className="text-xl font-bold">🏗️ {tr("My projects", "Minhas obras", "Mis obras")}</h2>
            {projectsQ.isPending && <p className="py-8 text-center text-[var(--dim)]">{tr("Loading your projects…", "Carregando suas obras…", "Cargando tus obras…")}</p>}
            {projectsQ.error && <p className="py-8 text-center font-semibold text-red-600">{tr("Could not load your projects. Please try again.", "Não foi possível carregar suas obras. Tente novamente.", "No se pudieron cargar tus obras. Inténtalo de nuevo.")}</p>}
            {projectsQ.data && projectsQ.data.projects.length === 0 && <p className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center text-[var(--dim)]">{tr("No projects linked to your account yet. Your contractor will add them here.", "Nenhuma obra vinculada à sua conta ainda. Sua construtora irá adicioná-las aqui.", "Todavía no hay obras vinculadas a tu cuenta. Tu contratista las agregará aquí.")}</p>}
            {(projectsQ.data?.projects ?? []).map((p) => (
              <button key={p.id} type="button" onClick={() => setOpenProjectId(p.id)} aria-label={tr(`View project ${p.name}`, `Ver a obra ${p.name}`, `Ver la obra ${p.name}`)} className="block w-full overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface)] text-left active:opacity-80">
                {p.coverPhoto ? <img src={safeImgSrc(p.coverPhoto)} alt={tr(`Latest photo of ${p.name}`, `Foto mais recente de ${p.name}`, `Foto más reciente de ${p.name}`)} className="h-40 w-full object-cover" /> : null}
                <span className="block p-4">
                  <span className="flex items-start justify-between gap-2">
                    <span className="font-bold leading-snug">{p.name}</span>
                    <Badge text={projectStatusLabel(p.status)} tone={p.status === "andamento" ? "green" : p.status === "concluida" ? "navy" : "gray"} />
                  </span>
                  {p.address && <span className="mt-1 block text-sm text-[var(--dim)]">📍 {p.address}</span>}
                  <span className="mt-3 block">
                    <span className="flex justify-between text-xs font-semibold text-[var(--dim)]"><span>{tr("Progress", "Andamento", "Progreso")}</span><span>{p.progress}%</span></span>
                    <span className="mt-1 block h-2 overflow-hidden rounded-full bg-[var(--surface2)]"><span className="block h-full rounded-full bg-[#f97316]" style={{ width: `${p.progress}%` }} /></span>
                  </span>
                </span>
              </button>
            ))}
          </div>
        ) : (
          <div className="space-y-3">
            <h2 className="text-xl font-bold">📄 {tr("Invoices", "Faturas", "Facturas")}</h2>
            {invoicesQ.isPending && <p className="py-8 text-center text-[var(--dim)]">{tr("Loading your invoices…", "Carregando suas faturas…", "Cargando tus facturas…")}</p>}
            {invoicesQ.error && <p className="py-8 text-center font-semibold text-red-600">{tr("Could not load your invoices. Please try again.", "Não foi possível carregar suas faturas. Tente novamente.", "No se pudieron cargar tus facturas. Inténtalo de nuevo.")}</p>}
            {invoicesQ.data && invoicesQ.data.invoices.length === 0 && <p className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-8 text-center text-[var(--dim)]">{tr("No invoices yet.", "Nenhuma fatura ainda.", "Todavía no hay facturas.")}</p>}
            {(invoicesQ.data?.invoices ?? []).map((inv) => (
              <button key={inv.id} type="button" onClick={() => setOpenInvoiceId(inv.id)} aria-label={tr(`View invoice ${inv.number}`, `Ver a fatura ${inv.number}`, `Ver la factura ${inv.number}`)} className="block w-full rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left active:opacity-80">
                <span className="flex items-center justify-between gap-2"><span className="font-bold">{tr("Invoice", "Fatura", "Factura")} #{inv.number}</span>{invBadge(inv.status)}</span>
                <span className="mt-0.5 block text-xs text-[var(--dim)]">{fmtDate(inv.issueDate)}{inv.projectName ? ` • ${inv.projectName}` : ""} • {tr("Due", "Vencimento", "Vencimiento")} {fmtDate(inv.dueDate)}</span>
                <span className="mt-1.5 flex justify-between text-sm">
                  <span className="text-[var(--dim)]">{tr("Total", "Total", "Total")} <strong className="text-[var(--text)]">{fmtUSD(inv.total)}</strong></span>
                  <span className="text-[var(--dim)]">{tr("Balance Due", "Saldo a pagar", "Saldo por pagar")} <strong className="text-[var(--text)]">{fmtUSD(inv.balance)}</strong></span>
                </span>
              </button>
            ))}
          </div>
        )}
      </main>
      <nav className="fixed inset-x-0 bottom-0 z-20 border-t border-[var(--border)] bg-[var(--surface)] pb-[env(safe-area-inset-bottom)]" aria-label={tr("Client portal navigation", "Navegação do portal do cliente", "Navegación del portal del cliente")}>
        <div className="mx-auto flex max-w-5xl">
          <button type="button" aria-label={tr("My projects", "Minhas obras", "Mis obras")} aria-current={tab === "projects" ? "page" : undefined} onClick={() => { setTab("projects"); setOpenProjectId(null); setOpenInvoiceId(null); }} className={`flex flex-1 flex-col items-center gap-0.5 py-2 text-[11px] font-semibold ${tab === "projects" && openProjectId === null ? "text-[#f97316]" : "text-[var(--dim)]"}`}><span className="text-lg leading-none">🏗️</span>{tr("My projects", "Minhas obras", "Mis obras")}</button>
          <button type="button" aria-label={tr("Invoices", "Faturas", "Facturas")} aria-current={tab === "invoices" ? "page" : undefined} onClick={() => { setTab("invoices"); setOpenProjectId(null); setOpenInvoiceId(null); }} className={`flex flex-1 flex-col items-center gap-0.5 py-2 text-[11px] font-semibold ${tab === "invoices" && openInvoiceId === null ? "text-[#f97316]" : "text-[var(--dim)]"}`}><span className="text-lg leading-none">📄</span>{tr("Invoices", "Faturas", "Facturas")}</button>
        </div>
      </nav>
    </div>
  );
}

function ClientProjectDetail({ cid, session, projectId, onBack }: { cid: string; session: Session; projectId: number; onBack: () => void }) {
  const q = useQuery({ queryKey: ["client-project", cid, session.userId, projectId], queryFn: () => api.getClientProjectDetail({ companyId: cid, userId: session.userId, projectId }) });
  const [viewPlan, setViewPlan] = useState<ProjectPlanMeta | null>(null);
  const [photoIdx, setPhotoIdx] = useState<number | null>(null);
  if (q.isPending) return <p className="py-10 text-center text-[var(--dim)]">{tr("Loading project…", "Carregando a obra…", "Cargando la obra…")}</p>;
  const d = q.data;
  if (!d?.project) return <div className="py-10 text-center"><p>{tr("Project not found.", "Obra não encontrada.", "Obra no encontrada.")}</p><button className={`${btnGhost} mt-3`} onClick={onBack}>{tr("Back", "Voltar", "Volver")}</button></div>;
  const p = d.project;
  return (
    <div className="space-y-4">
      <button onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to my projects", "Voltar para minhas obras", "Volver a mis obras")}>{tr("← My projects", "← Minhas obras", "← Mis obras")}</button>
      <div className="rounded-2xl bg-[#0f2a44] p-5 text-white">
        <div className="flex items-start justify-between gap-2"><h2 className="text-lg font-bold leading-snug">{p.name}</h2><Badge text={projectStatusLabel(p.status)} tone={p.status === "andamento" ? "green" : "gray"} /></div>
        {p.address && <p className="mt-1 text-sm text-white/70">📍 {p.address}</p>}
        {(p.startDate || p.endDate) && <p className="mt-1 text-sm text-white/70">{fmtDate(p.startDate)} → {fmtDate(p.endDate)}</p>}
        <div className="mt-4">
          <div className="flex justify-between text-xs font-semibold text-white/60"><span>{tr("Progress", "Andamento", "Progreso")}</span><span>{p.progress}%</span></div>
          <div className="mt-1 h-2.5 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#f97316]" style={{ width: `${p.progress}%` }} /></div>
        </div>
      </div>
      {p.scope && (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Scope of work", "Escopo do trabalho", "Alcance del trabajo")}>
          <h3 className="font-bold">{tr("Scope of work", "Escopo do trabalho", "Alcance del trabajo")}</h3>
          <p className="mt-2 whitespace-pre-line text-sm leading-relaxed">{p.scope}</p>
        </section>
      )}
      {d.jobs.map((j) => (
        <section key={j.id} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={j.name}>
          <div className="flex items-start justify-between gap-2"><h3 className="font-bold">🔧 {j.name}</h3>{jobStatusBadge(j.status)}</div>
          {j.scope && <p className="mt-1 whitespace-pre-line text-sm text-[var(--dim)]">{j.scope}</p>}
          <div className="mt-3 space-y-1.5">
            {j.tasks.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No checklist items yet.", "Nenhum item de checklist ainda.", "Todavía no hay elementos de la lista.")}</p>}
            {j.tasks.map((t) => (
              <div key={t.id} className="flex items-center justify-between gap-2 rounded-lg bg-[var(--surface2)] px-3 py-2">
                <span className="text-sm">{t.status === "done" ? "✅ " : t.status === "in_progress" ? "🔄 " : "⬜ "}{t.title}</span>
                {taskStatusBadge(t.status)}
              </div>
            ))}
          </div>
        </section>
      ))}
      {d.photos.length > 0 && (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Progress photos", "Fotos de andamento", "Fotos de progreso")}>
          <h3 className="font-bold">📷 {tr("Progress photos", "Fotos de andamento", "Fotos de progreso")}</h3>
          <div className="mt-3 grid grid-cols-3 gap-2">
            {d.photos.map((ph, i) => (
              <button key={ph.id} type="button" onClick={() => setPhotoIdx(i)} aria-label={tr(`View progress photo ${i + 1}`, `Ver a foto de andamento ${i + 1}`, `Ver la foto de progreso ${i + 1}`)} className="overflow-hidden rounded-lg active:opacity-70">
                <img src={safeImgSrc(ph.photoUrl)} alt={ph.note || tr("Progress photo", "Foto de andamento", "Foto de progreso")} className="h-24 w-full object-cover" />
              </button>
            ))}
          </div>
        </section>
      )}
      {photoIdx !== null && d.photos[photoIdx] && (
        <div className="fixed inset-0 z-50 flex flex-col bg-black/90 p-4" role="dialog" aria-modal="true" aria-label={tr("Progress photo", "Foto de andamento", "Foto de progreso")}>
          <div className="flex justify-end"><button type="button" aria-label={tr("Close photo", "Fechar a foto", "Cerrar la foto")} onClick={() => setPhotoIdx(null)} className="rounded-lg bg-white px-3 py-1.5 text-sm font-bold text-[#12222f]">{tr("✕ Close", "✕ Fechar", "✕ Cerrar")}</button></div>
          <img src={safeImgSrc(d.photos[photoIdx]!.photoUrl)} alt={d.photos[photoIdx]!.note || tr("Progress photo", "Foto de andamento", "Foto de progreso")} className="mx-auto mt-3 max-h-[75vh] rounded-xl object-contain" />
          <p className="mt-2 text-center text-xs text-white/70">{fmtDate(d.photos[photoIdx]!.createdAt)}{d.photos[photoIdx]!.note ? ` • ${d.photos[photoIdx]!.note}` : ""}</p>
        </div>
      )}
      {d.services.length > 0 && (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Services and measurements", "Serviços e medições", "Servicios y mediciones")}>
          <h3 className="font-bold">🧱 {tr("Services & measurements", "Serviços e medições", "Servicios y mediciones")}</h3>
          <div className="mt-2 space-y-1.5">
            {d.services.map((sv) => (
              <div key={sv.id} className="flex items-center justify-between rounded-lg bg-[var(--surface2)] px-3 py-2 text-sm"><span>{sv.serviceName}</span><span className="font-semibold">{fmtQty(sv.quantity)} {sv.unit}</span></div>
            ))}
          </div>
        </section>
      )}
      {d.plans.length > 0 && (
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Plans and blueprints", "Plantas", "Planos")}>
          <h3 className="font-bold">📐 {tr("Plans & blueprints", "Plantas", "Planos")}</h3>
          <div className="mt-3 space-y-2">
            {d.plans.map((pl) => (
              <button key={pl.id} type="button" onClick={() => setViewPlan(pl)} aria-label={tr(`View plan ${pl.name}`, `Ver a planta ${pl.name}`, `Ver el plano ${pl.name}`)} className="flex w-full items-center gap-3 rounded-xl bg-[var(--surface2)] p-2.5 text-left active:opacity-70">
                {pl.isImage && pl.thumbnailData ? <img src={pl.thumbnailData} alt={tr(`Preview of plan ${pl.name}`, `Pré-visualização da planta ${pl.name}`, `Vista previa del plano ${pl.name}`)} className="h-14 w-14 shrink-0 rounded-lg object-cover" /> : <span className="flex h-14 w-14 shrink-0 flex-col items-center justify-center rounded-lg bg-[var(--surface)] text-[var(--dim)]"><span className="text-xl" aria-hidden="true">📄</span><span className="text-[9px] font-black uppercase">PDF</span></span>}
                <span className="min-w-0"><span className="block truncate text-sm font-semibold">{pl.name}</span><span className="block text-[11px] text-[var(--dim)]">{fmtDate(pl.createdAt)} • {fmtBytes(pl.fileSize)}</span><span className="text-[11px] font-bold text-[#f97316]">{tr("Tap to view full-screen ›", "Toque para ver em tela cheia ›", "Toca para ver en pantalla completa ›")}</span></span>
              </button>
            ))}
          </div>
        </section>
      )}
      {viewPlan && <ClientPlanViewer cid={cid} session={session} plan={viewPlan} onClose={() => setViewPlan(null)} />}
    </div>
  );
}

/* Read-only plan viewer for the portal (bytes via getClientPlanFile). */
function ClientPlanViewer({ cid, session, plan, onClose }: { cid: string; session: Session; plan: ProjectPlanMeta; onClose: () => void }) {
  const q = useQuery({ queryKey: ["client-plan-file", cid, session.userId, plan.id], queryFn: () => api.getClientPlanFile({ companyId: cid, userId: session.userId, planId: plan.id }) });
  const [zoom, setZoom] = useState(1);
  const data = q.data?.fileData ?? "";
  const isPdf = plan.mimeType === "application/pdf";
  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-black/90" role="dialog" aria-modal="true" aria-label={tr(`Plan ${plan.name}`, `Planta ${plan.name}`, `Plano ${plan.name}`)}>
      <div className="flex items-center justify-between gap-2 px-4 pb-2 pt-[max(0.75rem,env(safe-area-inset-top))]">
        <p className="min-w-0 truncate text-sm font-bold text-white">📐 {plan.name}</p>
        <span className="flex shrink-0 items-center gap-1.5">
          {!isPdf && data && (<>
            <button type="button" aria-label={tr("Zoom out plan", "Reduzir o zoom da planta", "Alejar el plano")} onClick={() => setZoom((z) => Math.max(0.5, Math.round((z - 0.25) * 100) / 100))} className="rounded-lg bg-white/15 px-3 py-1.5 text-sm font-black text-white">−</button>
            <span className="min-w-11 text-center text-xs font-bold text-white/80">{Math.round(zoom * 100)}%</span>
            <button type="button" aria-label={tr("Zoom in plan", "Aumentar o zoom da planta", "Acercar el plano")} onClick={() => setZoom((z) => Math.min(4, Math.round((z + 0.25) * 100) / 100))} className="rounded-lg bg-white/15 px-3 py-1.5 text-sm font-black text-white">+</button>
          </>)}
          <button type="button" aria-label={tr("Close plan viewer", "Fechar o visualizador da planta", "Cerrar el visor del plano")} onClick={onClose} className="rounded-lg bg-white px-3 py-1.5 text-sm font-bold text-[#12222f]">{tr("✕ Close", "✕ Fechar", "✕ Cerrar")}</button>
        </span>
      </div>
      <div className="min-h-0 flex-1 px-3 pb-3">
        {q.isPending && <p className="py-10 text-center text-sm text-white/70">{tr("Loading plan…", "Carregando a planta…", "Cargando el plano…")}</p>}
        {q.error && <p className="py-10 text-center text-sm font-semibold text-red-300">{tr("Could not load this plan.", "Não foi possível carregar esta planta.", "No se pudo cargar este plano.")}</p>}
        {!q.isPending && !q.error && data && (isPdf ? <iframe title={plan.name} src={data} className="h-full w-full rounded-xl bg-white" /> : (
          <div className="h-full overflow-auto rounded-xl bg-white/5" style={{ touchAction: "pan-x pan-y pinch-zoom" }}>
            <img src={data} alt={tr(`Plan ${plan.name}`, `Planta ${plan.name}`, `Plano ${plan.name}`)} className="mx-auto block max-w-none" style={{ width: `${zoom * 100}%` }} draggable={false} />
          </div>
        ))}
      </div>
    </div>
  );
}

function ClientInvoiceDetail({ cid, session, invoiceId, onBack }: { cid: string; session: Session; invoiceId: number; onBack: () => void }) {
  const q = useQuery({ queryKey: ["client-invoice", cid, session.userId, invoiceId], queryFn: () => api.getClientInvoiceDetail({ companyId: cid, userId: session.userId, invoiceId }) });
  const [pdfMsg, setPdfMsg] = useState("");
  if (q.isPending) return <p className="py-10 text-center text-[var(--dim)]">{tr("Loading invoice…", "Carregando a fatura…", "Cargando la factura…")}</p>;
  const d = q.data;
  if (!d?.invoice) return <div className="py-10 text-center"><p>{tr("Invoice not found.", "Fatura não encontrada.", "Factura no encontrada.")}</p><button className={`${btnGhost} mt-3`} onClick={onBack}>{tr("Back", "Voltar", "Volver")}</button></div>;
  const inv = d.invoice;
  const accent = d.from?.invoiceAccentColor ?? "#F97316";
  const downloadPdf = async () => {
    setPdfMsg("");
    try {
      const blob = await makeStyledInvoicePdf({
        companyName: session.companyName,
        from: d.from ? { name: d.from.name, address: d.from.address, phone: d.from.phone, email: d.from.email, logoUrl: d.from.logoUrl } : null,
        billTo: d.billTo,
        invoice: { number: inv.number, terms: inv.terms, issueDate: inv.issueDate, dueDate: inv.dueDate, projectAddress: inv.projectAddress, projectName: inv.projectName, status: inv.status, statusLabel: inv.status === "paga" ? tr("Paid", "Paga", "Pagada") : inv.status === "parcial" ? tr("Partial", "Parcial", "Parcial") : inv.status === "vencida" ? tr("Overdue", "Vencida", "Vencida") : tr("Open", "Aberta", "Abierta") },
        items: d.items.map((i) => ({ description: i.description, quantity: i.quantity, unitPrice: i.unitPrice, total: i.total })),
        total: d.total, paid: d.paid, balance: d.balance, accentHex: accent,
        labels: { billTo: tr("Bill to", "Cobrar de", "Facturar a"), invoiceNumber: tr("Invoice #", "Fatura nº", "Factura n.º"), terms: tr("Terms", "Condições", "Condiciones"), invoiceDate: tr("Invoice date", "Data da fatura", "Fecha de la factura"), dueDate: tr("Due date", "Vencimento", "Vencimiento"), ref: tr("Ref.:", "Ref.:", "Ref.:"), description: tr("Description", "Descrição", "Descripción"), quantity: tr("Quantity", "Quantidade", "Cantidad"), rate: tr("Rate", "Valor unit.", "Tarifa"), amount: tr("Amount", "Valor", "Importe"), subtotal: tr("Subtotal", "Subtotal", "Subtotal"), total: tr("Total", "Total", "Total"), paid: tr("Paid", "Pago", "Pagado"), balanceDue: tr("Balance Due", "Saldo a pagar", "Saldo por pagar"), noClient: tr("No client linked", "Nenhum cliente vinculado", "Ningún cliente vinculado"), noItems: tr("No line items", "Nenhum item", "Sin elementos") },
        formatMoney: fmtUSD, formatDate: fmtDate,
      });
      downloadBlob(`invoice-${inv.number}.pdf`, blob);
    } catch { setPdfMsg(tr("Could not generate the PDF. Please try again.", "Não foi possível gerar o PDF. Tente novamente.", "No se pudo generar el PDF. Inténtalo de nuevo.")); }
  };
  return (
    <div className="space-y-4">
      <button onClick={onBack} className="text-sm font-semibold text-[#f97316]" aria-label={tr("Back to invoices", "Voltar para faturas", "Volver a facturas")}>{tr("← Invoices", "← Faturas", "← Facturas")}</button>
      <div className="overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface)]">
        <div className="p-5 text-white" style={{ backgroundColor: accent }}>
          {d.from?.logoUrl ? <img src={safeImgSrc(d.from.logoUrl)} alt={tr(`${d.from.name} logo`, `Logo de ${d.from.name}`, `Logotipo de ${d.from.name}`)} className="mb-2 h-12 w-auto max-w-[140px] rounded-md bg-white object-contain p-1" /> : null}
          <p className="text-xl font-black uppercase leading-tight tracking-wide">{d.from?.name || session.companyName}</p>
          {d.from?.address && <p className="text-sm text-white/85">{d.from.address}</p>}
          {(d.from?.phone || d.from?.email) && <p className="text-sm text-white/85">{[d.from?.phone, d.from?.email].filter(Boolean).join(" • ")}</p>}
        </div>
        <div className="space-y-4 p-5">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <p className="text-xs font-black uppercase tracking-wide" style={{ color: accent }}>{tr("Bill to", "Cobrar de", "Facturar a")}</p>
              <p className="mt-1 font-bold">{d.billTo?.name}</p>
              {d.billTo?.address && <p className="text-sm text-[var(--dim)]">{d.billTo.address}</p>}
              {d.billTo?.email && <p className="text-sm text-[var(--dim)]">{d.billTo.email}</p>}
            </div>
            <div className="text-right text-sm">
              <p><span className="font-bold text-[var(--dim)]">{tr("Invoice #", "Fatura nº", "Factura n.º")}</span> <strong style={{ color: accent }}>{inv.number}</strong></p>
              <p><span className="font-bold text-[var(--dim)]">{tr("Terms", "Condições", "Condiciones")}</span> {inv.terms}</p>
              <p><span className="font-bold text-[var(--dim)]">{tr("Invoice date", "Data da fatura", "Fecha de la factura")}</span> {fmtDate(inv.issueDate)}</p>
              <p><span className="font-bold text-[var(--dim)]">{tr("Due date", "Vencimento", "Vencimiento")}</span> {fmtDate(inv.dueDate)}</p>
              <p className="mt-1">{invBadge(inv.status)}</p>
            </div>
          </div>
          {inv.projectAddress && <p className="rounded-lg px-3 py-2 text-sm" style={{ backgroundColor: `${accent}14` }}><strong style={{ color: accent }}>{tr("Ref.:", "Ref.:", "Ref.:")}</strong> {inv.projectAddress}{inv.projectName ? ` — ${inv.projectName}` : ""}</p>}
          <div className="overflow-hidden rounded-xl border border-[var(--border)]">
            <table className="w-full text-sm">
              <thead><tr className="text-white" style={{ backgroundColor: accent }}><th className="px-3 py-2 text-left">{tr("Description", "Descrição", "Descripción")}</th><th className="px-3 py-2 text-right">{tr("Qty", "Qtd.", "Cant.")}</th><th className="px-3 py-2 text-right">{tr("Rate", "Valor unit.", "Tarifa")}</th><th className="px-3 py-2 text-right">{tr("Amount", "Valor", "Importe")}</th></tr></thead>
              <tbody>
                {d.items.length === 0 && <tr><td colSpan={4} className="px-3 py-4 text-center text-[var(--dim)]">{tr("No line items", "Nenhum item", "Sin elementos")}</td></tr>}
                {d.items.map((i, idx) => (
                  <tr key={i.id} className={idx % 2 === 1 ? "bg-[var(--surface2)]" : ""}><td className="px-3 py-2">{i.description}</td><td className="px-3 py-2 text-right">{i.quantity}</td><td className="px-3 py-2 text-right">{fmtUSD(i.unitPrice)}</td><td className="px-3 py-2 text-right font-semibold">{fmtUSD(i.total)}</td></tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="ml-auto w-full max-w-xs space-y-1 text-sm">
            <div className="flex justify-between"><span className="text-[var(--dim)]">{tr("Subtotal", "Subtotal", "Subtotal")}</span><span>{fmtUSD(d.total)}</span></div>
            <div className="flex justify-between border-t-2 pt-1 font-bold" style={{ borderColor: accent }}><span>{tr("Total", "Total", "Total")}</span><span>{fmtUSD(d.total)}</span></div>
            <div className="flex justify-between text-green-700"><span>{tr("Paid", "Pago", "Pagado")}</span><span>{fmtUSD(d.paid)}</span></div>
            <div className="flex items-center justify-between rounded-lg px-3 py-2 text-white" style={{ backgroundColor: accent }}><span className="text-xs font-black uppercase">{tr("Balance Due", "Saldo a pagar", "Saldo por pagar")}</span><span className="text-lg font-black">{fmtUSD(d.balance)}</span></div>
          </div>
          {d.payments.length > 0 && (
            <div>
              <h3 className="text-sm font-bold">{tr("Payment history", "Histórico de pagamentos", "Historial de pagos")}</h3>
              <div className="mt-2 space-y-1.5">
                {d.payments.map((pay) => (
                  <div key={pay.id} className="flex items-center justify-between rounded-lg bg-[var(--surface2)] px-3 py-2 text-sm"><span>{fmtDate(pay.payDate)} • {pay.method}{pay.notes ? ` • ${pay.notes}` : ""}</span><span className="font-semibold text-green-700">{fmtUSD(pay.amount)}</span></div>
                ))}
              </div>
            </div>
          )}
          <button type="button" onClick={downloadPdf} className={`${btnPrimary} w-full`} aria-label={tr(`Download invoice ${inv.number} as PDF`, `Baixar a fatura ${inv.number} em PDF`, `Descargar la factura ${inv.number} en PDF`)}>⬇ {tr("Download PDF", "Baixar PDF", "Descargar PDF")}</button>
          {pdfMsg && <p className="text-sm font-semibold text-red-600" role="alert">{pdfMsg}</p>}
          <p className="text-center text-xs text-[var(--dim)]">{tr("Questions about this invoice? Contact your contractor directly.", "Dúvidas sobre esta fatura? Fale diretamente com sua construtora.", "¿Dudas sobre esta factura? Habla directamente con tu contratista.")}</p>
        </div>
      </div>
    </div>
  );
}

/* ---------------- Company Settings (admin) ---------------- */
/* Overtime rules (admin): apply to hourly employees only. Payroll splits
   Regular vs OT per Mon–Sun week — daily OT first, then weekly OT. */
function OvertimeSettings({ cid, session }: { cid: string; session: Session }) {
  const qc = useQueryClient();
  const q = useQuery({ queryKey: ["settings", cid], queryFn: () => api.getSettings({ companyId: cid }) });
  const [enabled, setEnabled] = useState(false);
  const [daily, setDaily] = useState("8");
  const [weekly, setWeekly] = useState("40");
  const [multiplier, setMultiplier] = useState("1.5");
  const [loaded, setLoaded] = useState(false);
  const [msg, setMsg] = useState("");
  useEffect(() => {
    if (q.data && !loaded) {
      setEnabled(q.data.otEnabled);
      setDaily(String(q.data.otDailyHours));
      setWeekly(String(q.data.otWeeklyHours));
      setMultiplier(String(q.data.otMultiplier));
      setLoaded(true);
    }
  }, [q.data, loaded]);
  const save = useMutation({
    mutationFn: () => api.updateSettings({
      companyId: cid, actorId: session.userId,
      noShowCutoff: q.data?.noShowCutoff ?? "09:00", autoCloseTime: q.data?.autoCloseTime ?? "17:00",
      otEnabled: enabled,
      otDailyHours: Math.max(0, parseFloat(daily.replace(",", ".")) || 0),
      otWeeklyHours: Math.max(0, parseFloat(weekly.replace(",", ".")) || 0),
      otMultiplier: Math.max(1, parseFloat(multiplier.replace(",", ".")) || 1),
    }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["settings", cid] }); qc.invalidateQueries({ queryKey: ["payroll", cid] }); setMsg(tr("Overtime rules saved. Payroll now splits Regular vs OT for hourly staff. ✅", "Regras de hora extra salvas. A folha agora separa Regular e Extra para funcionários por hora. ✅", "Reglas de horas extra guardadas. La nómina ahora separa Regulares y Extra para el personal por hora. ✅")); },
    onError: () => setMsg(tr("Could not save the overtime rules.", "Não foi possível salvar as regras de hora extra.", "No se pudieron guardar las reglas de horas extra.")),
  });
  return (
    <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Overtime rules", "Regras de hora extra", "Reglas de horas extra")}>
      <h3 className="font-bold">{tr("Overtime (hourly employees)", "Hora extra (funcionários por hora)", "Horas extra (empleados por hora)")}</h3>
      <p className="mt-1 text-sm text-[var(--dim)]">{tr("When on, Payroll splits each hourly worker's week into Regular and OT hours: hours past the daily threshold count as OT first, then hours past the weekly threshold (Mon–Sun) — an hour is never counted twice. Daily-rate and contract pay are not affected.", "Quando ativado, a Folha divide a semana de cada funcionário por hora em horas Regulares e Extras: horas além do limite diário contam como Extra primeiro, depois horas além do limite semanal (seg–dom) — uma hora nunca é contada duas vezes. Pagamento por dia e por contrato não é afetado.", "Cuando está activado, la Nómina divide la semana de cada empleado por hora en horas Regulares y Extra: las horas que superan el límite diario cuentan primero como Extra, luego las que superan el límite semanal (lun–dom): una hora nunca se cuenta dos veces. El pago por día y por contrato no se afecta.")}</p>
      {q.isPending && <p className="mt-3 text-sm text-[var(--dim)]">{tr("Loading…", "Carregando…", "Cargando…")}</p>}
      {loaded && (
        <form className="mt-3 space-y-3" onSubmit={(e) => { e.preventDefault(); save.mutate(); }}>
          <label className="flex items-center gap-2.5 text-sm font-semibold">
            <input type="checkbox" aria-label={tr("Enable overtime", "Ativar hora extra", "Activar horas extra")} checked={enabled} onChange={(e) => setEnabled(e.target.checked)} className="h-5 w-5" />
            {tr("Overtime enabled", "Hora extra ativada", "Horas extra activadas")}
          </label>
          <div className="grid grid-cols-3 gap-3">
            <Field label={tr("Daily threshold (hours)", "Limite diário (horas)", "Límite diario (horas)")}><input aria-label={tr("Daily overtime threshold in hours", "Limite diário de hora extra em horas", "Límite diario de horas extra en horas")} className={inputCls} inputMode="decimal" value={daily} onChange={(e) => setDaily(e.target.value)} disabled={!enabled} /></Field>
            <Field label={tr("Weekly threshold (hours)", "Limite semanal (horas)", "Límite semanal (horas)")}><input aria-label={tr("Weekly overtime threshold in hours", "Limite semanal de hora extra em horas", "Límite semanal de horas extra en horas")} className={inputCls} inputMode="decimal" value={weekly} onChange={(e) => setWeekly(e.target.value)} disabled={!enabled} /></Field>
            <Field label={tr("Multiplier (× rate)", "Multiplicador (× valor)", "Multiplicador (× tarifa)")}><input aria-label={tr("Overtime multiplier", "Multiplicador de hora extra", "Multiplicador de horas extra")} className={inputCls} inputMode="decimal" value={multiplier} onChange={(e) => setMultiplier(e.target.value)} disabled={!enabled} /></Field>
          </div>
          <p className="text-xs text-[var(--dim)]">{tr("Example: with 8h/day, 40h/week at 1.5×, a 10-hour day pays 8 regular + 2 OT; a 45-hour week pays 40 regular + 5 OT (daily OT is not double-counted).", "Exemplo: com 8h/dia, 40h/semana a 1,5×, um dia de 10 horas paga 8 regulares + 2 extras; uma semana de 45 horas paga 40 regulares + 5 extras (a extra diária não é contada em dobro).", "Ejemplo: con 8 h/día, 40 h/semana a 1,5×, un día de 10 horas paga 8 regulares + 2 extra; una semana de 45 horas paga 40 regulares + 5 extra (la extra diaria no se cuenta dos veces).")}</p>
          {msg && <p className="text-sm font-semibold" role="status">{msg}</p>}
          <button className={`${btnNavy} w-full`} disabled={save.isPending}>{save.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save overtime rules", "Salvar regras de hora extra", "Guardar reglas de horas extra")}</button>
        </form>
      )}
    </section>
  );
}

function CompanySettings({ cid, session }: { cid: string; session: Session }) {
  const q = useQuery({ queryKey: ["company-profile", cid], queryFn: () => api.getCompanyProfile({ companyId: cid }) });
  const qc = useQueryClient();
  const { lang, setLang } = useLanguage();
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [addr, setAddr] = useState<AddrParts>(emptyAddr());
  const [accentColor, setAccentColor] = useState("#F97316");
  const [logoDataUrl, setLogoDataUrl] = useState("");
  const [logoBusy, setLogoBusy] = useState(false);
  const [logoMsg, setLogoMsg] = useState("");
  const logoInputRef = useRef<HTMLInputElement | null>(null);
  const [msg, setMsg] = useState("");
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (q.data?.profile && !loaded) {
      setName(q.data.profile.name); setPhone(q.data.profile.phone); setEmail(q.data.profile.email);
      setAddr({ streetNumber: q.data.profile.streetNumber, streetName: q.data.profile.streetName, city: q.data.profile.city, state: q.data.profile.state, zip: q.data.profile.zip });
      setAccentColor(q.data.profile.invoiceAccentColor || "#F97316");
      setLogoDataUrl(q.data.profile.logoUrl || "");
      setLoaded(true);
    }
  }, [q.data, loaded]);
  const accentValid = /^#[0-9a-fA-F]{6}$/.test(accentColor);
  const save = useMutation({
    mutationFn: () => api.updateCompanyProfile({ companyId: cid, actorId: session.userId, name, phone, email, ...addr, invoiceAccentColor: accentColor, logoDataUrl }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ["company-profile", cid] }); qc.invalidateQueries({ queryKey: ["bootstrap"] }); qc.invalidateQueries({ queryKey: ["invoice-detail", cid] }); setMsg(tr("Company profile saved. It now appears at the top of every invoice. ✅", "Perfil da empresa salvo. Ele agora aparece no topo de todas as faturas. ✅", "Perfil de la empresa guardado. Ahora aparece en la parte superior de cada factura. ✅")); },
    onError: () => setMsg(tr("Could not save. Only an admin can edit the company profile.", "Não foi possível salvar. Somente um administrador pode editar o perfil da empresa.", "No se pudo guardar. Solo un administrador puede editar el perfil de la empresa.")),
  });
  const onPickLogo = async (file: File | null) => {
    if (!file) return;
    setLogoBusy(true); setLogoMsg("");
    const data = await readLogoFile(file);
    setLogoBusy(false);
    if (!data) { setLogoMsg(tr("Could not read that image. Please choose a PNG, JPG, or WebP logo.", "Não foi possível ler essa imagem. Escolha um logo em PNG, JPG ou WebP.", "No se pudo leer esa imagen. Elige un logotipo en PNG, JPG o WebP.")); return; }
    setLogoDataUrl(data);
    setLogoMsg(tr("Logo ready — tap Save company profile to put it on your invoices.", "Logo pronto — toque em Salvar perfil da empresa para colocá-lo nas suas faturas.", "Logotipo listo: toca Guardar perfil de la empresa para ponerlo en tus facturas."));
  };
  if (session.role !== "admin") return <p className="py-10 text-center text-[var(--dim)]">{tr("Only an admin can edit Settings.", "Somente um administrador pode editar as Configurações.", "Solo un administrador puede editar Configuración.")}</p>;
  const accentPresets = ["#F97316", "#0F2A44", "#0F766E", "#15803D", "#2563EB", "#DC2626", "#1F2937", "#B45309"];
  return (
    <div className="space-y-4">
      <h2 className="text-xl font-bold">{tr("Settings", "Configurações", "Configuración")}</h2>

      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Language", "Idioma", "Idioma")}>
        <h3 className="font-bold">{tr("Language", "Idioma", "Idioma")}</h3>
        <p className="mt-1 text-sm text-[var(--dim)]">{tr("Choose the interface language. Money (USD), measurements (feet), and dates (MM/DD/YYYY) always stay in the US format.", "Escolha o idioma da interface. Dinheiro (USD), medidas (pés) e datas (MM/DD/YYYY) sempre permanecem no formato americano.", "Elige el idioma de la interfaz. El dinero (USD), las medidas (pies) y las fechas (MM/DD/YYYY) siempre se mantienen en formato de EE. UU.")}</p>
        <div className="mt-3 grid grid-cols-3 gap-2" role="radiogroup" aria-label={tr("Interface language", "Idioma da interface", "Idioma de la interfaz")}>
          <button type="button" role="radio" aria-checked={lang === "en"} aria-label={tr("Interface language: English", "Idioma da interface: inglês", "Idioma de la interfaz: inglés")} onClick={() => setLang("en")} className={`rounded-xl border px-3 py-3 text-left ${lang === "en" ? "border-[#f97316] bg-[#f97316] text-white" : "border-[var(--border)] bg-[var(--surface)]"}`}>
            <span className="block text-sm font-black">English</span><span className={`block text-xs ${lang === "en" ? "text-white/85" : "text-[var(--dim)]"}`}>EN — US English</span>
          </button>
          <button type="button" role="radio" aria-checked={lang === "pt"} aria-label={tr("Interface language: Portuguese", "Idioma da interface: português", "Idioma de la interfaz: portugués")} onClick={() => setLang("pt")} className={`rounded-xl border px-3 py-3 text-left ${lang === "pt" ? "border-[#f97316] bg-[#f97316] text-white" : "border-[var(--border)] bg-[var(--surface)]"}`}>
            <span className="block text-sm font-black">Português</span><span className={`block text-xs ${lang === "pt" ? "text-white/85" : "text-[var(--dim)]"}`}>PT — Português (Brasil)</span>
          </button>
          <button type="button" role="radio" aria-checked={lang === "es"} aria-label={tr("Interface language: Spanish", "Idioma da interface: espanhol", "Idioma de la interfaz: español")} onClick={() => setLang("es")} className={`rounded-xl border px-3 py-3 text-left ${lang === "es" ? "border-[#f97316] bg-[#f97316] text-white" : "border-[var(--border)] bg-[var(--surface)]"}`}>
            <span className="block text-sm font-black">Español</span><span className={`block text-xs ${lang === "es" ? "text-white/85" : "text-[var(--dim)]"}`}>ES — Español (Latinoamérica)</span>
          </button>
        </div>
      </section>

      <OvertimeSettings cid={cid} session={session} />
      <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Company profile", "Perfil da empresa", "Perfil de la empresa")}>
        <h3 className="font-bold">{tr("Company profile — invoice header", "Perfil da empresa — cabeçalho da fatura", "Perfil de la empresa: encabezado de la factura")}</h3>
        <p className="mt-1 text-sm text-[var(--dim)]">{tr("This is the “from” block printed at the top of every invoice, like the contractor header on your reference invoice.", "Este é o bloco do remetente impresso no topo de todas as faturas, como o cabeçalho do empreiteiro na sua fatura de referência.", "Este es el bloque del remitente que se imprime en la parte superior de cada factura, como el encabezado del contratista en tu factura de referencia.")}</p>
        {q.isPending && <p className="mt-3 text-sm text-[var(--dim)]">{tr("Loading…", "Carregando…", "Cargando…")}</p>}
        <form className="mt-3 space-y-4" onSubmit={(e) => { e.preventDefault(); save.mutate(); }}>
          <Field label={tr("Company name", "Nome da empresa", "Nombre de la empresa")}><input aria-label={tr("Company name", "Nome da empresa", "Nombre de la empresa")} autoComplete="organization" className={inputCls} value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. JPS GENERAL CONSTRUCTION" required /></Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label={tr("Phone", "Telefone", "Teléfono")}><input aria-label={tr("Company phone", "Telefone da empresa", "Teléfono de la empresa")} autoComplete="tel" type="tel" className={inputCls} value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="(732) 555-0100" /></Field>
            <Field label={tr("Email", "E-mail", "Correo electrónico")}><input aria-label={tr("Company email", "E-mail da empresa", "Correo de la empresa")} autoComplete="email" type="email" className={inputCls} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="billing@company.com" /></Field>
          </div>
          <div>
            <span className="mb-1 block text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Company address", "Endereço da empresa", "Dirección de la empresa")}</span>
            <AddressForm idPrefix="company" value={addr} onChange={setAddr} />
          </div>

          <div className="rounded-xl bg-[var(--surface2)] p-3">
            <span className="block text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Company logo", "Logo da empresa", "Logotipo de la empresa")}</span>
            <div className="mt-2 flex flex-wrap items-center gap-3">
              {logoDataUrl ? (
                <img src={safeImgSrc(logoDataUrl)} alt={tr(`${name || "Company"} logo`, `Logo de ${name || "empresa"}`, `Logotipo de ${name || "la empresa"}`)} className="h-16 w-auto max-w-[180px] rounded-lg bg-white object-contain p-1 ring-1 ring-[var(--border)]" />
              ) : (
                <span className="flex h-16 w-28 items-center justify-center rounded-lg bg-white px-2 text-center text-[11px] font-bold text-[var(--dim)] ring-1 ring-[var(--border)]">{tr("No logo yet", "Nenhum logo ainda", "Todavía no hay logotipo")}</span>
              )}
              <span className="flex flex-wrap gap-2">
                <button type="button" aria-label={tr("Upload logo", "Enviar logo", "Subir logotipo")} disabled={logoBusy} onClick={() => logoInputRef.current?.click()} className="rounded-xl bg-[#0f2a44] px-4 py-2.5 text-sm font-bold text-white active:opacity-80 disabled:opacity-40">{logoBusy ? tr("Loading…", "Carregando…", "Cargando…") : tr("Upload logo", "Enviar logo", "Subir logotipo")}</button>
                {logoDataUrl && <button type="button" aria-label={tr("Remove logo", "Remover logo", "Quitar logotipo")} onClick={() => { setLogoDataUrl(""); setLogoMsg(tr("Logo removed — tap Save company profile to confirm.", "Logo removido — toque em Salvar perfil da empresa para confirmar.", "Logotipo quitado: toca Guardar perfil de la empresa para confirmar.")); }} className="rounded-xl border border-[var(--border)] bg-[var(--surface)] px-4 py-2.5 text-sm font-bold active:opacity-80">{tr("Remove logo", "Remover logo", "Quitar logotipo")}</button>}
              </span>
              <input ref={logoInputRef} type="file" accept="image/png,image/jpeg,image/webp" className="hidden" aria-label={tr("Company logo image file", "Arquivo de imagem do logo da empresa", "Archivo de imagen del logotipo de la empresa")} onChange={(e) => { void onPickLogo(e.target.files?.[0] ?? null); e.target.value = ""; }} />
            </div>
            <p className="mt-2 text-xs text-[var(--dim)]">{tr("The logo is resized to fit the invoice header (max 512 px) and prints next to your company name. Without a logo, invoices show the name only.", "O logo é redimensionado para caber no cabeçalho da fatura (máx. 512 px) e é impresso ao lado do nome da sua empresa. Sem logo, as faturas mostram somente o nome.", "El logotipo se ajusta para caber en el encabezado de la factura (máx. 512 px) y se imprime junto al nombre de tu empresa. Sin logotipo, las facturas muestran solo el nombre.")}</p>
            {logoMsg && <p className="mt-1 text-xs font-semibold" role="status">{logoMsg}</p>}
          </div>

          <div className="rounded-xl bg-[var(--surface2)] p-3">
            <span className="block text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Invoice accent color", "Cor de destaque da fatura", "Color de acento de la factura")}</span>
            <p className="mt-1 text-xs text-[var(--dim)]">{tr("Used on every invoice: the header band, the items table header, dividers, and the highlighted Balance Due box. Default: construction orange.", "Usada em todas as faturas: a faixa do cabeçalho, o cabeçalho da tabela de itens, os divisores e a caixa de destaque do Saldo a pagar. Padrão: laranja construção.", "Se usa en todas las facturas: la banda del encabezado, el encabezado de la tabla de conceptos, los separadores y el recuadro destacado de Saldo por pagar. Predeterminado: naranja construcción.")}</p>
            <div className="mt-2 flex flex-wrap items-center gap-2" role="radiogroup" aria-label={tr("Invoice accent color", "Cor de destaque da fatura", "Color de acento de la factura")}>
              {accentPresets.map((c) => (
                <button key={c} type="button" role="radio" aria-checked={accentColor.toUpperCase() === c} aria-label={tr(`Invoice accent color ${c}`, `Cor de destaque da fatura ${c}`, `Color de acento de la factura ${c}`)} onClick={() => setAccentColor(c)} className={`h-9 w-9 shrink-0 rounded-full ring-2 ring-offset-2 ${accentColor.toUpperCase() === c ? "ring-[#0f2a44]" : "ring-transparent"}`} style={{ backgroundColor: c }} />
              ))}
              <label className="flex items-center gap-2 rounded-lg bg-white px-2 py-1 ring-1 ring-[var(--border)]">
                <input type="color" aria-label={tr("Custom invoice accent color", "Cor personalizada de destaque da fatura", "Color de acento personalizado de la factura")} value={accentValid ? accentColor : "#F97316"} onChange={(e) => setAccentColor(e.target.value.toUpperCase())} className="h-8 w-10 cursor-pointer bg-transparent" />
                <input aria-label={tr("Invoice accent color hex value", "Valor hexadecimal da cor de destaque da fatura", "Valor hexadecimal del color de acento de la factura")} value={accentColor} onChange={(e) => setAccentColor(e.target.value.toUpperCase())} className="w-24 bg-transparent font-mono text-sm uppercase outline-none" placeholder="#F97316" />
              </label>
            </div>
            <div className="mt-3 overflow-hidden rounded-lg ring-1 ring-[var(--border)]" aria-label={tr("Invoice color preview", "Pré-visualização das cores da fatura", "Vista previa de colores de la factura")}>
              <div className="flex items-center gap-2 px-3 py-2 text-white" style={{ backgroundColor: accentValid ? accentColor : "#F97316" }}>
                {logoDataUrl ? <img src={safeImgSrc(logoDataUrl)} alt="" className="h-6 w-auto max-w-[72px] rounded bg-white object-contain p-0.5" /> : null}
                <span className="truncate text-xs font-black uppercase tracking-wide">{name || tr("Your company", "Sua empresa", "Tu empresa")}</span>
              </div>
              <div className="flex items-center justify-between bg-white px-3 py-2 text-[11px] font-bold text-[#12222f]"><span>{tr("Items table header", "Cabeçalho da tabela de itens", "Encabezado de la tabla de conceptos")}</span><span className="rounded px-2 py-1 text-white" style={{ backgroundColor: accentValid ? accentColor : "#F97316" }}>{tr("Balance Due", "Saldo a pagar", "Saldo por pagar")}</span></div>
            </div>
          </div>

          {addr.streetName && <p className="rounded-xl bg-[var(--surface2)] px-3 py-2 text-sm text-[var(--dim)]">{tr("Invoice header preview:", "Pré-visualização do cabeçalho da fatura:", "Vista previa del encabezado de la factura:")} <strong className="text-[var(--text)]">{name || "—"}</strong>{formatAddr(addr) ? `, ${formatAddr(addr)}` : ""}</p>}
          {msg && <p className="text-sm font-semibold" role="status">{msg}</p>}
          <button className={`${btnNavy} w-full`} disabled={save.isPending || !name.trim() || !accentValid}>{save.isPending ? tr("Saving…", "Salvando…", "Guardando…") : tr("Save company profile", "Salvar perfil da empresa", "Guardar perfil de la empresa")}</button>
        </form>
      </section>
      <p className="rounded-xl bg-[var(--surface)] px-3 py-2 text-xs text-[var(--dim)]">{tr("Time-clock rules (no-show cutoff and auto-close time) are on the Dashboard.", "As regras de ponto (horário de falta e fechamento automático) estão no Painel.", "Las reglas de registro de horas (hora límite de ausencia y hora de cierre automático) están en el Panel.")}</p>
    </div>
  );
}


/* ---------------- Platform Owner (super-admin) ---------------- */
type TenantRow = {
  id: string; name: string; code: string; status: string; plan: string; createdAt: string;
  counts: { users: number; projects: number; jobs: number; timesheets: number; invoices: number };
  totalRows: number; storageBytes: number;
};
const TENANT_STATUS_LABEL: Record<string, string> = { trial: "Trial", active: "Active", suspended: "Suspended" };
function tenantStatusLabel(status: string): string {
  if (status === "trial") return tr("Trial", "Teste", "Prueba");
  if (status === "active") return tr("Active", "Ativa", "Activa");
  if (status === "suspended") return tr("Suspended", "Suspensa", "Suspendida");
  return TENANT_STATUS_LABEL[status] ?? status;
}

function OwnerPanel({ ownerEmail, ownerName, onSignOut }: { ownerEmail: string; ownerName: string; onSignOut: () => void }) {
  const qc = useQueryClient();
  const q = useQuery({ queryKey: ["tenants", ownerEmail], queryFn: () => api.listTenants({ ownerEmail }) });
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState<"name" | "created" | "users" | "status">("name");
  const [msg, setMsg] = useState("");
  const [showCreate, setShowCreate] = useState(false);
  const [coName, setCoName] = useState("");
  const [adminName, setAdminName] = useState("");
  const [adminEmail, setAdminEmail] = useState("");
  const [createdMsg, setCreatedMsg] = useState("");
  const [exportedIds, setExportedIds] = useState<Set<string>>(new Set());
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [isoResult, setIsoResult] = useState<{ ok: boolean; tenantCount: number; checks: { name: string; ok: boolean; detail: string }[] } | null>(null);

  const invalidate = () => { qc.invalidateQueries({ queryKey: ["tenants", ownerEmail] }); qc.invalidateQueries({ queryKey: ["bootstrap"] }); };
  const createTenant = useMutation({
    mutationFn: () => api.createTenant({ ownerEmail, companyName: coName, adminName, adminEmail }),
    onSuccess: (r) => {
      invalidate();
      setCreatedMsg(tr(`Tenant created: ${coName} (${r.code}). ${adminName} can sign in right away from the company login screen — the tenant starts empty.`, `Empresa cliente criada: ${coName} (${r.code}). ${adminName} já pode entrar pela tela de login da empresa — ela começa vazia.`, `Empresa cliente creada: ${coName} (${r.code}). ${adminName} ya puede iniciar sesión desde la pantalla de inicio de la empresa: empieza vacía.`));
      setCoName(""); setAdminName(""); setAdminEmail(""); setShowCreate(false);
    },
    onError: (e) => setCreatedMsg(e instanceof Error ? e.message : tr("Could not create the tenant.", "Não foi possível criar a empresa cliente.", "No se pudo crear la empresa cliente.")),
  });
  const setStatus = useMutation({
    mutationFn: (args: { companyId: string; status: "trial" | "active" | "suspended" }) => api.setTenantStatus({ ownerEmail, ...args }),
    onSuccess: (_r, args) => { invalidate(); setMsg(args.status === "suspended" ? tr("Tenant suspended. Its users can no longer sign in; all data is preserved.", "Empresa cliente suspensa. Seus usuários não podem mais entrar; todos os dados estão preservados.", "Empresa cliente suspendida. Sus usuarios ya no pueden iniciar sesión; todos los datos se conservan.") : tr("Tenant reactivated. Its users can sign in again.", "Empresa cliente reativada. Seus usuários já podem entrar novamente.", "Empresa cliente reactivada. Sus usuarios ya pueden iniciar sesión de nuevo.")); },
    onError: () => setMsg(tr("Could not change the tenant status.", "Não foi possível alterar o status da empresa cliente.", "No se pudo cambiar el estado de la empresa cliente.")),
  });
  const setPlan = useMutation({
    mutationFn: (args: { companyId: string; plan: string }) => api.setTenantPlan({ ownerEmail, ...args }),
    onSuccess: () => invalidate(),
  });
  const exportMut = useMutation({
    mutationFn: (companyId: string) => api.exportTenant({ ownerEmail, companyId }),
  });
  const doExport = async (t: TenantRow, format: "json" | "sql") => {
    try {
      const r = await exportMut.mutateAsync(t.id);
      const base = `smartbuilder-tenant-${t.code.toLowerCase()}`;
      if (format === "json") downloadTextFile(`${base}.json`, r.json, "application/json");
      else downloadTextFile(`${base}.sql`, r.sql, "application/sql");
      setExportedIds((prev) => new Set(prev).add(t.id));
      setMsg(tr(`Export downloaded for ${t.name} (${r.totalRows} rows). Keep it safe — deleting this tenant will require this step.`, `Exportação baixada de ${t.name} (${r.totalRows} linhas). Guarde com segurança — excluir esta empresa exigirá esta etapa.`, `Exportación descargada de ${t.name} (${r.totalRows} filas). Guárdala con seguridad: eliminar esta empresa requerirá este paso.`));
    } catch {
      setMsg(tr("Export failed. Please try again.", "A exportação falhou. Tente novamente.", "La exportación falló. Inténtalo de nuevo."));
    }
  };
  const deleteTenant = useMutation({
    mutationFn: (companyId: string) => api.deleteTenant({ ownerEmail, companyId, exportConfirmed: true }),
    onSuccess: () => { invalidate(); setConfirmDeleteId(null); setMsg(tr("Tenant and all of its data were permanently deleted.", "A empresa cliente e todos os seus dados foram excluídos permanentemente.", "La empresa cliente y todos sus datos se eliminaron permanentemente.")); },
    onError: (e) => setMsg(e instanceof Error ? e.message : tr("Could not delete the tenant.", "Não foi possível excluir a empresa cliente.", "No se pudo eliminar la empresa cliente.")),
  });
  const runIso = useMutation({
    mutationFn: () => api.runIsolationCheck({ ownerEmail }),
    onSuccess: (r) => setIsoResult(r),
  });

  const tenants = (q.data?.tenants ?? []).filter((t) => t.name.toLowerCase().includes(search.trim().toLowerCase()) || t.code.toLowerCase().includes(search.trim().toLowerCase()));
  const sorted = [...tenants].sort((a, b) => {
    if (sortBy === "users") return b.counts.users - a.counts.users;
    if (sortBy === "created") return b.createdAt.localeCompare(a.createdAt);
    if (sortBy === "status") return a.status.localeCompare(b.status) || a.name.localeCompare(b.name);
    return a.name.localeCompare(b.name);
  });

  const statusBadge = (s: string) => (
    <span className={`inline-block rounded-full px-2 py-0.5 text-[11px] font-bold ${s === "active" ? "bg-green-100 text-green-800" : s === "suspended" ? "bg-red-100 text-red-700" : "bg-amber-100 text-amber-800"}`}>{tenantStatusLabel(s)}</span>
  );

  return (
    <div className="min-h-screen bg-[var(--bg)] pb-10 text-[var(--text)]">
      <header className="sticky top-0 z-20 bg-[#0f2a44] px-4 pb-3 pt-[max(0.75rem,env(safe-area-inset-top))] text-white shadow">
        <div className="mx-auto flex max-w-5xl items-center justify-between gap-2">
          <div className="flex min-w-0 items-center gap-2.5">
            <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#f97316] text-sm font-black">SB</div>
            <div className="min-w-0">
              <p className="truncate text-sm font-bold leading-tight">{tr("SmartBuilder — Platform owner", "SmartBuilder — Proprietário da plataforma", "SmartBuilder: propietario de la plataforma")}</p>
              <p className="truncate text-xs text-white/60">{ownerName ? `${ownerName} • ` : ""}{ownerEmail}</p>
            </div>
          </div>
          <span className="flex shrink-0 items-center gap-2">
            <button aria-label={tr("Switch user — sign out of the platform owner panel and return to the main login screen", "Trocar usuário — sair do painel do proprietário e voltar para a tela de login principal", "Cambiar de usuario: salir del panel del propietario y volver a la pantalla principal de inicio de sesión")} onClick={onSignOut} className="shrink-0 rounded-lg bg-[#f97316] px-3 py-2 text-xs font-bold text-white shadow-sm active:opacity-80">{tr("Switch user", "Trocar usuário", "Cambiar de usuario")}</button>
            <button aria-label={tr("Sign out of the platform owner panel", "Sair do painel do proprietário da plataforma", "Cerrar sesión del panel del propietario de la plataforma")} onClick={onSignOut} className="shrink-0 rounded-lg bg-white/10 px-3 py-2 text-xs font-semibold active:opacity-70">{tr("Sign out", "Sair", "Cerrar sesión")}</button>
          </span>
        </div>
      </header>

      <main className="mx-auto max-w-5xl space-y-4 px-4 pt-4">
        {msg && <p className="rounded-xl bg-[var(--surface)] px-4 py-3 text-sm font-semibold ring-1 ring-[var(--border)]" role="status">{msg}</p>}

        {/* Production architecture */}
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Production architecture", "Arquitetura de produção", "Arquitectura de producción")}>
          <h2 className="font-bold">{tr("Production architecture", "Arquitetura de produção", "Arquitectura de producción")}</h2>
          <p className="mt-1 text-sm leading-relaxed text-[var(--dim)]">
            {tr("The recommended production setup is", "A configuração de produção recomendada é", "La configuración de producción recomendada es")} <strong className="text-[var(--text)]">{tr("database-per-tenant MySQL", "MySQL com um banco por empresa cliente", "MySQL con una base de datos por empresa cliente")}</strong>: {tr("one MySQL database per customer company", "um banco MySQL por empresa cliente", "una base de datos MySQL por empresa cliente")}
            (<span className="font-mono text-xs">smartbuilder_tenant_&lt;id&gt;</span>), {tr("plus one small platform database with the tenant registry and owner logins.", "mais um pequeno banco da plataforma com o cadastro das empresas e os logins dos proprietários.", "más una pequeña base de datos de la plataforma con el registro de empresas y los inicios de sesión de los propietarios.")}
            {tr("No customer ever shares tables with another customer. The pilot already keys every row by tenant, and the per-tenant export below", "Nenhum cliente compartilha tabelas com outro cliente. O piloto já vincula cada linha à sua empresa, e a exportação por empresa abaixo", "Ningún cliente comparte tablas con otro cliente. El piloto ya vincula cada fila a su empresa, y la exportación por empresa de abajo")}
            {tr("(JSON or MySQL SQL dump) makes migrating a tenant into its own database mechanical: create the database, run the production", "(JSON ou dump SQL do MySQL) torna mecânica a migração de uma empresa para seu próprio banco: crie o banco, execute o", "(JSON o volcado SQL de MySQL) hace mecánica la migración de una empresa a su propia base de datos: crea la base de datos, ejecuta el")}
            {tr("schema file, import the tenant's dump, register the tenant.", "arquivo de esquema de produção, importe o dump da empresa, cadastre a empresa.", "archivo de esquema de producción, importa el volcado de la empresa, registra la empresa.")}
          </p>
        </section>

        {/* Tenants */}
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Tenants", "Empresas clientes", "Empresas cliente")}>
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h2 className="font-bold">{tr("Tenants", "Empresas clientes", "Empresas cliente")} ({q.data?.tenants.length ?? 0})</h2>
            <button className={btnPrimary} onClick={() => { setShowCreate((s) => !s); setCreatedMsg(""); }} aria-label={tr("Create a new tenant", "Criar uma nova empresa cliente", "Crear una nueva empresa cliente")}>{showCreate ? tr("Close", "Fechar", "Cerrar") : tr("+ New tenant", "+ Nova empresa", "+ Nueva empresa")}</button>
          </div>

          {showCreate && (
            <form className="mt-3 space-y-3 rounded-xl bg-[var(--surface2)] p-3" onSubmit={(e) => { e.preventDefault(); createTenant.mutate(); }}>
              <p className="text-sm font-semibold">{tr("Provision a new tenant — it starts with an empty dataset and one admin login.", "Crie uma nova empresa cliente — ela começa com um conjunto de dados vazio e um login de administrador.", "Crea una nueva empresa cliente: empieza con un conjunto de datos vacío y un inicio de sesión de administrador.")}</p>
              <Field label={tr("Company name", "Nome da empresa", "Nombre de la empresa")}><input aria-label={tr("New tenant company name", "Nome da nova empresa cliente", "Nombre de la nueva empresa cliente")} className={inputCls} value={coName} onChange={(e) => setCoName(e.target.value)} placeholder={tr("E.g.: ABC Builders LLC", "Ex.: ABC Builders LLC", "Ej.: ABC Builders LLC")} required /></Field>
              <div className="grid gap-3 sm:grid-cols-2">
                <Field label={tr("Admin name", "Nome do administrador", "Nombre del administrador")}><input aria-label={tr("New tenant admin name", "Nome do administrador da nova empresa", "Nombre del administrador de la nueva empresa")} className={inputCls} value={adminName} onChange={(e) => setAdminName(e.target.value)} placeholder={tr("Person who will run the company", "Pessoa que administrará a empresa", "Persona que administrará la empresa")} required /></Field>
                <Field label={tr("Admin email", "E-mail do administrador", "Correo del administrador")}><input aria-label={tr("New tenant admin email", "E-mail do administrador da nova empresa", "Correo del administrador de la nueva empresa")} type="email" className={inputCls} value={adminEmail} onChange={(e) => setAdminEmail(e.target.value)} placeholder="admin@company.com" required /></Field>
              </div>
              <button className={`${btnNavy} w-full`} disabled={createTenant.isPending || !coName.trim() || !adminName.trim() || !adminEmail.trim()}>{createTenant.isPending ? tr("Provisioning…", "Criando…", "Creando…") : tr("Create tenant", "Criar empresa", "Crear empresa")}</button>
            </form>
          )}
          {createdMsg && <p className="mt-2 rounded-xl bg-green-100 px-3 py-2 text-sm font-semibold text-green-800" role="status">✅ {createdMsg}</p>}

          <div className="mt-3 flex flex-wrap gap-2">
            <input aria-label={tr("Search tenants", "Buscar empresas clientes", "Buscar empresas cliente")} className={`${inputCls} min-w-0 flex-1`} value={search} onChange={(e) => setSearch(e.target.value)} placeholder={tr("Search by company name or code…", "Buscar pelo nome ou código da empresa…", "Buscar por nombre o código de la empresa…")} />
            <select aria-label={tr("Sort tenants", "Ordenar empresas clientes", "Ordenar empresas cliente")} className="rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm" value={sortBy} onChange={(e) => setSortBy(e.target.value as typeof sortBy)}>
              <option value="name">{tr("Sort: Name", "Ordenar: Nome", "Ordenar: Nombre")}</option>
              <option value="created">{tr("Sort: Newest", "Ordenar: Mais recentes", "Ordenar: Más recientes")}</option>
              <option value="users">{tr("Sort: Most users", "Ordenar: Mais usuários", "Ordenar: Más usuarios")}</option>
              <option value="status">{tr("Sort: Status", "Ordenar: Status", "Ordenar: Estado")}</option>
            </select>
          </div>

          {q.isPending && <p className="py-6 text-center text-sm text-[var(--dim)]">{tr("Loading tenants…", "Carregando as empresas clientes…", "Cargando las empresas cliente…")}</p>}
          {q.error && <p className="py-6 text-center text-sm text-red-600">{tr("Could not load tenants.", "Não foi possível carregar as empresas clientes.", "No se pudieron cargar las empresas cliente.")} <button className="underline" onClick={() => q.refetch()}>{tr("Retry", "Tentar novamente", "Reintentar")}</button></p>}
          {q.data && sorted.length === 0 && <p className="py-6 text-center text-sm text-[var(--dim)]">{tr("No tenants match your search.", "Nenhuma empresa corresponde à sua busca.", "Ninguna empresa coincide con tu búsqueda.")}</p>}

          {sorted.length > 0 && (
            <div className="mt-3 overflow-x-auto rounded-xl border border-[var(--border)]">
              <table className="w-full text-left text-sm">
                <thead>
                  <tr className="bg-[var(--surface2)] text-[11px] uppercase tracking-wide text-[var(--dim)]">
                    <th className="px-3 py-2 font-bold">{tr("Company", "Empresa", "Empresa")}</th>
                    <th className="px-3 py-2 font-bold">{tr("Status", "Status", "Estado")}</th>
                    <th className="hidden px-3 py-2 font-bold md:table-cell">{tr("Plan", "Plano", "Plan")}</th>
                    <th className="hidden px-3 py-2 font-bold lg:table-cell">{tr("Created", "Criada em", "Creada el")}</th>
                    <th className="px-3 py-2 text-right font-bold">{tr("Users", "Usuários", "Usuarios")}</th>
                    <th className="hidden px-3 py-2 text-right font-bold sm:table-cell">{tr("Projects", "Obras", "Obras")}</th>
                    <th className="hidden px-3 py-2 text-right font-bold md:table-cell">{tr("Jobs", "Trabalhos", "Trabajos")}</th>
                    <th className="hidden px-3 py-2 text-right font-bold md:table-cell">{tr("Timesheets", "Registros de ponto", "Registros de horas")}</th>
                    <th className="hidden px-3 py-2 text-right font-bold md:table-cell">{tr("Invoices", "Faturas", "Facturas")}</th>
                    <th className="hidden px-3 py-2 text-right font-bold lg:table-cell">{tr("Storage", "Armazenamento", "Almacenamiento")}</th>
                    <th className="px-3 py-2 text-right font-bold">{tr("Actions", "Ações", "Acciones")}</th>
                  </tr>
                </thead>
                <tbody>
                  {sorted.map((t) => {
                    const exported = exportedIds.has(t.id);
                    return (
                      <tr key={t.id} className="border-t border-[var(--border)] align-top">
                        <td className="px-3 py-2.5">
                          <p className="font-bold leading-snug">{t.name}</p>
                          <p className="font-mono text-[11px] text-[var(--dim)]">{t.code} • {t.totalRows} {tr("rows", "linhas", "filas")}</p>
                        </td>
                        <td className="px-3 py-2.5">{statusBadge(t.status)}</td>
                        <td className="hidden px-3 py-2.5 md:table-cell">
                          <select aria-label={tr(`Plan for ${t.name}`, `Plano de ${t.name}`, `Plan de ${t.name}`)} className="rounded-lg border border-[var(--border)] bg-[var(--surface)] px-2 py-1 text-xs" value={t.plan}
                            onChange={(e) => setPlan.mutate({ companyId: t.id, plan: e.target.value })} disabled={setPlan.isPending}>
                            {["Pilot", "Trial", "Pro", "Enterprise"].includes(t.plan) ? null : <option value={t.plan}>{t.plan}</option>}
                            <option value="Pilot">Pilot</option><option value="Trial">Trial</option><option value="Pro">Pro</option><option value="Enterprise">Enterprise</option>
                          </select>
                        </td>
                        <td className="hidden px-3 py-2.5 text-[var(--dim)] lg:table-cell">{t.createdAt ? fmtDate(t.createdAt) : "—"}</td>
                        <td className="px-3 py-2.5 text-right font-semibold">{t.counts.users}</td>
                        <td className="hidden px-3 py-2.5 text-right sm:table-cell">{t.counts.projects}</td>
                        <td className="hidden px-3 py-2.5 text-right md:table-cell">{t.counts.jobs}</td>
                        <td className="hidden px-3 py-2.5 text-right md:table-cell">{t.counts.timesheets}</td>
                        <td className="hidden px-3 py-2.5 text-right md:table-cell">{t.counts.invoices}</td>
                        <td className="hidden px-3 py-2.5 text-right text-[var(--dim)] lg:table-cell">{fmtBytes(t.storageBytes)}</td>
                        <td className="px-3 py-2.5">
                          <div className="flex flex-col items-end gap-1.5">
                            {t.status === "suspended" ? (
                              <button aria-label={tr(`Reactivate ${t.name}`, `Reativar ${t.name}`, `Reactivar ${t.name}`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate({ companyId: t.id, status: "active" })} className="rounded-lg bg-green-600 px-3 py-1.5 text-xs font-bold text-white active:opacity-80">{tr("Reactivate", "Reativar", "Reactivar")}</button>
                            ) : (
                              <button aria-label={tr(`Suspend ${t.name}`, `Suspender ${t.name}`, `Suspender ${t.name}`)} disabled={setStatus.isPending} onClick={() => setStatus.mutate({ companyId: t.id, status: "suspended" })} className="rounded-lg bg-amber-100 px-3 py-1.5 text-xs font-bold text-amber-800 active:opacity-80">{tr("Suspend", "Suspender", "Suspender")}</button>
                            )}
                            {confirmDeleteId === t.id ? (
                              <span className="flex items-center gap-1">
                                <button aria-label={tr(`Cancel deleting ${t.name}`, `Cancelar a exclusão de ${t.name}`, `Cancelar la eliminación de ${t.name}`)} onClick={() => setConfirmDeleteId(null)} className="rounded-lg border border-[var(--border)] px-2.5 py-1.5 text-xs font-bold">{tr("Keep", "Manter", "Conservar")}</button>
                                <button aria-label={tr(`Permanently delete ${t.name}`, `Excluir permanentemente ${t.name}`, `Eliminar permanentemente ${t.name}`)} disabled={deleteTenant.isPending} onClick={() => deleteTenant.mutate(t.id)} className="rounded-lg bg-red-600 px-2.5 py-1.5 text-xs font-bold text-white active:opacity-80 disabled:opacity-40">{deleteTenant.isPending ? tr("Deleting…", "Excluindo…", "Eliminando…") : tr("Delete forever", "Excluir para sempre", "Eliminar para siempre")}</button>
                              </span>
                            ) : (
                              <button aria-label={tr(`Delete ${t.name}`, `Excluir ${t.name}`, `Eliminar ${t.name}`)} disabled={!exported} onClick={() => setConfirmDeleteId(t.id)}
                                className="rounded-lg bg-red-100 px-3 py-1.5 text-xs font-bold text-red-700 active:opacity-80 disabled:opacity-40">
                                {tr("Delete", "Excluir", "Eliminar")}
                              </button>
                            )}
                          </div>
                          {!exported && <p className="mt-1 max-w-[11rem] text-right text-[10px] leading-tight text-[var(--dim)]">{tr("Export the database below first to unlock delete.", "Exporte o banco abaixo primeiro para liberar a exclusão.", "Primero exporta la base de datos de abajo para desbloquear la eliminación.")}</p>}
                          {confirmDeleteId === t.id && <p className="mt-1 max-w-[11rem] text-right text-[10px] font-semibold leading-tight text-red-600">{tr("This wipes the tenant and ALL its data. There is no undo.", "Isto apaga a empresa e TODOS os seus dados. Não há como desfazer.", "Esto borra la empresa y TODOS sus datos. No se puede deshacer.")}</p>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {/* Subscriptions */}
        <SubscriptionPanel ownerEmail={ownerEmail} />

        {/* Database: per-tenant exports */}
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Tenant exports", "Exportações das empresas", "Exportaciones de las empresas")}>
          <h2 className="font-bold">{tr("Export tenant database", "Exportar o banco da empresa", "Exportar la base de datos de la empresa")}</h2>
          <p className="mt-1 text-xs text-[var(--dim)]">{tr("Full dataset per tenant: JSON for inspection/backup. Downloading an export also unlocks that tenant's Delete button.", "Conjunto completo por empresa: JSON para inspeção/backup. Baixar uma exportação também libera o botão Excluir da empresa.", "Conjunto completo por empresa: JSON para inspección/respaldo. Descargar una exportación también desbloquea el botón Eliminar de esa empresa.")}</p>
          <div className="mt-2 space-y-2">
            {(q.data?.tenants ?? []).map((t) => (
              <div key={t.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-[var(--surface2)] px-3 py-2.5">
                <span className="min-w-0">
                  <span className="font-semibold">{t.name}</span>{" "}
                  <span className="font-mono text-[11px] text-[var(--dim)]">{t.code} • {t.totalRows} {tr("rows", "linhas", "filas")} • {fmtBytes(t.storageBytes)}</span>
                  {exportedIds.has(t.id) && <span className="ml-1 text-xs font-bold text-green-700">{tr("✓ exported", "✓ exportado", "✓ exportado")}</span>}
                </span>
                <span className="flex shrink-0 gap-2">
                  <button aria-label={tr(`Download JSON export for ${t.name}`, `Baixar a exportação JSON de ${t.name}`, `Descargar la exportación JSON de ${t.name}`)} disabled={exportMut.isPending} onClick={() => doExport(t, "json")} className="rounded-lg bg-[#0f2a44] px-3 py-1.5 text-xs font-bold text-white active:opacity-80 disabled:opacity-40">JSON</button>
                </span>
              </div>
            ))}
            {q.data && q.data.tenants.length === 0 && <p className="text-sm text-[var(--dim)]">{tr("No tenants yet.", "Nenhuma empresa ainda.", "Todavía no hay empresas.")}</p>}
          </div>
        </section>

        {/* Isolation check */}
        <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Tenant isolation check", "Verificação de isolamento das empresas", "Comprobación de aislamiento de empresas")}>
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div>
              <h2 className="font-bold">{tr("Tenant isolation check", "Verificação de isolamento das empresas", "Comprobación de aislamiento de empresas")}</h2>
              <p className="mt-0.5 text-xs text-[var(--dim)]">{tr("Self-test: verifies that no tenant's data is reachable from another tenant — orphan rows, cross-tenant references, and a scoped-read probe for every tenant pair.", "Autoteste: verifica se nenhum dado de uma empresa é acessível de outra — linhas órfãs, referências entre empresas e uma leitura com escopo para cada par de empresas.", "Autoprueba: verifica que ningún dato de una empresa sea accesible desde otra: filas huérfanas, referencias entre empresas y una lectura con alcance para cada par de empresas.")}</p>
            </div>
            <button className={btnPrimary} disabled={runIso.isPending} aria-label={tr("Run the tenant isolation check", "Executar a verificação de isolamento", "Ejecutar la comprobación de aislamiento")} onClick={() => runIso.mutate()}>
              {runIso.isPending ? tr("Checking…", "Verificando…", "Comprobando…") : tr("Run isolation check", "Executar a verificação de isolamento", "Ejecutar la comprobación de aislamiento")}
            </button>
          </div>
          {runIso.isError && <p className="mt-2 text-sm font-semibold text-red-600">{tr("The isolation check could not run.", "A verificação de isolamento não pôde ser executada.", "La comprobación de aislamiento no se pudo ejecutar.")}</p>}
          {isoResult && (
            <div className="mt-3 space-y-2">
              <p className={`rounded-xl px-3 py-2 text-sm font-bold ${isoResult.ok ? "bg-green-100 text-green-800" : "bg-red-100 text-red-700"}`} role="status">
                {isoResult.ok ? `"+tr("✅ Isolation holds across", "✅ O isolamento se mantém em", "✅ El aislamiento se mantiene en")+" ${isoResult.tenantCount} "+tr("tenant(s) — no cross-tenant data is readable.", "empresa(s) — nenhum dado entre empresas pode ser lido.", "empresa(s): ningún dato entre empresas se puede leer.")+"` : tr("🚨 Isolation problems found — see below.", "🚨 Problemas de isolamento encontrados — veja abaixo.", "🚨 Se encontraron problemas de aislamiento: mira abajo.")}
              </p>
              {isoResult.checks.map((c) => (
                <div key={c.name} className="flex items-start gap-2 rounded-xl bg-[var(--surface2)] px-3 py-2 text-sm">
                  <span aria-hidden="true">{c.ok ? "✅" : "🚨"}</span>
                  <span><span className="font-semibold">{c.name}</span><br /><span className="text-xs text-[var(--dim)]">{c.detail}</span></span>
                </div>
              ))}
            </div>
          )}
        </section>

        <p className="px-1 text-center text-[11px] text-[var(--dim)]">{tr("Suspended tenants keep all their data and can be reactivated anytime. Deleting a tenant is permanent and requires a fresh database export first.", "Empresas suspensas mantêm todos os dados e podem ser reativadas a qualquer momento. Excluir uma empresa é permanente e exige uma exportação nova do banco primeiro.", "Las empresas suspendidas conservan todos sus datos y se pueden reactivar en cualquier momento. Eliminar una empresa es permanente y primero requiere una exportación nueva de la base de datos.")}</p>
      </main>
    </div>
  );
}

function SubscriptionPanel({ ownerEmail }: { ownerEmail: string }) {
  const qc = useQueryClient();
  const q = useQuery({ queryKey: ["subscriptions", ownerEmail], queryFn: () => api.getSubscriptionOverview({ ownerEmail }) });
  const [editingFee, setEditingFee] = useState<string | null>(null);
  const [feeValue, setFeeValue] = useState("");
  const [showPayFor, setShowPayFor] = useState<string | null>(null);
  const [payAmount, setPayAmount] = useState("");
  const [payDate, setPayDate] = useState(todayInput());
  const [payNotes, setPayNotes] = useState("");
  const [msg, setMsg] = useState("");

  const invalidate = () => qc.invalidateQueries({ queryKey: ["subscriptions", ownerEmail] });

  const setFee = useMutation({
    mutationFn: (args: { companyId: string; weeklyFeeCents: number }) => api.setWeeklyFee({ ownerEmail, ...args }),
    onSuccess: () => { invalidate(); setEditingFee(null); setMsg(tr("Weekly fee updated.", "Valor semanal atualizado.", "Valor semanal actualizado.")); },
    onError: () => setMsg(tr("Could not update the fee.", "Não foi possível atualizar o valor.", "No se pudo actualizar el valor.")),
  });

  const recordPay = useMutation({
    mutationFn: (args: { companyId: string; amountCents: number; paidDate: string; notes: string }) =>
      api.recordSubscriptionPayment({ ownerEmail, ...args }),
    onSuccess: () => { invalidate(); setShowPayFor(null); setPayAmount(""); setPayNotes(""); setMsg(tr("Payment recorded.", "Pagamento lançado.", "Pago registrado.")); },
    onError: () => setMsg(tr("Could not record the payment.", "Não foi possível lançar o pagamento.", "No se pudo registrar el pago.")),
  });

  const payQ = useQuery({
    queryKey: ["subpayments", ownerEmail, showPayFor],
    queryFn: () => api.listSubscriptionPayments({ ownerEmail, companyId: showPayFor! }),
    enabled: !!showPayFor,
  });

  return (
    <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4" aria-label={tr("Subscriptions", "Assinaturas", "Suscripciones")}>
      <h2 className="font-bold">💳 {tr("Subscriptions", "Assinaturas", "Suscripciones")}</h2>
      {msg && <p className="mt-2 rounded-xl bg-[var(--surface2)] px-3 py-2 text-sm font-semibold" role="status">{msg}</p>}
      {q.isPending ? <p className="mt-2 text-sm text-[var(--dim)]">{tr("Loading…", "Carregando…", "Cargando…")}</p> : q.isError ? (
        <p className="mt-2 text-sm text-red-600">{tr("Could not load subscriptions.", "Não foi possível carregar as assinaturas.", "No se pudieron cargar las suscripciones.")}</p>
      ) : (
        <div className="mt-3 space-y-3">
          <div className="rounded-xl bg-[var(--surface2)] p-3">
            <p className="text-xs font-semibold uppercase tracking-wide text-[var(--dim)]">{tr("Total weekly", "Total semanal", "Total semanal")}</p>
            <p className="text-2xl font-black">{fmtUSD(q.data.totalWeeklyCents)}</p>
          </div>
          {q.data.builders.map((b) => (
            <div key={b.companyId} className="rounded-xl border border-[var(--border)] p-3">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div>
                  <p className="font-bold">{b.companyName} <span className="text-xs font-normal text-[var(--dim)]">({b.code})</span></p>
                  <p className="text-sm text-[var(--dim)]">👥 {b.userCount} {tr("users", "usuários", "usuarios")} • {b.billableUsers} {tr("billable", "pagantes", "de pago")}</p>
                </div>
                <div className="text-right">
                  {editingFee === b.companyId ? (
                    <div className="flex items-center gap-1">
                      <input aria-label={tr("Weekly fee per user in dollars", "Valor semanal por usuário em dólares", "Valor semanal por usuario en dólares")} className={inputCls} inputMode="decimal" value={feeValue} onChange={(e) => setFeeValue(e.target.value)} placeholder="0.00" style={{ width: 90 }} />
                      <button type="button" className={btnNavy} disabled={setFee.isPending} onClick={() => setFee.mutate({ companyId: b.companyId, weeklyFeeCents: Math.round(parseFloat(feeValue.replace(",", ".")) * 100) || 0 })}>{tr("Save", "Salvar", "Guardar")}</button>
                      <button type="button" className={btnGhost} onClick={() => setEditingFee(null)}>{tr("Cancel", "Cancelar", "Cancelar")}</button>
                    </div>
                  ) : (
                    <div>
                      <p className="font-bold">{fmtUSD(b.weeklyFeeCents)}<span className="text-xs font-normal text-[var(--dim)]\">/{tr("user/week", "usuário/semana", "usuario/semana")}</span></p>
                      <p className="text-sm font-semibold text-green-700">= {fmtUSD(b.weeklyFeeCents * b.billableUsers)}<span className="text-xs font-normal text-[var(--dim)]">/{tr("week", "semana", "semana")}</span></p>
                      <button type="button" className="text-xs font-bold text-[#f97316]" onClick={() => { setEditingFee(b.companyId); setFeeValue((b.weeklyFeeCents / 100).toFixed(2)); }}>{tr("Edit fee", "Editar valor", "Editar valor")}</button>
                    </div>
                  )}
                </div>
              </div>
              <div className="mt-2 flex flex-wrap items-center gap-2 text-sm">
                <span className="text-[var(--dim)]">{tr("Paid total:", "Total pago:", "Total pagado:")} <span className="font-semibold text-green-700">{fmtUSD(b.totalPaidCents)}</span></span>
                {b.lastPaymentDate && <span className="text-[var(--dim)]">• {tr("last:", "último:", "último:")} {fmtDate(b.lastPaymentDate)}</span>}
                <button type="button" className={btnGhost} onClick={() => { setShowPayFor(showPayFor === b.companyId ? null : b.companyId); setPayDate(todayInput()); }}>
                  {showPayFor === b.companyId ? tr("Close", "Fechar", "Cerrar") : tr("+ Record payment", "+ Lançar pagamento", "+ Registrar pago")}
                </button>
              </div>
              {showPayFor === b.companyId && (
                <div className="mt-2 rounded-xl bg-[var(--surface2)] p-3">
                  <div className="grid grid-cols-2 gap-2">
                    <Field label={tr("Amount (USD)", "Valor (USD)", "Importe (USD)")}>
                      <input aria-label={tr("Payment amount", "Valor do pagamento", "Importe del pago")} className={inputCls} inputMode="decimal" value={payAmount} onChange={(e) => setPayAmount(e.target.value)} placeholder="0.00" required />
                    </Field>
                    <Field label={tr("Date", "Data", "Fecha")}>
                      <input aria-label={tr("Payment date", "Data do pagamento", "Fecha del pago")} type="date" className={inputCls} value={payDate} onChange={(e) => setPayDate(e.target.value)} required />
                    </Field>
                  </div>
                  <Field label={tr("Notes (optional)", "Observações (opcional)", "Notas (opcional)")}>
                    <input aria-label={tr("Payment notes", "Observações do pagamento", "Notas del pago")} className={inputCls} value={payNotes} onChange={(e) => setPayNotes(e.target.value)} />
                  </Field>
                  <button type="button" className={`${btnNavy} mt-2 w-full`} disabled={recordPay.isPending || !payAmount.trim()}
                    onClick={() => recordPay.mutate({ companyId: b.companyId, amountCents: Math.round(parseFloat(payAmount.replace(",", ".")) * 100) || 0, paidDate: payDate, notes: payNotes })}>
                    {tr("Record payment", "Lançar pagamento", "Registrar pago")}
                  </button>
                  {payQ.data && payQ.data.payments.length > 0 && (
                    <div className="mt-3">
                      <p className="text-xs font-bold uppercase tracking-wide text-[var(--dim)]">{tr("History", "Histórico", "Historial")}</p>
                      <div className="mt-1 space-y-1">
                        {payQ.data.payments.map((p) => (
                          <p key={p.id} className="text-sm">{fmtDate(p.paidDate)} • <span className="font-semibold text-green-700">{fmtUSD(p.amountCents)}</span>{p.notes ? <span className="text-[var(--dim)]"> • {p.notes}</span> : null}</p>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </section>
  );
}
